import * as fs from 'fs';
import * as path from 'path';

/**
 * Counts the number of trailing zero bits in a 32-bit integer.
 */
function countTrailingZeros(n: number): number {
    if (n === 0) return 32;
    let count = 0;
    let temp = n;
    while ((temp & 1) === 0) {
        temp >>>= 1;
        count++;
    }
    return count;
}

/**
 * Counts the number of set bits (population count) in a 32-bit integer.
 */
function countSetBits(n: number): number {
    let count = 0;
    let temp = n;
    while (temp !== 0) {
        temp &= (temp - 1);
        count++;
    }
    return count;
}

function solve() {
    const args = process.argv.slice(2);
    if (args.length === 0) return;
    const dir = args[0];

    // Read all .bmp files in the directory and sort them by name.
    const files = fs.readdirSync(dir)
        .filter(f => f.endsWith('.bmp'))
        .sort()
        .map(f => path.join(dir, f));

    for (const file of files) {
        const buffer = fs.readFileSync(file);
        const fileName = path.basename(file);

        if (buffer.length < 14) {
            console.log(`== ${fileName}`);
            continue;
        }

        // BMP File Header
        const bfOffBits = buffer.readUInt32LE(10);
        const dibSize = buffer.readUInt32LE(14);

        // DIB Header
        const width = buffer.readInt32LE(18);
        const height = buffer.readInt32LE(22);
        const bpp = buffer.readUInt16LE(28);
        const compression = buffer.readUInt32LE(30);
        const colorsUsed = buffer.readUInt32LE(46);

        console.log(`== ${fileName}`);

        // Check for unsupported compression
        if (compression !== 0 && compression !== 3) {
            console.log(`error: unsupported compression ${compression}`);
            continue;
        }

        const absHeight = Math.abs(height);
        const orientation = height > 0 ? "bottom-up" : "top-down";
        const rowSize = Math.ceil((width * bpp) / 32) * 4;

        let colorTable: number[] = [];
        if (bpp === 1 || bpp === 4 || bpp === 8) {
            const numEntries = colorsUsed > 0 ? colorsUsed : (1 << bpp);
            const tableStart = 14 + dibSize;
            colorTable = [];
            for (let i = 0; i < numEntries; i++) {
                colorTable.push(
                    buffer.readUInt8(tableStart + i * 4),
                    buffer.readUInt8(tableStart + i * 4 + 1),
                    buffer.readUInt8(tableStart + i * 4 + 2)
                );
            }
        }

        let masks: number[] = [];
        if (bpp === 32 && compression === 3) {
            // Masks are at 40, 44, 48 bytes into the DIB header (starting at 14)
            masks = [
                buffer.readUInt32LE(14 + 40),
                buffer.readUInt32LE(14 + 44),
                buffer.readUInt32LE(14 + 48)
            ];
        }

        const isInk = Array.from({ length: absHeight }, () => new Uint8Array(width));
        let inkCount = 0;

        for (let i = 0; i < absHeight; i++) {
            // Calculate the y-coordinate based on the orientation of the BMP file
            const y = height > 0 ? (absHeight - 1 - i) : i;
            const offset = bfOffBits + i * rowSize;

            for (let x = 0; x < width; x++) {
                let r = 0, g = 0, b = 0;

                if (bpp === 1) {
                    const byteIdx = Math.floor(x / 8);
                    const val = (buffer[offset + byteIdx] >> (7 - (x % 8))) & 1;
                    b = colorTable[val * 3];
                    g = colorTable[val * 3 + 1];
                    r = colorTable[val * 3 + 2];
                } else if (bpp === 4) {
                    const byteIdx = Math.floor(x / 2);
                    const val = (buffer[offset + byteIdx] >> (7 - (x % 2) * 4)) & 0xF;
                    b = colorTable[val * 3];
                    g = colorTable[val * 3 + 1];
                    r = colorTable[val * 3 + 2];
                } else if (bpp === 8) {
                    const val = buffer[offset + x];
                    b = colorTable[val * 3];
                    g = colorTable[val * 3 + 1];
                    r = colorTable[val * 3 + 2];
                } else if (bpp === 24) {
                    const byteIdx = x * 3;
                    b = buffer[offset + byteIdx];
                    g = buffer[offset + byteIdx + 1];
                    r = buffer[offset + byteIdx + 2];
                } else if (bpp === 32) {
                    const byteIdx = x * 4;
                    if (compression === 0) {
                        b = buffer[offset + byteIdx];
                        g = buffer[offset + byteIdx + 1];
                        r = buffer[offset + byteIdx + 2];
                    } else {
                        const pixel = buffer.readUInt32LE(offset + byteIdx);
                        // Masks are in the order: red, green, blue
                        for (let j = 0; j < 3; j++) {
                            const mask = masks[j];
                            const v = (pixel & mask) >>> countTrailingZeros(mask);
                            const n = countSetBits(mask);
                            const m = (1 << n) - 1;
                            const val = Math.floor((v * 255 + Math.floor(m / 2)) / m);
                            if (j === 0) r = val;
                            else if (j === 1) g = val;
                            else b = val;
                        }
                    }
                }

                // Determine if the pixel is "ink"
                if (Math.floor((299 * r + 587 * g + 114 * b) / 1000) < 128) {
                    isInk[y][x] = 1;
                    inkCount++;
                }
            }
        }

        console.log(`size ${width}x${absHeight} bpp ${bpp} header ${dibSize} ${orientation} ink ${inkCount}`);

        const visited = Array.from({ length: absHeight }, () => new Uint8Array(width));
        const components: { firstX: number, firstY: number, minX: number, minY: number, maxX: number, maxY: number, count: number }[] = [];

        // Find connected components using BFS
        for (let y = 0; y < absHeight; y++) {
            for (let x = 0; x < width; x++) {
                if (isInk[y][x] && !visited[y][x]) {
                    let count = 0;
                    let minX = x, maxX = x, minY = y, maxY = y;
                    const queue: [number, number][] = [[x, y]];
                    visited[y][x] = 1;

                    let head = 0;
                    while (head < queue.length) {
                        const [cx, cy] = queue[head++];
                        count++;
                        if (cx < minX) minX = cx;
                        if (cx > maxX) maxX = cx;
                        if (cy < minY) minY = cy;
                        if (cy > maxY) maxY = cy;

                        for (let dy = -1; dy <= 1; dy++) {
                            for (let dx = -1; dx <= 1; dx++) {
                                const nx = cx + dx, ny = cy + dy;
                                if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight && isInk[ny][nx] && !visited[ny][nx]) {
                                    visited[ny][nx] = 1;
                                    queue.push([nx, ny]);
                                }
                            }
                        }
                    }
                    components.push({ firstX: x, firstY: y, minX, minY, maxX, maxY, count });
                }
            }
        }

        console.log(`components ${components.length}`);
        for (const c of components) {
            console.log(`${c.firstX},${c.firstY} bbox ${c.minX},${c.minY}-${c.maxX},${c.maxY} pixels ${c.count}`);
        }
    }
}

