import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    static class Currency {
        String code;
        int minorUnits;

        Currency(String code, int minorUnits) {
            this.code = code;
            this.minorUnits = minorUnits;
        }
    }

    static class Account {
        String name;
        Currency currency;
        BigDecimal balance;
        BigDecimal limit;

        Account(String name, Currency currency, BigDecimal limit) {
            this.name = name;
            this.currency = currency;
            this.balance = BigDecimal.ZERO;
            this.limit = limit;
        }
    }

    static Map<String, Currency> currencies = new LinkedHashMap<>();
    static Map<String, Account> accounts = new LinkedHashMap<>();
    static List<String> rejections = new ArrayList<>();

    public static void main(String[] args) {
        if (args.length < 1) return;
        File ledgerFile = new File(args[0], "ledger.txt");
        if (!ledgerFile.exists()) return;

        try (BufferedReader br = new BufferedReader(new FileReader(ledgerFile))) {
            String line;
            int lineNum = 0;
            while ((line = br.readLine()) != null) {
                lineNum++;
                String trimmed = line.trim();
                if (trimmed.isEmpty() || trimmed.startsWith("#")) continue;

                String[] parts = trimmed.split("\\s+");
                String command = parts[0];

                try {
                    switch (command) {
                        case "currency":
                            currencies.put(parts[1], new Currency(parts[1], Integer.parseInt(parts[2])));
                            break;
                        case "open":
                            String accName = parts[1];
                            Currency accCurr = currencies.get(parts[2]);
                            BigDecimal accLimit = parts.length > 3 ? new BigDecimal(parts[3]).setScale(accCurr.minorUnits, RoundingMode.HALF_EVEN) : BigDecimal.ZERO;
                            if (accounts.containsKey(accName)) {
                                rejections.add("line " + lineNum + ": REJECT account exists " + accName);
                            } else {
                                accounts.put(accName, new Account(accName, accCurr, accLimit));
                            }
                            break;
                        case "deposit":
                            handleDeposit(parts, lineNum);
                            break;
                        case "withdraw":
                            handleWithdraw(parts, lineNum);
                            break;
                        case "transfer":
                            handleTransfer(parts, lineNum);
                            break;
                        case "convert":
                            handleConvert(parts, lineNum);
                            break;
                        case "interest":
                            handleInterest(parts, lineNum);
                            break;
                        case "split":
                            handleSplit(parts, lineNum);
                            break;
                    }
                } catch (Exception e) {}
            }
        } catch (IOException e) {}

        System.out.println(String.join("\n", rejections));
        if (!rejections.isEmpty()) System.out.println();

        List<Account> sortedAccounts = new ArrayList<>(accounts.values());
        sortedAccounts.sort(Comparator.comparing(a -> a.name));
        for (Account a : sortedAccounts) {
            System.out.println(a.name + " " + a.currency.code + " " + formatMoneyCorrectly(a.balance, a.currency.minorUnits));
        }
        System.out.println();

        Map<String, List<Account>> currencyToAccounts = new HashMap<>();
        for (Account a : accounts.values()) {
            currencyToAccounts.computeIfAbsent(a.currency.code, k -> new ArrayList<>()).add(a);
        }
        List<String> sortedCodes = new ArrayList<>(currencyToAccounts.keySet());
        Collections.sort(sortedCodes);
        for (String code : sortedCodes) {
            List<Account> accs = currencyToAccounts.get(code);
            BigDecimal total = BigDecimal.ZERO;
            for (Account a : accs) total = total.add(a.balance);
            System.out.println("total " + code + " " + formatMoneyCorrectly(total, currencies.get(code).minorUnits) + " (" + accs.size() + " accounts)");
        }
    }

    private static void handleDeposit(String[] parts, int lineNum) {
        String name = parts[1];
        Account acc = accounts.get(name);
        BigDecimal amount = new BigDecimal(parts[2]).setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else {
            acc.balance = acc.balance.add(amount);
        }
    }

    private static void handleWithdraw(String[] parts, int lineNum) {
        String name = parts[1];
        Account acc = accounts.get(name);
        BigDecimal amount = new BigDecimal(parts[2]).setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else if (acc.balance.subtract(amount).compareTo(acc.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + name);
        } else {
            acc.balance = acc.balance.subtract(amount);
        }
    }

    private static void handleTransfer(String[] parts, int lineNum) {
        String fromName = parts[1];
        String toName = parts[2];
        Account from = accounts.get(fromName);
        Account to = accounts.get(toName);
        BigDecimal amount = new BigDecimal(parts[3]).setScale(from != null ? from.currency.minorUnits : 0, RoundingMode.HALF_EVEN);

        if (from == null || to == null) {
            if (from == null) rejections.add("line " + lineNum + ": REJECT unknown account " + fromName);
            else rejections.add("line " + lineNum + ": REJECT unknown account " + toName);
            return;
        }

        if (!from.currency.code.equals(to.currency.code)) {
            rejections.add("line " + lineNum + ": REJECT currency mismatch");
            return;
        }

        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else if (from.balance.subtract(amount).compareTo(from.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + fromName);
        } else {
            from.balance = from.balance.subtract(amount);
            to.balance = to.balance.add(amount);
        }
    }

    private static void handleConvert(String[] parts, int lineNum) {
        String fromName = parts[1];
        String toName = parts[2];
        Account from = accounts.get(fromName);
        Account to = accounts.get(toName);
        BigDecimal amountRaw = new BigDecimal(parts[3]);
        BigDecimal rate = new BigDecimal(parts[4]);

        if (from == null || to == null) {
            if (from == null) rejections.add("line " + lineNum + ": REJECT unknown account " + fromName);
            else rejections.add("line " + lineNum + ": REJECT unknown account " + toName);
            return;
        }

        BigDecimal amount = amountRaw.setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else if (from.balance.subtract(amount).compareTo(from.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + fromName);
        } else {
            from.balance = from.balance.subtract(amount);
            BigDecimal amountTo = amount.multiply(rate).setScale(to.currency.minorUnits, RoundingMode.HALF_EVEN);
            to.balance = to.balance.add(amountTo);
        }
    }

    private static void handleInterest(String[] parts, int lineNum) {
        String name = parts[1];
        Account acc = accounts.get(name);
        if (acc == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + name);
            return;
        }
        BigDecimal rate = new BigDecimal(parts[2]);
        BigDecimal interest = acc.balance.multiply(rate).setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
        acc.balance = acc.balance.add(interest);
    }

    private static void handleSplit(String[] parts, int lineNum) {
        String fromName = parts[1];
        Account from = accounts.get(fromName);
        BigDecimal amountRaw = new BigDecimal(parts[2]);

        List<String> targetNames = new ArrayList<>();
        List<Long> weights = new ArrayList<>();
        for (int i = 3; i < parts.length; i++) {
            String[] targetParts = parts[i].split(":");
            targetNames.add(targetParts[0]);
            weights.add(Long.parseLong(targetParts[1]));
        }

        if (from == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + fromName);
            return;
        }

        for (String name : targetNames) {
            if (!accounts.containsKey(name)) {
                rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                return;
            }
        }

        for (String name : targetNames) {
            Account target = accounts.get(name);
            if (!target.currency.code.equals(from.currency.code)) {
                rejections.add("line " + lineNum + ": REJECT currency mismatch");
                return;
            }
        }

        BigDecimal amount = amountRaw.setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
            return;
        }

        if (from.balance.subtract(amount).compareTo(from.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + fromName);
            return;
        }

        from.balance = from.balance.subtract(amount);
        BigDecimal A = amount.movePointRight(from.currency.minorUnits).abs();
        BigDecimal W = BigDecimal.ZERO;
        for (long w : weights) W = W.add(BigDecimal.valueOf(w));

        long[] shares = new long[targetNames.size()];
        long[] remainders = new long[targetNames.size()];
        for (int i = 0; i < targetNames.size(); i++) {
            BigDecimal weight = BigDecimal.valueOf(weights.get(i));
            BigDecimal product = A.multiply(weight);
            shares[i] = product.divide(W, RoundingMode.FLOOR).longValue();
            remainders[i] = product.remainder(W).longValue();
        }

        long totalRemainder = 0;
        for (long r : remainders) totalRemainder += r;

        Integer[] indices = new Integer[targetNames.size()];
        for (int i = 0; i < targetNames.size(); i++) indices[i] = i;
        Arrays.sort(indices, (a, b) -> {
            if (remainders[b] != remainders[a]) {
                return Long.compare(remainders[b], remainders[a]);
            }
            return Integer.compare(a, b);
        });

        for (int i = 0; i < totalRemainder; i++) {
            shares[indices[i]]++;
        }

        for (int i = 0; i < targetNames.size(); i++) {
            Account target = accounts.get(targetNames.get(i));
            BigDecimal share = BigDecimal.valueOf(shares[i]).movePointLeft(from.currency.minorUnits);
            target.balance = target.balance.add(share);
        }
    }

    private static String formatMoneyCorrectly(BigDecimal amount, int minorUnits) {
        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return "0" + (minorUnits > 0 ? "." + "0".repeat(minorUnits) : "");
        }

        boolean isNegative = amount.compareTo(BigDecimal.ZERO) < 0;
        BigDecimal absAmount = amount.abs().setScale(minorUnits, RoundingMode.HALF_EVEN);

        String s = absAmount.toPlainString();
        String[] parts = s.split("\\.");
        String integerPart = parts[0];

        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = integerPart.length() - 1; i >= 0; i--) {
            if (count > 0 && count % 3 == 0) {
                sb.append(",");
            }
            sb.append(integerPart.charAt(i));
            count++;
        }

        String result = sb.reverse().toString();
        if (minorUnits > 0) {
            String decimalPart = (parts.length > 1) ? parts[1] : "0".repeat(minorUnits);
            result += "." + decimalPart;
        }

        return (isNegative ? "-" : "") + result;
    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    static class Currency {
        String code;
        int minorUnits;

        Currency(String code, int minorUnits) {
            this.code = code;
            this.minorUnits = minorUnits;
        }
    }

    static class Account {
        String name;
        Currency currency;
        BigDecimal balance;
        BigDecimal limit;

        Account(String name, Currency currency, BigDecimal limit) {
            this.name = name;
            this.currency = currency;
            this.balance = BigDecimal.ZERO;
            this.limit = limit;
        }
    }

    static Map<String, Currency> currencies = new LinkedHashMap<>();
    static Map<String, Account> accounts = new LinkedHashMap<>();
    static List<String> rejections = new ArrayList<>();

    public static void main(String[] args) {
        if (args.length < 1) return;
        File ledgerFile = new File(args[0], "ledger.txt");
        if (!ledgerFile.exists()) return;

        try (BufferedReader br = new BufferedReader(new FileReader(ledgerFile))) {
            String line;
            int lineNum = 0;
            while ((line = br.readLine()) != null) {
                lineNum++;
                String trimmed = line.trim();
                if (trimmed.isEmpty() || trimmed.startsWith("#")) continue;

                String[] parts = trimmed.split("\\s+");
                String command = parts[0];

                try {
                    switch (command) {
                        case "currency":
                            currencies.put(parts[1], new Currency(parts[1], Integer.parseInt(parts[2])));
                            break;
                        case "open":
                            String accName = parts[1];
                            Currency accCurr = currencies.get(parts[2]);
                            BigDecimal accLimit = parts.length > 3 ? new BigDecimal(parts[3]).setScale(accCurr.minorUnits, RoundingMode.HALF_EVEN) : BigDecimal.ZERO;
                            if (accounts.containsKey(accName)) {
                                rejections.add("line " + lineNum + ": REJECT account exists " + accName);
                            } else {
                                accounts.put(accName, new Account(accName, accCurr, accLimit));
                            }
                            break;
                        case "deposit":
                            handleDeposit(parts, lineNum);
                            break;
                        case "withdraw":
                            handleWithdraw(parts, lineNum);
                            break;
                        case "transfer":
                            handleTransfer(parts, lineNum);
                            break;
                        case "convert":
                            handleConvert(parts, lineNum);
                            break;
                        case "interest":
                            handleInterest(parts, lineNum);
                            break;
                        case "split":
                            handleSplit(parts, lineNum);
                            break;
                    }
                } catch (Exception e) {}
            }
        } catch (IOException e) {}

        if (!rejections.isEmpty()) {
            System.out.println(String.join("\n", rejections));
            System.out.println();
        }

        List<Account> sortedAccounts = new ArrayList<>(accounts.values());
        sortedAccounts.sort(Comparator.comparing(a -> a.name));
        for (Account a : sortedAccounts) {
            System.out.println(a.name + " " + a.currency.code + " " + formatMoneyCorrectly(a.balance, a.currency.minorUnits));
        }
        System.out.println();

        Map<String, List<Account>> currencyToAccounts = new HashMap<>();
        for (Account a : accounts.values()) {
            currencyToAccounts.computeIfAbsent(a.currency.code, k -> new ArrayList<>()).add(a);
        }
        List<String> sortedCodes = new ArrayList<>(currencyToAccounts.keySet());
        Collections.sort(sortedCodes);
        for (String code : sortedCodes) {
            List<Account> accs = currencyToAccounts.get(code);
            BigDecimal total = BigDecimal.ZERO;
            for (Account a : accs) total = total.add(a.balance);
            System.out.println("total " + code + " " + formatMoneyCorrectly(total, currencies.get(code).minorUnits) + " (" + accs.size() + " accounts)");
        }
    }

    private static void handleDeposit(String[] parts, int lineNum) {
        String name = parts[1];
        Account acc = accounts.get(name);
        if (acc == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + name);
            return;
        }
        BigDecimal amount = new BigDecimal(parts[2]).setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else {
            acc.balance = acc.balance.add(amount);
        }
    }

    private static void handleWithdraw(String[] parts, int lineNum) {
        String name = parts[1];
        Account acc = accounts.get(name);
        if (acc == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + name);
            return;
        }
        BigDecimal amount = new BigDecimal(parts[2]).setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else if (acc.balance.subtract(amount).compareTo(acc.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + name);
        } else {
            acc.balance = acc.balance.subtract(amount);
        }
    }

    private static void handleTransfer(String[] parts, int lineNum) {
        String fromName = parts[1];
        String toName = parts[2];
        Account from = accounts.get(fromName);
        Account to = accounts.get(toName);

        if (from == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + fromName);
            return;
        }
        if (to == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + toName);
            return;
        }

        if (!from.currency.code.equals(to.currency.code)) {
            rejections.add("line " + lineNum + ": REJECT currency mismatch");
            return;
        }

        BigDecimal amount = new BigDecimal(parts[3]).setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else if (from.balance.subtract(amount).compareTo(from.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + fromName);
        } else {
            from.balance = from.balance.subtract(amount);
            to.balance = to.balance.add(amount);
        }
    }

    private static void handleConvert(String[] parts, int lineNum) {
        String fromName = parts[1];
        String toName = parts[2];
        Account from = accounts.get(fromName);
        Account to = accounts.get(toName);

        if (from == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + fromName);
            return;
        }
        if (to == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + toName);
            return;
        }

        BigDecimal amount = new BigDecimal(parts[3]).setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
        } else if (from.balance.subtract(amount).compareTo(from.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + fromName);
        } else {
            from.balance = from.balance.subtract(amount);
            BigDecimal rate = new BigDecimal(parts[4]);
            BigDecimal amountTo = amount.multiply(rate).setScale(to.currency.minorUnits, RoundingMode.HALF_EVEN);
            to.balance = to.balance.add(amountTo);
        }
    }

    private static void handleInterest(String[] parts, int lineNum) {
        String name = parts[1];
        Account acc = accounts.get(name);
        if (acc == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + name);
            return;
        }
        BigDecimal rate = new BigDecimal(parts[2]);
        BigDecimal interest = acc.balance.multiply(rate).setScale(acc.currency.minorUnits, RoundingMode.HALF_EVEN);
        acc.balance = acc.balance.add(interest);
    }

    private static void handleSplit(String[] parts, int lineNum) {
        String fromName = parts[1];
        Account from = accounts.get(fromName);
        if (from == null) {
            rejections.add("line " + lineNum + ": REJECT unknown account " + fromName);
            return;
        }

        List<String> targetNames = new ArrayList<>();
        List<Long> weights = new ArrayList<>();
        for (int i = 3; i < parts.length; i++) {
            String[] targetParts = parts[i].split(":");
            targetNames.add(targetParts[0]);
            weights.add(Long.parseLong(targetParts[1]));
        }

        for (String name : targetNames) {
            if (!accounts.containsKey(name)) {
                rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                return;
            }
        }

        for (String name : targetNames) {
            Account target = accounts.get(name);
            if (!target.currency.code.equals(from.currency.code)) {
                rejections.add("line " + lineNum + ": REJECT currency mismatch");
                return;
            }
        }

        BigDecimal amount = new BigDecimal(parts[2]).setScale(from.currency.minorUnits, RoundingMode.HALF_EVEN);
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            rejections.add("line " + lineNum + ": REJECT non-positive amount");
            return;
        }

        if (from.balance.subtract(amount).compareTo(from.limit.negate()) < 0) {
            rejections.add("line " + lineNum + ": REJECT insufficient funds " + fromName);
            return;
        }

        from.balance = from.balance.subtract(amount);
        BigInteger bigA = amount.movePointRight(from.currency.minorUnits).toBigInteger();
        BigInteger bigW = BigInteger.ZERO;
        for (long w : weights) bigW = bigW.add(BigInteger.valueOf(w));

        BigInteger[] shares = new BigInteger[targetNames.size()];
        BigInteger[] remainders = new BigInteger[targetNames.size()];
        BigInteger sumShares = BigInteger.ZERO;

        for (int i = 0; i < targetNames.size(); i++) {
            BigInteger weight = BigInteger.valueOf(weights.get(i));
            BigInteger product = bigA.multiply(weight);
            shares[i] = product.divide(bigW);
            remainders[i] = product.remainder(bigW);
            sumShares = sumShares.add(shares[i]);
        }

        BigInteger totalRemainder = bigA.subtract(sumShares);

        Integer[] indices = new Integer[targetNames.size()];
        for (int i = 0; i < targetNames.size(); i++) indices[i] = i;
        Arrays.sort(indices, (a, b) -> {
            int cmp = remainders[b].compareTo(remainders[a]);
            if (cmp != 0) return cmp;
            return Integer.compare(a, b);
        });

        for (int i = 0; i < totalRemainder.intValue(); i++) {
            shares[indices[i]] = shares[indices[i]].add(BigInteger.ONE);
        }

        for (int i = 0; i < targetNames.size(); i++) {
            Account target = accounts.get(targetNames.get(i));
            BigDecimal share = BigDecimal.valueOf(shares[i]).movePointLeft(from.currency.minorUnits);
            target.balance = target.balance.add(share);
        }
    }

    private static String formatMoneyCorrectly(BigDecimal amount, int minorUnits) {
        amount = amount.setScale(minorUnits, RoundingMode.HALF_EVEN);
        boolean isNegative = amount.compareTo(BigDecimal.ZERO) < 0;
        BigDecimal absAmount = amount.abs();

        String s = absAmount.toPlainString();
        String[] parts = s.split("\\.");
        String integerPart = parts[0];

        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = integerPart.length() - 1; i >= 0; i--) {
            if (count > 0 && count % 3 == 0) {
                sb.append(",");
            }
            sb.append(integerPart.charAt(i));
            count++;
        }

        String result = sb.reverse().toString();
        if (minorUnits > 0) {
            String decimalPart = (parts.length > 1) ? parts[1] : "0".repeat(minorUnits);
            if (decimalPart.length() > minorUnits) {
                decimalPart = decimalPart.substring(0, minorUnits);
            } else {
                decimalPart = String.format("%" + minorUnits + "s", decimalPart).replace(' ', '0');
            }
            result += "." + decimalPart;
        }

        if (isNegative && !result.equals("0" + (minorUnits > 0 ? "." + "0".repeat(minorUnits) : ""))) {
            return "-" + result;
        }
        return result;
    }
}

import os
import sys
from decimal import Decimal, ROUND_HALF_EVEN

def solve():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]
    ledger_path = os.path.join(dir_path, 'ledger.txt')

    if not os.path.exists(ledger_path):
        return

    with open(ledger_path, 'r') as f:
        lines = f.readlines()

    currencies = {} # CODE -> minor_units
    accounts = {} # name -> {code, balance, limit}
    rejections = []

    for i, line in enumerate(lines):
        line_num = i + 1
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        parts = line.split()
        cmd = parts[0]

        try:
            if cmd == 'currency':
                code = parts[1]
                minor_units = int(parts[2])
                currencies[code] = minor_units

            elif cmd == 'open':
                name = parts[1]
                code = parts[2]
                limit_str = parts[3] if len(parts) > 3 else '0'

                if name in accounts:
                    rejections.append(f"line {line_num}: REJECT account exists {name}")
                else:
                    # Round the limit to the currency's minor units
                    precision = Decimal('1').scaleb(-currencies[code])
                    limit = Decimal(limit_str).quantize(precision, rounding=ROUND_HALF_EVEN)
                    accounts[name] = {'code': code, 'balance': Decimal('0'), 'limit': limit}

            elif cmd == 'deposit':
                name = parts[1]
                amount_str = parts[2]
                if name not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name}")
                else:
                    precision = Decimal('1').scaleb(-currencies[accounts[name]['code']])
                    amount = Decimal(amount_str).quantize(precision, rounding=ROUND_HALF_EVEN)
                    if amount <= 0:
                        rejections.append(f"line {line_num}: REJECT non-positive amount")
                    else:
                        accounts[name]['balance'] += amount

            elif cmd == 'withdraw':
                name = parts[1]
                amount_str = parts[2]
                if name not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name}")
                else:
                    precision = Decimal('1').scaleb(-currencies[accounts[name]['code']])
                    amount = Decimal(amount_str).quantize(precision, rounding=ROUND_HALF_EVEN)
                    if amount <= 0:
                        rejections.append(f"line {line_num}: REJECT non-positive amount")
                    elif accounts[name]['balance'] - amount < -accounts[name]['limit']:
                        rejections.append(f"line {line_num}: REJECT insufficient funds {name}")
                    else:
                        accounts[name]['balance'] -= amount

            elif cmd == 'transfer':
                name_from = parts[1]
                name_to = parts[2]
                amount_str = parts[3]

                if name_from not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name_from}")
                elif name_to not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name_to}")
                else:
                    if accounts[name_from]['code'] != accounts[name_to]['code']:
                        rejections.append(f"line {line_num}: REJECT currency mismatch")
                    else:
                        precision = Decimal('1').scaleb(-currencies[accounts[name_from]['code']])
                        amount = Decimal(amount_str).quantize(precision, rounding=ROUND_HALF_EVEN)
                        if amount <= 0:
                            rejections.append(f"line {line_num}: REJECT non-positive amount")
                        elif accounts[name_from]['balance'] - amount < -accounts[name_from]['limit']:
                            rejections.append(f"line {line_num}: REJECT insufficient funds {name_from}")
                        else:
                            accounts[name_from]['balance'] -= amount
                            accounts[name_to]['balance'] += amount

            elif cmd == 'convert':
                name_from = parts[1]
                name_to = parts[2]
                amount_str = parts[3]
                rate_str = parts[4]

                if name_from not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name_from}")
                elif name_to not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name_to}")
                else:
                    precision_from = Decimal('1').scaleb(-currencies[accounts[name_from]['code']])
                    amount_from = Decimal(amount_str).quantize(precision_from, rounding=ROUND_HALF_EVEN)
                    if amount_from <= 0:
                        rejections.append(f"line {line_num}: REJECT non-positive amount")
                    elif accounts[name_from]['balance'] - amount_from < -accounts[name_from]['limit']:
                        rejections.append(f"line {line_num}: REJECT insufficient funds {name_from}")
                    else:
                        rate = Decimal(rate_str)
                        precision_to = Decimal('1').scaleb(-currencies[accounts[name_to]['code']])
                        amount_to = (amount_from * rate).quantize(precision_to, rounding=ROUND_HALF_EVEN)
                        accounts[name_from]['balance'] -= amount_from
                        accounts[name_to]['balance'] += amount_to

            elif cmd == 'interest':
                name = parts[1]
                rate_str = parts[2]
                if name not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name}")
                else:
                    rate = Decimal(rate_str)
                    precision = Decimal('1').scaleb(-currencies[accounts[name]['code']])
                    interest_amount = (accounts[name]['balance'] * rate).quantize(precision, rounding=ROUND_HALF_EVEN)
                    accounts[name]['balance'] += interest_amount

            elif cmd == 'split':
                name_from = parts[1]
                amount_str = parts[2]
                targets = []
                for t_str in parts[3:]:
                    t_name, w_val = t_str.split(':')
                    targets.append((t_name, int(w_val)))

                if name_from not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name_from}")
                else:
                    all_targets_exist = True
                    for t_name, _ in targets:
                        if t_name not in accounts:
                            rejections.append(f"line {line_num}: REJECT unknown account {t_name}")
                            all_targets_exist = False
                            break

                    if all_targets_exist:
                        mismatch = False
                        for t_name, _ in targets:
                            if accounts[t_name]['code'] != accounts[name_from]['code']:
                                mismatch = True
                                break
                        if mismatch:
                            rejections.append(f"line {line_num}: REJECT currency mismatch")
                        else:
                            precision = Decimal('1').scaleb(-currencies[accounts[name_from]['code']])
                            amount_from = Decimal(amount_str).quantize(precision, rounding=ROUND_HALF_EVEN)
                            if amount_from <= 0:
                                rejections.append(f"line {line_num}: REJECT non-positive amount")
                            elif accounts[name_from]['balance'] - amount_from < -accounts[name_from]['limit']:
                                rejections.append(f"line {line_num}: REJECT insufficient funds {name_from}")
                            else:
                                minor_units = currencies[accounts[name_from]['code']]
                                A = int(amount_from * (10**minor_units))
                                W = sum(w for _, w in targets)

                                shares = []
                                remainders = []
                                for _, w in targets:
                                    shares.append((A * w) // W)
                                    remainders.append((A * w) % W)

                                extra = A % W
                                indexed_remainders = []
                                for idx, rem in enumerate(remainders):
                                    indexed_remainders.append((rem, -idx, idx))

                                indexed_remainders.sort(key=lambda x: (x[0], x[1]), reverse=True)

                                for i in range(extra):
                                    _, _, original_idx = indexed_remainders[i]
                                    shares[original_idx] += 1

                                accounts[name_from]['balance'] -= amount_from
                                for i, (t_name, _) in enumerate(targets):
                                    share_decimal = Decimal(shares[i]) / Decimal(10**minor_units)
                                    accounts[t_name]['balance'] += share_decimal

        except (IndexError, ValueError):
            pass

    # Output rejections
    for rej in rejections:
        print(rej)
    print()

    # Output accounts
    sorted_account_names = sorted(accounts.keys())
    for name in sorted_account_names:
        acc = accounts[name]
        balance = acc['balance']
        if balance == 0:
            balance = Decimal('0')

        minor_units = currencies[acc['code']]
        precision = Decimal('1').scaleb(-minor_units)
        rounded_balance = balance.quantize(precision, rounding=ROUND_HALF_EVEN)

        s = "{:,.{}f}".format(rounded_balance, minor_units)
        print(f"{name} {acc['code']} {s}")

    print()

    # Output totals
    total_currencies = {} # code -> [sum_balance, count]
    for acc in accounts.values():
        code = acc['code']
        if code not in total_currencies:
            total_currencies[code] = [Decimal('0'), 0]
        total_currencies[code][0] += acc['balance']
        total_currencies[code][1] += 1

    for code in sorted(total_currencies.keys()):
        sum_balance, count = total_currencies[code]
        minor_units = currencies[code]
        precision = Decimal('1').scaleb(-minor_units)
        rounded_sum = sum_balance.quantize(precision, rounding=ROUND_HALF_EVEN)
        if rounded_sum == 0:
            rounded_sum = Decimal('0')

        s = "{:,.{}f}".format(rounded_sum, minor_units)
        print(f"total {code} {s} ({count} accounts)")

if __name__ == "__main__":
    solve()

