import java.io.*;
import java.nio.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".bmp"));
        if (files == null) return;
        Arrays.sort(files, Comparator.comparing(File::getName));

        for (File file : files) {
            processFile(file);
        }
    }

    private static void processFile(File file) throws IOException {
        byte[] data = Files.readAllBytes(file.toPath());
        ByteBuffer buffer = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);

        // File Header
        byte[] magic = new byte[2];
        buffer.get(magic);
        if (!(magic[0] == 'B' && magic[1] == 'M')) return;

        int fileSize = buffer.getInt();
        buffer.getShort(); // reserved
        buffer.getShort(); // reserved
        long bfOffBits = buffer.getInt() & 0xFFFFFFFFL;

        // DIB Header
        int dibSize = buffer.getInt();
        int width = buffer.getInt();
        int height = buffer.getInt();
        int planes = buffer.getShort() & 0xFFFF;
        int bpp = buffer.getShort() & 0xFFFF;
        int compression = buffer.getInt();
        int imageSize = buffer.getInt() & 0xFFFFFFFFL;
        int xPixelsPerMetre = buffer.getInt();
        int yPixelsPerMetre = buffer.getInt();
        int coloursUsed = buffer.getInt();
        int importantColours = buffer.getInt();

        if (compression != 0 && compression != 3) {
            System.out.println("== " + file.getName());
            System.out.println("error: unsupported compression " + compression);
            return;
        }

        int absHeight = Math.abs(height);
        boolean isBottomUp = height > 0;
        int rowSize = ((width * bpp + 7) / 8 + 3) & ~3;

        int[][] colorTable = null;
        if (bpp < 24) {
            int numEntries = (coloursUsed == 0) ? (1 << bpp) : coloursUsed;
            colorTable = new int[numEntries][3];
            int tableStart = 14 + dibSize;
            for (int i = 0; i < numEntries; i++) {
                colorTable[i][0] = buffer.get(tableStart + i * 4) & 0xFF; // Blue
                colorTable[i][1] = buffer.get(tableStart + i * 4 + 1) & 0xFF; // Green
                colorTable[i][2] = buffer.get(tableStart + i * 4 + 2) & 0xFF; // Red
            }
        }

        boolean[][] isInk = new boolean[absHeight][width];
        for (int i = 0; i < absHeight; i++) {
            int currentY = isBottomUp ? (absHeight - 1 - i) : i;
            int startPos = (int) bfOffBits + i * rowSize;

            for (int x = 0; x < width; x++) {
                int r, g, b;
                if (bpp == 1) {
                    int byteIdx = x / 8;
                    int bitIdx = 7 - (x % 8);
                    int index = (buffer.get(startPos + byteIdx) >> bitIdx) & 1;
                    b = colorTable[index][0];
                    g = colorTable[index][1];
                    r = colorTable[index][2];
                } else if (bpp == 4) {
                    int byteIdx = x / 2;
                    int bitIdx = 15 - (x % 2) * 4;
                    int index = (buffer.get(startPos + byteIdx) >> bitIdx) & 0xF;
                    b = colorTable[index][0];
                    g = colorTable[index][1];
                    r = colorTable[index][2];
                } else if (bpp == 8) {
                    int index = buffer.get(startPos + x) & 0xFF;
                    b = colorTable[index][0];
                    g = colorTable[index][1];
                    r = colorTable[index][2];
                } else if (bpp == 24) {
                    b = buffer.get(startPos + x * 3) & 0xFF;
                    g = buffer.get(startPos + x * 3 + 1) & 0xFF;
                    r = buffer.get(startPos + x * 3 + 2) & 0xFF;
                } else if (bpp == 32) {
                    if (compression == 0) {
                        b = buffer.get(startPos + x * 4) & 0xFF;
                        g = buffer.get(startPos + x * 4 + 1) & 0xFF;
                        r = buffer.get(startPos + x * 4 + 2) & 0xFF;
                    } else {
                        long redMask = buffer.getInt(14 + 40) & 0xFFFFFFFFL;
                        long greenMask = buffer.getInt(14 + 44) & 0xFFFFFFFFL;
                        long blueMask = buffer.getInt(14 + 48) & 0xFFFFFFFFL;
                        long pixel = buffer.getInt((int)bfOffBits + x * 4) & 0xFFFFFFFFL;

                        r = getChannel(pixel, redMask);
                        g = getChannel(pixel, greenMask);
                        b = getChannel(pixel, blueMask);
                    }
                }
                isInk[currentY][x] = (299 * r + 587 * g + 114 * b) / 1000 < 128;
            }
        }

        int inkCount = 0;
        for (int y = 0; y < absHeight; y++) {
            for (int x = 0; x < width; x++) {
                if (isInk[y][x]) inkCount++;
            }
        }

        System.out.println("== " + file.getName());
        System.out.println("size " + width + "x" + absHeight + " bpp " + bpp + " header " + dibSize + " " + (isBottomUp ? "bottom-up" : "top-down") + " ink " + inkCount);

        boolean[][] visited = new boolean[absHeight][width];
        List<Component> components = new ArrayList<>();
        for (int y = 0; y < absHeight; y++) {
            for (int x = 0; x < width; x++) {
                if (isInk[y][x] && !visited[y][x]) {
                    List<int[]> pixels = new ArrayList<>();
                    Queue<int[]> q = new LinkedList<>();
                    q.add(new int[]{x, y});
                    visited[y][x] = true;
                    while (!q.isEmpty()) {
                        int[] curr = q.poll();
                        pixels.add(curr);
                        for (int dy = -1; dy <= 1; dy++) {
                            for (int dx = -1; dx <= 1; dx++) {
                                if (dx == 0 && dy == 0) continue;
                                int nx = curr[0] + dx;
                                int ny = curr[1] + dy;
                                if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight && isInk[ny][nx] && !visited[ny][nx]) {
                                    visited[ny][nx] = true;
                                    q.add(new int[]{nx, ny});
                                }
                            }
                        }
                    }
                    int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
                    for (int[] p : pixels) {
                        minX = Math.min(minX, p[0]);
                        minY = Math.min(minY, p[1]);
                        maxX = Math.max(maxX, p[0]);
                        maxY = Math.max(maxY, p[1]);
                    }
                    components.add(new Component(curr[0], curr[1], minX, minY, maxX, maxY, pixels.size()));
                }
            }
        }

        System.out.println("components " + components.size());
        for (Component c : components) {
            System.out.println(c.firstX + "," + c.firstY + " bbox " + c.minX + "," + c.minY + "-" + c.maxX + "," + c.maxY + " pixels " + c.count);
        }
    }

    private static int getChannel(long pixel, long mask) {
        int s = Long.numberOfTrailingZeros(mask);
        int n = Long.bitCount(mask);
        long m = (1L << n) - 1;
        long v = (pixel & mask) >> s;
        return (int) ((v * 255 + m / 2) / m);
    }

    static class Component {
        int firstX, firstY, minX, minY, maxX, maxY, count;
        Component(int fx, int fy, int minx, int miny, int maxx, int maxy, int count) {
            this.firstX = fx; this.firstY = fy;
            this.minX = minx; this.minY = miny;
            this.maxX = maxx; this.maxY = maxy;
            this.count = count;
        }
    }
}

