use std::env;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, Copy)]
struct Color {
    r: u8,
    g: u8,
    b: u8,
}

struct Component {
    first_pixel: (i32, i32),
    bbox: (i32, i32, i32, i32),
    count: usize,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return;
    }
    let dir_path = &args[1];
    let paths = fs::read_dir(dir_path).expect("Could not read directory");

    let mut bmp_files: Vec<_> = paths
        .filter_map(|entry| {
            let path = entry.ok()?.path();
            if path.is_file() && path.extension().and_then(|s| s.to_str()) == Some("bmp") {
                Some(path)
            } else {
                None
            }
        })
        .collect();

    bmp_files.sort_by(|a, b| a.file_name().cmp(&b.file_name()));

    for path in bmp_files {
        let file_name = path.file_name().unwrap().to_string_lossy().into_owned();
        let data = fs::read(&path).expect("Could not read file");
        if data.len() < 14 {
            println!("== {}", file_name);
            println!("error: file too small");
            continue;
        }

        let bf_off_bits = u32::from_le_bytes(data[10..14].try_into().unwrap());
        let header_size = u32::from_le_bytes(data[14..18].try_into().unwrap()) as usize;

        if data.len() < 14 + header_size {
            println!("== {}", file_name);
            println!("error: file too small for header");
            continue;
        }

        let width = i32::from_le_bytes(data[18..22].try_into().unwrap());
        let height = i32::from_le_bytes(data[22..26].try_into().unwrap());
        let _planes = u16::from_le_bytes(data[26..28].try_into().unwrap());
        let bpp = u16::from_le_bytes(data[28..30].try_into().unwrap());
        let compression = u32::from_le_bytes(data[30..34].try_into().unwrap());
        let _image_size = u32::from_le_bytes(data[34..38].try_into().unwrap());
        let _x_pixels_per_m = i32::from_le_bytes(data[38..42].try_into().unwrap());
        let _y_pixels_per_m = i32::from_le_bytes(data[42..46].try_into().unwrap());
        let colors_used = u32::from_le_bytes(data[46..50].try_into().unwrap());
        let _important_colors = u32::from_le_bytes(data[50..54].try_into().unwrap());

        if compression != 0 && compression != 3 {
            println!("== {}", file_name);
            println!("error: unsupported compression {}", compression);
            continue;
        }

        let abs_height = height.abs() as usize;
        let is_bottom_up = height > 0;
        let bytes_per_row = ((width as usize * (bpp as usize + 7) / 8) + 3) & !3;

        let mut pixels = vec![vec![Color { r: 0, g: 0, b: 0 }; width as usize]; abs_height];

        let mut color_table = Vec::new();
        if bpp <= 8 {
            let num_colors = if colors_used > 0 { colors_used as usize } else { (1 << bpp as u32) as usize };
            let color_table_start = 14 + header_size;
            for i in 0..num_colors {
                let start = color_table_start + i * 4;
                if start + 4 <= data.len() {
                    color_table.push(Color {
                        b: data[start],
                        g: data[start + 1],
                        r: data[start + 2],
                    });
                }
            }
        }

        if bpp <= 8 {
            for i in 0..abs_height {
                let y = if is_bottom_up { abs_height - 1 - i } else { i };
                let start = bf_off_bits as usize + i * bytes_per_row;
                let row_data = &data[start..start + bytes_per_row];
                for x in 0..width as usize {
                    let index = match bpp {
                        1 => (row_data[x / 8] >> (7 - (x % 8))) & 1,
                        4 => (row_data[x / 2] >> (4 * (1 - (x % 2)))) & 0xF,
                        8 => row_data[x] & 0xFF,
                        _ => 0,
                    };
                    pixels[y][x] = color_table[index as usize];
                }
            }
        } else if bpp == 24 {
            for i in 0..abs_height {
                let y = if is_bottom_up { abs_height - 1 - i } else { i };
                let start = bf_off_bits as usize + i * bytes_per_row;
                let row_data = &data[start..start + bytes_per_row];
                for x in 0..width as usize {
                    pixels[y][x] = Color {
                        b: row_data[x * 3],
                        g: row_data[x * 3 + 1],
                        r: row_data[x * 3 + 2],
                    };
                }
            }
        } else if bpp == 32 {
            let (r_mask, g_mask, b_mask) = if compression == 0 {
                (0xFF0000, 0x00FF00, 0x0000FF)
            } else {
                let m_start = 14 + 40;
                (
                    u32::from_le_bytes(data[m_start..m_start + 4].try_into().unwrap()),
                    u32::from_le_bytes(data[m_start + 4..m_start + 8].try_into().unwrap()),
                    u32::from_le_bytes(data[m_start + 8..m_start + 12].try_into().unwrap()),
                )
            };

            for i in 0..abs_height {
                let y = if is_bottom_up { abs_height - 1 - i } else { i };
                let start = bf_off_bits as usize + i * bytes_per_row;
                let row_data = &data[start..start + bytes_per_row];
                for x in 0..width as usize {
                    let p = u32::from_le_bytes(row_data[x * 4..x * 4 + 4].try_into().unwrap());
                    let (r, g, b) = if compression == 0 {
                        (row_data[x * 4 + 2], row_data[x * 4 + 1], row_data[x * 4])
                    } else {
                        let extract = |pixel: u32, mask: u32| -> u8 {
                            let s = mask.trailing_zeros();
                            let v = (pixel & mask) >> s;
                            let n = mask.count_ones();
                            let m = (1 << n) - 1;
                            ((v * 255 + m / 2) / m) as u8
                        };
                        (extract(p, r_mask), extract(p, g_mask), extract(p, b_mask))
                    };
                    pixels[y][x] = Color { r, g, b };
                }
            }
        }

        let mut is_ink = vec![vec![false; width as usize]; abs_height];
        let mut ink_count = 0;
        for y in 0..abs_height {
            for x in 0..width as usize {
                let p = pixels[y][x];
                if (299 * p.r as i32 + 587 * p.g as i32 + 114 * p.b as i32) / 1000 < 128 {
                    is_ink[y][x] = true;
                    ink_count += 1;
                }
            }
        }

        let mut visited = vec![vec![false; width as usize]; abs_height];
        let mut components = Vec::new();

        for y in 0..abs_height {
            for x in 0..width as usize {
                if is_ink[y][x] && !visited[y][x] {
                    let mut component_pixels = Vec::new();
                    let mut q = std::collections::VecDeque::new();
                    q.push_back((x as i32, y as i32));
                    visited[y][x] = true;

                    while let Some((cx, cy)) = q.pop_front() {
                        component_pixels.push((cx, cy));
                        for dx in -1..=1 {
                            for dy in -1..=1 {
                                if dx == 0 && dy == 0 { continue; }
                                let nx = cx + dx;
                                let ny = cy + dy;
                                if nx >= 0 && nx < width as i32 && ny >= 0 && ny < abs_height as i32 {
                                    let nix = nx as usize;
                                    let niy = ny as usize;
                                    if is_ink[niy][nix] && !visited[niy][nix] {
                                        visited[niy][nix] = true;
                                        q.push_back((nx, ny));
                                    }
                                }
                            }
                        }
                    }

                    let mut min_x = i32::MAX;
                    let mut max_x = i32::MIN;
                    let mut min_y = i32::MAX;
                    let mut max_y = i32::MIN;
                    let mut first_pixel = (0, 0);

                    for &(px, py) in &component_pixels {
                        if px < min_x { min_x = px; }
                        if px > max_x { max_x = px; }
                        if py < min_y { min_y = py; }
                        if py > max_y { max_y = py; }
                        if py < first_pixel.1 || (py == first_pixel.1 && px < first_pixel.0) {
                            first_pixel = (px, py);
                        }
                    }

                    components.push(Component {
                        first_pixel,
                        bbox: (min_x, min_y, max_x, max_y),
                        count: component_pixels.len(),
                    });
                }
            }
        }

        components.sort_by(|a, b| {
            if a.first_pixel.1 != b.first_pixel.1 {
                a.first_pixel.1.cmp(&b.first_pixel.1)
            } else {
                a.first_pixel.0.cmp(&b.first_pixel.0)
            }
        });

        println!("== {}", file_name);
        println!(
            "size {}x{} bpp {} header {} {} ink {}",
            width,
            abs_height,
            bpp,
            header_size,
            if is_bottom_up { "bottom-up" } else { "top-down" },
            ink_count
        );
        println!("components {}", components.len());
        for c in components {
            println!(
                "{},{} bbox {},{}-{},{} pixels {}",
                c.first_pixel.0,
                c.first_pixel.1,
                c.bbox.0,
                c.bbox.1,
                c.bbox.2,
                c.bbox.3,
                c.count
            );
        }
    }
}

