                Some(path)
            } else {
                None
            }
        })
        .collect();

    bmp_files.sort_by(|a, b| a.file_name().cmp(&b.file_name()));

    for path in bmp_files {
        let file_name = path.file_name().unwrap().to_string_lossy().into_owned();
        let data = fs::read(&path).expect("Could not read file");
        if data.len() < 14 {
            println!("== {}", file_name);
            continue;
        }

        let bf_off_bits = u32::from_le_bytes(data[10..14].try_into().unwrap()) as usize;
