import Foundation
import Darwin

// --- DNS Data Structures ---

struct DNSHeader {
    var id: UInt16
    var flags: UInt16
    var qdCount: UInt16
    var anCount: UInt16
    var nsCount: UInt16
    var arCount: UInt16

    static func from(data: Data) -> DNSHeader? {
        guard data.count >= 12 else { return nil }
        let id = data.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let flags = data.subdata(in: 2..<4).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let qdCount = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let anCount = data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let nsCount = data.subdata(in: 8..<10).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let arCount = data.subdata(in: 10..<12).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        return DNSHeader(id: id, flags: flags, qdCount: qdCount, anCount: anCount, nsCount: nsCount, arCount: arCount)
    }
}

// --- Helper Functions ---

func get_uint16(data: Data, offset: Int) -> UInt16 {
    let val = data.subdata(in: offset..<(offset+2)).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
    return val
}

func get_uint32(data: Data, offset: Int) -> UInt32 {
    let val = data.subdata(in: offset..<(offset+4)).withUnsafeBytes { $0.load(as: UInt32.self).bigEndian }
    return val
}

func parseName_nested(data: Data, startOffset: Int) -> (String, Int) {
    var nameParts: [String] = []
    var currentOffset = startOffset
    while true {
        let byte = data[currentOffset]
        if (byte & 0xC0) == 0x00 {
            let len = Int(byte)
            currentOffset += 1
            if len == 0 { break }
            let labelData = data.subdata(in: currentOffset..<(currentOffset+len))
            nameParts.append(String(data: labelData, encoding: .utf8) ?? "")
            currentOffset += len
        } else if (byte & 0xC0) == 0xC0 {
            let ptr = (Int(byte & 0x3F) << 8) | Int(data[currentOffset+1])
            currentOffset += 2
            let (subName, _) = parseName_nested(data: data, startOffset: ptr)
            nameParts.append(subName)
            break
        } else {
            break
        }
    }
    let joined = nameParts.joined(separator: ".")
    return (joined.isEmpty ? "." : joined, currentOffset)
}

func parseName_final(data: Data, offset: inout Int) -> String {
    var nameParts: [String] = []
    var currentOffset = offset
    while true {
        let byte = data[currentOffset]
        if (byte & 0xC0) == 0x00 {
            let len = Int(byte)
            currentOffset += 1
            if len == 0 { break }
            let labelData = data.subdata(in: currentOffset..<(currentOffset+len))
            nameParts.append(String(data: labelData, encoding: .utf8) ?? "")
            currentOffset += len
        } else if (byte & 0xC0) == 0xC0 {
            let ptr = (Int(byte & 0x3F) << 8) | Int(data[currentOffset+1])
            currentOffset += 2
            let (subName, _) = parseName_nested(data: data, startOffset: ptr)
            nameParts.append(subName)
            break
        } else {
            break
        }
    }
    offset = currentOffset
    let joined = nameParts.joined(separator: ".")
    return joined.isEmpty ? "." : joined
}

// --- DNS Query Construction ---

func encodeName(name: String) -> Data {
    var data = Data()
    let labels = name.split(separator: ".").map { String($0) }
    for label in labels {
        let labelData = label.data(using: .utf8)!
        data.append(UInt8(labelData.count))
        data.append(labelData)
    }
    data.append(0)
    return data
}

// --- Main Logic ---

func solve() {
    let args = CommandLine.arguments
    guard args.count == 3 else { return }
    let directory = args[1]
    let port = UInt16(args[2])!

    let queryFilePath = (directory as NSString).appendingPathComponent("queries.txt")
    guard let content = try? String(contentsOfFile: queryFilePath) else { return }

    let lines = content.components(separatedBy: .newlines)

    for line in lines {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty { continue }
        let parts = trimmed.split(separator: " ")
        if parts.count < 2 { continue }

        let rawName = String(parts[0])
        var cleanName = rawName
        if cleanName.hasSuffix(".") { cleanName.removeLast() }
        let nameParts = cleanName.split(separator: ".").map { String($0) }
        let finalName = nameParts.joined(separator: ".")

        let typeStr = String(parts[1])
        var typeCode: UInt16 = 0
        switch typeStr {
        case "A": typeCode = 1
        case "CNAME": typeCode = 5
        case "MX": typeCode = 15
        case "TXT": typeCode = 16
        case "AAAA": typeCode = 28
        default: break
        }

        let queryData = constructQuery(name: finalName, type: typeCode)
        var responseData = fetchUDP(queryData, port: port)

        if let header = DNSHeader.from(data: responseData), (header.flags & 0x0100) != 0, (header.flags & 0x0400) != 0 {
            responseData = fetchTCP(queryData, port: port)
        }

        if let header = DNSHeader.from(data: responseData) {
            var offset = 12
            for _ in 0..<header.qdCount {
                _ = parseName_final(data: responseData, offset: &offset)
                offset += 4
            }

            let rcode = header.flags & 0x000F
            let rcodeStr = (rcode < 6) ? "\(rcode)" : "RCODE\(rcode)"
            print("\(finalName.lowercased()) \(typeStr) \(rcodeStr)")

            for _ in 0..<header.anCount {
                let owner = parseName_final(data: responseData, offset: &offset).lowercased()
                let ttl = get_uint32(data: responseData, offset: offset)
                offset += 4
                let type = get_uint16(data: responseData, offset: offset)
                offset += 2
                let rdLength = Int(get_uint16(data: responseData, offset: offset))
                offset += 2

                let rdata = responseData.subdata(in: offset..<(offset+rdLength))
                let dataStr = parseRData(data: rdata, type: type)

                print("  \(owner) \(ttl) \(type) \(dataStr)")
                offset += rdLength
            }
        }
    }
}

func constructQuery(name: String, type: UInt16) -> Data {
    var data = Data()
    let id = UInt16.random(in: 0...65535)
    data.append(contentsOf: withUnsafeBytes(of: id.bigEndian) { Array($0) })
    data.append(contentsOf: withUnsafeBytes(of: UInt16(0x0100).bigEndian) { Array($0) })
    data.append(contentsOf: withUnsafeBytes(of: UInt16(1).bigEndian) { Array($0) })
    data.append(contentsOf: withUnsafeBytes(of: UInt16(0).bigEndian) { Array($0) })
    data.append(contentsOf: withUnsafeBytes(of: UInt16(0).bigEndian) { Array($0) })
    data.append(contentsOf: withUnsafeBytes(of: UInt16(0).bigEndian) { Array($0) })

    data.append(encodeName(name: name))
    data.append(contentsOf: withUnsafeBytes(of: type.bigEndian) { Array($0) })
    data.append(contentsOf: withUnsafeBytes(of: UInt16(1).bigEndian) { Array($0) })

    return data
}

func fetchUDP(_ query: Data, port: UInt16) -> Data {
    let sock = socket(AF_INET, SOCK_DGRAM, 0)
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")

    query.withUnsafeBytes { (ptr: UnsafeRawBufferPointer) in
        sendto(sock, ptr.baseAddress, query.count, 0, &addr, MemoryLayout<sockaddr_in>.size)
    }

    var buffer = [UInt8](repeating: 0, count: 65535)
    while true {
        let received = recvfrom(sock, &buffer, buffer.count, 0, nil, nil)
        if received > 0 {
            let data = Data(buffer[0..<Int(received)])
            if let header = DNSHeader.from(data: data) {
                let id = header.id
                let qr = (header.flags & 0x8000) != 0
                if qr && header.id == id {
                    return data
                }
            }
        }
    }
}

func fetchTCP(_ query: Data, port: UInt16) -> Data {
    let sock = socket(AF_INET, SOCK_STREAM, 0)
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")

    connect(sock, &addr, MemoryLayout<sockaddr_in>.size)

    let len = UInt16(query.count).bigEndian
    var lenData = Data(withUnsafeBytes(of: len) { Data($0) })
    send(sock, lenData.bytes, lenData.count, 0)
    send(sock, query.bytes, query.count, 0)

    var lenBuffer = [UInt8](repeating: 0, count: 2)
    _ = recv(sock, &lenBuffer, 2, 0)
    let responseLen = UInt16(bigEndian: lenBuffer.withUnsafeBytes { $0.load(as: UInt16.self) })

    var responseBuffer = [UInt8](repeating: 0, count: Int(responseLen))
    var received = 0
    while received < Int(responseLen) {
        let n = recv(sock, &responseBuffer[received], Int(responseLen) - received, 0)
        if n > 0 { received += n }
    }

    return Data(responseBuffer)
}

extension Data {
    var bytes: UnsafeRawBufferPointer {
        return self.withUnsafeBytes { $0 }
    }
}

func parseRData(data: Data, type: UInt16) -> String {
    switch type {
    case 1:
        return data.map { String($0) }.joined(separator: ".")
    case 5:
        var offset = 0
        let name = parseName_final(data: data, offset: &offset).lowercased()
        return name
    case 15:
        let pref = get_uint16(data: data, offset: 0)
        var offset = 2
        let exchange = parseName_final(data: data, offset: &offset).lowercased()
        return "\(pref) \(exchange)"
    case 16:
        var results: [String] = []
        var offset = 0
        while offset < data.count {
            let len = Int(data[offset])
            offset += 1
            let strData = data.subdata(in: offset..<(offset+len))
            var str = ""
            for byte in strData {
                if byte == 34 { str += "\\\"" }
                else if byte == 92 { str += "\\\\" }
                else if byte >= 32 && byte <= 126 { str += String(UnicodeScalar(byte)) }
                else { str += "\\\(Int(byte))" }
            }
            results.append("\"\(str)\"")
            offset += len
        }
        return results.joined(separator: " ")
    case 28:
        let words = (0..<8).map { i in
            (UInt16(data[i*2]) << 8) | UInt16(data[i*2+1])
        }
        var bestStart = -1
        var bestLen = 0
        var currentStart = -1
        var currentLen = 0
        for j in 0..<words.count {
            if words[j] == 0 {
                if currentStart == -1 { currentStart = j; currentLen = 1 }
                else { currentLen += 1 }
            } else {
                if currentLen >= 2 && currentLen > bestLen {
                    bestLen = currentLen
                    bestStart = currentStart
                }
                currentStart = -1; currentLen = 0
            }
        }
        if currentLen >= 2 && currentLen > bestLen {
            bestLen = currentLen
            bestStart = currentStart
        }
        var result = ""
        var k = 0
        while k < words.count {
            if k == bestStart {
                result += "::"
                k += bestLen
            } else {
                let w = words[k]
                if result.isEmpty { result += String(w, radix: 16) }
                else { result += ":" + String(w, radix: 16) }
                k += 1
            }
        }
        return result
    default:
        let rdataStr = data.map { String(format: "%02x", $0) }.joined()
        return "TYPE\(type) # \(data.count) \(rdataStr)"
    }
}

