import Foundation
import Darwin

// --- DNS Data Structures ---

struct DNSHeader {
    var id: UInt16
    var flags: UInt16
    var qdCount: UInt16
    var anCount: UInt16
    var nsCount: UInt16
    var arCount: UInt16

    static func from(data: Data) -> DNSHeader? {
        guard data.count >= 12 else { return nil }
        let id = data.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let flags = data.subdata(in: 2..<4).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let qdCount = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let anCount = data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let nsCount = data.subdata(in: 8..<10).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        let arCount = data.subdata(in: 10..<12).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
        return DNSHeader(id: id, flags: flags, qdCount: qdCount, anCount: anCount, nsCount: nsCount, arCount: arCount)
    }
}

// --- Helper Functions ---

func get_uint16(data: Data, offset: Int) -> UInt16 {
    let val = data.subdata(in: offset..<(offset+2)).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
    return val
}

func get_uint32(data: Data, offset: Int) -> UInt32 {
    let val = data.subdata(in: offset..<(offset+4)).withUnsafeBytes { $0.load(as: UInt32.self).bigEndian }
    return val
}

func parseName(data: Data, at offset: Int) -> (String, Int) {
    var parts: [String] = []
    var current = offset

    while true {
        let byte = data[current]
        if (byte & 0xC0) == 0x00 {
            let len = Int(byte)
            current += 1
            if len == 0 { break }
            let label = data.subdata(in: current..<(current + len))
            if let str = String(data: label, encoding: .utf8) {
                parts.append(str.lowercased())
            }
            current += len
        } else if (byte & 0xC0) == 0xC0 {
            let ptr = Int((byte & 0x3F) << 8) | Int(data[current + 1])
            current += 2
            let (subName, _) = parseName(data: data, at: ptr)
            parts.append(subName)
            break
        } else {
            break
        }
    }

    let result = parts.isEmpty ? "." : parts.joined(separator: ".")
    return (result, current)
}

func encodeName(name: String) -> Data {
    var data = Data()
    let labels = name.split(separator: ".").map { String($0) }
    for label in labels {
        let labelData = label.data(using: .utf8)!
        data.append(UInt8(labelData.count))
        data.append(labelData)
    }
    data.append(0)
    return data
}

// --- Networking ---

func fetchUDP(_ query: Data, port: UInt16) -> Data {
    let sock = socket(AF_INET, SOCK_DGRAM, 0)
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")

    query.withUnsafeBytes { (ptr: UnsafeRawBufferPointer) in
        sendto(sock, ptr.baseAddress, query.count, 0, &addr, socklen_t(MemoryLayout<sockaddr_in>.size))
    }

    var buffer = [UInt8](repeating: 0, count: 65535)
    while true {
        let received = recvfrom(sock, &buffer, buffer.count, 0, nil, nil)
        if received > 0 {
            let data = Data(buffer[0..<Int(received)])
            if let header = DNSHeader.from(data: data) {
                let qr = (header.flags & 0x8000) != 0
                if qr && header.id == (query.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }) {
                    return data
                }
            }
        }
    }
}

func fetchTCP(_ query: Data, port: UInt16) -> Data {
    let sock = socket(AF_INET, SOCK_STREAM, 0)
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")

    withUnsafePointer(to: &addr) { ptr in
        connect(sock, ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { $0 }, socklen_t(MemoryLayout<sockaddr_in>.size))
    }

    let len = UInt16(query.count).bigEndian
    var lenData = Data(withUnsafeBytes(of: len) { Data($0) })
    lenData.withUnsafeBytes { send(sock, $0.baseAddress, lenData.count, 0) }
    query.withUnsafeBytes { send(sock, $0.baseAddress, query.count, 0) }

    var lenBuffer = [UInt8](repeating: 0, count: 2)
    _ = recv(sock, &lenBuffer, 2, 0)
    let responseLen = Int(UInt16(bigEndian: lenBuffer.withUnsafeBytes { $0.load(as: UInt16.self) }))

    var responseBuffer = [UInt8](repeating: 0, count: responseLen)
    var received = 0
    while received < responseLen {
        let n = recv(sock, &responseBuffer[received], responseLen - received, 0)
        if n > 0 { received += n }
    }

    return Data(responseBuffer)
}

// --- RData Parsing ---

func formatAAAA(data: Data) -> String {
    var groups: [UInt16] = []
    for i in 0..<8 {
        let val = (UInt16(data[i*2]) << 8) | UInt16(data[i*2+1])
        groups.append(val)
    }

    var zero_indices: [Int] = []
    for i in 0..<8 {
        if groups[i] == 0 { zero_indices.append(i) }
    }

    var runs: [(start: Int, length: Int)] = []
    if !zero_indices.isEmpty {
        var start = zero_indices[0]
        var count = 1
        for i in 1..<zero_indices.count {
            if zero_indices[i] == zero_indices[i-1] + 1 {
                count += 1
            } else {
                if count >= 2 { runs.append((start, count)) }
                start = zero_indices[i]
                count = 1
            }
        }
        if count >= 2 { runs.append((start, count)) }
    }

    var bestRun: (start: Int, length: Int)? = nil
    for run in runs {
        if bestRun == nil || run.length > bestRun!.length {
            bestRun = run
        }
    }

    if let best = bestRun, best.length == 8 { return "::" }

    var parts: [String] = []
    for i in 0..<8 {
        if let best = bestRun, i >= best.start && i < best.start + best.length {
            parts.append("")
        } else if groups[i] == 0 {
            parts.append("0")
        } else {
            parts.append(String(groups[i], radix: 16))
        }
    }

    var joined = parts.joined(separator: ":")
    if let best = bestRun {
        if best.start == 0 {
            joined = "::" + joined.dropFirst(1)
        } else if best.start + best.length == 8 {
            joined = joined.dropLast(1) + "::"
        }
    }
    return joined
}

func parseRData(data: Data, type: UInt16) -> String {
    switch type {
    case 1:
        return data.map { String($0) }.joined(separator: ".")
    case 5:
        var offset = 0
        let (name, _) = parseName(data: data, at: offset)
        return name
    case 15:
        let pref = get_uint16(data: data, offset: 0)
        var offset = 2
        let (exchange, _) = parseName(data: data, at: offset)
        return "\(pref) \(exchange)"
    case 16:
        var results: [String] = []
        var offset = 0
        while offset < data.count {
            let len = Int(data[offset])
            offset += 1
            let strData = data.subdata(in: offset..<(offset+len))
            var str = ""
            for byte in strData {
                if byte == 34 { str += "\\\"" }
                else if byte == 92 { str += "\\\\" }
                else if byte >= 32 && byte <= 126 { str += String(UnicodeScalar(byte)) }
                else { str += "\\\(Int(byte))" }
            }
            results.append("\"\(str)\"")
            offset += len
        }
        return results.joined(separator: " ")
    case 28:
        return formatAAAA(data: data)
    default:
        let rdataStr = data.map { String(format: "%02x", $0) }.joined()
        return "TYPE\(type) # \(data.count) \(rdataStr)"
    }
}

// --- Main Logic ---

func solve() {
    let args = CommandLine.arguments
    guard args.count == 3 else { return }
    let directory = args[1]
    let port = UInt16(args[2])!

    let queryFilePath = (directory as NSString).appendingPathComponent("queries.txt")
    guard let content = try? String(contentsOfFile: queryFilePath, encoding: .utf8) else { return }

    let lines = content.components(separatedBy: .newlines)

    for line in lines {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty { continue }
        let parts = trimmed.split(separator: " ")
        if parts.count < 2 { continue }

        let rawName = String(parts[0])
        var cleanName = rawName
        if cleanName.hasSuffix(".") { cleanName.removeLast() }
        let nameParts = cleanName.split(separator: ".").map { String($0) }
        let finalName = nameParts.joined(separator: ".")

        let typeStr = String(parts[1])
        var typeCode: UInt16 = 0
        switch typeStr {
        case "A": typeCode = 1
        case "CNAME": typeCode = 5
        case "MX": typeCode = 15
        case "TXT": typeCode = 16
        case "AAAA": typeCode = 28
        default: break
        }

        var queryData = Data()
        let id = UInt16.random(in: 0...65535)
        queryData.append(contentsOf: withUnsafeBytes(of: id.bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(0x0100).bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(1).bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(0).bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(0).bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(0).bigEndian) { Array($0) })
        queryData.append(encodeName(name: finalName))
        queryData.append(contentsOf: withUnsafeBytes(of: typeCode.bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(1).bigEndian) { Array($0) })

        var responseData = fetchUDP(queryData, port: port)

        if let header = DNSHeader.from(data: responseData), (header.flags & 0x0100) != 0, (header.flags & 0x0400) != 0 {
            responseData = fetchTCP(queryData, port: port)
        }

        if let header = DNSHeader.from(data: responseData) {
            var offset = 12
            for _ in 0..<header.qdCount {
                let (_, nextOffset) = parseName(data: responseData, at: offset)
                offset = nextOffset
                offset += 4
            }

            let rcode = header.flags & 0x000F
            let rcodeStr = (rcode < 6) ? "\(rcode)" : "RCODE\(rcode)"
            print("\(finalName.lowercased()) \(typeStr) \(rcodeStr)")

            for _ in 0..<header.anCount {
                let (owner, nextOwnerOffset) = parseName(data: responseData, at: offset)
                offset = nextOwnerOffset
                let ttl = get_uint32(data: responseData, offset: offset)
                offset += 4
                let type = get_uint16(data: responseData, offset: offset)
                offset += 2
                let rdLength = Int(get_uint16(data: responseData, offset: offset))
                offset += 2

                let rdata = responseData.subdata(in: offset..<(offset+rdLength))
                let dataStr = parseRData(data: rdata, type: type)

                print("  \(owner.lowercased()) \(ttl) \(type) \(dataStr)")
                offset += rdLength
            }
        }
    }
}

