import Foundation

// BMP Constants and Structs
struct FileHeader {
    let magic: UInt16
    let fileSize: UInt32
    let reserved1: UInt16
    let reserved2: UInt16
    let bfOffBits: UInt32
}

struct DIBHeader {
    let headerSize: UInt32
    let width: Int32
    let height: Int32
    let planes: UInt16
    let bpp: UInt16
    let compression: UInt32
    let imageSize: UInt32
    let xPixelsPerMeter: Int32
    let yPixelsPerMeter: Int32
    let colorsUsed: UInt32
    let importantColors: UInt32
}

func solve() {
    let args = CommandLine.arguments
    guard args.count > 1 else { return }
    let dirPath = args[1]

    let fileManager = FileManager.default
    let url = URL(fileURLWithPath: dirPath)

    guard let files = try? fileManager.contentsOfDirectory(at: url, includingPropertiesForKeys: nil) else { return }

    let bmpFiles = files
        .filter { $0.pathExtension.lowercased() == "bmp" }
        .sorted { $0.lastPathComponent < $1.lastPathComponent }

    for fileURL in bmpFiles {
        let fileName = fileURL.lastPathComponent
        do {
            let data = try Data(contentsOf: fileURL)
            let ptr = data.withUnsafeBytes { $0 }

            guard ptr.count >= 14 else { continue }
            let magic = ptr.load(fromByteOffset: 0, as: UInt16.self).littleEndian
            guard magic == 0x4D42 else { continue } // "BM"

            let bfOffBits = ptr.load(fromByteOffset: 10, as: UInt32.self).littleEndian

            guard ptr.count >= Int(bfOffBits) else { continue }
            let dibPtr = ptr.baseAddress!.advanced(by: Int(bfOffBits))
            let dibData = Data(bytes: dibPtr, count: Int(ptr.count) - Int(bfOffBits))

            let headerSize = dibData.withUnsafeBytes { $0.load(fromByteOffset: 0, as: UInt32.self).littleEndian }
            let width = Int32(bitPattern: dibData.withUnsafeBytes { $0.load(fromByteOffset: 4, as: Int32.self).littleEndian })
            let height = Int32(bitPattern: dibData.withUnsafeBytes { $0.load(fromByteOffset: 8, as: Int32.self).littleEndian })
            let bpp = UInt16(bitPattern: dibData.withUnsafeBytes { $0.load(fromByteOffset: 14, as: UInt16.self).littleEndian })
            let compression = dibData.withUnsafeBytes { $0.load(fromByteOffset: 16, as: UInt32.self).littleEndian }
            let colorsUsed = dibData.withUnsafeBytes { $0.load(fromByteOffset: 32, as: UInt32.self).littleEndian }

            if compression != 0 && compression != 3 {
                print("== \(fileName)")
                print("error: unsupported compression \(compression)")
                continue
            }

            let absHeight = Int(abs(height))
            let isBottomUp = height > 0
            let rowSize = (Int(width) * Int(bpp) + 31) / 32 * 4

            var colorTable = [ (r: Int, g: Int, b: Int) ]()
            if bpp <= 8 {
                let tableCount = colorsUsed > 0 ? Int(colorsUsed) : Int(pow(2.0, Double(bpp)))
                let tableOffset = 14 + Int(headerSize)
                for i in 0..<tableCount {
                    let offset = tableOffset + i * 4
                    let b = Int(data[offset])
                    let g = Int(data[offset+1])
                    let r = Int(data[offset+2])
                    colorTable.append((r, g, b))
                }
            }

            var isInk = Array(repeating: Array(repeating: false, count: Int(width)), count: absHeight)
            var inkCount = 0

            for y in 0..<absHeight {
                let rowIndex = isBottomUp ? (absHeight - 1 - y) : y
                let rowOffset = Int(bfOffBits) + rowIndex * rowSize

                for x in 0..<Int(width) {
                    var r = 0, g = 0, b = 0
                    if bpp == 1 {
                        let byteIdx = (rowIndex * rowSize + x) / 8
                        let shift = 7 - (x % 8)
                        let idx = Int((data[rowOffset + byteIdx] >> shift) & 1)
                        let color = colorTable[idx]
                        r = color.r; g = color.g; b = color.b
                    } else if bpp == 4 {
                        let byteIdx = (rowIndex * rowSize + x * 4) / 8
                        let shift = (1 - (x % 2)) * 4
                        let idx = Int((data[rowOffset + byteIdx] >> shift) & 3)
                        let color = colorTable[idx]
                        r = color.r; g = color.g; b = color.b
                    } else if bpp == 8 {
                        let byteIdx = rowIndex * rowSize + x
                        let color = colorTable[data[rowOffset + byteIdx]]
                        r = color.r; g = color.g; b = color.b
                    } else if bpp == 24 {
                        let byteIdx = rowIndex * rowSize + x * 3
                        b = Int(data[rowOffset + byteIdx])
                        g = Int(data[rowOffset + byteIdx + 1])
                        r = Int(data[rowOffset + byteIdx + 2])
                    } else if bpp == 32 {
                        let byteIdx = rowIndex * rowSize + x * 4
                        if compression == 0 {
                            b = Int(data[rowOffset + byteIdx])
                            g = Int(data[rowOffset + byteIdx + 1])
                            r = Int(data[rowOffset + byteIdx + 2])
                        } else {
                            let pixel = data.subdata(in: rowOffset + byteIdx ..< rowOffset + byteIdx + 4)
                            let rMask = UInt32(bitPattern: pixel.withUnsafeBytes { $0.load(fromByteOffset: 0, as: UInt32.self).littleEndian })
                            let gMask = UInt32(bitPattern: pixel.withUnsafeBytes { $0.load(fromByteOffset: 4, as: UInt32.self).littleEndian }) // Wait, this offset is wrong.
                            // Correct mask offsets for compression 3:
                            let rM = UInt32(bitPattern: data.withUnsafeBytes { $0.load(fromByteOffset: Int(bfOffBits) + 40, as: UInt32.self).littleEndian })
                            let gM = UInt32(bitPattern: data.withUnsafeBytes { $0.load(fromByteOffset: Int(bfOffBits) + 44, as: UInt32.self).littleEndian })
                            let bM = UInt32(bitPattern: data.withUnsafeBytes { $0.load(fromByteOffset: Int(bfOffBits) + 48, as: UInt32.self).littleEndian })

                            let rawR = (UInt32(pixel[0]) | (UInt32(pixel[1]) << 8) | (UInt32(pixel[2]) << 16) | (UInt32(pixel[3]) << 24))
                            let vR = (rawR & rM) >> rM.trailingZeroBitCount
                            let vG = (rawR & gM) >> gM.trailingZeroBitCount
                            let vB = (rawR & bM) >> bM.trailingZeroBitCount

                            let mR = (1 << rM.nonzeroBitCount) - 1
                            let mG = (1 << gM.nonzeroBitCount) - 1
                            let mB = (1 << bM.nonzeroBitCount) - 1

                            r = (vR * 255 + mR / 2) / mR
                            g = (vG * 255 + mG / 2) / mG
                            b = (vB * 255 + mB / 2) / mB
                        }
                    }

                    if (299 * r + 587 * g + 114 * b) / 1000 < 128 {
                        isInk[y][x] = true
                        inkCount += 1
                    }
                }
            }

            print("== \(fileName)")
            print("size \(width)x\(absHeight) bpp \(bpp) header \(headerSize) \(isBottomUp ? "bottom-up" : "top-down") ink \(inkCount)")

            var visited = Array(repeating: Array(repeating: false, count: Int(width)), count: absHeight)
            var components = [[(x: Int, y: Int)]]()

            for y in 0..<absHeight {
                for x in 0..<Int(width) {
                    if isInk[y][x] && !visited[y][x] {
                        var component = [(x: Int, y: Int)]()
                        var queue = [(x, y)]
                        visited[y][x] = true
                        var head = 0
                        while head < queue.count {
                            let (cx, cy) = queue[head]
                            head += 1
                            component.append((cx, cy))
                            for dx in -1...1 {
                                for dy in -1...1 {
                                    let nx = cx + dx
                                    let ny = cy + dy
                                    if nx >= 0 && nx < Int(width) && ny >= 0 && ny < absHeight &&
                                        isInk[ny][nx] && !visited[ny][nx] {
                                        visited[ny][nx] = true
                                        queue.append((nx, ny))
                                    }
                                }
                            }
                        }
                        components.append(component)
                    }
                }
            }

            print("components \(components.count)")
            for comp in components {
                var minX = Int.max
                var maxX = Int.min
                var minY = Int.max
                var maxY = Int.min
                for p in comp {
                    minX = min(minX, p.x)
                    maxX = max(maxX, p.x)
                    minY = min(minY, p.y)
                    maxY = max(maxY, p.y)
                }
                let first = comp[0]
                print("\(first.x),\(first.y) bbox \(minX),\(minY)-\(maxX),\(maxY) pixels \(comp.count)")
            }

        } catch {
            continue
        }
    }
}

