        .sorted { $0.lastPathComponent < $1.lastPathComponent }

    for fileURL in bmpFiles {
        let fileName = fileURL.lastPathComponent
        do {
            let data = try Data(contentsOf: fileURL)

            // File Header (14 bytes)
            guard data.count >= 14 else { continue }
            let magic = load(from: data, offset: 0) as UInt16
            guard magic == 0x4D42 else { continue } // "BM"

            let bfOffBits = Int(load(from: data, offset: 10) as UInt32)

            // DIB Header starts at offset 14
            guard data.count >= 14 + 40 else { continue }
            let headerSize = Int(load(from: data, offset: 14) as UInt32)
            let width = Int(load(from: data, offset: 18) as Int32)
            let height = Int(load(from: data, offset: 22) as Int32)
            let bpp = Int(load(from: data, offset: 26) as UInt16)
            let compression = Int(load(from: data, offset: 28) as UInt32)
            let colorsUsed = Int(load(from: data, offset: 42) as UInt32)

            if compression != 0 && compression != 3 {
                print("== \(fileName)")
                print("error: unsupported compression \(compression)")
                continue
            }

            let absHeight = Int(abs(height))
            let isBottomUp = height > 0
            let rowSize = (width * bpp + 31) / 32 * 4

            var colorTable = [(r: Int, g: Int, b: Int)]()
            if bpp <= 8 {
                let tableCount = colorsUsed > 0 ? Int(colorsUsed) : Int(pow(2.0, Double(bpp)))
                let tableOffset = 14 + headerSize
                for i in 0..<tableCount {
                    let offset = tableOffset + i * 4
                    let b = Int(data[offset])
                    let g = Int(data[offset+1])
                    let r = Int(data[offset+2])
                    colorTable.append((r, g, b))
                }
            }

            var isInk = Array(repeating: Array(repeating: false, count: width), count: absHeight)
            var inkCount = 0

            for y in 0..<absHeight {
                let rowIndex = isBottomUp ? (absHeight - 1 - y) : y
                let rowOffset = bfOffBits + rowIndex * rowSize

                for x in 0..<width {
                    var r = 0, g = 0, b = 0
                    if bpp == 1 {
                        let byteIdx = (rowIndex * rowSize + x) / 8
                        let shift = 7 - (x % 8)
                        let idx = Int((data[rowOffset + byteIdx] >> shift) & 1)
                        let color = colorTable[idx]
                        r = color.r; g = color.g; b = color.b
                    } else if bpp == 4 {
                        let byteIdx = (rowIndex * rowSize + x * 4) / 8
                        let shift = (1 - (x % 2)) * 4
                        let idx = Int((data[rowOffset + byteIdx] >> shift) & 0x0F)
                        let color = colorTable[idx]
                        r = color.r; g = color.g; b = color.b
                    } else if bpp == 8 {
                        let byteIdx = rowIndex * rowSize + x
                        let color = colorTable[Int(data[rowOffset + byteIdx])]
                        r = color.r; g = color.g; b = color.b
                    } else if bpp == 24 {
                        let byteIdx = rowIndex * rowSize + x * 3
                        b = Int(data[rowOffset + byteIdx])
                        g = Int(data[rowOffset + byteIdx + 1])
                        r = Int(data[rowOffset + byteIdx + 2])
                    } else if bpp == 32 {
                        let byteIdx = rowIndex * rowSize + x * 4
                        if compression == 0 {
                            b = Int(data[rowOffset + byteIdx])
                            g = Int(data[rowOffset + byteIdx + 1])
                            r = Int(data[rowOffset + byteIdx + 2])
                        } else {
                            let rM = load(from: data, offset: 14 + 40) as UInt32
                            let gM = load(from: data, offset: 14 + 44) as UInt32
                            let bM = load(from: data, offset: 14 + 48) as UInt32

                            let rawPixel = load(from: data, offset: rowOffset + byteIdx) as UInt32
                            let vR = (rawPixel & rM) >> rM.trailingZeroBitCount
                            let vG = (rawPixel & gM) >> gM.trailingZeroBitCount
                            let vB = (rawPixel & bM) >> bM.trailingZeroBitCount

                            let mR = (1 << rM.nonzeroBitCount) - 1
                            let mG = (1 << gM.nonzeroBitCount) - 1
                            let mB = (1 << bM.nonzeroBitCount) - 1

                            r = (vR * 255 + mR / 2) / mR
                            g = (vG * 255 + mG / 2) / mG
                            b = (vB * 255 + mB / 2) / mB
                        }
                    }

                    if (299 * r + 587 * g + 114 * b) / 1000 < 128 {
                        isInk[y][x] = true
                        inkCount += 1
                    }
                }
            }

            print("== \(fileName)")
            print("size \(width)x\(absHeight) bpp \(bpp) header \(headerSize) \(isBottomUp ? "bottom-up" : "top-down") ink \(inkCount)")

            var visited = Array(repeating: Array(repeating: false, count: width), count: absHeight)
            var components = [[(x: Int, y: Int)]]()

            for y in 0..<absHeight {
                for x in 0..<width {
                    if isInk[y][x] && !visited[y][x] {
                        var component = [(x: Int, y: Int)]()
                        var queue = [(x, y)]
                        visited[y][x] = true
                        var head = 0
                        while head < queue.count {
                            let (cx, cy) = queue[head]
                            head += 1
                            component.append((cx, cy))
                            for dx in -1...1 {
                                for dy in -1...1 {
                                    let nx = cx + dx
                                    let ny = cy + dy
                                    if nx >= 0 && nx < width && ny >= 0 && ny < absHeight &&
                                        isInk[ny][nx] && !visited[ny][nx] {
                                        visited[ny][nx] = true
                                        queue.append((nx, ny))
                                    }
                                }
                            }
                        }
                        components.append(component)
                    }
                }
            }

            print("components \(components.count)")
            for comp in components {
                var minX = width, maxX = -1, minY = absHeight, maxY = -1
                for p in comp {
                    minX = min(minX, p.x)
                    maxX = max(maxX, p.x)
                    minY = min(minY, p.y)
                    maxY = max(maxY, p.y)
                }
                let first = comp[0]
                print("\(first.x),\(first.y) bbox \(minX),\(minY)-\(maxX),\(maxY) pixels \(comp.count)")
            }

        } catch {
            continue
        }
    }
}

