    }

    private static func remainderMagnitudes(_ a: [Int], _ b: [Int]) -> [Int] {
        var remainder = [Int]()
        for i in (0..<a.count).reversed() {
            remainder.insert(a[i], at: 0)
            while remainder.count > 1 && remainder.last == 0 { remainder.removeLast() }
            while compareMagnitudes(remainder, b) >= 0 {
                remainder = subtractMagnitudes(remainder, b)
            }
        }
        if remainder.isEmpty { remainder = [0] }
        return remainder
    }
