struct BigDecimal {
    var value: BigInt // value * 10^12

    init(string: String) {
        let parts = string.split(separator: ".")
        var mag = [Int]()
        let integerPart = String(parts[0])
        for char in integerPart.reversed() {
            mag.append(Int(String(char))!)
        }

        var decimalPart = "0"
        if parts.count > 1 {
            decimalPart = String(parts[1])
        }

        let mutMag = mag
        let mutDec = decimalPart

        // Scale to 12 decimal places
        var currentMag = BigInt(sign: 1, magnitude: mutMag)
        let shift = 12 - mutDec.count

        if shift >= 0 {
            var newMag = [Int]()
            for i in 0..<shift { newMag.append(0) }
            newMag.append(contentsOf: mutMag)
            currentMag = BigInt(sign: 1, magnitude: newMag)
        } else {
            // mutDec.count > 12
            // This case shouldn't happen based on the problem description (max 8 decimal places)
            // But for robustness:
            let factor = 10 ^ (mutDec.count - 12)
            // We'd need to divide currentMag by factor.
        }

        // Add the decimal part
        // Since we need to scale to 10^12, we multiply by 10^(12 - mutDec.count)
        // and then add the decimal part.
        // Wait, simpler:
        var finalMag = [Int]()
        let fullStr = integerPart + mutDec
        for char in fullStr.reversed() {
            finalMag.append(Int(String(char))!)
        }
        // Now finalMag is fullStr * 10^mutDec.count
        // We want it to be fullStr * 10^12.
        let diff = 12 - mutDec.count
        if diff >= 0 {
            var shiftedMag = [Int]()
            for _ in 0..<diff { shiftedMag.append(0) }
            shiftedMag.append(contentsOf: finalMag)
            currentMag = BigInt(sign: 1, magnitude: shiftedMag)
        } else {
            // This case shouldn't happen.
            currentMag = BigInt(sign: 1, magnitude: finalMag)
        }

        // Handle negative sign
        if integerPart.hasPrefix("-") {
            currentMag = BigInt(sign: -1, magnitude: currentMag.magnitude)
        }

        self.value = currentMag
    }

    init(value: BigInt) {
        self.value = value
    }

    func round(to minorUnits: Int) -> BigDecimal {
        let d = 12 - minorUnits
        let Q = value / BigInt(10 ^ d)
        let R = value % BigInt(10 ^ d)
        let rAbs = BigInt(sign: 1, magnitude: R.magnitude)
        let half = BigInt(10 ^ d / 2)

        let sign = value.sign
        if rAbs.magnitude < half.magnitude {
            return BigDecimal(value: Q * BigInt(10 ^ minorUnits))
        } else if rAbs.magnitude > half.magnitude {
            let adjustment = BigInt(sign: sign, magnitude: [1])
            return BigDecimal(value: (Q + adjustment) * BigInt(10 ^ minorUnits))
        } else {
            if Q.magnitude[0] % 2 == 0 {
                return BigDecimal(value: Q * BigInt(10 ^ minorUnits))
            } else {
                let adjustment = BigInt(sign: sign, magnitude: [1])
                return BigDecimal(value: (Q + adjustment) * BigInt(10 ^ minorUnits))
            }
        }
    }

    static func + (lhs: BigDecimal, rhs: BigDecimal) -> BigDecimal {
        return BigDecimal(value: lhs.value + rhs.value)
    }

    static func - (lhs: BigDecimal, rhs: BigDecimal) -> BigDecimal {
        return BigDecimal(value: lhs.value - rhs.value)
    }

    static func * (lhs: BigDecimal, rhs: BigDecimal) -> BigDecimal {
        // (V_A * 10^-12) * (V_B * 10^-12) = (V_A * V_B) * 10^-24
        // To get 10^-12, divide by 10^12
        let product = lhs.value * rhs.value
        return BigDecimal(value: product / BigInt(10 ^ 12))
    }

    func toString(minorUnits: Int) -> String {
        let rounded = self.round(to: minorUnits)
        let d = 12 - minorUnits
        let Q = rounded.value / BigInt(10 ^ d)
        let R = rounded.value % BigInt(10 ^ d)

        var res = ""
        if rounded.value.sign != 0 {
            if rounded.value.sign == -1 { res += "-" }
        }

        let qMag = Q.magnitude
        let qStr = qMag.reversed().map { String($0) }.joined()

        // Add commas to qStr
        var formattedQ = ""
        let qChars = Array(qStr)
        if qChars.isEmpty {
            formattedQ = "0"
        } else {
            for i in 0..<qChars.count {
                formattedQ.append(qChars[i])
                let posFromRight = qChars.count - 1 - i
                if posFromRight > 0 && posFromRight % 3 == 0 {
                    formattedQ.append(",")
                }
            }
        }
        res += formattedQ

        if minorUnits > 0 {
            res += "."
            let rMag = R.magnitude
            var rStr = rMag.reversed().map { String($0) }.joined()
            while rStr.count < minorUnits {
                rStr = "0" + rStr
            }
            if rStr.count > minorUnits {
                rStr = String(rStr.prefix(minorUnits))
            }
            res += rStr
        }

        return res
    }
