                guard let acc = accounts[name] else {
                    rejections.append("line \(lineNum): REJECT unknown account \(name)")
                    break
                }
                let rate = BigDecimal(string: parts[2])
                let interest = (acc.balance * rate).round(to: currencies[acc.code]!)
                accounts[name] = (acc.code, acc.balance + interest, acc.limit)
