import Foundation

struct BigInt: CustomStringConvertible {
    var sign: Int // 1 for positive, -1 for negative, 0 for zero
    var magnitude: [Int] // Little-endian, base 10^7

    static let base = 10_000_000

    init(sign: Int = 1, magnitude: [Int] = [0]) {
        var mag = magnitude
        while mag.count > 1 && mag.last == 0 { mag.removeLast() }
        if mag.isEmpty { mag = [0] }
        if mag == [0] {
            self.sign = 0
            self.magnitude = [0]
        } else {
            self.sign = sign
            self.magnitude = mag
        }
    }

    init(_ value: Int) {
        if value == 0 {
            self.sign = 0
            self.magnitude = [0]
        } else {
            self.sign = value > 0 ? 1 : -1
            var mag = [Int]()
            var v = abs(value)
            while v > 0 {
                mag.append(v % BigInt.base)
                v /= BigInt.base
            }
            self.magnitude = mag
        }
    }

    var description: String {
        if sign == 0 { return "0" }
        var s = sign == -1 ? "-" : ""
        s += magnitude.reversed().map { String($0) }.joined()
        return s
    }

    static func + (lhs: BigInt, rhs: BigInt) -> BigInt {
        if lhs.sign == 0 { return rhs }
        if rhs.sign == 0 { return lhs }
        if lhs.sign == rhs.sign {
            return BigInt(sign: lhs.sign, magnitude: addMagnitudes(lhs.magnitude, rhs.magnitude))
        } else {
            if compareMagnitudes(lhs.magnitude, rhs.magnitude) >= 0 {
                return BigInt(sign: lhs.sign, magnitude: subtractMagnitudes(lhs.magnitude, rhs.magnitude))
            } else {
                return BigInt(sign: rhs.sign, magnitude: subtractMagnitudes(rhs.magnitude, lhs.magnitude))
            }
        }
    }

    static func - (lhs: BigInt, rhs: BigInt) -> BigInt {
        return lhs + BigInt(sign: -rhs.sign, magnitude: rhs.magnitude)
    }

    static func * (lhs: BigInt, rhs: BigInt) -> BigInt {
        if lhs.sign == 0 || rhs.sign == 0 { return BigInt(0) }
        let newMag = multiplyMagnitudes(lhs.magnitude, rhs.magnitude)
        return BigInt(sign: lhs.sign * rhs.sign, magnitude: newMag)
    }

    static func / (lhs: BigInt, rhs: BigInt) -> BigInt {
        if rhs.sign == 0 { fatalError("Division by zero") }
        let qMag = divideMagnitudes(lhs.magnitude, rhs.magnitude)
        return BigInt(sign: lhs.sign * rhs.sign, magnitude: qMag)
    }

    static func % (lhs: BigInt, rhs: BigInt) -> BigInt {
        if rhs.sign == 0 { fatalError("Division by zero") }
        let rMag = remainderMagnitudes(lhs.magnitude, rhs.magnitude)
        return BigInt(sign: lhs.sign, magnitude: rMag)
    }

    private static func addMagnitudes(_ a: [Int], _ b: [Int]) -> [Int] {
        var res = [Int]()
        let n = max(a.count, b.count)
        var carry = 0
        for i in 0..<n {
            let sum = (i < a.count ? a[i] : 0) + (i < b.count ? b[i] : 0) + carry
            res.append(sum % base)
            carry = sum / base
        }
        if carry > 0 { res.append(carry) }
        return res
    }

    private static func subtractMagnitudes(_ a: [Int], _ b: [Int]) -> [Int] {
        var res = [Int]()
        var borrow = 0
        for i in 0..<a.count {
            let sub = a[i] - (i < b.count ? b[i] : 0) - borrow
            if sub < 0 {
                res.append(sub + base)
                borrow = 1
            } else {
                res.append(sub)
                borrow = 0
            }
        }
        while res.count > 1 && res.last == 0 { res.removeLast() }
        return res
    }

    private static func multiplyMagnitudes(_ a: [Int], _ b: [Int]) -> [Int] {
        if a == [0] || b == [0] { return [0] }
        var res = Array(repeating: 0, count: a.count + b.count)
        for i in 0..<a.count {
            var carry = 0
            for j in 0..<b.count {
                let prod = a[i] * b[j] + res[i+j] + carry
                res[i+j] = prod % base
                carry = prod / base
            }
            var k = i + b.count
            while carry > 0 {
                let sum = res[k] + carry
                res[k] = sum % base
                carry = sum / base
                k += 1
                if k == res.count { res.append(0) }
            }
        }
        while res.count > 1 && res.last == 0 { res.removeLast() }
        return res
    }

    private static func compareMagnitudes(_ a: [Int], _ b: [Int]) -> Int {
        if a.count != b.count { return a.count > b.count ? 1 : -1 }
        for i in (0..<a.count).reversed() {
            if a[i] != b[i] { return a[i] > b[i] ? 1 : -1 }
        }
        return 0
    }

    private static func divideMagnitudes(_ a: [Int], _ b: [Int]) -> [Int] {
        if b == [0] { fatalError("Division by zero") }
        var quotient = [Int]()
        var remainder = [Int]()
        for i in (0..<a.count).reversed() {
            remainder.insert(a[i], at: 0)
            while remainder.count > 1 && remainder.last == 0 { remainder.removeLast() }

            var low = 0
            var high = base - 1
            var q = 0
            while low <= high {
                let mid = (low + high) / 2
                let prod = multiplyMagnitudes(b, [mid])
                if compareMagnitudes(remainder, prod) >= 0 {
                    q = mid
                    low = mid + 1
                } else {
                    high = mid - 1
                }
            }
            quotient.insert(q, at: 0)
            remainder = subtractMagnitudes(remainder, multiplyMagnitudes(b, [q]))
        }
        while quotient.count > 1 && quotient.first == 0 { quotient.removeFirst() }
        if quotient.isEmpty { quotient = [0] }
        return quotient
    }

    private static func remainderMagnitudes(_ a: [Int], _ b: [Int]) -> [Int] {
        let (_, r) = divideMagnitudes(a, b)
        return r
    }

    static func powerOf10(_ n: Int) -> BigInt {
        var res = BigInt(sign: 1, magnitude: [1])
        for _ in 0..<n {
            res = res * BigInt(sign: 1, magnitude: [10])
        }
        return res
    }
}

struct BigDecimal {
    var value: BigInt // value * 10^12

    init(string: String) {
        let parts = string.split(separator: ".")
        let integerPart = String(parts[0])
        var mag = [Int]()
        for char in integerPart.reversed() {
            mag.append(Int(String(char))!)
        }

        var decimalPart = "0"
        if parts.count > 1 {
            decimalPart = String(parts[1])
        }

        let fullStr = integerPart + decimalPart
        var finalMag = [Int]()
        for char in fullStr.reversed() {
            finalMag.append(Int(String(char))!)
        }

        let diff = 12 - decimalPart.count
        var shiftedMag = [Int]()
        if diff >= 0 {
            for _ in 0..<diff { shiftedMag.append(0) }
            shiftedMag.append(contentsOf: finalMag)
        } else {
            // This case shouldn't happen with max 8 decimal places
            shiftedMag = finalMag
        }

        let sign = integerPart.hasPrefix("-") ? -1 : 1
        self.value = BigInt(sign: sign, magnitude: shiftedMag)
    }

    init(value: BigInt) {
        self.value = value
    }

    func round(to minorUnits: Int) -> BigDecimal {
        let d = 12 - minorUnits
        let powerOf10D = BigInt.powerOf10(d)

        let Q = value / powerOf10D
        let R = value % powerOf10D

        let absR = BigInt(sign: 1, magnitude: R.magnitude)
        let half = powerOf10D / 2

        var qRounded = Q
        if absR > half {
            qRounded = Q + BigInt(sign: value.sign, magnitude: [1])
        } else if absR == half {
            if Q.magnitude[0] % 2 != 0 {
                qRounded = Q + BigInt(sign: value.sign, magnitude: [1])
            }
        }

        let newV = qRounded * BigInt.powerOf10(12 - minorUnits)
        return BigDecimal(value: newV)
    }

    static func + (lhs: BigDecimal, rhs: BigDecimal) -> BigDecimal {
        return BigDecimal(value: lhs.value + rhs.value)
    }

    static func - (lhs: BigDecimal, rhs: BigDecimal) -> BigDecimal {
        return BigDecimal(value: lhs.value - rhs.value)
    }

    static func * (lhs: BigDecimal, rhs: BigDecimal) -> BigDecimal {
        let product = lhs.value * rhs.value
        return BigDecimal(value: product / BigInt.powerOf10(12))
    }

    func toString(minorUnits: Int) -> String {
        let rounded = self.round(to: minorUnits)
        let d = 12 - minorUnits
        let Q = rounded.value / BigInt.powerOf10(d)
        let R = rounded.value % BigInt.powerOf10(d)

        var res = ""
        if rounded.value.sign != 0 {
            if rounded.value.sign == -1 { res += "-" }
        }

        let qStr = Q.magnitude.reversed().map { String($0) }.joined()
        var formattedQ = ""
        let qChars = Array(qStr)
        if qChars.isEmpty {
            formattedQ = "0"
        } else {
            for i in 0..<qChars.count {
                formattedQ.append(qChars[i])
                let posFromRight = qChars.count - 1 - i
                if posFromRight > 0 && posFromRight % 3 == 0 {
                    formattedQ.append(",")
                }
            }
        }
        res += formattedQ

        if minorUnits > 0 {
            res += "."
            let rStr = R.magnitude.reversed().map { String($0) }.joined()
            var paddedR = rStr
            while paddedR.count < minorUnits {
                paddedR = "0" + paddedR
            }
            if paddedR.count > minorUnits {
                paddedR = String(paddedR.prefix(minorUnits))
            }
            res += paddedR
        }

        return res
    }
}

func solve() {
    guard CommandLine.count > 1, let dirPath = URL(fileURLWithPath: CommandLine[1]) else { return }
    let fileURL = dirPath.appendingPathComponent("ledger.txt")
    guard let content = try? String(contentsOf: fileURL) else { return }

    var currencies = [String: Int]()
    var accounts = [String: (code: String, balance: BigDecimal, limit: BigDecimal)]()
    var rejections = [String]()

    let lines = content.components(separatedBy: .newlines)
    for (idx, line) in lines.enumerated() {
        let lineNum = idx + 1
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }

        let parts = trimmed.components(separatedBy: .whitespaces).filter { !$0.isEmpty }
        let command = parts[0]

        switch command {
        case "currency":
            currencies[parts[1]] = Int(parts[2])!
        case "open":
            let name = parts[1]
            if accounts[name] != nil {
                rejections.append("line \(lineNum): REJECT account exists \(name)")
            } else {
                let code = parts[2]
                let limitVal = parts.count > 3 ? BigDecimal(string: parts[3]).round(to: currencies[code]!) : BigDecimal(value: BigInt(0))
                accounts[name] = (code, BigDecimal(value: BigInt(0)), limitVal)
            }
        case "deposit":
            let name = parts[1]
            guard let acc = accounts[name] else {
                rejections.append("line \(lineNum): REJECT unknown account \(name)")
                break
            }
            let amount = BigDecimal(string: parts[2]).round(to: currencies[acc.code]!)
            if amount.value.sign == 0 {
                rejections.append("line \(lineNum): REJECT non-positive amount")
            } else {
                accounts[name] = (acc.code, acc.balance + amount, acc.limit)
            }
        case "withdraw":
            let name = parts[1]
            guard let acc = accounts[name] else {
                rejections.append("line \(lineNum): REJECT unknown account \(name)")
                break
            }
            let amount = BigDecimal(string: parts[2]).round(to: currencies[acc.code]!)
            if amount.value.sign == 0 {
                rejections.append("line \(lineNum): REJECT non-positive amount")
            } else if acc.balance - amount < BigDecimal(value: BigInt(sign: -1, magnitude: acc.limit.value.magnitude)) {
                rejections.append("line \(lineNum): REJECT insufficient funds \(name)")
            } else {
                accounts[name] = (acc.code, acc.balance - amount, acc.limit)
            }
        case "transfer":
            let fromName = parts[1]
            let toName = parts[2]
            guard let fromAcc = accounts[fromName] else {
                rejections.append("line \(lineNum): REJECT unknown account \(fromName)")
                break
            }
            guard let toAcc = accounts[toName] else {
                rejections.append("line \(lineNum): REJECT unknown account \(toName)")
                break
            }
            if fromAcc.code != toAcc.code {
                rejections.append("line \(lineNum): REJECT currency mismatch")
                break
            }
            let amount = BigDecimal(string: parts[3]).round(to: currencies[fromAcc.code]!)
            if amount.value.sign == 0 {
                rejections.append("line \(lineNum): REJECT non-positive amount")
                break
            } else if fromAcc.balance - amount < BigDecimal(value: BigInt(sign: -1, magnitude: fromAcc.limit.value.magnitude)) {
                rejections.append("line \(lineNum): REJECT insufficient funds \(fromName)")
                break
            } else {
                accounts[fromName] = (fromAcc.code, fromAcc.balance - amount, fromAcc.limit)
                accounts[toName] = (toAcc.code, toAcc.balance + amount, toAcc.limit)
            }
        case "convert":
            let fromName = parts[1]
            let toName = parts[2]
            guard let fromAcc = accounts[fromName] else {
                rejections.append("line \(lineNum): REJECT unknown account \(fromName)")
                break
            }
            guard let toAcc = accounts[toName] else {
                rejections.append("line \(lineNum): REJECT unknown account \(toName)")
                break
            }
            let amount = BigDecimal(string: parts[3]).round(to: currencies[fromAcc.code]!)
            if amount.value.sign == 0 {
                rejections.append("line \(lineNum): REJECT non-positive amount")
                break
            } else if fromAcc.balance - amount < BigDecimal(value: BigInt(sign: -1, magnitude: fromAcc.limit.value.magnitude)) {
                rejections.append("line \(lineNum): REJECT insufficient funds \(fromName)")
                break
            } else {
                let rate = BigDecimal(string: parts[4])
                let converted = (amount * rate).round(to: currencies[toAcc.code]!)
                accounts[fromName] = (fromAcc.code, fromAcc.balance - amount, fromAcc.limit)
                accounts[toName] = (toAcc.code, toAcc.balance + converted, toAcc.limit)
            }
        case "interest":
            let name = parts[1]
            guard let acc = accounts[name] else {
                rejections.append("line \(lineNum): REJECT unknown account \(name)")
                break
            }
            let rate = BigDecimal(string: parts[2])
            let interest = (acc.balance * rate).round(to: currencies[acc.code]!)
            accounts[name] = (acc.code, acc.balance + interest, acc.limit)
        case "split":
            let fromName = parts[1]
            guard let fromAcc = accounts[fromName] else {
                rejections.append("line \(lineNum): REJECT unknown account \(fromName)")
                break
            }
            let amount = BigDecimal(string: parts[2]).round(to: currencies[fromAcc.code]!)
            if amount.value.sign == 0 {
                rejections.append("line \(lineNum): REJECT non-positive amount")
                break
            }

            var targets = [(name: String, weight: Int, originalIndex: Int)]()
            for i in 3..<parts.count {
                let targetParts = parts[i].split(separator: ":")
                let tName = String(targetParts[0])
                let tWeight = Int(String(targetParts[1]))!
                targets.append((tName, tWeight, i-3))
            }

            var allValid = true
            for t in targets {
                if accounts[t.name] == nil {
                    rejections.append("line \(lineNum): REJECT unknown account \(t.name)")
                    allValid = false
                    break
                }
                if accounts[t.name]!.code != fromAcc.code {
                    rejections.append("line \(lineNum): REJECT currency mismatch")
                    allValid = false
                    break
                }
            }
            if !allValid { break }

            if fromAcc.balance - amount < BigDecimal(value: BigInt(sign: -1, magnitude: fromAcc.limit.value.magnitude)) {
                rejections.append("line \(lineNum): REJECT insufficient funds \(fromName)")
            } else {
                let A = amount.value.magnitude
                let W = targets.reduce(0) { $0 + $1.weight }
                var shares = [Int]()
                var remainders = [Int]()
                for t in targets {
                    let p = BigInt(sign: 1, magnitude: A) * BigInt(sign: 1, magnitude: t.weight)
                    let q = p / BigInt(sign: 1, magnitude: W)
                    let r = p % BigInt(sign: 1, magnitude: W)
                    shares.append(q.magnitude[0])
                    remainders.append(r.magnitude[0])
                }

                let totalRemainder = A.magnitude[0] % W
                let sortedIndices = (0..<targets.count).sorted { i, j in
                    if remainders[i] != remainders[j] { return remainders[i] > remainders[j] }
                    return targets[i].originalIndex < targets[j].originalIndex
                }

                for i in 0..<min(totalRemainder, targets.count) {
                    shares[sortedIndices[i]] += 1
                }

                accounts[fromName] = (fromAcc.code, fromAcc.balance - amount, fromAcc.limit)
                let minorUnits = currencies[fromAcc.code]!
                for i in 0..<targets.count {
                    let targetName = targets[i].name
                    let currentAcc = accounts[targetName]!
                    let shareValue = BigInt(sign: 1, magnitude: [shares[i]]) * BigInt.powerOf10(12 - minorUnits)
                    accounts[targetName] = (currentAcc.code, currentAcc.balance + BigDecimal(value: shareValue), currentAcc.limit)
                }
            }
        default:
            break
        }
    }

    for rejection in rejections {
        print(rejection)
    }
    print()

    let sortedAccounts = accounts.sorted { $0.key < $1.key }
    for (name, acc) in sortedAccounts {
        print("\(name) \(acc.code) \(acc.balance.toString(minorUnits: currencies[acc.code]!))")
    }
    print()

    var totals = [String: (sum: BigDecimal, count: Int)]()
    for (_, acc) in accounts {
        let code = acc.code
        if let existing = totals[code] {
            totals[code] = (existing.sum + acc.balance, existing.count + 1)
        } else {
            totals[code] = (acc.balance, 1)
        }
    }

    let sortedCodes = totals.keys.sorted()
    for code in sortedCodes {
        let data = totals[code]!
        print("total \(code) \(data.sum.toString(minorUnits: currencies[code]!)) (\(data.count) accounts)")
    }
}

