const BASE_SCALE = 1000000000000n; // 10^12

function parseDecimal(s: string): bigint {
    const [intPart, fracPart = ""] = s.split(".");
    let val = BigInt(intPart) * BASE_SCALE;
    const fracLen = fracPart.length;
    if (fracLen > 0) {
        const fracVal = BigInt(fracPart);
        const scale = BASE_SCALE / (10n ** BigInt(Math.min(fracLen, 12)));
        // If fracLen > 12, we only care about the first 12 digits.
        // But the problem says amounts have up to 8 decimal places.
        // So fracLen will be <= 8.
        val += (fracVal * (BASE_SCALE / (10n ** BigInt(fracLen))));
