/**
 * Round a BigInt value to a specific number of decimal places (D).
 * The value is assumed to be in some scale, and we want to round it 
 * to a scale that is D places smaller.
 */
function round(v: bigint, d: number): bigint {
    const divisor = 10n ** BigInt(d);
    const absV = v < 0n ? -v : v;
    const q = absV / divisor;
