"use strict";

import * as fs from "fs";
import * as path from "path";

/**
 * Exact arithmetic using BigInt.
 * All values are stored in an internal scale of 10^20.
 */
const SCALE_EXP = 20n;
const BASE_SCALE = 10n ** SCALE_EXP;

function parseDecimal(s: string): bigint {
    const [intPart, fracPart = ""] = s.split(".");
    let val = BigInt(intPart) * BASE_SCALE;
    const fracLen = fracPart.length;
    const fracVal = BigInt(fracPart);
    // The problem states amounts have up to 8 decimal places and rates up to 12.
    // We handle any fracLen up to 20 correctly.
    if (fracLen <= Number(SCALE_EXP)) {
        val += fracVal * (10n ** (SCALE_EXP - BigInt(fracLen)));
    } else {
        val += fracVal / (10n ** BigInt(fracLen - Number(SCALE_EXP)));
    }
    return val;
}

/**
 * Rounds a value in scale S to the currency's minor units (m) using round-half-even.
 * The result is returned in scale S.
 */
function roundTo(valueInS: bigint, m: number): bigint {
    const divisor = 10n ** (SCALE_EXP - BigInt(m));
    const absV = valueInS < 0n ? -valueInS : valueInS;
    const q = absV / divisor;
    const r = absV % divisor;
    const half = divisor / 2n;

    let roundedQ = q;
    if (r > half) {
        roundedQ += 1n;
    } else if (r === half) {
        if (q % 2n !== 0n) {
            roundedQ += 1n;
        }
    }

    const result = valueInS < 0n ? -roundedQ : roundedQ;
    return result * (10n ** BigInt(m));
}

interface Currency {
    code: string;
    minorUnits: number;
}

interface Account {
    name: string;
    currency: Currency;
    balance: bigint;
    limit: bigint;
}

