        try {
            if (cmd === "currency") {
                const code = parts[1];
                const minorUnits = parseInt(parts[2]);
                currencies.set(code, { code, minorUnits });
            } else if (cmd === "open") {
                const name = parts[1];
                const code = parts[2];
                const limitRaw = parts[3] ? parseDecimal(parts[3]) : 0n;
                const currency = currencies.get(code);
                if (!currency) {
                    // Should not happen based on problem description
                } else {
                    const limit = roundTo(limitRaw, currency.minorUnits);
                    if (accounts.has(name)) {
                        rejections.push(`line ${lineNum}: REJECT account exists ${name}`);
                    } else {
                        accounts.set(name, { name, currency, balance: 0n, limit });
