#define MAX_DIGITS 150

typedef struct {
    int d[MAX_DIGITS];
    int len;
    int sign; // 1 for positive, -1 for negative, 0 for zero
} BigInt;

BigInt from_int(long long v) {
    BigInt res = {{0}, 0, 0};
    if (v == 0) { res.len = 1; res.d[0] = 0; res.sign = 0; return res; }
    res.sign = (v > 0) ? 1 : -1;
    long long val = (v > 0) ? v : -v;
    int i = 0;
    while (val > 0) {
        res.d[i++] = val % 10;
        val /= 10;
    }
    res.len = i;
    return res;
}

BigInt from_string(const char *s) {
    BigInt res = {{0}, 0, 0};
    int start = 0;
    if (s[0] == '-') {
        res.sign = -1;
        start = 1;
    } else if (s[0] != '0') {
        res.sign = 1;
    } else {
        res.sign = 0;
    }
    int i = 0;
    int len = 0;
    for (int j = start; s[j] != '\0' && s[j] != '.'; j++) {
        if (isdigit(s[j])) {
            res.d[i++] = s[j] - '0';
        }
    }
    res.len = i;
    if (res.len == 0) { res.len = 1; res.d[0] = 0; res.sign = 0; }
    return res;
}

BigInt add_abs(BigInt a, BigInt b) {
    BigInt res = {{0}, 0, 1};
    int max_len = a.len > b.len ? a.len : b.len;
    int carry = 0;
    for (int i = 0; i < max_len || carry; i++) {
        int sum = carry + (i < a.len ? a.d[i] : 0) + (i < b.len ? b.d[i] : 0);
        res.d[i] = sum % 10;
        carry = sum / 10;
        res.len = i + 1;
    }
    return res;
}

BigInt sub_abs(BigInt a, BigInt b) {
    // Assumes a >= b
    BigInt res = {{0}, 0, 1};
    int borrow = 0;
    for (int i = 0; i < a.len; i++) {
        int sub = a.d[i] - borrow - (i < b.len ? b.d[i] : 0);
        if (sub < 0) {
            sub += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        res.d[i] = sub;
    }
    res.len = a.len;
    while (res.len > 1 && res.d[res.len - 1] == 0) res.len--;
    return res;
}

int compare_abs(BigInt a, BigInt b) {
    if (a.len != b.len) return a.len > b.len ? 1 : -1;
    for (int i = a.len - 1; i >= 0; i--) {
        if (a.d[i] != b.d[i]) return a.d[i] > b.d[i] ? 1 : -1;
    }
    return 0;
}

BigInt add(BigInt a, BigInt b) {
    if (a.sign == 0) return b;
    if (b.sign == 0) return a;
    if (a.sign == b.sign) {
        BigInt res = add_abs(a, b);
        res.sign = a.sign;
        return res;
    }
    int cmp = compare_abs(a, b);
    if (cmp == 0) return from_int(0);
    if (cmp > 0) {
        BigInt res = sub_abs(a, b);
        res.sign = a.sign;
        return res;
    } else {
        BigInt res = sub_abs(b, a);
        res.sign = b.sign;
        return res;
    }
}

BigInt sub(BigInt a, BigInt b) {
    BigInt neg_b = b;
    neg_b.sign = -b.sign;
    return add(a, neg_b);
}

BigInt mul(BigInt a, BigInt b) {
    if (a.sign == 0 || b.sign == 0) return from_int(0);
    BigInt res = {{0}, 0, a.sign * b.sign};
    for (int i = 0; i < a.len; i++) {
        int carry = 0;
        for (int j = 0; j < b.len || carry; j++) {
            long long cur = res.d[i + j] + a.d[i] * 1LL * (j < b.len ? b.d[j] : 0) + carry;
            res.d[i + j] = cur % 10;
            carry = cur / 10;
            if (i + j >= res.len) res.len = i + j + 1;
        }
    }
    while (res.len > 1 && res.d[res.len - 1] == 0) res.len--;
    return res;
}

