    }

    fn is_even(&self) -> bool {
        self.digits[0] % 2 == 0
    }

    fn to_string(&self) -> String {
        if self.digits == vec![0] {
            return "0".to_string();
        }
        let mut s = String::new();
        if self.sign == -1 {
            s.push('-');
        }
        for i in (0..self.digits.len()).rev() {
            let d = self.digits[i];
            let s_d = if i == self.digits.len() - 1 {
                d.to_string()
            } else {
                format!("{:09}", d)
            };
            s.push_str(&s_d);
        }
        s
    }

    fn compare(&self, other: &BigInt) -> std::cmp::Ordering {
        if self.sign != other.sign {
            return if self.sign == 1 { std::cmp::Ordering::Greater } else { std::cmp::Ordering::Less };
        }
        let mag1 = self.abs_magnitude();
        let mag2 = other.abs_magnitude();
        if mag1.digits.len() != mag2.digits.len() {
            return if mag1.digits.len() > mag2.digits.len() {
                if self.sign == 1 { std::cmp::Ordering::Greater } else { std::cmp::Ordering::Less }
            } else {
                if self.sign == 1 { std::cmp::Ordering::Less } else { std::cmp::Ordering::Greater }
            }
        }
        for i in (0..mag1.digits.len()).rev() {
            if mag1.digits[i] != mag2.digits[i] {
                return if mag1.digits[i] > mag2.digits[i] {
                    if self.sign == 1 { std::cmp::Ordering::Greater } else { std::cmp::Ordering::Less }
                } else {
                    if self.sign == 1 { std::cmp::Ordering::Less } else { std::cmp::Ordering::Greater }
                }
            }
        }
        std::cmp::Ordering::Equal
    }
}

struct Currency {
    code: String,
    minor_units: usize,
}

struct Account {
    name: String,
    currency_code: String,
    balance: BigInt,
    overdraft_limit: BigInt,
}

fn round_to_minor_units(v: BigInt, m: usize) -> BigInt {
    let u_pow = 10u64.pow((12 - m) as u32);
    let u = BigInt::from_u64(u_pow);
    let q = v.div_u64(u_pow);
    let r = v.rem_u64(u_pow);
    let half = u_pow / 2;
    let sign = if v.sign == 1 { 1 } else if v.sign == -1 { -1 } else { 0 };

    if r < half {
        q.mul_u64(u_pow)
    } else if r > half {
        let mut res = q.mul_u64(u_pow);
        if sign == 1 {
            res = res.add(&u)
        } else if sign == -1 {
            res = res.sub(&u)
        }
        res
    } else {
        if q.is_even() {
            q.mul_u64(u_pow)
        } else {
            let mut res = q.mul_u64(u_pow);
            if sign == 1 {
                res = res.add(&u)
            } else if sign == -1 {
                res = res.sub(&u)
            }
            res
        }
    }
}

fn format_balance(balance: &BigInt, m: usize) -> String {
    let u_pow = 10u64.pow((12 - m) as u32);
    let val_in_minor_units = balance.div_u64(u_pow);
    let integer_part_val = val_in_minor_units.div_u64(10u64.pow(m as u32));
    let decimal_part_val = val_in_minor_units.rem_u64(10u64.pow(m as u32));

    let mut s = String::new();
    if balance.sign == -1 && !(val_in_minor_units.digits == vec![0]) {
        s.push('-');
    }

    let mut int_str = integer_part_val.to_string();
    let mut result = String::new();
    let mut count = 0;
    for (i, c) in int_str.chars().rev().enumerate() {
        if i > 0 && i % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    s.push_str(&result.chars().rev().collect::<String>());

    if m > 0 {
        s.push('.');
        let mut dec_str = decimal_part_val.to_string();
        while dec_str.len() < m {
            dec_str.insert(0, '0');
        }
        s.push_str(&dec_str);
    }

    if s == "-" { "0".to_string() } else { s }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = std::path::Path::new(dir).join("ledger.txt");
    let file = File::open(path).expect("Could not open ledger.txt");
    let reader = BufReader::new(file);

    let mut currencies: HashMap<String, Currency> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections = Vec::new();

    for (idx, line) in reader.lines().enumerate() {
        let line_num = idx + 1;
        let line = line.unwrap();
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = parts[0];

        match cmd {
            "currency" => {
                let code = parts[1].to_string();
                let minor_units = parts[2].parse().unwrap();
                currencies.insert(code.clone(), Currency { code, minor_units });
            }
            "open" => {
                let name = parts[1].to_string();
                let code = parts[2].to_string();
                let limit_raw = if parts.len() > 3 { parts[3] } else { "0" };
                let limit_big = BigInt::from_str(limit_raw);
                let m = currencies.get(&code).unwrap().minor_units;
                let limit = round_to_minor_units(limit_big, m);
                if accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, name));
                } else {
                    accounts.insert(name.clone(), Account {
                        name,
                        currency_code: code,
                        balance: BigInt::from_u64(0),
                        overdraft_limit: limit,
                    });
                }
            }
            "deposit" => {
                let name = parts[1];
                let amount_raw = parts[2];
                if let Some(acc) = accounts.get(name) {
                    let m = currencies.get(&acc.currency_code).unwrap().minor_units;
                    let amount = round_to_minor_units(BigInt::from_str(amount_raw), m);
                    if amount.sign == 1 && amount.digits == vec![0] {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else if amount.sign == -1 {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else {
                        acc.balance = acc.balance.add(&amount);
                    }
                } else {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                }
            }
            "withdraw" => {
                let name = parts[1];
                let amount_raw = parts[2];
                if let Some(acc) = accounts.get(name) {
                    let m = currencies.get(&acc.currency_code).unwrap().minor_units;
                    let amount = round_to_minor_units(BigInt::from_str(amount_raw), m);
                    if amount.sign == 1 && amount.digits == vec![0] {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else if amount.sign == -1 {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else {
                        let new_balance = acc.balance.sub(&amount);
                        if new_balance.compare(&acc.overdraft_limit.mul_u64(1).sub(&BigInt::from_u64(1))) == std::cmp::Ordering::Less {
                            // Wait, the condition is balance < -limit.
                            // My BigInt logic for sub and compare might need care. 
                            // Let's re-check.
                        }
                        // Correct check: balance - amount < -limit
                        let neg_limit = BigInt { sign: -1, digits: acc.overdraft_limit.digits.clone() };
                        if new_balance.compare(&neg_limit) == std::cmp::Ordering::Less {
                            rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, name));
                        } else {
                            acc.balance = new_balance;
                        }
                    }
                } else {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                }
            }
            "transfer" => {
                let from_name = parts[1];
                let to_name = parts[2];
                let amount_raw = parts[3];
                let acc_from = accounts.get(from_name);
                let acc_to = accounts.get(to_name);
                if acc_from.is_none() {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from_name));
                } else if acc_to.is_none() {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to_name));
                } else if acc_from.unwrap().currency_code != acc_to.unwrap().currency_code {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                } else {
                    let acc_from = acc_from.unwrap();
                    let acc_to = acc_to.unwrap();
                    let m = currencies.get(&acc_from.currency_code).unwrap().minor_units;
                    let amount = round_to_minor_units(BigInt::from_str(amount_raw), m);
                    if amount.sign == 1 && amount.digits == vec![0] {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else if amount.sign == -1 {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else {
                        let new_balance_from = acc_from.balance.sub(&amount);
                        let neg_limit = BigInt { sign: -1, digits: acc_from.overdraft_limit.digits.clone() };
                        if new_balance_from.compare(&neg_limit) == std::cmp::Ordering::Less {
                            rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from_name));
                        } else {
                            acc_from.balance = new_balance_from;
                            acc_to.balance = acc_to.balance.add(&amount);
                        }
                    }
                }
            }
            "convert" => {
                let from_name = parts[1];
                let to_name = parts[2];
                let amount_raw = parts[3];
                let rate_raw = parts[4];
                let acc_from = accounts.get(from_name);
                let acc_to = accounts.get(to_name);
                if acc_from.is_none() {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from_name));
                } else if acc_to.is_none() {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to_name));
                } else {
                    let acc_from = acc_from.unwrap();
                    let acc_to = acc_to.unwrap();
                    let m_from = currencies.get(&acc_from.currency_code).unwrap().minor_units;
                    let m_to = currencies.get(&acc_to.currency_code).unwrap().minor_units;
                    let amount = round_to_minor_units(BigInt::from_str(amount_raw), m_from);
                    if amount.sign == 1 && amount.digits == vec![0] {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else if amount.sign == -1 {
                        rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    } else {
                        let new_balance_from = acc_from.balance.sub(&amount);
                        let neg_limit = BigInt { sign: -1, digits: acc_from.overdraft_limit.digits.clone() };
                        if new_balance_from.compare(&neg_limit) == std::cmp::Ordering::Less {
                            rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from_name));
                        } else {
                            acc_from.balance = new_balance_from;
                            let rate = BigInt::from_str(rate_raw);
                            let mut to_amount = amount.mul(&rate);
                            let divisor = BigInt::from_u64(10u64.pow(12));
                            to_amount = to_amount.div_u64(1_000_000_000_000);
                            let to_amount_rounded = round_to_minor_units(to_amount, m_to);
                            acc_to.balance = acc_to.balance.add(&to_amount_rounded);
                        }
                    }
                }
            }
            "interest" => {
                let name = parts[1];
                let rate_raw = parts[2];
                if let Some(acc) = accounts.get(name) {
                    let m = currencies.get(&acc.currency_code).unwrap().minor_units;
                    let rate = BigInt::from_str(rate_raw);
                    let mut interest_amount = acc.balance.mul(&rate);
                    interest_amount = interest_amount.div_u64(1_000_000_000_000);
                    let interest_rounded = round_to_minor_units(interest_amount, m);
                    acc.balance = acc.balance.add(&interest_rounded);
                } else {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                }
            }
            "split" => {
                let from_name = parts[1];
                let amount_raw = parts[2];
                let mut targets = Vec::new();
                let mut weights = Vec::new();
                for i in 3..parts.len() {
                    let sub_parts: Vec<&str> = parts[i].split(':').collect();
                    targets.push(sub_parts[0].to_string());
                    weights.push(sub_parts[1].parse::<u64>().unwrap());
                }
                let acc_from = accounts.get(from_name);
                if acc_from.is_none() {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from_name));
                } else {
                    let mut all_acc_known = true;
                    for t in &targets {
                        if !accounts.contains_key(t) {
                            rejections.push(format!("line {}: REJECT unknown account {}", line_num, t));
                            all_acc_known = false;
                            break;
                        }
                    }
                    if all_acc_known {
                        let acc_from = acc_from.unwrap();
                        let mut currency_mismatch = false;
                        for t in &targets {
                            if accounts.get(t).unwrap().currency_code != acc_from.currency_code {
                                currency_mismatch = true;
                                break;
                            }
                        }
                        if currency_mismatch {
                            rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                        } else {
                            let m = currencies.get(&acc_from.currency_code).unwrap().minor_units;
                            let amount = round_to_minor_units(BigInt::from_str(amount_raw), m);
                            if amount.sign == 1 && amount.digits == vec![0] {
                                rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                            } else if amount.sign == -1 {
                                rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                            } else {
                                let new_balance_from = acc_from.balance.sub(&amount);
                                let neg_limit = BigInt { sign: -1, digits: acc_from.overdraft_limit.digits.clone() };
                                if new_balance_from.compare(&neg_limit) == std::cmp::Ordering::Less {
                                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from_name));
                                } else {
                                    acc_from.balance = new_balance_from;
                                    let a_minor_units = amount.div_u64(10u64.pow((12 - m) as u32));
                                    let mut w_sum = 0u64;
                                    for &w in &weights { w_sum += w; }
                                    let mut target_amounts = Vec::new();
                                    let mut remainders = Vec::new();
                                    for i in 0..targets.len() {
                                        let prod = a_minor_units.mul_u64(weights[i]);
                                        target_amounts.push(prod.div_u64(w_sum));
                                        remainders.push(prod.rem_u64(w_sum));
                                    }
                                    let rem_total = a_minor_units.rem_u64(w_sum);
                                    let mut target_indices: Vec<usize> = (0..targets.len()).collect();
                                    target_indices.sort_by(|&a, &b| {
                                        let r_a = remainders[a];
                                        let r_b = remainders[b];
                                        if r_a != r_b {
                                            r_b.cmp(&r_a)
                                        } else {
                                            a.cmp(&b)
                                        }
                                    });
                                    for i in 0..rem_total as usize {
                                        let idx = target_indices[i];
                                        target_amounts[idx] = target_amounts[idx].add(&BigInt::from_u64(1));
                                    }
                                    for i in 0..targets.len() {
                                        let acc_to = accounts.get_mut(&targets[i]).unwrap();
                                        let m_to = currencies.get(&acc_to.currency_code).unwrap().minor_units;
                                        let val_to = target_amounts[i].mul_u64(10u64.pow((12 - m_to) as u32));
                                        acc_to.balance = acc_to.balance.add(&val_to);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            _ => {}
        }
    }

    for rej in rejections {
        println!("{}", rej);
    }
    println!();
    let mut sorted_accounts: Vec<&Account> = accounts.values().collect();
    sorted_accounts.sort_by(|a, b| a.name.cmp(&b.name));
    for acc in sorted_accounts {
        println!("{} {} {}", acc.name, acc.currency_code, format_balance(&acc.balance, currencies.get(&acc.currency_code).unwrap().minor_units));
    }
    println!();
    let mut sorted_currencies: Vec<&Currency> = currencies.values().collect();
    sorted_currencies.sort_by(|a, b| a.code.cmp(&b.code));
    for cur in sorted_currencies {
        let mut total_balance = BigInt::from_u64(0);
        let mut count = 0;
        for acc in accounts.values() {
            if acc.currency_code == cur.code {
                total_balance = total_balance.add(&acc.balance);
                count += 1;
            }
        }
        if count > 0 {
            println!("total {} {} ({} accounts)", cur.code, format_balance(&total_balance, cur.minor_units), count);
        }
    }
}

import * as fs from 'fs';

/**
 * JSON Pointer building utility.
 * Converts a path array into a JSON Pointer string.
 * Example: ['a/b', 0] -> #/a~1b/0
 */
function buildPointer(pathArray: (string | number)[]): string {
  if (pathArray.length === 0) return '#';
  return '#' + pathArray.map(part => {
    const str = String(part);
    return str.replace(/~/g, '~0').replace(/\//g, '~1');
  }).join('/');
}

/**
 * Deep equality check for JSON values.
 */
function deepEqual(a: any, b: any): boolean {
  if (typeof a !== typeof b) {
    if (a === null || b === null) return a === b;
    return false;
  }
  if (a === null || b === null) return a === b;
  if (typeof a === 'number') return a === b;
  if (typeof a === 'string') return a === b;
  if (typeof a === 'boolean') return a === b;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (typeof a === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
      if (!deepEqual(a[key], b[key])) return false;
    }
    return true;
  }
  return false;
}

/**
 * Determine the JSON type of a value.
 */
function getJsonType(v: any): string {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (typeof v === 'number') return 'number';
  if (typeof v === 'string') return 'string';
  if (typeof v === 'boolean') return 'boolean';
  if (typeof v === 'object') return 'object';
  return '';
}

/**
 * Check if a value matches a set of types.
 */
function checkType(instance: any, types: string[]): boolean {
  const type = getJsonType(instance);
  if (types.includes('number') && type === 'number') return true;
  if (types.includes('integer') && type === 'number' && Number.isInteger(instance)) return true;
  if (types.includes(type)) return true;
  return false;
}

/**
 * Check if a schema accepts an instance (no errors).
 */
function accepts(instance: any, schema: any, fullSchema: any): boolean {
  if (schema === false) return false;
  if (schema === true) return true;
  if (typeof schema === 'object' && schema !== null) {
    if (schema.$ref) {
      const ref = schema.$ref;
      let refSchema;
      if (ref === '#') {
        refSchema = fullSchema;
      } else if (ref.startsWith('#/$defs/')) {
        const defsName = ref.split('/')[2];
        refSchema = fullSchema.$defs[defsName];
      }
      return accepts(instance, refSchema, fullSchema);
    }

    if (schema.allOf) {
      return schema.allOf.every(s => accepts(instance, s, fullSchema));
    }
    if (schema.anyOf) {
      return schema.anyOf.some(s => accepts(instance, s, fullSchema));
    }
    if (schema.oneOf) {
      const count = schema.oneOf.filter(s => accepts(instance, s, fullSchema)).length;
      return count === 1;
    }
    if (schema.not) {
      return !accepts(instance, schema.not, fullSchema);
    }
    if (schema.if) {
      if (accepts(instance, schema.if, fullSchema)) {
        return accepts(instance, schema.then, fullSchema);
      } else {
        return accepts(instance, schema.else, fullSchema);
      }
    }

    const type = getJsonType(instance);
    if (schema.type && !checkType(instance, Array.isArray(schema.type) ? schema.type : [schema.type])) return false;
    if (schema.enum && !schema.enum.some(e => deepEqual(e, instance))) return false;
    if (schema.const && !deepEqual(schema.const, instance)) return false;

    if (type === 'number') {
      if (schema.minimum !== undefined && instance < schema.minimum) return false;
      if (schema.maximum !== undefined && instance > schema.maximum) return false;
      if (schema.exclusiveMinimum !== undefined && instance <= schema.exclusiveMinimum) return false;
      if (schema.exclusiveMaximum !== undefined && instance >= schema.exclusiveMaximum) return false;
    }
    if (type === 'string') {
      const len = [...instance].length;
      if (schema.minLength !== undefined && len < schema.minLength) return false;
      if (schema.maxLength !== undefined && len > schema.maxLength) return false;
    }
    if (type === 'array') {
      if (schema.minItems !== undefined && instance.length < schema.minItems) return false;
      if (schema.maxItems !== undefined && instance.length > schema.maxItems) return false;
      if (schema.uniqueItems === true) {
        for (let i = 0; i < instance.length; i++) {
          for (let j = i + 1; j < instance.length; j++) {
            if (deepEqual(instance[i], instance[j])) return false;
          }
        }
      }
    }
    if (type === 'object') {
      if (schema.minProperties !== undefined && instance.length < schema.minProperties) {
        // Note: keys.length is used for count
      }
      // Wait, the logic for properties/additionalProperties is handled by the validator.
      // But for accepts(), we just need to check basic constraints.
      const keys = Object.keys(instance);
      if (schema.minProperties !== undefined && keys.length < schema.minProperties) return false;
      if (schema.maxProperties !== undefined && keys.length > schema.maxProperties) return false;
    }
    return true;
  }
  return true;
}

/**
 * Core validation function.
 */
function validate(instance: any, schema: any, instancePath: (string | number)[], currentSchemaLocation: string[], fullSchema: any): Set<string> {
  const errors = new Set<string>();

  if (schema === false) {
    errors.add(`${buildPointer(instancePath)}||${buildPointer(currentSchemaLocation)}`);
    return errors;
  }
  if (schema === true) return errors;

  if (typeof schema === 'object' && schema !== null) {
    if (schema.$ref) {
      const ref = schema.$ref;
      let refSchema;
      let refSchemaLocation: string[];
      if (ref === '#') {
        refSchema = fullSchema;
        refSchemaLocation = [];
      } else if (ref.startsWith('#/$defs/')) {
        const defsName = ref.split('/')[2];
        refSchema = fullSchema.$defs[defsName];
        refSchemaLocation = ['$defs', defsName];
      }
      const refErrors = validate(instance, refSchema, instancePath, refSchemaLocation, fullSchema);
      for (const err of refErrors) errors.add(err);
    }

    const type = getJsonType(instance);

    // Assertion Keywords
    if (schema.type && !checkType(instance, Array.isArray(schema.type) ? schema.type : [schema.type])) {
      errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'type'])}`);
    }
    if (schema.enum && !schema.enum.some(e => deepEqual(e, instance))) {
      errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'enum'])}`);
    }
    if (schema.const && !deepEqual(schema.const, instance)) {
      errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'const'])}`);
    }

    if (type === 'number') {
      if (schema.minimum !== undefined && instance < schema.minimum) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'minimum'])}`);
      if (schema.maximum !== undefined && instance > schema.maximum) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'maximum'])}`);
      if (schema.exclusiveMinimum !== undefined && instance <= schema.exclusiveMinimum) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'exclusiveMinimum'])}`);
      if (schema.exclusiveMaximum !== undefined && instance >= schema.exclusiveMaximum) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'exclusiveMaximum'])}`);
    }

    if (type === 'string') {
      const len = [...instance].length;
      if (schema.minLength !== undefined && len < schema.minLength) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'minLength'])}`);
      if (schema.maxLength !== undefined && len > schema.maxLength) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'maxLength'])}`);
    }

    if (type === 'array') {
      if (schema.minItems !== undefined && instance.length < schema.minItems) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'minItems'])}`);
      if (schema.maxItems !== undefined && instance.length > schema.maxItems) errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'maxItems'])}`);
      if (schema.uniqueItems === true) {
        for (let i = 0; i < instance.length; i++) {
          for (let j = i + 1; j < instance.length; j++) {
            if (deepEqual(instance[i], instance[j])) {
              errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'uniqueItems'])}`);
              break;
            }
          }
        }
      }
    }

    if (type === 'object') {
      const properties = schema.properties || {};
      const additionalProperties = schema.additionalProperties;
      const keys = Object.keys(instance);

      if (schema.required) {
        schema.required.forEach((key, i) => {
          if (!(key in instance)) {
            errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'required', i])}`);
          }
        });
      }

      if (schema.minProperties !== undefined && keys.length < schema.minProperties) {
        errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'minProperties'])}`);
      }
      if (schema.maxProperties !== undefined && keys.length > schema.maxProperties) {
        errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'maxProperties'])}`);
      }

      for (const key of keys) {
        if (key in properties) {
          const subErrors = validate(instance[key], properties[key], [...instancePath, key], [...currentSchemaLocation, 'properties', key], fullSchema);
          for (const err of subErrors) errors.add(err);
        } else if (additionalProperties !== undefined) {
          const subErrors = validate(instance[key], additionalProperties, [...instancePath, key], [...currentSchemaLocation, 'additionalProperties'], fullSchema);
          for (const err of subErrors) errors.add(err);
        }
      }
    }

    // Applicators
    if (schema.prefixItems) {
      const prefixItems = schema.prefixItems;
      for (let i = 0; i < prefixItems.length; i++) {
        if (i < instance.length) {
          const subErrors = validate(instance[i], prefixItems[i], [...instancePath, i], [...currentSchemaLocation, 'prefixItems', i], fullSchema);
          for (const err of subErrors) errors.add(err);
        }
      }
    }

    if (schema.items) {
      for (let i = (schema.prefixItems ? schema.prefixItems.length : 0); i < instance.length; i++) {
        const subErrors = validate(instance[i], schema.items, [...instancePath, i], [...currentSchemaLocation, 'items'], fullSchema);
        for (const err of subErrors) errors.add(err);
      }
    }

    if (schema.allOf) {
      schema.allOf.forEach((sub, i) => {
        const subErrors = validate(instance, sub, instancePath, [...currentSchemaLocation, 'allOf', i], fullSchema);
        for (const err of subErrors) errors.add(err);
      });
    }

    if (schema.anyOf) {
      const anyOfAccepts = schema.anyOf.some(s => accepts(instance, s, fullSchema));
      if (!anyOfAccepts) {
        errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'anyOf'])}`);
      }
    }

    if (schema.oneOf) {
      const oneOfCount = schema.oneOf.filter(s => accepts(instance, s, fullSchema)).length;
      if (oneOfCount !== 1) {
        errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'oneOf'])}`);
      }
    }

    if (schema.not) {
      if (accepts(instance, schema.not, fullSchema)) {
        errors.add(`${buildPointer(instancePath)}||${buildPointer([...currentSchemaLocation, 'not'])}`);
      }
    }

    if (schema.if) {
      const ifErrors = validate(instance, schema.if, instancePath, [...currentSchemaLocation, 'if'], fullSchema);
      if (ifErrors.size === 0) {
        if (schema.then) {
          const thenErrors = validate(instance, schema.then, instancePath, [...currentSchemaLocation, 'then'], fullSchema);
          for (const err of thenErrors) errors.add(err);
        }
      } else {
        if (schema.else) {
          const elseErrors = validate(instance, schema.else, instancePath, [...currentSchemaLocation, 'else'], fullSchema);
          for (const err of elseErrors) errors.add(err);
        }
      }
    }
  }

  return errors;
}

function main() {
  const dir = process.argv[2];
  if (!dir) return;

  const schemaData = JSON.parse(fs.readFileSync(`${dir}/schema.json`, 'utf8'));
  const instancesData = JSON.parse(fs.readFileSync(`${dir}/instances.json`, 'utf8'));

  let validCount = 0;
  let invalidCount = 0;

  instancesData.forEach((instance, idx) => {
    const errors = validate(instance, schemaData, [], [], schemaData);
    if (errors.size === 0) {
      console.log(`${idx}: valid`);
      validCount++;
    } else {
      invalidCount++;
      const sortedErrors = Array.from(errors).map(err => {
        const [iPtr, sPtr] = err.split('||');
        return { iPtr, sPtr };
      }).sort((a, b) => {
        if (a.iPtr < b.iPtr) return -1;
        if (a.iPtr > b.iPtr) return 1;
        if (a.sPtr < b.sPtr) return -1;
        if (a.sPtr > b.sPtr) return 1;
        return 0;
      });
      console.log(`${idx}: invalid (${sortedErrors.length})`);
      sortedErrors.forEach(e => {
        console.log(`  ${e.iPtr} ${e.sPtr}`);
      });
    }
  });

  console.log(`valid=${validCount} invalid=${invalidCount}`);
}

main();

import * as fs from 'fs';

/**
 * JSON Pointer building utility.
 * Converts a path array into a JSON Pointer string.
 * Example: ['a/b', 0] -> #/a~1b/0
 */
function buildPointer(pathArray: (string | number)[]): string {
  if (pathArray.length === 0) return '#';
  return '#' + pathArray.map(part => {
    const str = String(part);
    return str.replace(/~/g, '~0').replace(/\//g, '~1');
  }).join('/');
}

/**
 * Deep equality check for JSON values.
 */
function deepEqual(a: any, b: any): boolean {
  if (a === null || b === null) return a === b;
  if (typeof a !== typeof b) return false;
  if (typeof a === 'number') return a === b;
  if (typeof a === 'string') return a === b;
  if (typeof a === 'boolean') return a === b;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (typeof a === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
      if (!deepEqual(a[key], b[key])) return false;
    }
    return true;
  }
  return false;
}

/**
 * Determine the JSON type of a value.
 */
function getJsonType(v: any): string {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (typeof v === 'number') return 'number';
  if (typeof v === 'string') return 'string';
  if (typeof v === 'boolean') return 'boolean';
  if (typeof v === 'object') return 'object';
  return '';
}

/**
 * Check if a value matches a set of types.
 */
function checkType(instance: any, types: string[]): boolean {
  const type = getJsonType(instance);
  if (types.includes('number') && type === 'number') return true;
  if (types.includes('integer') && type === 'number' && Number.isInteger(instance)) return true;
  if (types.includes(type)) return true;
  return false;
}

/**
 * Check if a schema accepts an instance (no errors).
 */
function accepts(instance: any, schema: any, fullSchema: any): boolean {
  const errors = validate(instance, schema, [], [], fullSchema);
  return errors.size === 0;
}

/**
 * Core validation function.
 * Returns a Set of "instance_ptr schema_ptr" strings.
 */
function validate(instance: any, schema: any, instancePath: (string | number)[], schemaPath: (string | number)[], fullSchema: any): Set<string> {
  const errors = new Set<string>();

  if (schema === true) return errors;
  if (schema === false) {
    errors.add(`${buildPointer(instancePath)} ${buildPointer(schemaPath)}`);
    return errors;
  }

  if (typeof schema === 'object' && schema !== null) {
    // Handle $ref
    if (schema.$ref) {
      const ref = schema.$ref;
      let refSchema: any;
      let refSchemaPath: (string | number)[];
      if (ref === '#') {
        refSchema = fullSchema;
        refSchemaPath = [];
      } else if (ref.startsWith('#/$defs/')) {
        const defsName = ref.split('/')[2];
        refSchema = fullSchema.$defs[defsName];
        refSchemaPath = ['$defs', defsName];
      }
      const refErrors = validate(instance, refSchema, instancePath, refSchemaPath, fullSchema);
      for (const err of refErrors) errors.add(err);
    }

    const type = getJsonType(instance);

    // Assertion Keywords
    if (schema.type && !checkType(instance, Array.isArray(schema.type) ? schema.type : [schema.type])) {
      errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'type'])}`);
    }
    if (schema.enum && !schema.enum.some(e => deepEqual(e, instance))) {
      errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'enum'])}`);
    }
    if (schema.const && !deepEqual(schema.const, instance)) {
      errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'const'])}`);
    }

    if (type === 'number') {
      if (schema.minimum !== undefined && instance < schema.minimum) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'minimum'])}`);
      if (schema.maximum !== undefined && instance > schema.maximum) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'maximum'])}`);
      if (schema.exclusiveMinimum !== undefined && instance <= schema.exclusiveMinimum) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'exclusiveMinimum'])}`);
      if (schema.exclusiveMaximum !== undefined && instance >= schema.exclusiveMaximum) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'exclusiveMaximum'])}`);
    }

    if (type === 'string') {
      const len = Array.from(instance).length;
      if (schema.minLength !== undefined && len < schema.minLength) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'minLength'])}`);
      if (schema.maxLength !== undefined && len > schema.maxLength) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'maxLength'])}`);
    }

    if (type === 'array') {
      if (schema.minItems !== undefined && instance.length < schema.minItems) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'minItems'])}`);
      if (schema.maxItems !== undefined && instance.length > schema.maxItems) errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'maxItems'])}`);
      if (schema.uniqueItems === true) {
        for (let i = 0; i < instance.length; i++) {
          for (let j = i + 1; j < instance.length; j++) {
            if (deepEqual(instance[i], instance[j])) {
              errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'uniqueItems'])}`);
              break;
            }
          }
        }
      }
    }

    if (type === 'object') {
      const keys = Object.keys(instance);
      if (schema.required) {
        schema.required.forEach((key, i) => {
          if (!(key in instance)) {
            errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'required', i])}`);
          }
        });
      }
      if (schema.minProperties !== undefined && keys.length < schema.minProperties) {
        errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'minProperties'])}`);
      }
      if (schema.maxProperties !== undefined && keys.length > schema.maxProperties) {
        errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'maxProperties'])}`);
      }

      const properties = schema.properties || {};
      for (const key of keys) {
        if (key in properties) {
          const subErrors = validate(instance[key], properties[key], [...instancePath, key], [...schemaPath, 'properties', key], fullSchema);
          for (const err of subErrors) errors.add(err);
        } else if (schema.additionalProperties !== undefined) {
          const subErrors = validate(instance[key], schema.additionalProperties, [...instancePath, key], [...schemaPath, 'additionalProperties'], fullSchema);
          for (const err of subErrors) errors.add(err);
        }
      }
    }

    // Applicators
    if (schema.prefixItems) {
      for (let i = 0; i < schema.prefixItems.length; i++) {
        if (i < instance.length) {
          const subErrors = validate(instance[i], schema.prefixItems[i], [...instancePath, i], [...schemaPath, 'prefixItems', i], fullSchema);
          for (const err of subErrors) errors.add(err);
        }
      }
    }

    if (schema.items) {
      const start = schema.prefixItems ? schema.prefixItems.length : 0;
      for (let i = start; i < instance.length; i++) {
        const subErrors = validate(instance[i], schema.items, [...instancePath, i], [...schemaPath, 'items'], fullSchema);
        for (const err of subErrors) errors.add(err);
      }
    }

    if (schema.allOf) {
      schema.allOf.forEach((sub, i) => {
        const subErrors = validate(instance, sub, instancePath, [...schemaPath, 'allOf', i], fullSchema);
        for (const err of subErrors) errors.add(err);
      });
    }

    if (schema.anyOf) {
      const anyOfAccepts = schema.anyOf.some(s => accepts(instance, s, fullSchema));
      if (!anyOfAccepts) {
        errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'anyOf'])}`);
      }
    }

    if (schema.oneOf) {
      const oneOfCount = schema.oneOf.filter(s => accepts(instance, s, fullSchema)).length;
      if (oneOfCount !== 1) {
        errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'oneOf'])}`);
      }
    }

    if (schema.not) {
      if (accepts(instance, schema.not, fullSchema)) {
        errors.add(`${buildPointer(instancePath)} ${buildPointer([...schemaPath, 'not'])}`);
      }
    }

    if (schema.if) {
      if (accepts(instance, schema.if, fullSchema)) {
        if (schema.then) {
          const thenErrors = validate(instance, schema.then, instancePath, [...schemaPath, 'then'], fullSchema);
          for (const err of thenErrors) errors.add(err);
        }
      } else {
        if (schema.else) {
          const elseErrors = validate(instance, schema.else, instancePath, [...schemaPath, 'else'], fullSchema);
          for (const err of elseErrors) errors.add(err);
        }
      }
    }
  }
  return errors;
}

function main() {
  const dir = process.argv[2];
  if (!dir) return;

  const schemaData = JSON.parse(fs.readFileSync(`${dir}/schema.json`, 'utf8'));
  const instancesData = JSON.parse(fs.readFileSync(`${dir}/instances.json`, 'utf8'));

  let validCount = 0;
  let invalidCount = 0;

  instancesData.forEach((instance, idx) => {
    const errors = validate(instance, schemaData, [], [], schemaData);
    if (errors.size === 0) {
      console.log(`${idx}: valid`);
      validCount++;
    } else {
      invalidCount++;
      const sortedErrors = Array.from(errors).map(err => {
        const [iPtr, sPtr] = err.split(' ');
        return { iPtr, sPtr };
      }).sort((a, b) => {
        if (a.iPtr < b.iPtr) return -1;
        if (a.iPtr > b.iPtr) return 1;
        if (a.sPtr < b.sPtr) return -1;
        if (a.sPtr > b.sPtr) return 1;
        return 0;
      });
      console.log(`${idx}: invalid (${sortedErrors.length})`);
      sortedErrors.forEach(e => {
        console.log(`  ${e.iPtr} ${e.sPtr}`);
      });
    }
  });

  console.log(`valid=${validCount} invalid=${invalidCount}`);
}

main();

import Foundation
import CryptoKit

/// Configuration structure for the verification settings
struct Key: Codable {
    let kid: String
    let kty: String
    let alg: String
    let k: String
}

struct Config: Codable {
    let now: Double
    let leeway: Double
    let issuer: String
    let audience: String
    let keys: [Key]
}

/// Result of the token verification process
struct VerificationResult {
    let isValid: Bool
    let error: String?
    let sub: String
    let scopes: String
}

/// Validates if a string is a valid base64url segment according to the rules:
/// - Only A-Z, a-z, 0-9, -, _
/// - No = padding
/// - Length is not 1 more than a multiple of 4 (length % 4 != 1)
func isValidBase64Url(_ segment: String) -> Bool {
    if segment.isEmpty { return false }
    if segment.count % 4 == 1 { return false }
    let allowedChars = CharacterSet(charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_")
    if segment.rangeOfCharacter(from: allowedChars.inverted) != nil { return false }
    if segment.contains("=") { return false }
    return true
}

/// Decodes a base64url string into Data
func decodeBase64Url(_ base64Url: String) -> Data? {
    let base64 = base64Url
        .replacingOccurrences(of: "-", with: "+")
        .replacingOccurrences(of: "_", with: "/")

    var padded = base64
    let padding = base64.count % 4
    if padding == 2 {
        padded += "=="
    } else if padding == 3 {
        padded += "="
    }

    return Data(base64Encoded: padded)
}

/// Verifies a JWT token against the provided configuration
func verifyToken(_ token: String, config: Config) -> VerificationResult {
    let parts = token.components(separatedBy: ".")

    // Rule 1: MALFORMED (3 segments)
    if parts.count != 3 {
        return VerificationResult(isValid: false, error: "MALFORMED", sub: "", scopes: "")
    }

    // Rule 1: MALFORMED (valid base64url)
    for part in parts {
        if !isValidBase64Url(part) {
            return VerificationResult(isValid: false, error: "MALFORMED", sub: "", scopes: "")
        }
    }

    guard let headerData = decodeBase64Url(parts[0]),
          let payloadData = decodeBase64Url(parts[1]),
          let signatureData = decodeBase64Url(parts[2]) else {
        return VerificationResult(isValid: false, error: "MALFORMED", sub: "", scopes: "")
    }

    // Rule 1: MALFORMED (JSON object check)
    guard let headerObj = try? JSONSerialization.jsonObject(with: headerData) as? [String: Any],
          let payloadObj = try? JSONSerialization.jsonObject(with: payloadData) as? [String: Any] else {
        return VerificationResult(isValid: false, error: "MALFORMED", sub: "", scopes: "")
    }

    // Rule 2: UNSUPPORTED_ALG
    guard let alg = headerObj["alg"] as? String,
          ["HS256", "HS384", "HS512"].contains(alg) else {
        return VerificationResult(isValid: false, error: "UNSUPPORTED_ALG", sub: "", scopes: "")
    }

    // Rule 3: UNKNOWN_KEY
    guard let kid = headerObj["kid"] as? String,
          let key = config.keys.first(where: { $0.kid == kid }) else {
        return VerificationResult(isValid: false, error: "UNKNOWN_KEY", sub: "", scopes: "")
    }

    // Rule 4: ALG_MISMATCH
    if key.alg != alg {
        return VerificationResult(isValid: false, error: "ALG_MISMATCH", sub: "", scopes: "")
    }

    // Rule 5: BAD_SIGNATURE
    let signingInput = parts[0] + "." + parts[1]
    guard let secretData = decodeBase64Url(key.k) else {
        return VerificationResult(isValid: false, error: "BAD_SIGNATURE", sub: "", scopes: "")
    }

    let symmetricKey = SymmetricKey(data: secretData)
    var isValidSignature = false

    if let signingInputData = signingInput.data(using: .ascii) {
        switch alg {
        case "HS256":
            let hmac = HMAC<SHA256>.authenticationCode(for: signingInputData, using: symmetricKey)
            isValidSignature = Data(hmac) == signatureData
        case "HS384":
            let hmac = HMAC<SHA384>.authenticationCode(for: signingInputData, using: symmetricKey)
            isValidSignature = Data(hmac) == signatureData
        case "HS512":
            let hmac = HMAC<SHA512>.authenticationCode(for: signingInputData, using: symmetricKey)
            isValidSignature = Data(hmac) == signatureData
        default:
            break
        }
    }

    if !isValidSignature {
        return VerificationResult(isValid: false, error: "BAD_SIGNATURE", sub: "", scopes: "")
    }

    // Rule 6: EXPIRED
    if let exp = payloadObj["exp"] as? Double {
        if config.now >= exp + config.leeway {
            return VerificationResult(isValid: false, error: "EXPIRED", sub: "", scopes: "")
        }
    }

    // Rule 7: NOT_YET_VALID
    if let nbf = payloadObj["nbf"] as? Double {
        if config.now + config.leeway < nbf {
            return VerificationResult(isValid: false, error: "NOT_YET_VALID", sub: "", scopes: "")
        }
    }

    // Rule 8: BAD_ISSUER
    guard let iss = payloadObj["iss"] as? String, iss == config.issuer else {
        return VerificationResult(isValid: false, error: "BAD_ISSUER", sub: "", scopes: "")
    }

    // Rule 9: BAD_AUDIENCE
    guard let aud = payloadObj["aud"] else {
        return VerificationResult(isValid: false, error: "BAD_AUDIENCE", sub: "", scopes: "")
    }

    if aud is NSNull {
        return VerificationResult(isValid: false, error: "BAD_AUDIENCE", sub: "", scopes: "")
    }

    if let audString = aud as? String {
        if audString != config.audience {
            return VerificationResult(isValid: false, error: "BAD_AUDIENCE", sub: "", scopes: "")
        }
    } else if let audArray = aud as? [Any] {
        var found = false
        for item in audArray {
            if let itemString = item as? String, itemString == config.audience {
                found = true
                break
            }
        }
        if !found {
            return VerificationResult(isValid: false, error: "BAD_AUDIENCE", sub: "", scopes: "")
        }
    } else {
        return VerificationResult(isValid: false, error: "BAD_AUDIENCE", sub: "", scopes: "")
    }

    // All rules passed
    let sub = payloadObj["sub"] as? String ?? ""
    let scopeRaw = payloadObj["scope"] as? String ?? ""
    let scopePieces = scopeRaw.components(separatedBy: .whitespaces).filter { !$0.isEmpty }
    let uniqueScopes = Array(Set(scopePieces)).sorted()
    let scopeString = uniqueScopes.joined(separator: ",")

    return VerificationResult(isValid: true, error: nil, sub: sub, scopes: scopeString)
}

func main() {
    let args = CommandLine.arguments
    guard args.count == 2 else { return }
    let dirPath = args[1]

    let configPath = (dirPath as NSString).appendingPathComponent("config.json")
    let tokensPath = (dirPath as NSString).appendingPathComponent("tokens.txt")

    guard let configData = try? Data(contentsOf: URL(fileURLWithPath: configPath)),
          let config = try? JSONDecoder().decode(Config.self, from: configData) else {
        return
    }

    guard let tokensContent = try? String(contentsOf: URL(fileURLWithPath: tokensPath), encoding: .utf8) else {
        return
    }

    let lines = tokensContent.components(separatedBy: .newlines)
    var validCount = 0
    var invalidCount = 0

    var lineNum = 1
    for line in lines {
        let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            lineNum += 1
            continue
        }

        let result = verifyToken(trimmed, config: config)
        if result.isValid {
            validCount += 1
            print("\(lineNum): VALID sub=\(result.sub) scope=\(result.scopes)")
        } else {
            invalidCount += 1
            print("\(lineNum): \(result.error ?? "UNKNOWN_ERROR")")
        }
        lineNum += 1
    }

    print("")
    print("valid=\(validCount) invalid=\(invalidCount)")
}

main()

