                            result = "MALFORMED";
                        } else {
                            byte[] headerBytes = Base64.getUrlDecoder().decode(segments[0]);
                            byte[] payloadBytes = Base64.getUrlDecoder().decode(segments[1]);
                            String headerStr = new String(headerBytes, StandardCharsets.UTF_8);
                            String payloadStr = new String(payloadBytes, StandardCharsets.UTF_8);

                            JsonParser headerParser = new JsonParser(headerStr);
                            Map<String, Object> header = (Map<String, Object>) headerParser.parse();
                            JsonParser payloadParser = new JsonParser(payloadStr);
                            Map<String, Object> payload = (Map<String, Object>) payloadParser.parse();

                            if (header == null || payload == null) {
                                result = "MALFORMED";
                            } else {
                                Object algObj = header.get("alg");
                                if (!(algObj instanceof String)) {
                                    result = "UNSUPPORTED_ALG";
                                } else {
                                    String alg = (String) algObj;
                                    if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512")) {
                                        result = "UNSUPPORTED_ALG";
                                    } else {
                                        Object kidObj = header.get("kid");
                                        if (!(kidObj instanceof String)) {
                                            result = "UNKNOWN_KEY";
                                        } else {
                                            String kid = (String) kidObj;
                                            Map<String, Object> key = null;
                                            for (Map<String, Object> k : keys) {
                                                if (k.get("kid").equals(kid)) {
                                                    key = k;
                                                    break;
