                                                } else {
                                                    byte[] signatureBytes = Base64.getUrlDecoder().decode(segments[2]);
                                                    byte[] expectedSignature = calculateHMAC(segments[0] + "." + segments[1], (String) key.get("k"), alg);
                                                    if (!Arrays.equals(signatureBytes, expectedSignature)) {
