    }

    private static boolean isValidBase64Url(String s) {
        if (s.isEmpty()) return false;
        if (s.length() % 4 == 1) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_')) return false;
            if (c == '=') return false;
        }
        return true;
    }

    private static byte[] calculateHMAC(String data, String secret, String alg) throws Exception {
        byte[] keyBytes = Base64.getUrlDecoder().decode(secret);
        String macName = "HmacSHA" + alg.substring(3);
        SecretKeySpec secretKey = new SecretKeySpec(keyBytes, macName);
        Mac mac = Mac.getInstance(macName);
        mac.init(secretKey);
        return mac.doFinal(data.getBytes(StandardCharsets.US_ASCII));
    }

    static class JsonParser {
        private String json;
        private int pos;
        public JsonParser(String json) { this.json = json; this.pos = 0; }
        public Object parse() throws Exception {
            skipWhitespace();
            Object res = parseValue();
            skipWhitespace();
            return res;
        }
        private void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
        }
        private Object parseValue() throws Exception {
            skipWhitespace();
            if (pos >= json.length()) throw new Exception("Unexpected end of input");
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (json.startsWith("true", pos)) { pos += 4; return true; }
            if (json.startsWith("false", pos)) { pos += 5; return false; }
            if (json.startsWith("null", pos)) { pos += 4; return null; }
            if (Character.isDigit(c) || c == '-') return parseNumber();
            throw new Exception("Invalid JSON");
        }
        private Map<String, Object> parseObject() throws Exception {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // {
            while (pos < json.length()) {
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == '}') { pos++; break; }
                String key = parseString();
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ':') pos++;
                Object val = parseValue();
                map.put(key, val);
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') pos++;
            }
            return map;
        }
        private List<Object> parseArray() throws Exception {
            List<Object> list = new ArrayList<>();
            pos++; // [
            while (pos < json.length()) {
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ']') { pos++; break; }
                list.add(parseValue());
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') pos++;
            }
            return list;
        }
        private String parseString() throws Exception {
            pos++; // "
            StringBuilder sb = new StringBuilder();
            while (pos < json.length() && json.charAt(pos) != '"') {
                char c = json.charAt(pos);
                if (c == '\\') {
                    pos++;
                    if (pos >= json.length()) throw new Exception("Unexpected end of string");
                    char next = json.charAt(pos);
                    if (next == 'u') {
                        pos += 4;
                        String hex = json.substring(pos - 4, pos);
                        sb.append((char) Integer.parseInt(hex, 16));
                    } else if (next == '"') sb.append('"');
                    else if (next == '\\') sb.append('\\');
                    else if (next == '/') sb.append('/');
                    else sb.append(next);
                } else {
                    sb.append(c);
                }
                pos++;
            }
            pos++; // "
            return sb.toString();
        }
        private Number parseNumber() throws Exception {
            int start = pos;
            while (pos < json.length() && "0123456789.-".indexOf(json.charAt(pos)) != -1) pos++;
            String s = json.substring(start, pos);
            if (s.contains(".")) return Double.parseDouble(s);
            return Long.parseLong(s);
        }
    }
}

