        public JsonParser(String json) { this.json = json; this.pos = 0; }
        public Object parse() throws Exception {
            skipWhitespace();
            Object res = parseValue();
            skipWhitespace();
            return res;
        }
        private void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
        }
        private Object parseValue() throws Exception {
            skipWhitespace();
            if (pos >= json.length()) throw new Exception("Unexpected end of input");
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (json.startsWith("true", pos)) { pos += 4; return true; }
            if (json.startsWith("false", pos)) { pos += 5; return false; }
            if (json.startsWith("null", pos)) { pos += 4; return null; }
            if (Character.isDigit(c) || c == '-') return parseNumber();
            throw new Exception("Invalid JSON");
        }
        private Map<String, Object> parseObject() throws Exception {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // {
            while (true) {
                skipWhitespace();
                if (pos >= json.length() || json.charAt(pos) == '}') {
                    if (pos < json.length()) pos++;
                    break;
                }
                String key = parseString();
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ':') pos++;
                Object val = parseValue();
                map.put(key, val);
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') {
                    pos++;
                } else {
                    break;
                }
            }
            return map;
        }
        private List<Object> parseArray() throws Exception {
            List<Object> list = new ArrayList<>();
            pos++; // [
            while (true) {
                skipWhitespace();
                if (pos >= json.length() || json.charAt(pos) == ']') {
                    if (pos < json.length()) pos++;
                    break;
                }
                list.add(parseValue());
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') {
                    pos++;
                } else {
                    break;
                }
            }
            return list;
        }
        private String parseString() throws Exception {
            if (pos >= json.length() || json.charAt(pos) != '"') throw new Exception("Expected \"");
            pos++; // "
            StringBuilder sb = new StringBuilder();
            while (pos < json.length() && json.charAt(pos) != '"') {
                char c = json.charAt(pos);
                if (c == '\\') {
                    pos++;
                    if (pos >= json.length()) throw new Exception("Unexpected end of string");
                    char next = json.charAt(pos);
                    if (next == 'u') {
                        pos += 4;
                        String hex = json.substring(pos - 4, pos);
                        sb.append((char) Integer.parseInt(hex, 16));
                    } else if (next == '"') sb.append('"');
                    else if (next == '\\') sb.append('\\');
                    else if (next == '/') sb.append('/');
                    else sb.append(next);
                } else {
                    sb.append(c);
                }
                pos++;
            }
            if (pos >= json.length()) throw new Exception("Unterminated string");
            pos++; // "
            return sb.toString();
        }
        private Number parseNumber() throws Exception {
            int start = pos;
            if (pos < json.length() && json.charAt(pos) == '-') pos++;
            while (pos < json.length() && (Character.isDigit(json.charAt(pos)) || json.charAt(pos) == '.')) {
                pos++;
            }
            String s = json.substring(start, pos);
            if (s.isEmpty()) throw new Exception("Empty number");
            if (s.contains(".")) return Double.parseDouble(s);
            return Long.parseLong(s);
        }
    }
}

import sys
import json

def deep_equal(v1, v2):
    def get_json_type(v):
        if v is None: return "null"
        if isinstance(v, bool): return "boolean"
        if isinstance(v, (int, float)): return "number"
        if isinstance(v, str): return "string"
        if isinstance(v, list): return "array"
        if isinstance(v, dict): return "object"
        return None

    t1 = get_json_type(v1)
    t2 = get_json_type(v2)
    if t1 != t2: return False
    if t1 == "number": return v1 == v2
    if t1 == "string": return v1 == v2
    if t1 == "boolean" or t1 == "null": return v1 == v2
    if t1 == "array":
        if len(v1) != len(v2): return False
        return all(deep_equal(a, b) for a, b in zip(v1, v2))
    if t1 == "object":
        if len(v1) != len(v2): return False
        for k in v1:
            if k not in v2 or not deep_equal(v1[k], v2[k]):
                return False
        return True
    return False

def print_path(path):
    res = "#"
    for token in path:
        res += "/" + token.replace("~", "~0").replace("/", "~1")
    return res

def validate(instance, schema, instance_path, schema_path, root_schema, defs):
    errors = set()
    if schema is True:
        return errors
    if schema is False:
        errors.add((instance_path, schema_path))
        return errors
    if not isinstance(schema, dict):
        return errors

    # type
    if "type" in schema:
        allowed_types = schema["type"]
        if isinstance(allowed_types, str):
            allowed_types = [allowed_types]
        match = False
        if "integer" in allowed_types:
            if isinstance(instance, (int, float)) and instance == int(instance):
                match = True
        if "number" in allowed_types:
            if isinstance(instance, (int, float)):
                match = True
        if "string" in allowed_types:
            if isinstance(instance, str):
                match = True
        if "boolean" in allowed_types:
            if isinstance(instance, bool):
                match = True
        if "null" in allowed_types:
            if instance is None:
                match = True
        if "array" in allowed_types:
            if isinstance(instance, list):
                match = True
        if "object" in allowed_types:
            if isinstance(instance, dict):
                match = True
        if not match:
            errors.add((instance_path, schema_path + ("type",)))

    # enum
    if "enum" in schema:
        if not any(deep_equal(instance, e) for e in schema["enum"]):
            errors.add((instance_path, schema_path + ("enum",)))

    # const
    if "const" in schema:
        if not deep_equal(instance, schema["const"]):
            errors.add((instance_path, schema_path + ("const",)))

    # numbers
    if "minimum" in schema:
        if not (instance >= schema["minimum"]):
            errors.add((instance_path, schema_path + ("minimum",)))
    if "maximum" in schema:
        if not (instance <= schema["maximum"]):
            errors.add((instance_path, schema_path + ("maximum",)))
    if "exclusiveMinimum" in schema:
        if not (instance > schema["exclusiveMinimum"]):
            errors.add((instance_path, schema_path + ("exclusiveMinimum",)))
    if "exclusiveMaximum" in schema:
        if not (instance < schema["exclusiveMaximum"]):
            errors.add((instance_path, schema_path + ("exclusiveMaximum",)))

    # strings
    if "minLength" in schema:
        if len(instance) < schema["minLength"]:
            errors.add((instance_path, schema_path + ("minLength",)))
    if "maxLength" in schema:
        if len(instance) > schema["maxLength"]:
            errors.add((instance_path, schema_path + ("maxLength",)))

    # arrays
    if "minItems" in schema:
        if len(instance) < schema["minItems"]:
            errors.add((instance_path, schema_path + ("minItems",)))
    if "maxItems" in schema:
        if len(instance) > schema["maxItems"]:
            errors.add((instance_path, schema_path + ("maxItems",)))
    if schema.get("uniqueItems") is True:
        seen = []
        for item in instance:
            if any(deep_equal(item, s) for s in seen):
                errors.add((instance_path, schema_path + ("uniqueItems",)))
                break
            seen.append(item)

    # prefixItems / items
    if "prefixItems" in schema:
        prefix_items = schema["prefixItems"]
        for i, subschema in enumerate(prefix_items):
            if i < len(instance):
                errors.update(validate(instance[i], subschema, instance_path + (str(i),), schema_path + ("prefixItems", str(i)), root_schema, defs))
    if "items" in schema:
        subschema = schema["items"]
        prefix_items = schema.get("prefixItems", [])
        for i in range(len(prefix_items), len(instance)):
            errors.update(validate(instance[i], subschema, instance_path + (str(i),), schema_path + ("items",), root_schema, defs))

    # objects
    if "properties" in schema:
        properties = schema["properties"]
        for name, subschema in properties.items():
            if name in instance:
                errors.update(validate(instance[name], subschema, instance_path + (name,), schema_path + ("properties", name), root_schema, defs))
    if "required" in schema:
        for j, name in enumerate(schema["required"]):
            if name not in instance:
                errors.add((instance_path, schema_path + ("required", str(j))))
    if "additionalProperties" in schema:
        subschema = schema["additionalProperties"]
        properties = schema.get("properties", {})
        for name, value in instance.items():
            if name not in properties:
                errors.update(validate(value, subschema, instance_path + (name,), schema_path + ("additionalProperties",), root_schema, defs))
    if "minProperties" in schema:
        if len(instance) < schema["minProperties"]:
            errors.add((instance_path, schema_path + ("minProperties",)))
    if "maxProperties" in schema:
        if len(instance) > schema["maxProperties"]:
            errors.add((instance_path, schema_path + ("maxProperties",)))

    # applicators
    if "allOf" in schema:
        for i, subschema in enumerate(schema["allOf"]):
            errors.update(validate(instance, subschema, instance_path, schema_path + ("allOf", str(i)), root_schema, defs))
    if "anyOf" in schema:
        subschemas = schema["anyOf"]
        any_accepted = False
        for i, subschema in enumerate(subschemas):
            if not validate(instance, subschema, instance_path, schema_path + ("anyOf", str(i)), root_schema, defs):
                any_accepted = True
                break
        if not any_accepted:
            errors.add((instance_path, schema_path + ("anyOf",)))
    if "oneOf" in schema:
        subschemas = schema["oneOf"]
        accepted_count = 0
        for i, subschema in enumerate(subschemas):
            if not validate(instance, subschema, instance_path, schema_path + ("oneOf", str(i)), root_schema, defs):
                accepted_count += 1
        if accepted_count != 1:
            errors.add((instance_path, schema_path + ("oneOf",)))
    if "not" in schema:
        if not validate(instance, schema["not"], instance_path, schema_path + ("not",), root_schema, defs):
            errors.add((instance_path, schema_path + ("not",)))
    if "if" in schema:
        if not validate(instance, schema["if"], instance_path, schema_path + ("if",), root_schema, defs):
            if "else" in schema:
                errors.update(validate(instance, schema["else"], instance_path, schema_path + ("else",), root_schema, defs))
        else:
            if "then" in schema:
                errors.update(validate(instance, schema["then"], instance_path, schema_path + ("then",), root_schema, defs))

    if "$ref" in schema:
        ref = schema["$ref"]
        if ref == "#":
            subschema = root_schema
            subschema_path = ()
        else:
            parts = ref.split("/")
            subschema_path = tuple(parts[1:])
            curr = root_schema["$defs"]
            for i in range(2, len(parts)):
                curr = curr[parts[i]]
            subschema = curr
        errors.update(validate(instance, subschema, instance_path, subschema_path, root_schema, defs))

