/**
 * Verifies JSON Web Tokens (JWT) based on specific rules.
 */

function isBase64Url(segment: string): boolean {
    if (segment.length === 0) return false;
    if (segment.length % 4 === 1) return false;
    if (segment.includes('=')) return false;
    const validChars = /^[A-Za-z0-9\-_]+$/;
    if (!validChars.test(segment)) return false;

    const charMap: Record<string, number> = {};
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_".split('').forEach((c, i) => {
        charMap[c] = i;
    });

    if (segment.length % 4 === 2) {
        const lastChar = segment[segment.length - 1];
        const val = charMap[lastChar];
        if ((val & 0xF) !== 0) return false;
    } else if (segment.length % 4 === 3) {
        const lastChar = segment[segment.length - 1];
        const val = charMap[lastChar];
        if ((val & 0x3) !== 0) return false;
    }
    return true;
}

function base64urlDecode(str: string): Buffer {
    let base64 = str.replace(/-/g, '+').replace(/_/g, '/');
    while (base64.length % 4 !== 0) {
        base64 += '=';
    }
    return Buffer.from(base64, 'base64');
}

function parseAndCheck(jsonStr: string): any {
    let i = 0;
    function skipWhitespace() {
        while (i < jsonStr.length && /\s/.test(jsonStr[i])) i++;
    }
    function parseValue(): any {
        skipWhitespace();
        if (i >= jsonStr.length) throw new Error("End of input");
        const char = jsonStr[i];
        if (char === '{') return parseObject();
        if (char === '[') return parseArray();
        if (char === '"') return parseString();
        if (char === 't' || char === 'f' || char === 'n') return parseLiteral();
        if (/[0-9\.\eE+-]/.test(char)) return parseNumber();
        throw new Error("Invalid character");
    }
    function parseObject(): any {
        i++; // {
        const obj: any = {};
        skipWhitespace();
        if (jsonStr[i] === '}') {
            i++;
            return obj;
        }
        while (true) {
            skipWhitespace();
            const key = parseString();
            if (Object.prototype.hasOwnProperty.call(obj, key)) throw new Error("Duplicate key");
            obj[key] = undefined;
            skipWhitespace();
            if (jsonStr[i] !== ':') throw new Error("Expected :");
            i++;
            obj[key] = parseValue();
            skipWhitespace();
            if (jsonStr[i] === '}') {
                i++;
                break;
            }
            if (jsonStr[i] !== ',') throw new Error("Expected ,");
            i++;
        }
        return obj;
    }
    function parseArray(): any {
        i++; // [
        const arr: any[] = [];
        skipWhitespace();
        if (jsonStr[i] === ']') {
            i++;
            return arr;
        }
        while (true) {
            arr.push(parseValue());
            skipWhitespace();
            if (jsonStr[i] === ']') {
                i++;
                break;
            }
            if (jsonStr[i] !== ',') throw new Error("Expected ,");
            i++;
        }
        return arr;
    }
    function parseString(): string {
        i++; // "
        let str = "";
        while (i < jsonStr.length && jsonStr[i] !== '"') {
            if (jsonStr[i] === '\\') {
                i++;
                const esc = jsonStr[i];
                if (esc === 'u') {
                    str += String.fromCharCode(parseInt(jsonStr.substring(i + 1, i + 5), 16));
                    i += 5;
                } else if (esc === 'n') { str += '\n'; i++; }
                else if (esc === 'r') { str += '\r'; i++; }
                else if (esc === 't') { str += '\t'; i++; }
                else if (esc === '\\') { str += '\\'; i++; }
                else if (esc === '"') { str += '"'; i++; }
                else if (esc === '/') { str += '/'; i++; }
                else { str += esc; i++; }
            } else {
                str += jsonStr[i];
                i++;
            }
        }
        i++; // "
        return str;
    }
    function parseNumber(): number {
        let start = i;
        if (jsonStr[i] === '-') i++;
        if (jsonStr[i] === '+') i++;
        while (i < jsonStr.length && /[0-9\.\eE]/.test(jsonStr[i])) i++;
        return Number(jsonStr.substring(start, i));
    }
    function parseLiteral(): any {
        let start = i;
        while (i < jsonStr.length && /[a-z]/.test(jsonStr[i])) i++;
        const val = jsonStr.substring(start, i);
        if (val === "true") return true;
        if (val === "false") return false;
        if (val === "null") return null;
        throw new Error("Invalid literal");
    }
    skipWhitespace();
    return parseValue();
}

function main() {
    const args = process.argv.slice(2);
    if (args.length < 1) return;
    const dir = args[0];

    const configRaw = fs.readFileSync(path.join(dir, 'config.json'), 'utf8');
    const config = JSON.parse(configRaw);

    const tokensRaw = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf8');
    const lines = tokensRaw.split(/\r?\n/);

    let validCount = 0;
    let invalidCount = 0;
    let output: string[] = [];

    let lineNumber = 1;
    for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed === "") continue;

        let result: string;
        const segments = trimmed.split('.');

        if (segments.length !== 3 || segments.some(s => s === "" || !isBase64Url(s))) {
            result = "MALFORMED";
        } else {
            try {
                const headerBuf = base64urlDecode(segments[0]);
                const payloadBuf = base64urlDecode(segments[1]);
                const signatureBuf = base64urlDecode(segments[2]);

                const decoder = new TextDecoder('utf-8', { fatal: true });
                const headerStr = decoder.decode(headerBuf);
                const payloadStr = decoder.decode(payloadBuf);

                const header = parseAndCheck(headerStr);
                const payload = parseAndCheck(payloadStr);

                if (typeof header !== 'object' || header === null || Array.isArray(header) ||
                    typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
                    result = "MALFORMED";
                } else {
                    if (typeof header.alg !== 'string' || !['HS256', 'HS384', 'HS512'].includes(header.alg)) {
                        result = "UNSUPPORTED_ALG";
                    } else if (typeof header.kid !== 'string' || !config.keys.find(k => k.kid === header.kid)) {
                        result = "UNKNOWN_KEY";
                    } else {
                        const key = config.keys.find(k => k.kid === header.kid)!;
                        if (key.alg !== header.alg) {
                            result = "ALG_MISMATCH";
                        } else {
                            const secret = base64urlDecode(key.k);
                            const signingInput = segments[0] + "." + segments[1];
                            const hmac = crypto.createHmac(header.alg.replace('HS', '').toLowerCase() === '256' ? 'sha256' : 
                                            header.alg.replace('HS', '').toLowerCase() === '384' ? 'sha384' : 'sha512')
                                            .update(signingInput)
                                            .digest();

                            if (!Buffer.compare(Buffer.from(segments[2], 'base64url'), hmac) === 0) {
                                // Note: Buffer.from(segments[2], 'base64url') handles the base64url decoding
                                // Let's use a more direct comparison for signature.
                                const sigDecoded = base64urlDecode(segments[2]);
                                if (!sigDecoded.equals(hmac)) {
                                    result = "BAD_SIGNATURE";
                                }
                            }

                            if (result === undefined) {
                                if (payload.exp !== undefined && config.now >= payload.exp + config.leeway) {
                                    result = "EXPIRED";
                                } else if (payload.nbf !== undefined && config.now + config.leeway < payload.nbf) {
                                    result = "NOT_YET_VALID";
                                } else if (payload.iss === undefined || payload.iss !== config.issuer) {
                                    result = "BAD_ISSUER";
                                } else if (payload.aud === undefined || 
                                           (typeof payload.aud === 'string' && payload.aud !== config.audience) ||
                                           (Array.isArray(payload.aud) && !payload.aud.includes(config.audience)) ||
                                           (typeof payload.aud !== 'string' && !Array.isArray(payload.aud))) {
                                    result = "BAD_AUDIENCE";
                                } else {
                                    result = "VALID";
                                }
                            }
                        }
                    }
                }
            } catch (e) {
                result = "MALFORMED";
            }

            if (result === "VALID") {
                const sub = payload.sub;
                const scopeRaw = payload.scope || "";
                const scopes = scopeRaw.split(/\s+/).filter(s => s.length > 0);
                const uniqueScopes = [...new Set(scopes)].sort();
                const scopeStr = uniqueScopes.join(',');
                output.push(`${lineNumber}: VALID sub=${sub} scope=${scopeStr}`);
                validCount++;
            } else {
                output.push(`${lineNumber}: ${result}`);
                invalidCount++;
            }
            lineNumber++;
        }

    }

    process.stdout.write(output.join('\n') + '\n\n');
    process.stdout.write(`valid=${validCount} invalid=${invalidCount}\n`);
}

