import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

/**
 * Verifies JSON Web Tokens (JWT) based on a configuration and a set of tokens.
 * The program checks each token against a series of rules in a specific order.
 */

/**
 * Decodes a base64url-encoded string and validates it.
 * Base64url rules:
 * - No padding '='.
 * - Characters are A-Z, a-z, 0-9, '-', '_'.
 * - Length L is not 1 mod 4.
 * - Unused bits in the last byte must be zero.
 */
function getBase64UrlBytes(segment: string): Buffer | null {
    if (segment.length === 0) return null;
    if (segment.length % 4 === 1) return null;
    if (segment.includes('=')) return null;
    if (!/^[A-Za-z0-9\-_]+$/.test(segment)) return null;

    const bits: number[] = [];
    for (let i = 0; i < segment.length; i++) {
        const char = segment[i];
        let val: number;
        if (char >= 'A' && char <= 'Z') val = char.charCodeAt(0) - 65;
        else if (char >= 'a' && char <= 'z') val = char.charCodeAt(0) - 97 + 26;
        else if (char >= '0' && char <= '9') val = char.charCodeAt(0) - 48 + 52;
        else if (char === '-') val = 62;
        else if (char === '_') val = 63;
        else return null;

        for (let j = 5; j >= 0; j--) {
            bits.push((val >> j) & 1);
        }
    }

    const numBytes = Math.floor(bits.length / 8);
    for (let i = numBytes * 8; i < bits.length; i++) {
        if (bits[i] !== 0) return null;
    }

    const bytes = new Uint8Array(numBytes);
    for (let i = 0; i < numBytes; i++) {
        let byte = 0;
        for (let j = 0; j < 8; j++) {
            byte = (byte << 1) | bits[i * 8 + j];
        }
        bytes[i] = byte;
    }
    return Buffer.from(bytes);
}

/**
 * Custom JSON parser to ensure no duplicate keys and strict object/array/literal parsing.
 */
function parseJSON(str: string): any {
    let i = 0;
    function skipWhitespace() {
        while (i < str.length && /\s/.test(str[i])) i++;
    }
    function parseValue(): any {
        skipWhitespace();
        if (i >= str.length) throw new Error("Unexpected end of input");
        const char = str[i];
        if (char === '{') return parseObject();
        if (char === '[') return parseArray();
        if (char === '"') return parseString();
        if (char === 't' || char === 'f' || char === 'n') return parseLiteral();
        if (/[0-9\.\eE+-]/.test(char)) return parseNumber();
        throw new Error("Invalid character");
    }
    function parseObject(): any {
        i++; // {
        const obj: any = {};
        skipWhitespace();
        if (str[i] === '}') {
            i++;
            return obj;
        }
        while (true) {
            skipWhitespace();
            const key = parseString();
            if (Object.prototype.hasOwnProperty.call(obj, key)) throw new Error("Duplicate key");
            obj[key] = undefined;
            skipWhitespace();
            if (str[i] !== ':') throw new Error("Expected :");
            i++;
            obj[key] = parseValue();
            skipWhitespace();
            if (str[i] === '}') {
                i++;
                break;
            }
            if (str[i] !== ',') throw new Error("Expected ,");
            i++;
        }
        return obj;
    }
    function parseArray(): any {
        i++; // [
        const arr: any[] = [];
        skipWhitespace();
        if (str[i] === ']') {
            i++;
            return arr;
        }
        while (true) {
            arr.push(parseValue());
            skipWhitespace();
            if (str[i] === ']') {
                i++;
                break;
            }
            if (str[i] !== ',') throw new Error("Expected ,");
            i++;
        }
        return arr;
    }
    function parseString(): string {
        i++; // "
        let res = "";
        while (i < str.length && str[i] !== '"') {
            if (str[i] === '\\') {
                i++;
                const esc = str[i];
                if (esc === 'u') {
                    res += String.fromCharCode(parseInt(str.substring(i + 1, i + 5), 16));
                    i += 5;
                } else if (esc === 'n') { res += '\n'; i++; }
                else if (esc === 'r') { res += '\r'; i++; }
                else if (esc === 't') { res += '\t'; i++; }
                else if (esc === '\\') { res += '\\'; i++; }
                else if (esc === '"') { res += '"'; i++; }
                else if (esc === '/') { res += '/'; i++; }
                else { res += esc; i++; }
            } else {
                res += str[i];
                i++;
            }
        }
        i++; // "
        return res;
    }
    function parseNumber(): number {
        let start = i;
        if (str[i] === '-') i++;
        if (str[i] === '+') i++;
        while (i < str.length && /[0-9\.\eE]/.test(str[i])) i++;
        return Number(str.substring(start, i));
    }
    function parseLiteral(): any {
        let start = i;
        while (i < str.length && /[a-z]/.test(str[i])) i++;
        const val = str.substring(start, i);
        if (val === "true") return true;
        if (val === "false") return false;
        if (val === "null") return null;
        throw new Error("Invalid literal");
    }
    skipWhitespace();
    return parseValue();
}

function main() {
    const args = process.argv.slice(2);
    if (args.length < 1) return;
    const dir = args[0];

    const configRaw = fs.readFileSync(path.join(dir, 'config.json'), 'utf8');
    const config = JSON.parse(configRaw);

    const tokensRaw = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf8');
    const lines = tokensRaw.split(/\r?\n/);

    let validCount = 0;
    let invalidCount = 0;
    let output: string[] = [];

    let lineNumber = 1;
    for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed === "") continue;

        let result: string | null = null;
        const segments = trimmed.split('.');

        // Rule 1: MALFORMED
        if (segments.length !== 3) {
            result = "MALFORMED";
        } else {
            const seg1Bytes = getBase64UrlBytes(segments[0]);
            const seg2Bytes = getBase64UrlBytes(segments[1]);
            const seg3Bytes = getBase64UrlBytes(segments[2]);

            if (!seg1Bytes || !seg2Bytes || !seg3Bytes) {
                result = "MALFORMED";
            } else {
                try {
                    const headerStr = new TextDecoder('utf-8', { fatal: true }).decode(seg1Bytes);
                    const payloadStr = new TextDecoder('utf-8', { fatal: true }).decode(seg2Bytes);
                    const header = parseJSON(headerStr);
                    const payload = parseJSON(payloadStr);

                    if (typeof header !== 'object' || header === null || Array.isArray(header) ||
                        typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
                        result = "MALFORMED";
                    } else {
                        // Rules 2-9
                        if (typeof header.alg !== 'string' || !['HS256', 'HS384', 'HS512'].includes(header.alg)) {
                            result = "UNSUPPORTED_ALG";
                        } else if (typeof header.kid !== 'string' || !config.keys.some(k => k.kid === header.kid)) {
                            result = "UNKNOWN_KEY";
                        } else {
                            const key = config.keys.find(k => k.kid === header.kid)!;
                            if (key.alg !== header.alg) {
                                result = "ALG_MISMATCH";
                            } else {
                                const secret = getBase64UrlBytes(key.k)!;
                                const signingInput = segments[0] + "." + segments[1];
                                const hmac = crypto.createHmac(header.alg === 'HS256' ? 'sha256' : 
                                                                header.alg === 'HS384' ? 'sha384' : 'sha512')
                                                .update(signingInput)
                                                .digest();

                                const signature = seg3Bytes;
                                if (!signature.equals(hmac)) {
                                    result = "BAD_SIGNATURE";
                                } else if (payload.exp !== undefined && config.now >= payload.exp + config.leeway) {
                                    result = "EXPIRED";
                                } else if (payload.nbf !== undefined && config.now + config.leeway < payload.nbf) {
                                    result = "NOT_YET_VALID";
                                } else if (payload.iss === undefined || payload.iss !== config.issuer) {
                                    result = "BAD_ISSUER";
                                } else if (payload.aud === undefined || 
                                           (typeof payload.aud === 'string' && payload.aud !== config.audience) ||
                                           (Array.isArray(payload.aud) && !payload.aud.includes(config.audience)) ||
                                           (typeof payload.aud !== 'string' && !Array.isArray(payload.aud))) {
                                    result = "BAD_AUDIENCE";
                                } else {
                                    result = "VALID";
                                }
                            }
                        }
                    }
                } catch (e) {
                    result = "MALFORMED";
                }
            }
        }

        if (result === "VALID") {
            const sub = payload.sub;
            const scopeRaw = payload.scope || "";
            const scopes = scopeRaw.split(/\s+/).filter(s => s.length > 0);
            const uniqueScopes = [...new Set(scopes)].sort();
            const scopeStr = uniqueScopes.join(',');
            output.push(`${lineNumber}: VALID sub=${sub} scope=${scopeStr}`);
            validCount++;
        } else {
            output.push(`${lineNumber}: ${result || "MALFORMED"}`);
            invalidCount++;
        }
        lineNumber++;
    }

    process.stdout.write(output.join('\n') + '\n\n');
    process.stdout.write(`valid=${validCount} invalid=${invalidCount}\n`);
}

