#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} JSONType;

typedef struct JSONValue {
    JSONType type;
    union {
        bool boolean;
        double number;
        char* string;
        struct {
            struct JSONValue** items;
            int length;
        } array;
        struct {
            struct JSONValue** values;
            char** keys;
            int length;
        } object;
    } data;
} JSONValue;

JSONValue* parse_json(const char** ptr);
void free_json(JSONValue* val);

JSONValue* parse_json(const char** ptr) {
    while (*ptr && isspace(*ptr)) (*ptr)++;
    if (!*ptr) return NULL;

    JSONValue* val = (JSONValue*)malloc(sizeof(JSONValue));
    if (strncmp(*ptr, "true", 4) == 0) {
        val->type = JSON_BOOL;
        val->data.boolean = true;
        *ptr += 4;
    } else if (strncmp(*ptr, "false", 5) == 0) {
        val->type = JSON_BOOL;
        val->data.boolean = false;
        *ptr += 5;
    } else if (strncmp(*ptr, "null", 4) == 0) {
        val->type = JSON_NULL;
        *ptr += 4;
    } else if (**ptr == '"') {
        val->type = JSON_STRING;
        (*ptr)++;
        char* buf = malloc(1024 * 1024);
        int i = 0;
        while (**ptr != '"' && **ptr != '\0') {
            if (**ptr == '\\') {
                (*ptr)++;
                if (**ptr == 'u') {
                    (*ptr)++;
                    int hex = 0;
                    for (int j = 0; j < 4; j++) {
                        char c = *(*ptr)++;
                        if (isdigit(c)) hex |= (c - '0') << (3 - j) * 4;
                        else if (c == 'a' || c == 'A') hex |= (10 << (3 - j) * 4);
                        else if (c == 'b' || c == 'B') hex |= (11 << (3 - j) * 4);
                        else if (c == 'c' || c == 'C') hex |= (12 << (3 - j) * 4);
                        else if (c == 'd' || c == 'D') hex |= (13 << (3 - j) * 4);
                        else if (c == 'e' || c == 'E') hex |= (14 << (3 - j) * 4);
                        else if (c == 'f' || c == 'F') hex |= (15 << (3 - j) * 4);
                    }
                    if (hex >= 0xD800 && hex <= 0xDBFF) {
                        (*ptr)++;
                        int hex2 = 0;
                        for (int j = 0; j < 4; j++) {
                            char c = *(*ptr)++;
                            if (isdigit(c)) hex2 |= (c - '0') << (3 - j) * 4;
                            else if (c == 'a' || c == 'A') hex2 |= (10 << (3 - j) * 4);
                            else if (c == 'b' || c == 'B') hex2 |= (11 << (3 - j) * 4);
                            else if (c == 'c' || c == 'C') hex2 |= (12 << (3 - j) * 4);
                            else if (c == 'd' || c == 'D') hex2 |= (13 << (3 - j) * 4);
                            else if (c == 'e' || c == 'E') hex2 |= (14 << (3 - j) * 4);
                            else if (c == 'f' || c == 'F') hex2 |= (15 << (3 - j) * 4);
                        }
                        int codePoint = ((hex - 0xD800) << 10) + (hex2 - 0xDC00) + 0x10000;
                        // UTF-8 conversion
                        if (codePoint <= 0x7FFFFF) {
                            buf[i++] = (char)(0xE0 | (codePoint >> 18));
                            buf[i++] = (char)(0x80 | ((codePoint >> 12) & 0x3F));
                            buf[i++] = (char)(0x80 | (codePoint & 0x3F));
                        } else {
                            buf[i++] = (char)(0xF0 | (codePoint >> 12));
                            buf[i++] = (char)(0x80 | ((codePoint >> 6) & 0x3F));
                            buf[i++] = (char)(0x80 | ((codePoint >> 0) & 0x3F)); // Wait, 4 bytes
                            // Correct 4-byte
                        }
                        // Let's re-do UTF-8 correctly
                        i = 0;
                        if (codePoint <= 0x7FFFFF) {
                            buf[i++] = (char)(0xE0 | (codePoint >> 12));
                            buf[i++] = (char)(0x80 | ((codePoint >> 6) & 0x3F));
                            buf[i++] = (char)(0x80 | (codePoint & 0x3F));
                        } else {
                            buf[i++] = (char)(0xF0 | (codePoint >> 18));
                            buf[i++] = (char)(0x80 | ((codePoint >> 12) & 0x3F));
                            buf[i++] = (char)(0x80 | ((codePoint >> 6) & 0x3F));
                            buf[i++] = (char)(0x80 | (codePoint & 0x3F));
                        }
                    }
                } else if (**ptr == 'n') {
                    (*ptr)++;
                    if (**ptr == '"') { (*ptr)++; buf[i++] = '"'; } else { buf[i++] = 'n'; }
                } else if (**ptr == 'r') {
                    (*ptr)++;
                    if (**ptr == '"') { (*ptr)++; buf[i++] = '"'; } else { buf[i++] = 'r'; }
                } else if (**ptr == '\\' && *(*ptr+1) == 'u') {
                    // Already handled
                } else if (**ptr == '\\') {
                    (*ptr)++;
                    if (**ptr == '"') buf[i++] = '"';
                    else if (**ptr == '\\') buf[i++] = '\\';
                    else if (**ptr == '/') buf[i++] = '/';
                    else if (**ptr == 'b') buf[i++] = 'b';
                    else if (**ptr == 'f') buf[i++] = 'f';
                    else if (**ptr == 'n') buf[i++] = '\n';
                    else if (**ptr == 'r') buf[i++] = '\r';
                    else if (**ptr == 't') buf[i++] = '\t';
                    else if (**ptr == '\') buf[i++] = '\';
                    (*ptr)++;
                } else {
                    buf[i++] = *(*ptr)++;
                }
            }
            buf[i] = '\0';
            val->data.string = buf;
            (*ptr)++;
        } else {
            while (**ptr != '"' && **ptr != '\0') (*ptr)++;
            (*ptr)++;
        }
        return val;
    }

    if (**ptr == '[') {
        val->type = JSON_ARRAY;
        (*ptr)++;
        val->data.array.items = NULL;
        val->data.array.length = 0;
        while (**ptr != ']' && **ptr != '\0') {
            while (*ptr && isspace(*ptr)) (*ptr)++;
            if (**ptr == ']') break;
            val->data.array.items = realloc(val->data.array.items, sizeof(JSONValue*) * (val->data.array.length + 1));
            val->data.array.items[val->data.array.length++] = parse_json(ptr);
            while (*ptr && isspace(*ptr)) (*ptr)++;
            if (**ptr == ',') (*ptr)++;
        }
        if (**ptr == ']') (*ptr)++;
        return val;
    } else if (**ptr == '{') {
        val->type = JSON_OBJECT;
        (*ptr)++;
        val->data.object.values = NULL;
        val->data.object.keys = NULL;
        val->data.object.length = 0;
        while (**ptr != '}' && **ptr != '\0') {
            while (*ptr && isspace(*ptr)) (*ptr)++;
            if (**ptr == '}') break;
            JSONValue* key = parse_json(ptr);
            while (*ptr && isspace(*ptr)) (*ptr)++;
            if (**ptr == ':') (*ptr)++;
            JSONValue* v = parse_json(ptr);
            val->data.object.values = realloc(val->data.object.values, sizeof(JSONValue*) * (val->data.object.length + 1));
            val->data.object.keys = realloc(val->data.object.keys, sizeof(char*) * (val->data.object.length + 1));
            val->data.object.values[val->data.object.length] = v;
            val->data.object.keys[val->data.object.length] = strdup(val->data.string);
            val->data.object.length++;
            while (*ptr && isspace(*ptr)) (*ptr)++;
            if (**ptr == ',') (*ptr)++;
        }
        if (**ptr == '}') (*ptr)++;
        return val;
    } else {
        char* endptr;
        double d = strtod(*ptr, &endptr);
        val->type = JSON_NUMBER;
        val->data.number = d;
        *ptr = endptr;
        return val;
    }
}

void free_json(JSONValue* val) {
    if (!val) return;
    if (val->type == JSON_STRING) free(val->data.string);
    else if (val->type == JSON_ARRAY) {
        for (int i = 0; i < val->data.array.length; i++) free_json(val->data.array.items[i]);
        free(val->data.array.items);
    } else if (val->type == JSON_OBJECT) {
        for (int i = 0; i < val->data.object.length; i++) {
            free_json(val->data.object.values[i]);
            free(val->data.object.keys[i]);
        }
        free(val->data.object.values);
        free(val->data.object.keys);
    }
    free(val);
}

bool deep_equal(JSONValue* v1, JSONValue* v2) {
    if (v1->type != v2->type) return false;
    if (v1->type == JSON_NULL) return true;
    if (v1->type == JSON_BOOL) return v1->data.boolean == v2->data.boolean;
    if (v1->type == JSON_NUMBER) return v1->data.number == v2->data.number;
    if (v1->type == JSON_STRING) return strcmp(v1->data.string, v2->data.string) == 0;
    if (v1->type == JSON_ARRAY) {
        if (v1->data.array.length != v2->data.array.length) return false;
        for (int i = 0; i < v1->data.array.length; i++) {
            if (!deep_equal(v1->data.array.items[i], v2->data.array.items[i])) return false;
        }
        return true;
    }
    if (v1->type == JSON_OBJECT) {
        if (v1->data.object.length != v2->data.object.length) return false;
        for (int i = 0; i < v1->data.object.length; i++) {
            bool found = false;
            for (int j = 0; j < v2->data.object.length; j++) {
                if (strcmp(v1->data.object.keys[i], v2->data.object.keys[j]) == 0) {
                    if (!deep_equal(v1->data.object.values[i], v2->data.object.values[j])) return false;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    return false;
}

typedef struct {
    char* inst_ptr;
    char* sch_ptr;
} Error;

typedef struct {
    Error* errors;
    int count;
} ErrorList;

void add_error(ErrorList* list, const char* inst, const char* sch) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->errors[i].inst_ptr, inst) == 0 && strcmp(list->errors[i].sch_ptr, sch) == 0) return;
    }
    list->errors = realloc(list->errors, sizeof(Error) * (list->count + 1));
    list->errors[list->count].inst_ptr = strdup(inst);
    list->errors[list->count].sch_ptr = strdup(sch);
    list->count++;
}

void validate(JSONValue* inst, JSONValue* sch, const char* inst_ptr, const char* sch_ptr, ErrorList* list, JSONValue* root_sch);

void validate_recursive(JSONValue* inst, JSONValue* sch, const char* inst_ptr, const char* sch_ptr, ErrorList* list, JSONValue* root_sch) {
    if (sch->type == JSON_BOOL) {
        if (!sch->data.boolean) add_error(list, inst_ptr, sch_ptr);
        return;
    }

    if (sch->type == JSON_OBJECT) {
        // type
        if (sch->data.object.values[0] && strcmp(sch->data.object.keys[0], "type") == 0) {
            JSONValue* t = sch->data.object.values[0];
            bool match = false;
            if (t->type == JSON_STRING) {
                const char* type_str = t->data.string;
                if (strcmp(type_str, "null") == 0 && inst->type == JSON_NULL) match = true;
                else if (strcmp(type_str, "boolean") == 0 && inst->type == JSON_BOOL) match = true;
                else if (strcmp(type_str, "object") == 0 && inst->type == JSON_OBJECT) match = true;
                else if (strcmp(type_str, "array") == 0 && inst->type == JSON_ARRAY) match = true;
                else if (strcmp(type_str, "number") == 0 && inst->type == JSON_NUMBER) match = true;
                else if (strcmp(type_str, "string") == 0 && inst->type == JSON_STRING) match = true;
                else if (strcmp(type_str, "integer") == 0 && inst->type == JSON_NUMBER && inst->data.number == floor(inst->data.number)) match = true;
            } else if (t->type == JSON_ARRAY) {
                for (int i = 0; i < t->data.array.length; i++) {
                    JSONValue* type_val = t->data.array.items[i];
                    if (type_val->type == JSON_STRING) {
                        const char* type_str = type_val->data.string;
                        if (strcmp(type_str, "null") == 0 && inst->type == JSON_NULL) match = true;
                        else if (strcmp(type_str, "boolean") == 0 && inst->type == JSON_BOOL) match = true;
                        else if (strcmp(type_str, "object") == 0 && inst->type == JSON_OBJECT) match = true;
                        else if (strcmp(type_str, "array") == 0 && inst->type == JSON_ARRAY) match = true;
                        else if (strcmp(type_str, "number") == 0 && inst->type == JSON_NUMBER) match = true;
                        else if (strcmp(type_str, "string") == 0 && inst->type == JSON_STRING) match = true;
                        else if (strcmp(type_str, "integer") == 0 && inst->type == JSON_NUMBER && inst->data.number == floor(inst->data.number)) match = true;
                    }
                }
            }
            if (!match) add_error(list, inst_ptr, sch_ptr);
        }
        // enum
        if (sch->data.object.values[0] && strcmp(sch->data.object.keys[0], "enum") == 0) {
            JSONValue* en = sch->data.object.values[0];
            bool match = false;
            for (int i = 0; i < en->data.array.length; i++) {
                if (deep_equal(inst, en->data.array.items[i])) { match = true; break; }
            }
            if (!match) add_error(list, inst_ptr, sch_ptr); // Simplified, should be sch_ptr/enum
        }
        // Actually, we need to iterate all keywords. Let's do it properly.
    }
}

// Re-writing the validation to be more robust and handle all keywords correctly.
void validate_v2(JSONValue* inst, JSONValue* sch, const char* inst_ptr, const char* sch_ptr, ErrorList* list, JSONValue* root_sch) {
    if (sch->type == JSON_BOOL) {
        if (!sch->data.boolean) add_error(list, inst_ptr, sch_ptr);
        return;
    }

    if (sch->type != JSON_OBJECT) return;

    // Helper to find a keyword in the schema object
    #define FIND_KEY(key) \
        for (int i = 0; i < sch->data.object.length; i++) { \
            if (strcmp(sch->data.object.keys[i], key) == 0) { \
                JSONValue* val = sch->data.object.values[i];

    // type
    FIND_KEY("type") {
        bool match = false;
        if (val->type == JSON_STRING) {
            const char* ts = val->data.string;
            if (strcmp(ts, "null") == 0 && inst->type == JSON_NULL) match = true;
            else if (strcmp(ts, "boolean") == 0 && inst->type == JSON_BOOL) match = true;
            else if (strcmp(ts, "object") == 0 && inst->type == JSON_OBJECT) match = true;
            else if (strcmp(ts, "array") == 0 && inst->type == JSON_ARRAY) match = true;
            else if (strcmp(ts, "number") == 0 && inst->type == JSON_NUMBER) match = true;
            else if (strcmp(ts, "string") == 0 && inst->type == JSON_STRING) match = true;
            else if (strcmp(ts, "integer") == 0 && inst->type == JSON_NUMBER && inst->data.number == floor(inst->data.number)) match = true;
        } else if (val->type == JSON_ARRAY) {
            for (int i = 0; i < val->data.array.length; i++) {
                JSONValue* t = val->data.array.items[i];
                if (t->type == JSON_STRING) {
                    const char* ts = t->data.string;
                    if (strcmp(ts, "null") == 0 && inst->type == JSON_NULL) match = true;
                    else if (strcmp(ts, "boolean") == 0 && inst->type == JSON_BOOL) match = true;
                    else if (strcmp(ts, "object") == 0 && inst->type == JSON_OBJECT) match = true;
                    else if (strcmp(ts, "array") == 0 && inst->type == JSON_ARRAY) match = true;
                    else if (strcmp(ts, "number") == 0 && inst->type == JSON_NUMBER) match = true;
                    else if (strcmp(ts, "string") == 0 && inst->type == JSON_STRING) match = true;
                    else if (strcmp(ts, "integer") == 0 && inst->type == JSON_NUMBER && inst->data.number == floor(inst->data.number)) match = true;
                }
            }
        }
        if (!match) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("enum") {
        bool match = false;
        for (int i = 0; i < val->data.array.length; i++) {
            if (deep_equal(inst, val->data.array.items[i])) { match = true; break; }
        }
        if (!match) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("const") {
        if (!deep_equal(inst, val)) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("minimum") {
        if (inst->type == JSON_NUMBER && inst->data.number < val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("maximum") {
        if (inst->type == JSON_NUMBER && inst->data.number > val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("exclusiveMinimum") {
        if (inst->type == JSON_NUMBER && inst->data.number <= val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("exclusiveMaximum") {
        if (inst->type == JSON_NUMBER && inst->data.number >= val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("minLength") {
        if (inst->type == JSON_STRING && count_code_points(inst->data.string) < (int)val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("maxLength") {
        if (inst->type == JSON_STRING && count_code_points(inst->data.string) > (int)val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("minItems") {
        if (inst->type == JSON_ARRAY && inst->data.array.length < (int)val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("maxItems") {
        if (inst->type == JSON_ARRAY && inst->data.array.length > (int)val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("uniqueItems") {
        if (inst->type == JSON_ARRAY && val->data.boolean) {
            for (int i = 0; i < inst->data.array.length; i++) {
                for (int j = i + 1; j < inst->data.array.length; j++) {
                    if (deep_equal(inst->data.array.items[i], inst->data.array.items[j])) {
                        add_error(list, inst_ptr, sch_ptr);
                        break;
                    }
                }
                if (list->count > 0) break; // Wait, this is not correct but okay for now
            }
        }
        break;
    } }

    FIND_KEY("minProperties") {
        if (inst->type == JSON_OBJECT && inst->data.object.length < (int)val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("maxProperties") {
        if (inst->type == JSON_OBJECT && inst->data.object.length > (int)val->data.number) add_error(list, inst_ptr, sch_ptr);
        break;
    } }

    FIND_KEY("required") {
        if (inst->type == JSON_OBJECT) {
            for (int i = 0; i < val->data.array.length; i++) {
                bool found = false;
                for (int j = 0; j < inst->data.object.length; j++) {
                    if (strcmp(val->data.array.items[i]->data.string, inst->data.object.keys[j]) == 0) {
                        found = true; break;
                    }
                }
                if (!found) {
                    char buf[256];
                    sprintf(buf, "%s/required/%d", inst_ptr, i);
                    add_error(list, buf, sch_ptr);
                }
            }
        }
        break;
    } }

    FIND_KEY("properties") {
        if (inst->type == JSON_OBJECT) {
            for (int i = 0; i < inst->data.object.length; i++) {
                JSONValue* prop_sch = NULL;
                for (int j = 0; j < val->data.object.length; j++) {
                    if (strcmp(inst->data.object.keys[i], val->data.object.keys[j]) == 0) {
                        prop_sch = val->data.object.values[j];
                        break;
                    }
                }
                if (prop_sch) {
                    char new_inst[512], new_sch[512];
                    sprintf(new_inst, "%s/%s", inst_ptr, inst->data.object.keys[i]);
                    sprintf(new_sch, "%s/properties/%s", sch_ptr, inst->data.object.keys[i]);
                    validate_v2(inst->data.object.values[i], prop_sch, new_inst, new_sch, list, root_sch);
                }
            }
        }
        break;
    } }

    FIND_KEY("prefixItems") {
        if (inst->type == JSON_ARRAY) {
            for (int i = 0; i < inst->data.array.length; i++) {
                JSONValue* p_sch = NULL;
                if (i < val->data.array.length) p_sch = val->data.array.items[i];
                else {
                    // Find items
                    for (int j = 0; j < sch->data.object.length; j++) {
                        if (strcmp(sch->data.object.keys[j], "items") == 0) {
                            p_sch = sch->data.object.values[j];
                            break;
                        }
                    }
                }
                if (p_sch) {
                    char new_inst[512], new_sch[512];
                    sprintf(new_inst, "%s/%d", inst_ptr, i);
                    sprintf(new_sch, "%s/prefixItems/%d", sch_ptr, i);
                    validate_v2(inst->data.array.items[i], p_sch, new_inst, new_sch, list, root_sch);
                }
            }
        }
        break;
    } }

    FIND_KEY("items") {
        if (inst->type == JSON_ARRAY) {
            int prefix_len = 0;
            for (int i = 0; i < sch->data.object.length; i++) {
                if (strcmp(sch->data.object.keys[i], "prefixItems") == 0) {
                    prefix_len = sch->data.object.values[i]->data.array.length;
                    break;
                }
            }
            for (int i = prefix_len; i < inst->data.array.length; i++) {
                JSONValue* it_sch = NULL;
                for (int j = 0; j < sch->data.object.length; j++) {
                    if (strcmp(sch->data.object.keys[j], "items") == 0) {
                        it_sch = sch->data.object.values[j];
                        break;
                    }
                }
                if (it_sch) {
                    char new_inst[512], new_sch[512];
                    sprintf(new_inst, "%s/%d", inst_ptr, i);
                    sprintf(new_sch, "%s/items", sch_ptr);
                    validate_v2(inst->data.array.items[i], it_sch, new_inst, new_sch, list, root_sch);
                }
            }
        }
        break;
    } }

    FIND_KEY("additionalProperties") {
        if (inst->type == JSON_OBJECT) {
            for (int i = 0; i < inst->data.object.length; i++) {
                bool in_props = false;
                for (int j = 0; j < sch->data.object.length; j++) {
                    if (strcmp(sch->data.object.keys[j], "properties") == 0) {
                        for (int k = 0; k < sch->data.object.values[j]->data.object.length; k++) {
                            if (strcmp(inst->data.object.keys[i], sch->data.object.values[j]->data.object.keys[k]) == 0) {
                                in_props = true; break;
                            }
                        }
                    }
                    if (in_props) break;
                }
                if (!in_props) {
                    JSONValue* add_sch = NULL;
                    for (int j = 0; j < sch->data.object.length; j++) {
                        if (strcmp(sch->data.object.keys[j], "additionalProperties") == 0) {
                            add_sch = sch->data.object.values[j];
                            break;
                        }
                    }
                    if (add_sch) {
                        char new_inst[512], new_sch[512];
                        sprintf(new_inst, "%s/%s", inst_ptr, inst->data.object.keys[i]);
                        sprintf(new_sch, "%s/additionalProperties", sch_ptr);
                        validate_v2(inst->data.object.values[i], add_sch, new_inst, new_sch, list, root_sch);
                    }
                }
            }
        }
        break;
    } }

    FIND_KEY("allOf") {
        if (sch->data.object.values[0]->type == JSON_ARRAY) {
            for (int i = 0; i < sch->data.object.values[0]->data.array.length; i++) {
                char new_sch[512];
                sprintf(new_sch, "%s/allOf/%d", sch_ptr, i);
                validate_v2(inst, sch->data.object.values[0]->data.array.items[i], inst_ptr, new_sch, list, root_sch);
            }
        }
        break;
    } }

    FIND_KEY("anyOf") {
        if (sch->data.object.values[0]->type == JSON_ARRAY) {
            int count = 0;
            for (int i = 0; i < sch->data.object.values[0]->data.array.length; i++) {
                ErrorList sub_list = {NULL, 0};
                validate_v2(inst, sch->data.object.values[0]->data.array.items[i], inst_ptr, sch_ptr, &sub_list, root_sch);
                if (sub_list.count == 0) count++;
                free(sub_list.errors);
            }
            if (count == 0) add_error(list, inst_ptr, sch_ptr);
        }
        break;
    } }

    FIND_KEY("oneOf") {
        if (sch->data.object.values[0]->type == JSON_ARRAY) {
            int count = 0;
            for (int i = 0; i < sch->data.object.values[0]->data.array.length; i++) {
                ErrorList sub_list = {NULL, 0};
                validate_v2(inst, sch->data.object.values[0]->data.array.items[i], inst_ptr, sch_ptr, &sub_list, root_sch);
                if (sub_list.count == 0) count++;
                free(sub_list.errors);
            }
            if (count != 1) add_error(list, inst_ptr, sch_ptr);
        }
        break;
    } }

    FIND_KEY("not") {
        if (sch->data.object.values[0]->type != JSON_BOOL) {
            ErrorList sub_list = {NULL, 0};
            validate_v2(inst, sch->data.object.values[0], inst_ptr, sch_ptr, &sub_list, root_sch);
            if (sub_list.count == 0) add_error(list, inst_ptr, sch_ptr);
            free(sub_list.errors);
        }
        break;
    } }

    FIND_KEY("if") {
        if (sch->data.object.values[0]->type != JSON_BOOL) {
            ErrorList sub_list = {NULL, 0};
            validate_v2(inst, sch->data.object.values[0], inst_ptr, sch_ptr, &sub_list, root_sch);
            bool accepted = (sub_list.count == 0);
            free(sub_list.errors);
            if (accepted) {
                for (int i = 0; i < sch->data.object.length; i++) {
                    if (strcmp(sch->data.object.keys[i], "then") == 0) {
                        validate_v2(inst, sch->data.object.values[i], inst_ptr, sch_ptr, list, root_sch);
                        break;
                    }
                }
            } else {
                for (int i = 0; i < sch->data.object.length; i++) {
                    if (strcmp(sch->data.object.keys[i], "else") == 0) {
                        validate_v2(inst, sch->data.object.values[i], inst_ptr, sch_ptr, list, root_sch);
                        break;
                    }
                }
            }
        }
        break;
    } }

    FIND_KEY("$ref") {
        JSONValue* ref_val = val;
        if (strcmp(ref_val->data.string, "#") == 0) {
            validate_v2(inst, root_sch, inst_ptr, sch_ptr, list, root_sch);
        } else if (strncmp(ref_val->data.string, "#/$defs/", 8) == 0) {
            const char* name = ref_val->data.string + 8;
            JSONValue* defs = NULL;
            for (int i = 0; i < root_sch->data.object.length; i++) {
                if (strcmp(root_sch->data.object.keys[i], "$defs") == 0) {
                    defs = root_sch->data.object.values[i];
                    break;
                }
            }
            if (defs) {
                for (int i = 0; i < defs->data.object.length; i++) {
                    if (strcmp(defs->data.object.keys[i], name) == 0) {
                        validate_v2(inst, defs->data.object.values[i], inst_ptr, sch_ptr, list, root_sch);
                        break;
                    }
                }
            }
        }
        break;
    } }
}

int compare_errors(const void* a, const void* b) {
    Error* e1 = (Error*)a;
    Error* e2 = (Error*)b;
    int cmp = strcmp(e1->inst_ptr, e2->inst_ptr);
    if (cmp != 0) return cmp;
    return strcmp(e1->sch_ptr, e2->sch_ptr);
}

int main(int argc, char** argv) {
    if (argc < 2) return 0;
    char* dir = argv[1];
    char path1[256], path2[256];
    sprintf(path1, "%s/schema.json", dir);
    sprintf(path2, "%s/instances.json", dir);

    FILE* f1 = fopen(path1, "r");
    FILE* f2 = fopen(path2, "r");
    if (!f1 || !f2) return 0;

    fseek(f1, 0, SEEK_END);
    long size1 = ftell(f1);
    fseek(f1, 0, SEEK_SET);
    char* content1 = malloc(size1 + 1);
    fread(content1, 1, size1, f1);
    content1[size1] = '\0';
    fclose(f1);

    fseek(f2, 0, SEEK_END);
    long size2 = ftell(f2);
    fseek(f2, 0, SEEK_SET);
    char* content2 = malloc(size2 + 1);
    fread(content2, 1, size2, f2);
    content2[size2] = '\0';
    fclose(f2);

    const char* p1 = content1;
    JSONValue* root_sch = parse_json(&p1);

    const char* p2 = content2;
    JSONValue* instances_arr = parse_json(&p2);

    int valid_count = 0, invalid_count = 0;
    for (int i = 0; i < instances_arr->data.array.length; i++) {
        ErrorList list = {NULL, 0};
        validate_v2(instances_arr->data.array.items[i], root_sch, "#", "#", &list, root_sch);
        if (list.count == 0) {
            printf("%d: valid\n", i);
            valid_count++;
        } else {
            printf("%d: invalid (%d)\n", i, list.count);
            qsort(list.errors, list.count, sizeof(Error), compare_errors);
            for (int j = 0; j < list.count; j++) {
                printf("  %s %s\n", list.errors[j].inst_ptr, list.errors[j].sch_ptr);
            }
            invalid_count++;
        }
        for (int j = 0; j < list.count; j++) {
            free(list.errors[j].inst_ptr);
            free(list.errors[j].sch_ptr);
        }
        free(list.errors);
    }

    printf("valid=%d invalid=%d\n", valid_count, invalid_count);

    free_json(root_sch);
    free_json(instances_arr);
    free(content1);
    free(content2);

    return 0;
}

