    title: "List keys",
    description: "List the stored keys that start with a prefix, sorted by Unicode code point.",
    inputSchema: {
      type: "object",
      properties: {
        prefix: { type: "string" }
      },
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        keys: { type: "array", items: { type: "string" } },
        count: { type: "integer" }
      },
      required: ["keys", "count"]
    }
  },
  {
    name: "sum",
    title: "Sum integers",
