      },
      required: ["numbers"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        sum: { type: "integer" },
        count: { type: "integer" }
      },
      required: ["sum", "count"]
    },
    annotations: { readOnlyHint: true, idempotentHint: true }
  },
  {
    name: "text_stats",
    title: "Text statistics",
    description: "Count the words, Unicode code points and UTF-8 bytes of a text.",
    inputSchema: {
      type: "object",
      properties: {
        text: { type: "string" }
      },
      required: ["text"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        words: { type: "integer" },
        codepoints: { type: "integer" },
        utf8_bytes: { type: "integer" }
      },
      required: ["words", "codepoints", "utf8_bytes"]
    },
    annotations: { readOnlyHint: true }
  }
];

let isInitialized = false;
const kvMap = new Map<string, string>();

function sendResponse(id: any, result?: any, error?: any) {
  const response: any = { jsonrpc: "2.0", id };
  if (result !== undefined) response.result = result;
  if (error !== undefined) response.error = error;
  process.stdout.write(JSON.stringify(response) + '\n');
}

function validateArguments(tool: ToolDefinition, args: any): string | null {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    return "arguments must be an object";
  }

  const schema = tool.inputSchema;
  const properties = schema.properties;

  const unknownArgs: string[] = [];
  for (const key in args) {
    if (!(key in properties)) {
      unknownArgs.push(key);
    }
  }
  if (unknownArgs.length > 0) {
    unknownArgs.sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
    return `unknown argument: ${unknownArgs[0]}`;
  }

  const propertyNames = Object.keys(properties);
  for (const name of propertyNames) {
    const prop = properties[name];
    const val = args[name];

    if (!(name in args)) {
      if (schema.required && schema.required.includes(name)) {
        return `missing required argument: ${name}`;
      }
      continue;
    }

    if (val === null) {
      return `argument ${name} must be ${prop.type === 'string' ? 'a string' : 'an array of integers'}`;
    }

    if (prop.type === 'string') {
      if (typeof val !== 'string') {
        return `argument ${name} must be a string`;
      }
    } else if (prop.type === 'array') {
      if (!Array.isArray(val)) {
        return `argument ${name} must be an array of integers`;
      }
      for (const item of val) {
        if (!Number.isInteger(item)) {
          return `argument ${name} must be an array of integers`;
        }
      }
    }

    if (prop.minLength !== undefined && val.length < prop.minLength) {
      return `argument ${name} must not be empty`;
    }
    if (prop.minItems !== undefined && val.length < prop.minItems) {
      return `argument ${name} must not be empty`;
    }
  }
  return null;
}

const rl = readline.createInterface({
  input: process.stdin,
  terminal: false
});

rl.on('line', (line) => {
  const trimmed = line.trim();
  if (!trimmed) return;

  let parsed: any;
  try {
    parsed = JSON.parse(trimmed);
  } catch (e) {
    sendResponse(null, undefined, { code: -32700, message: "Parse error" });
    return;
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    sendResponse(null, undefined, { code: -32600, message: "Invalid Request" });
    return;
  }

  if (!parsed.method && (parsed.result !== undefined || parsed.error !== undefined)) {
    return;
  }

  const { jsonrpc, method, id, params } = parsed;

  const hasId = parsed.hasOwnProperty('id');
  let isIdValid = true;
  if (hasId) {
    if (typeof id === 'string') {
      isIdValid = true;
    } else if (typeof id === 'number') {
      isIdValid = Number.isInteger(id);
      if (isIdValid) {
        const idMatch = trimmed.match(/"id":\s*(?:"([^"]*)"|([-+]?\d*\.?\d+([eE][-+]?\d+)?))/);
        if (idMatch && idMatch[2] !== undefined) {
          const idStr = idMatch[2];
          if (idStr.includes('.') || idStr.toLowerCase().includes('e')) {
            isIdValid = false;
          }
        }
      }
    } else {
      isIdValid = false;
    }
  }

  const isInvalidRequest =
    jsonrpc !== "2.0" ||
    typeof method !== 'string' ||
    (hasId && !isIdValid);

  if (isInvalidRequest) {
    sendResponse(hasId && isIdValid ? id : null, undefined, { code: -32600, message: "Invalid Request" });
    return;
  }

  if (!hasId) {
    return;
  }

  const validMethods = ['initialize', 'ping', 'tools/list', 'tools/call'];
  if (!validMethods.includes(method)) {
    sendResponse(id, undefined, { code: -32601, message: "Method not found" });
    return;
  }

  if (params !== undefined && (typeof params !== 'object' || params === null || Array.isArray(params))) {
    sendResponse(id, undefined, { code: -32602, message: "Invalid params" });
    return;
  }

  if (!isInitialized && method !== 'initialize' && method !== 'ping') {
    sendResponse(id, undefined, { code: -32002, message: "Server not initialized" });
    return;
  }

  if (method === 'initialize') {
    if (isInitialized) {
      sendResponse(id, undefined, { code: -32600, message: "Already initialized" });
      return;
    }
    if (!params || typeof params.protocolVersion !== 'string') {
      sendResponse(id, undefined, { code: -32602, message: "Invalid params" });
      return;
    }
    isInitialized = true;
    sendResponse(id, {
      protocolVersion: params.protocolVersion,
      capabilities: { tools: { listChanged: false } },
      serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
    });
  } else if (method === 'ping') {
    sendResponse(id, {});
  } else if (method === 'tools/list') {
    sendResponse(id, { tools });
  } else if (method === 'tools/call') {
    if (typeof params?.name !== 'string') {
      sendResponse(id, undefined, { code: -32602, message: "Invalid params" });
      return;
    }
    const tool = tools.find(t => t.name === params.name);
    if (!tool) {
      sendResponse(id, undefined, { code: -32602, message: `Unknown tool: ${params.name}` });
      return;
    }

    let args: any;
    if (params.arguments === undefined) {
      args = {};
    } else {
      const argError = validateArguments(tool, params.arguments);
      if (argError) {
        sendResponse(id, { content: [{ type: "text", text: argError }], isError: true });
        return;
      }
      args = params.arguments;
    }

    let result: any;
    switch (tool.name) {
      case 'kv_set': {
        const { key, value } = args;
        let text = "";
        if (!kvMap.has(key)) {
          kvMap.set(key, value);
          text = `created ${key}`;
        } else {
          kvMap.set(key, value);
          text = `updated ${key}`;
        }
        result = { content: [{ type: "text", text }], isError: false };
        break;
      }
      case 'kv_get': {
        const { key } = args;
        if (!kvMap.has(key)) {
          result = { content: [{ type: "text", text: `key not found: ${key}` }], isError: true };
        } else {
          result = { content: [{ type: "text", text: kvMap.get(key) }], isError: false };
        }
        break;
      }
      case 'kv_list': {
        const prefix = args.prefix || "";
        const keys = Array.from(kvMap.keys()).filter(k => k.startsWith(prefix));
        keys.sort();
        const S = { keys, count: keys.length };
        result = { content: [{ type: "text", text: JSON.stringify(S) }], structuredContent: S, isError: false };
        break;
      }
      case 'sum': {
        const { numbers } = args;
        const sum = numbers.reduce((acc, val) => acc + val, 0);
        const S = { sum, count: numbers.length };
        result = { content: [{ type: "text", text: JSON.stringify(S) }], structuredContent: S, isError: false };
        break;
      }
      case 'text_stats': {
        const { text } = args;
        const words = text.split(/[ \t\r\n]/).filter(s => s.length > 0).length;
        const codepoints = Array.from(text).length;
        const utf8_bytes = Buffer.from(text, 'utf8').length;
        const S = { words, codepoints, utf8_bytes };
        result = { content: [{ type: "text", text: JSON.stringify(S) }], structuredContent: S, isError: false };
        break;
      }
    }
    sendResponse(id, result);
  }
});

rl.on('close', () => {
  process.exit(0);
});

use std::io::{self, BufRead};

#[derive(Debug, Clone)]
enum JsonValue {
    Object(Vec<(String, JsonValue)>),
    Array(Vec<JsonValue>),
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    Null,
}

struct Parser {
    input: Vec<u8>,
    pos: usize,
}

impl Parser {
    fn new(input: Vec<u8>) -> Self {
        Parser { input, pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_whitespace();
        if self.pos >= self.input.len() {
            return Err("Unexpected EOF".to_string());
        }
        let first = self.input[self.pos];
        match first {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string(),
            b't' | b'f' => self.parse_bool(),
            b'n' => self.parse_null(),
            b'0'..=b'9' | b'-' => self.parse_number(),
            _ => Err(format!("Unexpected character: {}", first)),
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1; // skip {
        let mut map = Vec::new();
        self.skip_whitespace();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
            return Ok(JsonValue::Object(map));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.skip_whitespace();
            if self.pos >= self.input.len() || self.input[self.pos] != b':' {
                return Err("Expected ':'".to_string());
            }
            self.pos += 1;
            let value = self.parse_value()?;
            map.push((key, value));
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == b',' {
                self.pos += 1;
                self.skip_whitespace();
            } else if self.pos < self.input.len() && self.input[self.pos] == b'}' {
                self.pos += 1;
                break;
            } else {
                return Err("Expected ',' or '}'".to_string());
            }
        }
        Ok(JsonValue::Object(map))
    }

    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1; // skip [
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
            return Ok(JsonValue::Array(arr));
        }
        loop {
            arr.push(self.parse_value()?);
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == b',' {
                self.pos += 1;
                self.skip_whitespace();
            } else if self.pos < self.input.len() && self.input[self.pos] == b']' {
                self.pos += 1;
                break;
            } else {
                return Err("Expected ',' or ']'".to_string());
            }
        }
        Ok(JsonValue::Array(arr))
    }

    fn parse_string(&mut self) -> Result<JsonValue, String> {
        self.pos += 1; // skip "
        let mut s = String::new();
        while self.pos < self.input.len() && self.input[self.pos] != b'"' {
            if self.input[self.pos] == b'\\' {
                self.pos += 1;
                match self.input[self.pos] {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'b' => s.push('\x08'),
                    b'f' => s.push('\x0c'),
                    b'n' => s.push('\n'),
                    b'r' => s.push('\r'),
                    b't' => s.push('\t'),
                    _ => return Err("Invalid escape".to_string()),
                }
            } else {
                s.push(self.input[self.pos] as char);
            }
            self.pos += 1;
        }
        self.pos += 1; // skip "
        Ok(JsonValue::String(s))
    }

    fn parse_bool(&mut self) -> Result<JsonValue, String> {
        if self.input[self.pos..].starts_with(b"true") {
            self.pos += 4;
            Ok(JsonValue::Boolean(true))
        } else if self.input[self.pos..].starts_with(b"false") {
            self.pos += 5;
            Ok(JsonValue::Boolean(false))
        } else {
            Err("Expected boolean".to_string())
        }
    }

    fn parse_null(&mut self) -> Result<JsonValue, String> {
        if self.input[self.pos..].starts_with(b"null") {
            self.pos += 4;
            Ok(JsonValue::Null)
        } else {
            Err("Expected null".to_string())
        }
    }

    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        while self.pos < self.input.len() &&
              (self.input[self.pos].is_ascii_digit() ||
               self.input[self.pos] == b'.' ||
               self.input[self.pos] == b'-' ||
               self.input[self.pos] == b'+' ||
               self.input[self.pos] == b'e' ||
               self.input[self.pos] == b'E') {
            self.pos += 1;
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| "Invalid UTF-8")?;
        if s.contains('.') || s.contains('e') || s.contains('E') {
            let f = s.parse::<f64>().map_err(|_| "Invalid number")?;
            Ok(JsonValue::Float(f))
        } else {
            let i = s.parse::<i64>().map_err(|_| "Invalid integer")?;
            Ok(JsonValue::Integer(i))
        }
    }
}

fn get_property(obj: &JsonValue, key: &str) -> Option<&JsonValue> {
    if let JsonValue::Object(map) = obj {
        for (k, v) in map {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

fn serialize(value: &JsonValue) -> String {
    match value {
        JsonValue::Object(map) => {
            let mut parts = Vec::new();
            for (k, v) in map {
                parts.push(format!("\"{}\":{}", k, serialize(v)));
            }
            format!("{{{}}}", parts.join(","))
        }
        JsonValue::Array(arr) => {
            let parts: Vec<String> = arr.iter().map(|v| serialize(v)).collect();
            format!("[{}]", parts.join(","))
        }
        JsonValue::String(s) => {
            let mut escaped = String::new();
            for c in s.chars() {
                match c {
                    '"' => escaped.push_str("\\\""),
                    '\\' => escaped.push_str("\\\\"),
                    '\n' => escaped.push_str("\\n"),
                    '\r' => escaped.push_str("\\r"),
                    '\t' => escaped.push_str("\\t"),
                    _ => escaped.push(c),
                }
            }
            format!("\"{}\"", escaped)
        }
        JsonValue::Integer(i) => i.to_string(),
        JsonValue::Float(f) => f.to_string(),
        JsonValue::Boolean(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Null => "null".to_string(),
    }
}

