            let jsonrpc = get_property(&json_val, "jsonrpc");
            let method = get_property(&json_val, "method");
            let id_val = get_property(&json_val, "id");

            let is_valid_jsonrpc = matches!(jsonrpc, Some(JsonValue::String(s)) if s == "2.0");
            let is_valid_method = matches!(method, Some(JsonValue::String(_)));

            let mut valid_id = false;
