                                    ("type".to_string(), JsonValue::String("text".to_string())),
                                    ("text".to_string(), JsonValue::String(escaped)),
                                ])])),
                                ("structuredContent".to_string(), result.clone()),
                                ("isError".to_string(), JsonValue::Boolean(false)),
                            ]));
                        }
                        "text_stats" => {
                            let text = match get_property(arguments, "text") {
                                Some(JsonValue::String(s)) => s,
                                _ => {
                                    response_error = Some((-32602, "Invalid params"));
                                    break;
                                }
                            };
                            let mut words = 0;
                            let mut in_word = false;
                            for c in text.chars() {
                                if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                                    in_word = false;
                                } else if !in_word {
                                    in_word = true;
                                    words += 1;
                                }
                            }
                            let codepoints = text.chars().count() as i64;
                            let utf8_bytes = text.len() as i64;
                            let result = JsonValue::Object(vec![
                                ("words".to_string(), JsonValue::Integer(words)),
                                ("codepoints".to_string(), JsonValue::Integer(codepoints)),
                                ("utf8_bytes".to_string(), JsonValue::Integer(utf8_bytes)),
                            ]);
                            let result_json = serialize(&result);
                            let escaped = result_json.replace('"', "\\\"");
                            tool_result = Some(JsonValue::Object(vec![
                                ("content".to_string(), JsonValue::Array(vec![JsonValue::Object(vec![
                                    ("type".to_string(), JsonValue::String("text".to_string())),
                                    ("text".to_string(), JsonValue::String(escaped)),
                                ])])),
                                ("structuredContent".to_string(), result.clone()),
                                ("isError".to_string(), JsonValue::Boolean(false)),
                            ]));
                        }
                        _ => {}
                    }
                    break;
                }
                Err(e) => {
                    tool_result = Some(JsonValue::Object(vec![
                        ("content".to_string(), JsonValue::Array(vec![JsonValue::Object(vec![
                            ("type".to_string(), JsonValue::String("text".to_string())),
                            ("text".to_string(), JsonValue::String(e)),
                        ])])),
                        ("isError".to_string(), JsonValue::Boolean(true)),
                    ]));
