                }
            }
        }

        if let Some(err) = response_error {
            println!(r#"{{"jsonrpc":"2.0","id":{:?},"error":{"code":{},"message":"{}"}}}"#, id_to_use, err.0, err.1);
        } else if let Some(res) = response_result {
            println!(r#"{{"jsonrpc":"2.0","id":{:?},"result":{}}}"#, id_to_use, serialize(&res));
        }
    }
}

fn validate_arguments(tool_def: &JsonValue, arguments: &JsonValue) -> Result<(), String> {
    if let JsonValue::Object(_) = arguments {
        let properties = get_property(tool_def, "inputSchema")
            .and_then(|v| get_property(v, "properties"))
            .and_then(|v| match v {
                JsonValue::Object(m) => Some(m),
                _ => None,
            });

        let mut unknown_args = Vec::new();
        if let Some(props) = properties {
            for (k, _) in &arguments {
                if !props.iter().any(|(pk, _)| pk == k) {
                    unknown_args.push(k.clone());
                }
            }
        }
        if !unknown_args.is_empty() {
            unknown_args.sort();
            return Err(format!("unknown argument: {}", unknown_args[0]));
        }

        if let Some(props) = properties {
            for (name, _) in props {
                let arg = get_property(arguments, name);
                let schema = get_property(tool_def, "inputSchema")
                    .and_then(|v| get_property(v, "properties"))
                    .and_then(|v| match v {
                        JsonValue::Object(m) => Some(m),
                        _ => None,
                    })
                    .and_then(|m| m.iter().find(|(k, _)| k == name).map(|(_, v)| v));

                let required = get_property(tool_def, "inputSchema")
                    .and_then(|v| get_property(v, "required"))
                    .and_then(|v| match v {
                        JsonValue::Array(a) => Some(a),
                        _ => None,
                    });

                if arg.is_none() {
                    if let Some(reqs) = required {
                        if reqs.iter().any(|v| match v {
                            JsonValue::String(s) => s == name,
                            _ => false,
                        }) {
                            return Err(format!("missing required argument: {}", name));
                        }
                    }
                } else {
                    let val = arg.unwrap();
                    let is_type_ok = match schema {
                        Some(JsonValue::Object(s_props)) => {
                            let prop_schema = s_props.iter().find(|(k, _)| k == name).map(|(_, v)| v);
                            match prop_schema {
                                Some(JsonValue::Object(p)) => {
                                    let expected_type = get_property(p, "type");
                                    match expected_type {
                                        Some(JsonValue::String(t)) if t == "string" => {
                                            matches!(val, JsonValue::String(_))
                                        }
                                        Some(JsonValue::String(t)) if t == "array" => {
                                            if let JsonValue::Array(a) = val {
                                                a.iter().all(|v| matches!(v, JsonValue::Integer(_)))
                                            } else {
                                                false
                                            }
                                        }
                                        _ => false,
                                    }
                                }
                                _ => false,
                            }
                        }
                        _ => false,
                    };

                    if !is_type_ok {
                        let type_msg = match schema {
                            Some(JsonValue::Object(s_props)) => {
                                let prop_schema = s_props.iter().find(|(k, _)| k == name).map(|(_, v)| v);
                                match prop_schema {
                                    Some(JsonValue::Object(p)) => {
                                        let expected_type = get_property(p, "type");
                                        match expected_type {
                                            Some(JsonValue::String(t)) if t == "string" => "string",
                                            Some(JsonValue::String(t)) if t == "array" => "an array of integers",
                                            _ => "something else",
                                        }
                                    }
                                    _ => "something else",
                                }
                            }
                            _ => "something else",
                        };
                        return Err(format!("argument {} must be {}", name, type_msg));
                    }

                    let min_len = get_property(schema, "minLength");
                    let min_items = get_property(schema, "minItems");
                    let mut empty = false;
                    match val {
                        JsonValue::String(s) => if s.is_empty() { empty = true; },
                        JsonValue::Array(a) => if a.is_empty() { empty = true; },
                        _ => {}
                    }
                    if empty {
                        if let Some(JsonValue::Integer(l)) = min_len {
                            if l > 0 { return Err(format!("argument {} must not be empty", name)); }
                        }
                        if let Some(JsonValue::Integer(i)) = min_items {
                            if i > 0 { return Err(format!("argument {} must not be empty", name)); }
                        }
                    }
                }
            }
        }
        Ok(())
    }
}

