                    tools.add(Map.of("name", "sum", "title", "Sum integers", "description", "Add up a non-empty list of integers.", "inputSchema", Map.of("type", "object", "properties", Map.of("numbers", Map.of("type", "array", "items", Map.of("type", "integer"), "minItems", 1)), "required", List.of("numbers"), "additionalProperties", false), "outputSchema", Map.of("type", "object", "properties", Map.of("sum", Map.of("type", "integer"), "count", Map.of("type", "integer")), "required", List.of("sum", "count")), "annotations", Map.of("readOnlyHint", true, "idempotentHint", true)));
                    tools.add(Map.of("name", "text_stats", "title", "Text statistics", "description", "Count the words, Unicode code points and UTF-8 bytes of a text.", "inputSchema", Map.of("type", "object", "properties", Map.of("text", Map.of("type", "string")), "required", List.of("text"), "additionalProperties", false), "outputSchema", Map.of("type", "object", "properties", Map.of("words", Map.of("type", "integer"), "codepoints", Map.of("type", "integer"), "utf8_bytes", Map.of("type", "integer")), "required", List.of("words", "codepoints", "utf8_bytes")), "annotations", Map.of("readOnlyHint", true)));
                    System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", idObj, "result", Map.of("tools", tools))));
                } else if (method.equals("tools/call")) {
                    Map<String, Object> params = (paramsObj instanceof Map) ? (Map<String, Object>) paramsObj : new HashMap<>();
                    Object nameObj = params.get("name");
                    if (!(nameObj instanceof String)) {
                        System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", idObj, "error", Map.of("code", -32602, "message", "Invalid params"))));
                    } else {
                        String name = (String) nameObj;
                        if (!name.equals("kv_set") && !name.equals("kv_get") && !name.equals("kv_list") && !name.equals("sum") && !name.equals("text_stats")) {
                            System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", idObj, "error", Map.of("code", -32602, "message", "Unknown tool: " + name))));
                        } else {
                            Object argsObj = params.get("arguments");
                            if (params.containsKey("arguments") && !(argsObj instanceof Map)) {
                                System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", idObj, "result", Map.of("content", List.of(Map.of("type", "text", "text", "arguments must be an object")), "isError", true))));
                            } else {
