                                if (argsObj instanceof Map) arguments.putAll((Map<String, Object>) argsObj);
                                String failure = null;
                                List<String> unknownArgs = new ArrayList<>();
                                for (String key : arguments.keySet()) {
                                    if (!getSchema(name).properties.containsKey(key)) unknownArgs.add(key);
                                }
                                if (!unknownArgs.isEmpty()) {
                                    Collections.sort(unknownArgs, Comparator.comparingInt(String::codePointAt));
                                    failure = "unknown argument: " + unknownArgs.get(0);
                                } else {
                                    Map<String, Object> props = getSchema(name).properties;
                                    for (String key : getSchema(name).propertiesMapOrder) {
                                        Object val = arguments.get(key);
                                        if (val == null && getSchema(name).required.contains(key)) {
                                            failure = "missing required argument: " + key;
                                            break;
                                        }
                                        if (val != null) {
                                            Object type = props.get(key);
