                                                List<?> list = (List<?>) val;
                                                if (list.isEmpty()) {
                                                    failure = "argument " + key + " must not be empty";
                                                    break;
                                                }
                                                for (Object item : list) {
                                                    if (!(item instanceof Long)) {
                                                        failure = "argument " + key + " must be an array of integers";
                                                        break;
                                                    }
                                                }
                                                if (failure != null) break;
                                            }
