                                    for (String k : kvStore.keySet()) {
                                        if (k.startsWith(prefix)) keys.add(k);
                                    }
                                    keys.sort(Comparator.comparingInt(String::codePointAt));
                                    Map<String, Object> s = Map.of("keys", keys, "count", keys.size());
                                    System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", idObj, "result", Map.of("content", List.of(Map.of("type", "text", "text", toJson(s))), "structuredContent", s, "isError", false))));
                                } else if (name.equals("sum")) {
                                    List<Long> numbers = new ArrayList<>();
                                    for (Object n : arguments.get("numbers")) numbers.add((Long) n);
                                    long sum = 0;
                                    for (long n : numbers) sum += n;
                                    Map<String, Object> s = Map.of("sum", sum, "count", numbers.size());
                                    System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", idObj, "result", Map.of("content", List.of(Map.of("type", "text", "text", toJson(s))), "structuredContent", s, "isError", false))));
                                } else if (name.equals("text_stats")) {
                                    String text = (String) arguments.get("text");
                                    int words = 0;
                                    boolean inWord = false;
                                    for (int i = 0; i < text.length(); ) {
                                        int cp = text.codePointAt(i);
                                        if (cp == 0x0020 || cp == 0x0009 || cp == 0x000A || cp == 0x000D) {
                                            inWord = false;
                                        } else {
                                            if (!inWord) {
                                                words++;
                                                inWord = true;
                                            }
                                        }
                                        i += Character.charCount(cp);
                                    }
                                    Map<String, Object> s = Map.of("words", words, "codepoints", text.codePoints().count(), "utf8_bytes", text.getBytes(StandardCharsets.UTF_8).length);
                                    System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", idObj, "result", Map.of("content", List.of(Map.of("type", "text", "text", toJson(s))), "structuredContent", s, "isError", false))));
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                System.out.println(toJson(Map.of("jsonrpc", "2.0", "id", null, "error", Map.of("code", -32700, "message", "Parse error"))));
            }
        }
    }

    static class Schema {
        Map<String, Object> properties;
        List<String> required;
        List<String> propertiesMapOrder;
        Schema(Map<String, Object> props, List<String> req) {
            this.properties = props;
            this.required = req;
            this.propertiesMapOrder = new ArrayList<>(props.keySet());
        }
    }

    static Map<String, Schema> schemas = new HashMap<>();
    static {
        schemas.put("kv_set", new Schema(Map.of("key", Map.of("type", "string", "minLength", 1), "value", Map.of("type", "string")), List.of("key", "value")));
        schemas.put("kv_get", new Schema(Map.of("key", Map.of("type", "string", "minLength", 1)), List.of("key")));
        schemas.put("kv_list", new Schema(Map.of("prefix", Map.of("type", "string")), List.of()));
        schemas.put("sum", new Schema(Map.of("numbers", Map.of("type", "array", "items", Map.of("type", "integer"), "minItems", 1)), List.of("numbers")));
        schemas.put("text_stats", new Schema(Map.of("text", Map.of("type", "string")), List.of("text")));
    }

    static Schema getSchema(String name) {
        return schemas.get(name);
    }

    static String toJson(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof Number) {
            if (obj instanceof Long) return obj.toString();
            return Double.toString((Double) obj);
        }
        if (obj instanceof String) return "\"" + escapeJson((String) obj) + "\"";
        if (obj instanceof List) {
            StringBuilder sb = new StringBuilder("[");
            List<?> list = (List<?>) obj;
            for (int i = 0; i < list.size(); i++) {
                sb.append(toJson(list.get(i)));
                if (i < list.size() - 1) sb.append(",");
            }
            sb.append("]");
            return sb.toString();
        }
        if (obj instanceof Map) {
            StringBuilder sb = new StringBuilder("{");
            Map<?, ?> map = (Map<?, ?>) obj;
            int i = 0;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                sb.append("\"").append(escapeJson((String) entry.getKey())).append("\":").append(toJson(entry.getValue()));
                if (++i < map.size()) sb.append(",");
            }
            sb.append("}");
            return sb.toString();
        }
        return "";
    }

    static String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\b", "\\b").replace("\f", "\\f").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t");
    }

    static class JsonParser {
        private final String input;
        private int pos = 0;
        public JsonParser(String input) { this.input = input; }
        public Object parse() throws Exception {
            skipWhitespace();
            Object result = parseValue();
            skipWhitespace();
            return result;
        }
        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
        }
        private Object parseValue() throws Exception {
            skipWhitespace();
            if (pos >= input.length()) throw new Exception();
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f' || c == 'n') return parseLiteral();
            if (Character.isDigit(c) || c == '-') return parseNumber();
            throw new Exception();
        }
        private Map<String, Object> parseObject() throws Exception {
            Map<String, Object> obj = new LinkedHashMap<>();
            pos++;
            skipWhitespace();
            while (pos < input.length() && input.charAt(pos) != '}') {
                String key = parseString();
                skipWhitespace();
                pos++; // skip :
                skipWhitespace();
                obj.put(key, parseValue());
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') {
                    pos++;
                    skipWhitespace();
                }
            }
            pos++;
            return obj;
        }
        private List<Object> parseArray() throws Exception {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWhitespace();
            while (pos < input.length() && input.charAt(pos) != ']') {
                list.add(parseValue());
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') {
                    pos++;
                    skipWhitespace();
                }
            }
            pos++;
            return list;
        }
        private String parseString() throws Exception {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    char next = input.charAt(pos);
                    if (next == '"') sb.append('"');
                    else if (next == '\\') sb.append('\\');
                    else if (next == '/') sb.append('/');
                    else if (next == 'b') sb.append('\b');
                    else if (next == 'f') sb.append('\f');
                    else if (next == 'n') sb.append('\n');
                    else if (next == 'r') sb.append('\r');
                    else if (next == 't') sb.append('\t');
                    else if (next == 'u') {
                        String hex = input.substring(pos + 1, pos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        pos += 4;
                    }
                } else { sb.append(c); }
                pos++;
            }
            throw new Exception();
        }
        private Object parseLiteral() throws Exception {
            if (input.startsWith("true", pos)) { pos += 4; return true; }
            if (input.startsWith("false", pos)) { pos += 5; return false; }
            if (input.startsWith("null", pos)) { pos += 4; return null; }
            throw new Exception();
        }
        private Object parseNumber() throws Exception {
            int start = pos;
            if (input.charAt(pos) == '-') pos++;
            while (pos < input.length() && (Character.isDigit(input.charAt(pos)) || input.charAt(pos) == '.' || input.charAt(pos) == 'e' || input.charAt(pos) == 'E' || input.charAt(pos) == '+')) pos++;
            String s = input.substring(start, pos);
            if (s.contains(".") || s.toLowerCase().contains("e")) return Double.parseDouble(s);
            return Long.parseLong(s);
        }
    }
}

import * as fs from 'fs';

/**
 * A TypeScript program that renders a 2-D scene from a JSON file
 * and saves it as a PNG image, printing a summary to standard output.
 */

// --- CRC-32 and Adler-32 Utilities ---

const CRC_TABLE = new Uint32Array(256);
for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    CRC_TABLE[i] = c;
}

function crc32(data: Buffer): number {
    let crc = 0 ^ -1;
    for (let i = 0; i < data.length; i++) {
        crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ data[i]) & 0xFF];
    }
    return (crc ^ -1) >>> 0;
}

function adler32(data: Buffer): number {
    let s1 = 1;
    let s2 = 0;
    for (let i = 0; i < data.length; i++) {
        s1 = (s1 + data[i]) % 65535;
        s2 = (s2 + s1) % 65535;
    }
    return (s2 << 16) | s1;
}

// --- Scene Types and Parsing ---

interface Scene {
    width: number;
    height: number;
    background: [number, number, number];
    shapes: Shape[];
}

interface Shape {
    type: "rect" | "circle" | "triangle" | "line";
    x?: number;
    y?: number;
    w?: number;
    h?: number;
    cx?: number;
    cy?: number;
    r?: number;
    points?: [number, number][];
    x1?: number;
    y1?: number;
    x2?: number;
    y2?: number;
    color: [number, number, number, number];
}

// --- Rendering Logic ---

function blend(current: [number, number, number], shapeColor: [number, number, number, number]): [number, number, number] {
    const [dR, dG, dB] = current;
    const [sR, sG, sB, A] = shapeColor;
    const newR = Math.floor((sR * A + dR * (255 - A) + 127) / 255);
    const newG = Math.floor((sG * A + dG * (255 - A) + 127) / 255);
    const newB = Math.floor((sB * A + dB * (255 - A) + 127) / 255);
    return [newR, newG, newB];
}

function isCovered(x: number, y: number, shape: Shape): boolean {
    switch (shape.type) {
        case "rect":
            return x >= (shape.x || 0) && x < (shape.x || 0) + (shape.w || 0) &&
                   y >= (shape.y || 0) && y < (shape.y || 0) + (shape.h || 0);
        case "circle":
            return Math.pow(x - (shape.cx || 0), 2) + Math.pow(y - (shape.cy || 0), 2) <= Math.pow(shape.r || 0, 2);
        case "triangle":
            const pts = shape.points || [];
            const [x0, y0] = pts[0];
            const [x1, y1] = pts[1];
            const [x2, y2] = pts[2];
            const E0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0);
            const E1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);
            const E2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2);
            return (E0 >= 0 && E1 >= 0 && E2 >= 0) || (E0 <= 0 && E1 <= 0 && E2 <= 0);
        case "line":
            const x1 = shape.x1 || 0, y1 = shape.y1 || 0;
            const x2 = shape.x2 || 0, y2 = shape.y2 || 0;
            const r = shape.r || 0;
            const dx = x2 - x1, dy = y2 - y1;
            const L = dx * dx + dy * dy;
            const t = (x - x1) * dx + (y - y1) * dy;
            if (L === 0) return Math.pow(x - x1, 2) + Math.pow(y - y1, 2) <= r * r;
            if (t <= 0) return Math.pow(x - x1, 2) + Math.pow(y - y1, 2) <= r * r;
            if (t >= L) return Math.pow(x - x2, 2) + Math.pow(y - y2, 2) <= r * r;
            const c = (x - x1) * dy - (y - y1) * dx;
            return c * c <= r * r * L;
        default:
            return false;
    }
}

// --- Main Execution ---

function main() {
    const dirPath = process.argv[2];
    if (!dirPath) return;

    const sceneData = JSON.parse(fs.readFileSync(`${dirPath}/scene.json`, 'utf8'));
    const { width, height, background, shapes } = sceneData as Scene;

    const canvas: [number, number, number][] = new Array(width * height);
    for (let i = 0; i < width * height; i++) {
        canvas[i] = [...background];
    }

    const shapeStats: string[] = [];

    shapes.forEach((shape, index) => {
        let count = 0;
        // Optimization: Determine the bounding box for each shape to limit iteration
        let minX = 0, maxX = width - 1, minY = 0, maxY = height - 1;

        if (shape.type === "rect") {
            minX = Math.max(0, shape.x || 0);
            maxX = Math.min(width - 1, (shape.x || 0) + (shape.w || 0) - 1);
            minY = Math.max(0, shape.y || 0);
            maxY = Math.min(height - 1, (shape.y || 0) + (shape.h || 0) - 1);
        } else if (shape.type === "circle") {
            minX = Math.max(0, (shape.cx || 0) - (shape.r || 0));
            maxX = Math.min(width - 1, (shape.cx || 0) + (shape.r || 0));
            minY = Math.max(0, (shape.cy || 0) - (shape.r || 0));
            maxY = Math.min(height - 1, (shape.cy || 0) + (shape.r || 0));
        } else if (shape.type === "triangle") {
            const pts = shape.points || [];
            minX = Math.max(0, Math.min(pts[0][0], pts[1][0], pts[2][0]));
            maxX = Math.min(width - 1, Math.max(pts[0][0], pts[1][0], pts[2][0]));
            minY = Math.max(0, Math.min(pts[0][1], pts[1][1], pts[2][1]));
            maxY = Math.min(height - 1, Math.max(pts[0][1], pts[1][1], pts[2][1]));
        } else if (shape.type === "line") {
            const r = shape.r || 0;
            minX = Math.max(0, Math.min(shape.x1 || 0, shape.x2 || 0) - r);
            maxX = Math.min(width - 1, Math.max(shape.x1 || 0, shape.x2 || 0) + r);
            minY = Math.max(0, Math.min(shape.y1 || 0, shape.y2 || 0) - r);
            maxY = Math.min(height - 1, Math.max(shape.y1 || 0, shape.y2 || 0) + r);
        }

        for (let y = minY; y <= maxY; y++) {
            for (let x = minX; x <= maxX; x++) {
                if (isCovered(x, y, shape)) {
                    count++;
                    canvas[y * width + x] = blend(canvas[y * width + x], shape.color);
                }
            }
        }
        shapeStats.push(`${index + 1} ${shape.type} ${count}`);
    });

    const uniqueColors = new Set(canvas.map(c => c.join(',')));
    shapeStats.forEach(s => console.log(s));
    console.log(`colors ${uniqueColors.size}`);

    // --- PNG Generation ---

    const rawData = Buffer.alloc(width * height * 3);
    for (let i = 0; i < width * height; i++) {
        rawData[i * 3] = canvas[i][0];
        rawData[i * 3 + 1] = canvas[i][1];
        rawData[i * 3 + 2] = canvas[i][2];
    }

    // DEFLATE "stored" blocks
    const deflateBlocks: Buffer[] = [];
    const blockSize = 65535;
    for (let i = 0; i < rawData.length; i += blockSize) {
        const chunk = rawData.slice(i, i + blockSize);
        const block = Buffer.alloc(1 + chunk.length + 4);
        block.writeUInt8(0, 0); // Type 0
        chunk.copy(block, 1);
        const crc = crc32(chunk);
        block.writeUInt32LE(crc, 1 + chunk.length);
        deflateBlocks.push(block);
    }

    const deflateStream = Buffer.concat(deflateBlocks);
    const zlibData = Buffer.concat([Buffer.from([0x78, 0x01]), deflateStream]);
    const adler = adler32(deflateStream);
    const adlerBuf = Buffer.alloc(4);
    adlerBuf.writeUInt16BE((adler >> 16) & 0xFFFF, 0);
    adlerBuf.writeUInt16BE(adler & 0xFFFF, 2);
    const fullZlibData = Buffer.concat([zlibData, adlerBuf]);

    const png = Buffer.alloc(8 + 12 + 8 + 4 + 8 + 4 + 8 + 4 + 8 + 4 + 8 + 4 + 8 + 4); // Placeholder size
    let offset = 8;

    // IHDR
    const ihdrData = Buffer.alloc(12);
    ihdrData.writeUInt32LE(width, 0);
    ihdrData.writeUInt32LE(height, 4);
    ihdrData.writeUInt8(8, 8);
    ihdrData.writeUInt8(2, 9);
    ihdrData.writeUInt8(0, 10);
    ihdrData.writeUInt8(0, 11);
    const ihdrLen = 12;
    const ihdrChunk = Buffer.alloc(ihdrLen + 8 + 4);
    ihdrChunk.writeUInt32LE(ihdrLen, 0);
    ihdrChunk.write("IHDR", 4);
    ihdrChunk.set(ihdrData, 8);
    ihdrChunk.writeUInt32LE(crc32(ihdrData), 8 + ihdrLen);
    png.set(ihdrChunk, offset);
    offset += ihdrChunk.length;

    // IDAT
    const idatLen = fullZlibData.length;
    const idatChunk = Buffer.alloc(idatLen + 12 + 4);
    idatChunk.writeUInt32LE(idatLen, 0);
    idatChunk.write("IDAT", 4);
    fullZlibData.copy(idatChunk, 8);
    idatChunk.writeUInt32LE(crc32(fullZlibData), 8 + idatLen);
    png.set(idatChunk, offset);
    offset += idatChunk.length;

    // IEND
    const iendChunk = Buffer.alloc(12);
    iendChunk.writeUInt32LE(0, 0);
    iendChunk.write("IEND", 4);
    iendChunk.writeUInt32LE(crc32(Buffer.alloc(0)), 8);
    png.set(iendChunk, offset);

    fs.writeFileSync('out.png', Buffer.concat([Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]), png]));
}

main();

import * as fs from 'fs';

/**
 * A TypeScript program that renders a 2-D scene from a JSON file
 * and saves it as a PNG image, printing a summary to standard output.
 */

// --- CRC-32 and Adler-32 Utilities ---

const CRC_TABLE = new Uint32Array(256);
for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    CRC_TABLE[i] = c;
}

function crc32(data: Buffer): number {
    let crc = 0 ^ -1;
    for (let i = 0; i < data.length; i++) {
        crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ data[i]) & 0xFF];
    }
    return (crc ^ -1) >>> 0;
}

function adler32(data: Buffer): number {
    let s1 = 1;
    let s2 = 0;
    for (let i = 0; i < data.length; i++) {
        s1 = (s1 + data[i]) % 65535;
        s2 = (s2 + s1) % 65535;
    }
    return (s2 << 16) | s1;
}

// --- Scene Types ---

interface Scene {
    width: number;
    height: number;
    background: [number, number, number];
    shapes: Shape[];
}

interface Shape {
    type: "rect" | "circle" | "triangle" | "line";
    x?: number;
    y?: number;
    w?: number;
    h?: number;
    cx?: number;
    cy?: number;
    r?: number;
    points?: [number, number][];
    x1?: number;
    y1?: number;
    x2?: number;
    y2?: number;
    color: [number, number, number, number];
}

// --- Rendering Logic ---

function blend(current: [number, number, number], shapeColor: [number, number, number, number]): [number, number, number] {
    const [dR, dG, dB] = current;
    const [sR, sG, sB, A] = shapeColor;
    const newR = Math.floor((sR * A + dR * (255 - A) + 127) / 255);
    const newG = Math.floor((sG * A + dG * (255 - A) + 127) / 255);
    const newB = Math.floor((sB * A + dB * (255 - A) + 127) / 255);
    return [newR, newG, newB];
}

function isCovered(x: number, y: number, shape: Shape): boolean {
    switch (shape.type) {
        case "rect": {
            const rx = shape.x || 0;
            const ry = shape.y || 0;
            const rw = shape.w || 0;
            const rh = shape.h || 0;
            return x >= rx && x < rx + rw && y >= ry && y < ry + rh;
        }
        case "circle": {
            const cx = shape.cx || 0;
            const cy = shape.cy || 0;
            const r = shape.r || 0;
            return (x - cx) ** 2 + (y - cy) ** 2 <= r * r;
        }
        case "triangle": {
            const pts = shape.points || [];
            const [x0, y0] = pts[0];
            const [x1, y1] = pts[1];
            const [x2, y2] = pts[2];
            const E0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0);
            const E1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);
            const E2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2);
            return (E0 >= 0 && E1 >= 0 && E2 >= 0) || (E0 <= 0 && E1 <= 0 && E2 <= 0);
        }
        case "line": {
            const x1 = shape.x1 || 0, y1 = shape.y1 || 0;
            const x2 = shape.x2 || 0, y2 = shape.y2 || 0;
            const r = shape.r || 0;
            const dx = x2 - x1, dy = y2 - y1;
            const L = dx * dx + dy * dy;
            const t = (x - x1) * dx + (y - y1) * dy;
            if (L === 0) return (x - x1) ** 2 + (y - y1) ** 2 <= r * r;
            if (t <= 0) return (x - x1) ** 2 + (y - y1) ** 2 <= r * r;
            if (t >= L) return (x - x2) ** 2 + (y - y2) ** 2 <= r * r;
            const c = (x - x1) * dy - (y - y1) * dx;
            return c * c <= r * r * L;
        }
        default:
            return false;
    }
}

// --- Main Execution ---

function main() {
    const dirPath = process.argv[2];
    if (!dirPath) return;

    const sceneData = JSON.parse(fs.readFileSync(`${dirPath}/scene.json`, 'utf8'));
    const { width, height, background, shapes } = sceneData as Scene;

    // Use a 1D array to represent the canvas for performance
    const canvas: [number, number, number][] = new Array(width * height);
    for (let i = 0; i < width * height; i++) {
        canvas[i] = [...background];
    }

    const shapeStats: string[] = [];

    shapes.forEach((shape, index) => {
        let count = 0;
        let minX = 0, maxX = width - 1, minY = 0, maxY = height - 1;

        // Bounding box calculation for optimization
        if (shape.type === "rect") {
            minX = Math.max(0, shape.x || 0);
            maxX = Math.min(width - 1, (shape.x || 0) + (shape.w || 0) - 1);
            minY = Math.max(0, shape.y || 0);
            maxY = Math.min(height - 1, (shape.y || 0) + (shape.h || 0) - 1);
        } else if (shape.type === "circle") {
            minX = Math.max(0, (shape.cx || 0) - (shape.r || 0));
            maxX = Math.min(width - 1, (shape.cx || 0) + (shape.r || 0));
            minY = Math.max(0, (shape.cy || 0) - (shape.r || 0));
            maxY = Math.min(height - 1, (shape.cy || 0) + (shape.r || 0));
        } else if (shape.type === "triangle") {
            const pts = shape.points || [];
            minX = Math.max(0, Math.min(pts[0][0], pts[1][0], pts[2][0]));
            maxX = Math.min(width - 1, Math.max(pts[0][0], pts[1][0], pts[2][0]));
            minY = Math.max(0, Math.min(pts[0][1], pts[1][1], pts[2][1]));
            maxY = Math.min(height - 1, Math.max(pts[0][1], pts[1][1], pts[2][1]));
        } else if (shape.type === "line") {
            const r = shape.r || 0;
            minX = Math.max(0, Math.min(shape.x1 || 0, shape.x2 || 0) - r);
            maxX = Math.min(width - 1, Math.max(shape.x1 || 0, shape.x2 || 0) + r);
            minY = Math.max(0, Math.min(shape.y1 || 0, shape.y2 || 0) - r);
            maxY = Math.min(height - 1, Math.max(shape.y1 || 0, shape.y2 || 0) + r);
        }

        for (let y = minY; y <= maxY; y++) {
            for (let x = minX; x <= maxX; x++) {
                if (isCovered(x, y, shape)) {
                    count++;
                    canvas[y * width + x] = blend(canvas[y * width + x], shape.color);
                }
            }
        }
        shapeStats.push(`${index + 1} ${shape.type} ${count}`);
    });

    const uniqueColors = new Set(canvas.map(c => c.join(',')));
    shapeStats.forEach(s => console.log(s));
    console.log(`colors ${uniqueColors.size}`);

    // --- PNG Generation ---

    const rawData = Buffer.alloc(width * height * 3);
    for (let i = 0; i < width * height; i++) {
        rawData[i * 3] = canvas[i][0];
        rawData[i * 3 + 1] = canvas[i][1];
        rawData[i * 3 + 2] = canvas[i][2];
    }

    // DEFLATE "stored" blocks
    const deflateBlocks: Buffer[] = [];
    const blockSize = 65535;
    for (let i = 0; i < rawData.length; i += blockSize) {
        const chunk = rawData.slice(i, i + blockSize);
        const block = Buffer.alloc(1 + chunk.length + 4);
        const isLast = (i + blockSize >= rawData.length);
        block.writeUInt8(isLast ? 0x80 : 0x00, 0); // BFINAL=1 for last block, BTYPE=0
        chunk.copy(block, 1);
        const crc = crc32(chunk);
        block.writeUInt32LE(crc, 1 + chunk.length);
        deflateBlocks.push(block);
    }

    const deflateStream = Buffer.concat(deflateBlocks);
    const zlibData = Buffer.concat([Buffer.from([0x78, 0x01]), deflateStream]);
    const adler = adler32(deflateStream);
    const adlerBuf = Buffer.alloc(4);
    adlerBuf.writeUInt16BE((adler >> 16) & 0xFFFF, 0);
    adlerBuf.writeUInt16BE(adler & 0xFFFF, 2);
    const fullZlibData = Buffer.concat([zlibData, adlerBuf]);

    // PNG construction
    const chunks: { type: string, data: Buffer }[] = [];

    // IHDR
    const ihdrData = Buffer.alloc(12);
    ihdrData.writeUInt32LE(width, 0);
    ihdrData.writeUInt32LE(height, 4);
    ihdrData.writeUInt8(8, 8);
    ihdrData.writeUInt8(2, 9);
    ihdrData.writeUInt8(0, 10);
    ihdrData.writeUInt8(0, 11);
    chunks.push({ type: "IHDR", data: ihdrData });

    // IDAT
    chunks.push({ type: "IDAT", data: fullZlibData });

    // IEND
    chunks.push({ type: "IEND", data: Buffer.alloc(0) });

    const pngChunks = chunks.map(chunk => {
        const len = chunk.data.length;
        const header = Buffer.alloc(8);
        header.writeUInt32LE(len, 0);
        header.write(chunk.type, 4);
        const crc = crc32(chunk.data);
        const footer = Buffer.alloc(4);
        footer.writeUInt32LE(crc, 0);
        return Buffer.concat([header, chunk.data, footer]);
    });

    const png = Buffer.concat([
        Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
        ...pngChunks
    ]);

    fs.writeFileSync('out.png', png);
}

main();

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <time.h>

#define MAX_BUF 1048576

// --- SHA-1 Implementation ---
typedef struct {
    uint32_t state[5];
    uint64_t count;
    uint8_t buffer[64];
} SHA1_CTX;

void sha1_transform(SHA1_CTX *ctx, const uint8_t *data) {
    uint32_t w[80];
    for (int i = 0; i < 16; i++)
        w[i] = (data[i*4] << 24) | (data[i*4+1] << 16) | (data[i*4+2] << 8) | (data[i*4+3]);
    for (int i = 16; i < 80; i++)
        w[i] = (uint32_t)((w[i-3] + w[i-8] + w[i-14] + w[i-16]) ^
                 ((w[i-7] << 19) | (w[i-7] >> 13)) ^
                 ((w[i-15] << 7) | (w[i-15] >> 25)));

    uint32_t a = ctx->state[0], b = ctx->state[1], c = ctx->state[2], d = ctx->state[3], e = ctx->state[4];
    for (int i = 0; i < 80; i++) {
        uint32_t f, k;
        if (i < 20) { f = (b & c) | (~b & d); k = 0x5A827999; }
        else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1; }
        else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
        else { f = b ^ c ^ d; k = 0xCA62C1D6; }
        uint32_t temp = ((a << 5) | (a >> 27)) + f + e + k + w[i];
        e = d; d = c; c = ((b << 30) | (b >> 2)); b = a; a = temp;
    }
    ctx->state[0] += a; ctx->state[1] += b; ctx->state[2] += c; ctx->state[3] += d; ctx->state[4] += e;
}

void sha1_init(SHA1_CTX *ctx) {
    ctx->state[0] = 0x67452301; ctx->state[1] = 0xefcdab89; ctx->state[2] = 0x98badcfe;
    ctx->state[3] = 0x10325476; ctx->state[4] = 0xc3d2e1f0;
    ctx->count = 0;
}

void sha1_update(SHA1_CTX *ctx, const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        ctx->buffer[ctx->count % 64] = data[i];
        ctx->count++;
        if (ctx->count % 64 == 0) sha1_transform(ctx, ctx->buffer);
    }
}

void sha1_final(SHA1_CTX *ctx, uint8_t *digest) {
    uint64_t total_count = ctx->count;
    uint8_t last_block[64] = {0};
    uint64_t remaining = ctx->count % 64;
    memcpy(last_block, ctx->buffer, remaining);
    last_block[remaining] = 0x80;
    if (remaining >= 56) {
        sha1_transform(ctx, last_block);
        memset(last_block, 0, 64);
    }
    for (int i = 0; i < 8; i++) last_block[56 + i] = (total_count >> (56 - i * 8)) & 0xFF;
    sha1_transform(ctx, last_block);
    for (int i = 0; i < 5; i++) {
        digest[i*4] = (ctx->state[i] >> 24) & 0xFF;
        digest[i*4+1] = (ctx->state[i] >> 16) & 0xFF;
        digest[i*4+2] = (ctx->state[i] >> 8) & 0xFF;
        digest[i*4+3] = ctx->state[i] & 0xFF;
    }
}

// --- Base64 Implementation ---
const char *base64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

char *base64_encode(const uint8_t *data, size_t len) {
    size_t out_len = 4 * ((len + 2) / 3);
    char *out = malloc(out_len + 1);
    for (size_t i = 0, j = 0; i < len; ) {
        uint32_t val = data[i] << 16;
        if (i + 1 < len) val |= data[i+1] << 8;
        if (i + 2 < len) val |= data[i+2];
        i += 3;
        out[j++] = base64_chars[(val >> 18) & 0x3F];
        out[j++] = base64_chars[(val >> 12) & 0x3F];
        out[j++] = (i <= len) ? base64_chars[(val >> 6) & 0x3F] : '=';
        out[j++] = (i <= len) ? base64_chars[val & 0x3F] : '=';
    }
    out[out_len] = '\0';
    return out;
}

// --- WebSocket Logic ---
void send_frame(int fd, uint8_t opcode, const uint8_t *payload, size_t len) {
    uint8_t *buf = malloc(len + 10);
    buf[0] = 0x80 | opcode;
    if (len <= 125) {
        buf[1] = (uint8_t)len | 0x80;
        memcpy(buf + 2, payload, len);
    } else if (len <= 65535) {
        buf[1] = 126 | 0x80;
        uint16_t nlen = htons((uint16_t)len);
        memcpy(buf + 2, &nlen, 2);
        memcpy(buf + 4, payload, len);
    } else {
        buf[1] = 127 | 0x80;
        for (int i = 0; i < 8; i++) buf[2 + i] = (len >> (56 - i * 8)) & 0xFF;
        memcpy(buf + 10, payload, len);
    }
    uint8_t mask[4];
    for (int i = 0; i < 4; i++) mask[i] = rand() % 256;
    while (mask[0] == mask[1] && mask[1] == mask[2] && mask[2] == mask[3] && mask[0] == 0) {
        for (int i = 0; i < 4; i++) mask[i] = rand() % 256;
    }
    int mask_pos = (len <= 125) ? 2 : (len <= 65535 ? 4 : 10);
    memcpy(buf + mask_pos, mask, 4);
    uint8_t *masked_payload = malloc(len);
    for (size_t i = 0; i < len; i++) masked_payload[i] = payload[i] ^ mask[i % 4];
    memcpy(buf + mask_pos + 4, masked_payload, len);
    send(fd, buf, mask_pos + 4 + len, 0);
    free(masked_payload);
    free(buf);
}

void handle_session(const char *url, int session_num) {
    printf("session %d\n", session_num);
    char host[256], path[1024];
    int port;
    sscanf(url, "ws://%[^:]:%d%s", host, &port, path);

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct hostent *he = gethostbyname(host);
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    memcpy(&addr.sin_addr, he->h_addr, he->h_length);

    if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) return;

    uint8_t key_bytes[16];
    for (int i = 0; i < 16; i++) key_bytes[i] = rand() % 256;
    char *key_b64 = base64_encode(key_bytes, 16);

    char req[2048];
    sprintf(req, "GET %s HTTP/1.1\r\nHost: %s:%d\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: %s\r\n\r\n", path, host, port, key_b64);
    send(sockfd, req, strlen(req), 0);
    free(key_b64);

    char resp[MAX_BUF];
    int bytes_read = 0;
    while (1) {
        int n = recv(sockfd, resp + bytes_read, MAX_BUF - bytes_read - 1, 0);
        if (n <= 0) break;
        bytes_read += n;
        if (strstr(resp, "\r\n\r\n")) break;
    }

    char *status_line = strstr(resp, "HTTP/1.1");
    if (!status_line) { close(sockfd); return; }
    int status_code = 0;
    sscanf(status_line, "HTTP/1.1 %d", &status_code);
    if (status_code != 101) {
        printf("handshake failed: %d %s\n", status_code, strchr(status_line, ' ') + 1);
        close(sockfd); return;
    }

    char *accept_header = strstr(resp, "Sec-WebSocket-Accept:");
    if (!accept_header) { printf("handshake failed: bad Sec-WebSocket-Accept\n"); close(sockfd); return; }

    char key_str[128];
    sprintf(key_str, "%s", key_b64);
    SHA1_CTX sha_ctx;
    sha1_init(&sha_ctx);
    sha1_update(&sha_ctx, (uint8_t*)key_str, strlen(key_str));
    sha1_update(&sha_ctx, (uint8_t*)"258EAFA5-E914-47DA-95CA-C5AB0DC85B11", 24);
    uint8_t digest[20];
    sha1_final(&sha_ctx, digest);
    char *expected_accept = base64_encode(digest, 20);

    char *actual_accept = strchr(accept_header, ':') + 1;
    while (*actual_accept == ' ') actual_accept++;
    char *end_line = strchr(actual_accept, '\r');
    size_t accept_len = end_line - actual_accept;

    if (strncmp(actual_accept, expected_accept, accept_len) != 0 || strlen(expected_accept) != accept_len) {
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        free(expected_accept); close(sockfd); return;
    }
    free(expected_accept);

    int frame_start = bytes_read;
    uint8_t *msg_buf = NULL;
    size_t msg_len = 0;
    int waiting_for_sha1 = 0;
    int closed_sent = 0;
    int is_bye = 0;

    while (1) {
        uint8_t head[10];
        int h_bytes = recv(sockfd, head, 10, 0);
        if (h_bytes <= 0) break;

        uint8_t opcode = head[0] & 0x0F;
        uint8_t fin = head[0] & 0x80;
        uint8_t len_code = head[1] & 0x7F;
        size_t payload_len = 0;
        int header_size = 0;

        if (len_code <= 125) { payload_len = len_code; header_size = 2; }
        else if (len_code == 126) {
            uint16_t nlen;
            memcpy(&nlen, head + 2, 2);
            payload_len = ntohs(nlen);
            header_size = 4;
        } else {
            payload_len = 0;
            for (int i = 0; i < 8; i++) payload_len |= ((uint64_t)head[2+i] << (56 - i*8));
            header_size = 10;
        }

        uint8_t *payload = malloc(payload_len);
        recv(sockfd, payload, payload_len, 0);

        if (opcode == 9) {
            send_frame(sockfd, 10, payload, payload_len);
        } else if (opcode == 10) {
            // Pong ignore
        } else if (opcode == 8) {
            int code = (payload[0] << 8) | payload[1];
            char *reason = payload + 2;
            size_t reason_len = payload_len - 2;
            if (reason_len > 0) {
                reason[reason_len] = '\0';
                printf("closed %d %s\n", code, reason);
            } else {
                printf("closed %d\n", code);
            }
            if (!closed_sent) {
                uint8_t close_p[2] = {0x03, 0xE8};
                send_frame(sockfd, 8, close_p, 2);
                closed_sent = 1;
            }
            close(sockfd); return;
        } else if (opcode == 1 || opcode == 2) {
            if (fin) {
                if (waiting_for_sha1) {
                    SHA1_CTX s_ctx;
                    sha1_init(&s_ctx);
                    sha1_update(&s_ctx, payload, payload_len);
                    uint8_t d[20];
                    sha1_final(&s_ctx, d);
                    char *hex = malloc(41);
                    sprintf(hex, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
                        d[0],d[1],d[2],d[3],d[4],d[5],d[6],d[7],d[8],d[9],d[10],d[11],d[12],d[13],d[14],d[15],d[16],d[17],d[18],d[19]);
                    printf("SHA1 %zu -> %s\n", payload_len, hex);
                    free(hex);
                    waiting_for_sha1 = 0;
                } else {
                    msg_buf = realloc(msg_buf, msg_len + payload_len + 1);
                    memcpy(msg_buf + msg_len, payload, payload_len);
                    msg_len += payload_len;
                    msg_buf[msg_len] = '\0';

                    if (msg_len > 0) {
                        if (strncmp(msg_buf, "ADD ", 4) == 0) {
                            long long a, b;
                            sscanf(msg_buf + 4, "%lld %lld", &a, &b);
                            printf("ADD %lld %lld -> %lld\n", a, b, a + b);
                        } else if (strncmp(msg_buf, "REV ", 4) == 0) {
                            char *text = msg_buf + 4;
                            int len = strlen(text);
                            int *starts = malloc(len * 4);
                            int count = 0;
                            for (int i = 0; i < len; i++) {
                                if ((text[i] & 0xC0) != 0x80) starts[count++] = i;
                            }
                            char *rev = malloc(len + 1);
                            int r_idx = 0;
                            for (int i = count - 1; i >= 0; i--) {
                                int start = starts[i];
                                int end = (i + 1 < count) ? starts[i+1] : len;
                                memcpy(rev + r_idx, text + start, end - start);
                                r_idx += (end - start);
                            }
                            rev[r_idx] = '\0';
                            printf("REV %s -> %s\n", text, rev);
                            free(rev); free(starts);
                        } else if (strncmp(msg_buf, "SHA1", 4) == 0) {
                            waiting_for_sha1 = 1;
                        } else if (strncmp(msg_buf, "BYE", 3) == 0) {
                            uint8_t close_p[2] = {0x03, 0xE8};
                            send_frame(sockfd, 8, close_p, 2);
                            closed_sent = 1;
                            // read until server close
                            while(1) {
                                uint8_t h2[10];
                                int n2 = recv(sockfd, h2, 10, 0);
                                if (n2 <= 0) break;
                                uint8_t op2 = h2[0] & 0x0F;
