import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static class Line {
        byte[] content;
        boolean hasNewline;
        Line(byte[] content, boolean hasNewline) { this.content = content; this.hasNewline = hasNewline; }
        boolean equals(Line other) {
            return Arrays.equals(this.content, other.content) && this.hasNewline == other.hasNewline;
        }
    }

    enum Kind { CREATE, DELETE, MODIFY }

    static class Hunk {
        int a, b, c, d;
        List<Line> oldLines = new ArrayList<>();
        List<Line> newLines = new ArrayList<>();
        String status;
        int appliedAt, offset;
        Hunk(int a, int b, int c, int d) { this.a = a; this.b = b; this.c = c; this.d = d; }
    }

    static class Section {
        String path;
        Kind kind;
        List<Hunk> hunks = new ArrayList<>();
        String error = null;
        Section(String path, Kind kind) { this.path = path; this.kind = kind; }
    }

    public static void main(String[] args) throws IOException {
        if (args.length < 1) return;
        Path diffPath = Paths.get(args[0]).toAbsolutePath();
        Path treePath = Paths.get("tree").toAbsolutePath();
        byte[] diffBytes = Files.readAllBytes(diffPath);
        String diffStr = new String(diffBytes, StandardCharsets.UTF_8);
        String[] diffLines = diffStr.split("\n", -1);

        List<Section> sections = new ArrayList<>();
        int i = 0;
        while (i < diffLines.length) {
            String line = diffLines[i];
            if (line.startsWith("diff --git ")) {
                String[] parts = line.split(" ");
                String path = parts[2].substring(2);
                Section section = new Section(path, Kind.MODIFY);
                i++;
                while (i < diffLines.length && !diffLines[i].startsWith("diff --git ") && !diffLines[i].startsWith("@@")) {
                    if (diffLines[i].startsWith("new file mode")) section.kind = Kind.CREATE;
                    else if (diffLines[i].startsWith("deleted file mode")) section.kind = Kind.DELETE;
                    i++;
                }
                while (i < diffLines.length && !diffLines[i].startsWith("diff --git ") && !diffLines[i].startsWith("@@")) i++;
                if (i < diffLines.length && diffLines[i].startsWith("@@")) {
                    while (i < diffLines.length && !diffLines[i].startsWith("diff --git ") && !diffLines[i].startsWith("@@")) {
                        String header = diffLines[i];
                        if (header.startsWith("@@")) {
                            String[] parts = header.split(" ");
                            String[] oldR = parts[1].split(",");
                            String[] newR = parts[3].split(",");
                            int a = Integer.parseInt(oldR[0]), b = oldR.length > 1 ? Integer.parseInt(oldR[1]) : 1;
                            int c = Integer.parseInt(newR[0]), d = newR.length > 1 ? Integer.parseInt(newR[1]) : 1;
                            Hunk hunk = new Hunk(a, b, c, d);
                            i++;
                            while (i < diffLines.length && !diffLines[i].startsWith("@@") && !diffLines[i].startsWith("diff --git ")) {
                                String bodyLine = diffLines[i];
                                if (bodyLine.startsWith("\\")) {
                                    if (!hunk.oldLines.isEmpty()) hunk.oldLines.get(hunk.oldLines.size() - 1).hasNewline = false;
                                    if (!hunk.newLines.isEmpty()) hunk.newLines.get(hunk.newLines.size() - 1).hasNewline = false;
                                } else {
                                    char marker = bodyLine.charAt(0);
                                    byte[] content = bodyLine.substring(1).getBytes(StandardCharsets.UTF_8);
                                    if (marker == '-') hunk.oldLines.add(new Line(content, true));
                                    else if (marker == '+') hunk.newLines.add(new Line(content, true));
                                    else if (marker == ' ') {
                                        hunk.oldLines.add(new Line(content, true));
                                        hunk.newLines.add(new Line(content, true));
                                    }
                                }
                                i++;
                            }
                            if (hunk.oldLines.size() != b || hunk.newLines.size() != d) hunk.status = "malformed";
                            section.hunks.add(hunk);
                        } else i++;
                    }
                }
                sections.add(section);
            } else i++;
        }

        sections.sort(Comparator.comparing(s -> s.path));
        for (Section section : sections) {
            Path filePath = treePath.resolve(section.path);
            System.out.println(section.path + ": " + section.kind);
            List<Line> content = new ArrayList<>();
            if (section.kind == Kind.CREATE) {
                if (Files.exists(filePath)) { System.out.println("  error: already exists"); continue; }
            } else {
                if (!Files.exists(filePath)) { System.out.println("  error: not found"); continue; }
                byte[] bytes = Files.readAllBytes(filePath);
                int start = 0;
                for (int j = 0; j < bytes.length; j++) {
                    if (bytes[j] == '\n') {
                        content.add(new Line(Arrays.copyOfRange(bytes, start, j), true));
                        start = j + 1;
                    }
                }
                if (start < bytes.length) content.add(new Line(Arrays.copyOfRange(bytes, start, bytes.length), false));
            }

            int delta = 0;
            boolean allApplied = true;
            for (int h = 0; h < section.hunks.size(); h++) {
                Hunk hunk = section.hunks.get(h);
                if (hunk.status.equals("malformed")) {
                    System.out.println("  hunk " + (h + 1) + ": malformed");
                    allApplied = false;
                    continue;
                }
                int P = hunk.a + delta;
                if (hunk.b == 0) {
                    if (P >= 0 && P <= content.size()) {
                        hunk.appliedAt = P;
                        hunk.offset = 0;
                        hunk.status = "applied";
                        content.addAll(hunk.newLines);
                        delta += hunk.d;
                    } else {
                        hunk.status = "rejected";
                        allApplied = false;
                    }
                } else {
                    int bestP = -1;
                    int minDist = Integer.MAX_VALUE;
                    for (int dist = 0; ; dist++) {
                        int p1 = P - dist;
                        int p2 = P + dist;
                        boolean found = false;
                        if (p1 >= 1 && p1 <= content.size() - hunk.b) {
                            boolean match = true;
                            for (int k = 0; k < hunk.b; k++) {
                                if (!content.get(p1 - 1).equals(hunk.oldLines.get(k))) {
                                    match = false; break;
                                }
                            }
                            if (match) { bestP = p1; found = true; }
                        }
                        if (!found && p2 >= 1 && p2 <= content.size() - hunk.b) {
                            boolean match = true;
                            for (int k = 0; k < hunk.b; k++) {
                                if (!content.get(p2 - 1).equals(hunk.oldLines.get(k))) {
                                    match = false; break;
                                }
                            }
                            if (match) { bestP = p2; found = true; }
                        }
                        if (found || (p1 < 1 && p2 > content.size() - hunk.b)) break;
                    }
                    if (bestP != -1) {
                        hunk.appliedAt = bestP;
                        hunk.offset = bestP - P;
                        hunk.status = "applied";
                        content.subList(bestP - 1, bestP - 1 + hunk.b).clear();
                        content.addAll(bestP - 1, hunk.newLines);
                        delta += (hunk.d - hunk.b);
                    } else {
                        hunk.status = "rejected";
                        allApplied = false;
                    }
                }
                System.out.println("  hunk " + (h + 1) + ": " + (hunk.status.equals("applied") ? "applied at " + hunk.appliedAt + " (offset " + (hunk.offset >= 0 ? "+" + hunk.offset : hunk.offset) + ")" : hunk.status));
            }
            if (section.kind == Kind.DELETE) {
                if (allApplied && content.isEmpty()) System.out.println("  result: deleted");
                else {
                    long crc = 0;
                    CRC32 crc32 = new CRC32();
                    for (Line l : content) {
                        crc32.update(l.content);
                        if (l.hasNewline) crc32.update((byte) '\n');
                    }
                    System.out.println("  result: " + content.size() + " lines, crc32 " + String.format("%08x", crc32.getValue()));
                }
            } else {
                long crc = 0;
                CRC32 crc32 = new CRC32();
                for (Line l : content) {
                    crc32.update(l.content);
                    if (l.hasNewline) crc32.update((byte) '\n');
                }
                System.out.println("  result: " + content.size() + " lines, crc32 " + String.format("%08x", crc32.getValue()));
            }
        }
    }
}

