class Value {
    constructor(public type: Type, public data: any) {}

    toString(seen: Set<Value> = new Set()): string {
        switch (this.type) {
            case 'int': return this.data.toString();
            case 'bool': return this.data ? 'true' : 'false';
            case 'string': return this.data;
            case 'nil': return 'nil';
            case 'function': return '<fn>';
            case 'list': {
                if (seen.has(this)) return '[...]';
                seen.add(this);
                const elements = this.data.map(v => v.toString(seen)).join(', ');
                seen.delete(this);
                return `[${elements}]`;
            }
        }
        return '';
