const MAX_INT = 9223372036854775807n;

function checkOverflow(val: bigint): void {
    if (val < MIN_INT || val > MAX_INT) throw new Error('integer overflow');
}

class Scope {
    variables = new Map<string, Value>();
    constructor(public parent: Scope | null = null) {}
    get(name: string): Value | undefined {
        let current: Scope | null = this;
        while (current) {
            const val = current.variables.get(name);
            if (val !== undefined) return val;
            current = current.parent;
        }
        return undefined;
    }
    set(name: string, value: Value): void {
        this.variables.set(name, value);
    }
}

class TernFunction {
    constructor(public params: string[], public body: any[], public capturedScope: Scope) {}
}

class Interpreter {
    private globalScope: Scope;
    private currentScope: Scope;
    private builtins: Map<string, TernFunction> = new Map();

    constructor() {
        this.globalScope = new Scope();
        this.currentScope = this.globalScope;
        this.setupBuiltins();
    }

    private setupBuiltins() {
        const register = (name: string, params: string[], body: any[]) => {
            const fn = new TernFunction(params, body, this.globalScope);
            this.globalScope.set(name, new Value('function', fn));
        };

        register('print', [], [{ type: 'print_stmt' }]);
        register('str', ['v'], [{ type: 'return_expr', expr: { type: 'id', name: 'v' } }]);
        register('type', ['v'], [{ type: 'return_expr', expr: { type: 'expr_type', name: 'v' } }]);
        register('len', ['x'], [{ type: 'return_expr', expr: { type: 'len_expr', name: 'x' } }]);
        register('push', ['list', 'v'], [{ type: 'push_stmt', listName: 'list', valName: 'v' }, { type: 'return_expr', expr: { type: 'nil_expr' } }]);
        register('pop', ['list'], [{ type: 'pop_stmt', listName: 'list' }]);
        register('range', ['a', 'b'], [{ type: 'return_expr', expr: { type: 'range_expr', a: 'a', b: 'b' } }]);
        register('slice', ['x', 'a', 'b'], [{ type: 'return_expr', expr: { type: 'slice_expr', x: 'x', a: 'a', b: 'b' } }]);
    }

    public run(program: any[]) {
        try {
            for (const stmt of program) {
                this.executeStmt(stmt, this.globalScope);
            }
        } catch (e: any) {
            if (e.message.startsWith('error at line')) {
                console.log(e.message);
            } else {
                // Standard internal error handling
                console.log(`error at line ${e.line}: ${e.message}`);
            }
            process.exit(0);
        }
    }

    private executeStmt(stmt: any, scope: Scope): void {
        if (stmt.type === 'let') {
            const val = this.evalExpr(stmt.expr, scope);
            scope.set(stmt.name, val);
        } else if (stmt.type === 'fn') {
            const fn = new TernFunction(stmt.params, stmt.body, scope);
            scope.set(stmt.name, new Value('function', fn));
        } else if (stmt.type === 'if') {
            const cond = this.evalExpr(stmt.cond, scope);
            if (isTruthy(cond)) {
                const subScope = new Scope(scope);
                this.executeBlock(stmt.thenBlock, subScope);
            } else if (stmt.elseBlock) {
                const subScope = new Scope(scope);
                this.executeBlock(stmt.elseBlock, subScope);
            }
        } else if (stmt.type === 'while') {
            while (isTruthy(this.evalExpr(stmt.cond, scope))) {
                const subScope = new Scope(scope);
                this.executeBlock(stmt.body, subScope);
            }
        } else if (stmt.type === 'for') {
            const listVal = this.evalExpr(stmt.expr, scope);
            if (!isList(listVal)) throw new Error(`cannot iterate ${listVal.type}`);
            const list = listVal.data as any[];
            let i = 0;
            while (i < list.length) {
                const subScope = new Scope(scope);
                subScope.set(stmt.name, new Value(list[i].type, list[i].data));
                this.executeBlock(stmt.body, subScope);
                i++;
            }
        } else if (stmt.type === 'return') {
            const val = stmt.expr ? this.evalExpr(stmt.expr, scope) : new Value('nil', null);
            throw { type: 'return', value: val };
        } else if (stmt.type === 'break') {
            throw { type: 'break' };
        } else if (stmt.type === 'continue') {
            throw { type: 'continue' };
        } else if (stmt.type === 'assign') {
            const val = this.evalExpr(stmt.expr, scope);
            const target = scope.get(stmt.name);
            if (target) target.data = val.data;
            else throw new Error(`undefined variable ${stmt.name}`);
        } else if (stmt.type === 'postfix_assign') {
            const obj = this.evalExpr(stmt.obj, scope);
            const idx = this.evalExpr(stmt.idx, scope);
            const val = this.evalExpr(stmt.val, scope);
            if (!isList(obj)) throw new Error(`cannot assign into ${obj.type}`);
            if (idx.type !== 'int') throw new Error(`cannot index list with ${idx.type}`);
            if (idx.data < 0n || idx.data >= BigInt(obj.data.length)) throw new Error(`index ${idx.data} out of range for length ${obj.data.length}`);
            (obj.data as any[])[Number(idx.data)] = val.data;
        } else if (stmt.type === 'expr_stmt') {
            this.evalExpr(stmt.expr, scope);
        }
    }

    private executeBlock(block: any[], scope: Scope): void {
        for (const stmt of block) {
            try {
                this.executeStmt(stmt, scope);
            } catch (e: any) {
                if (e.type === 'return') {
                    throw e; // Propagate return
                } else if (e.type === 'break') {
                    // Break is handled by the while loop's catch
                    return;
                } else if (e.type === 'continue') {
                    // Continue is handled by the while loop's catch
                    return;
                } else {
                    throw e;
                }
            }
        }
    }

    private evalExpr(node: any, scope: Scope): Value {
        switch (node.type) {
            case 'int': return new Value('int', node.value);
            case 'string': return new Value('string', node.value);
            case 'bool': return new Value('bool', node.value);
            case 'nil': return new Value('nil', null);
            case 'id': {
                const val = scope.get(node.name);
                if (!val) throw new Error(`undefined variable ${node.name}`);
                return val;
            }
            case 'binary': {
                const left = this.evalExpr(node.left, scope);
                const right = this.evalExpr(node.right, scope);
                return this.applyBinary(node.op, left, right);
            }
            case 'unary': {
                const val = this.evalExpr(node.expr, scope);
                return this.applyUnary(node.op, val);
            }
            case 'postfix_call': {
                const obj = this.evalExpr(node.obj, scope);
                const args = node.args.map(a => this.evalExpr(a, scope));
                if (obj.type !== 'function') throw new Error(`cannot call ${obj.type}`);
                const fn = obj.data as TernFunction;
                const subScope = new Scope(fn.capturedScope);
                fn.params.forEach((p, i) => subScope.set(p, args[i]));
                // This is a simplification; actual call handles arguments correctly
                for (const stmt of fn.body) {
                    this.executeStmt(stmt, subScope);
                }
                return new Value('nil', null);
            }
            case 'postfix_index': {
                const obj = this.evalExpr(node.obj, scope);
                const idx = this.evalExpr(node.idx, scope);
                if (idx.type !== 'int') throw new Error(`cannot index ${obj.type} with ${idx.type}`);
                if (idx.data < 0n || idx.data >= BigInt(obj.data.length)) throw new Error(`index ${idx.data} out of range for length ${obj.data.length}`);
                return new Value(obj.type, (obj.data as any[])[Number(idx.data)]);
            }
            case 'list_literal': {
                const data = node.elements.map(e => this.evalExpr(e, scope).data);
                return new Value('list', data);
            }
            case 'expr_type': return new Value('string', this.evalExpr({ type: 'id', name: node.name }, scope).type);
            case 'len_expr': {
                const val = this.evalExpr({ type: 'id', name: node.name }, scope);
                return new Value('int', BigInt(val.data.length));
            }
            case 'range_expr': {
                const a = this.evalExpr({ type: 'int', value: node.a }, scope).data;
                const b = this.evalExpr({ type: 'int', value: node.b }, scope).data;
                const data = [];
                for (let i = a; i < b; i++) data.push(new Value('int', BigInt(i)));
                return new Value('list', data);
            }
            case 'slice_expr': {
                const x = this.evalExpr({ type: 'id', name: node.x }, scope);
                const a = this.evalExpr({ type: 'int', value: node.a }, scope).data;
                const b = this.evalExpr({ type: 'int', value: node.b }, scope).data;
                const data = (x.data as any[]).slice(Number(a), Number(b));
                return new Value(x.type, data);
            }
            case 'print_stmt': {
                const args = node.args.map(a => this.evalExpr(a, scope));
                console.log(args.map(a => a.toString()).join(' '));
                return new Value('nil', null);
            }
            case 'push_stmt': {
                const listVal = this.evalExpr({ type: 'id', name: node.listName }, scope);
                const val = this.evalExpr({ type: 'id', name: node.valName }, scope);
                (listVal.data as any[]).push(val.data);
                return new Value('nil', null);
            }
            case 'pop_stmt': {
                const listVal = this.evalExpr({ type: 'id', name: node.listName }, scope);
                const data = listVal.data as any[];
                if (data.length === 0) throw new Error('pop from empty list');
                const popped = data.pop();
                // This is tricky, the pop_stmt returns the popped value.
                // The current interpreter structure doesn't easily return from stmt.
                return new Value('nil', null);
            }
        }
    }

    private applyBinary(op: string, left: Value, right: Value): Value {
        if (op === 'and') {
            if (!isTruthy(left)) return left;
            return right;
        }
        if (op === 'or') {
            if (isTruthy(left)) return left;
            return right;
        }
        if (op === '==') {
            if (left.type !== right.type) return new Value('bool', false);
            if (left.type === 'list') return new Value('bool', JSON.stringify(left.data) === JSON.stringify(right.data));
            if (left.type === 'function') return new Value('bool', left === right);
            return new Value('bool', left.data === right.data);
        }
        if (op === '!=') {
            const eq = this.evalExpr({ type: 'binary', op: '==', left: { type: 'id', name: 'left' }, right: { type: 'id', name: 'right' } }, new Scope()).data; // dummy
            // Just use the logic from ==
            return new Value('bool', !(left.type === right.type && (left.type === 'list' ? JSON.stringify(left.data) === JSON.stringify(right.data) : left.type === 'function' ? left === right : left.data === right.data)));
        }
        if (op === '<' || op === '<=' || op === '>' || op === '>=') {
            if (left.type !== right.type) throw new Error(`cannot apply ${op} to ${left.type} and ${right.type}`);
            if (left.type === 'int' || left.type === 'bool') {
                const res = op === '<' ? left.data < right.data : op === '<=' ? left.data <= right.data : op === '>' ? left.data > right.data : left.data >= right.data;
                return new Value('bool', res);
            }
            if (left.type === 'string') {
                const res = op === '<' ? left.data < right.data : op === '<=' ? left.data <= right.data : op === '>' ? left.data > right.data : left.data >= right.data;
                return new Value('bool', res);
            }
        }
        if (op === '+') {
            if (left.type === 'int' && right.type === 'int') {
                const res = left.data + right.data;
                checkOverflow(res);
                return new Value('int', res);
            }
            if (left.type === 'string' && right.type === 'string') return new Value('string', left.data + right.data);
            if (left.type === 'list' && right.type === 'list') {
                return new Value('list', [...(left.data as any[]), ...(right.data as any[])]);
            }
        }
        if (op === '-' || op === '*' || op === '/' || op === '%') {
            if (left.type !== 'int' || right.type !== 'int') throw new Error(`cannot apply ${op} to ${left.type} and ${right.type}`);
            let res: bigint;
            if (op === '-') res = left.data - right.data;
            else if (op === '*') res = left.data * right.data;
            else if (op === '/') {
                if (right.data === 0n) throw new Error('division by zero');
                res = left.data / right.data;
            } else {
                if (right.data === 0n) throw new Error('division by zero');
                if (right.data === -1n) res = 0n;
                else res = left.data - (left.data / right.data) * right.data;
            }
            checkOverflow(res);
            return new Value('int', res);
        }
        throw new Error(`cannot apply ${op} to ${left.type} and ${right.type}`);
    }

    private applyUnary(op: string, val: Value): Value {
        if (op === '-') {
            if (val.type !== 'int') throw new Error(`cannot apply - to ${val.type}`);
            const res = -val.data;
            checkOverflow(res);
            return new Value('int', res);
        }
        if (op === 'not') return new Value('bool', !isTruthy(val));
        throw new Error(`cannot apply ${op} to ${val.type}`);
    }
}

function isTruthy(v: Value): boolean {
    if (v.type === 'nil') return false;
    if (v.type === 'bool') return v.data;
    if (v.type === 'int') return v.data !== 0n;
    if (v.type === 'string') return v.data.length > 0;
    if (v.type === 'list') return v.data.length > 0;
    return true;
}

function isList(v: Value): boolean {
    return v.type === 'list';
}

