import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File progFile = new File(dir, "program.tern");
        String source = Files.readString(progFile.toPath());
        Lexer lexer = new Lexer(source);
        Parser parser = new Parser(lexer);
        Program program = parser.parse();
        Interpreter interpreter = new Interpreter();
        interpreter.interpret(program);
    }

    static class Token {
        enum Type { INT, STRING, IDENTIFIER, KEYWORD, OPERATOR, EOF }
        Type type; String value; int line;
        Token(Type t, String v, int l) { type = t; value = v; line = l; }
    }

    static class Lexer {
        String src; int pos = 0, line = 1;
        Lexer(String s) { src = s; }
        List<Token> tokenize() {
            List<Token> tokens = new ArrayList<>();
            while (pos < src.length()) {
                char c = src.charAt(pos);
                if (Character.isWhitespace(c)) {
                    if (c == '\n') line++;
                    pos++;
                } else if (c == '#') {
                    while (pos < src.length() && src.charAt(pos) != '\n') pos++;
                } else if (Character.isDigit(c)) {
                    StringBuilder sb = new StringBuilder();
                    while (pos < src.length() && Character.isDigit(src.charAt(pos))) sb.append(src.charAt(pos++));
                    tokens.add(new Token(Token.Type.INT, sb.toString(), line));
                } else if (c == '"') {
                    pos++; StringBuilder sb = new StringBuilder();
                    while (pos < src.length() && src.charAt(pos) != '"') {
                        char cur = src.charAt(pos);
                        if (cur == '\\') {
                            pos++; char next = src.charAt(pos);
                            if (next == 'n') sb.append('\n');
                            else if (next == 't') sb.append('\t');
                            else if (next == '"') sb.append('"');
                            else if (next == '\\') sb.append('\\');
                        } else sb.append(cur);
                        pos++;
                    }
                    pos++; tokens.add(new Token(Token.Type.STRING, sb.toString(), line));
                } else if (Character.isLetter(c) || c == '_') {
                    StringBuilder sb = new StringBuilder();
                    while (pos < src.length() && (Character.isLetterOrDigit(src.charAt(pos)) || src.charAt(pos) == '_')) sb.append(src.charAt(pos++));
                    String s = sb.toString();
                    if ("let fn if else while for in return break continue and or not true false nil".contains(s))
                        tokens.add(new Token(Token.Type.KEYWORD, s, line));
                    else tokens.add(new Token(Token.Type.IDENTIFIER, s, line));
                } else {
                    String op = "";
                    if ("=!<>".indexOf(c) != -1) {
                        if (pos + 1 < src.length() && src.charAt(pos+1) == '=') { op = src.substring(pos, pos+2); pos += 2; }
                        else { op = src.substring(pos, pos+1); pos++; }
                    } else if ("+-*/%()[]{},;".indexOf(c) != -1) { op = src.substring(pos, pos+1); pos++; }
                    else pos++;
                    tokens.add(new Token(Token.Type.OPERATOR, op, line));
                }
            }
            tokens.add(new Token(Token.Type.EOF, "", line));
            return tokens;
        }
    }

    static class Parser {
        List<Token> tokens; int pos = 0;
        Parser(Lexer l) { tokens = l.tokenize(); }
        Program parse() {
            List<Statement> stmts = new ArrayList<>();
            while (pos < tokens.size() && tokens.get(pos).type != Token.Type.EOF) stmts.add(parseStmt());
            return new Program(stmts);
        }
        Statement parseStmt() {
            Token t = tokens.get(pos);
            if (t.value.equals("let")) {
                pos++; String name = tokens.get(pos++).value; pos++; // =
                Expr val = parseExpr(); pos++; // ;
                return new LetStmt(name, val);
            } else if (t.value.equals("fn")) {
                pos++; String name = tokens.get(pos++).value; pos++; // (
                List<String> params = new ArrayList<>();
                if (!tokens.get(pos).value.equals(")")) {
                    params.add(tokens.get(pos++).value);
                    while (tokens.get(pos).value.equals(",")) { pos++; params.add(tokens.get(pos++).value); }
                }
                pos++; // )
                Block body = parseBlock();
                return new FnStmt(name, params, body);
            } else if (t.value.equals("if")) {
                pos++; Expr cond = parseExpr(); Block thenB = parseBlock();
                Block elseB = null;
                if (pos < tokens.size() && tokens.get(pos).value.equals("else")) {
                    pos++; elseB = parseBlock();
                }
                return new IfStmt(cond, thenB, elseB);
            } else if (t.value.equals("while")) {
                pos++; Expr cond = parseExpr(); Block body = parseBlock();
                return new WhileStmt(cond, body);
            } else if (t.value.equals("for")) {
                pos++; String varName = tokens.get(pos++).value; pos++; // in
                Expr iterable = parseExpr(); Block body = parseBlock();
                return new ForStmt(varName, iterable, body);
            } else if (t.value.equals("return")) {
                pos++; Expr val = null;
                if (!tokens.get(pos).value.equals(";")) val = parseExpr();
                pos++; return new ReturnStmt(val);
            } else if (t.value.equals("break")) { pos++; pos++; return new BreakStmt(); }
            else if (t.value.equals("continue")) { pos++; pos++; return new ContinueStmt(); }
            else {
                String name = t.value; pos++;
                if (pos < tokens.size() && tokens.get(pos).value.equals("=")) {
                    pos++; Expr val = parseExpr(); pos++;
                    return new AssignStmt(name, val);
                } else {
                    Expr e = parseExpr(); pos++;
                    return new ExprStmt(e);
                }
            }
        }
        Block parseBlock() {
            pos++; // {
            List<Statement> stmts = new ArrayList<>();
            while (pos < tokens.size() && !tokens.get(pos).value.equals("}")) {
                stmts.add(parseStmt());
            }
            pos++; // }
            return new Block(stmts);
        }
        Expr parseExpr() { return parseOr(); }
        private Expr parseOr() {
            Expr node = parseAnd();
            while (pos < tokens.size() && tokens.get(pos).value.equals("or")) {
                pos++;
                node = new BinaryExpr(node, "or", parseAnd());
            }
            return node;
        }
        private Expr parseAnd() {
            Expr node = parseNot();
            while (pos < tokens.size() && tokens.get(pos).value.equals("and")) {
                pos++;
                node = new BinaryExpr(node, "and", parseNot());
            }
            return node;
        }
        private Expr parseNot() {
            if (pos < tokens.size() && tokens.get(pos).value.equals("not")) {
                pos++;
                return new UnaryExpr("not", parseNot());
            }
            return parseComparison();
        }
        private Expr parseComparison() {
            Expr node = parseSum();
            if (pos < tokens.size() && "==!=<=>><=".contains(tokens.get(pos).value)) {
                String op = tokens.get(pos++).value;
                node = new BinaryExpr(node, op, parseSum());
            }
            return node;
        }
        private Expr parseSum() {
            Expr node = parseProduct();
            while (pos < tokens.size() && (tokens.get(pos).value.equals("+") || tokens.get(pos).value.equals("-"))) {
                String op = tokens.get(pos++).value;
                node = new BinaryExpr(node, op, parseProduct());
            }
            return node;
        }
        private Expr parseProduct() {
            Expr node = parseUnary();
            while (pos < tokens.size() && (tokens.get(pos).value.equals("*") || tokens.get(pos).value.equals("/") || tokens.get(pos).value.equals("%"))) {
                String op = tokens.get(pos++).value;
                node = new BinaryExpr(node, op, parseUnary());
            }
            return node;
        }
        private Expr parseUnary() {
            if (pos < tokens.size() && tokens.get(pos).value.equals("-")) {
                pos++;
                return new UnaryExpr("-", parseUnary());
            }
            return parsePrimary();
        }
        private Expr parsePrimary() {
            Token t = tokens.get(pos);
            if (t.type == Token.Type.INT) { pos++; return new IntLit(Long.parseLong(t.value)); }
            if (t.type == Token.Type.STRING) { pos++; return new StringLit(t.value); }
            if (t.value.equals("true")) { pos++; return new BoolLit(true); }
            if (t.value.equals("false")) { pos++; return new BoolLit(false); }
            if (t.value.equals("nil")) { pos++; return new NilLit(); }
            if (t.type == Token.Type.IDENTIFIER) {
                String name = t.value; pos++;
                if (pos < tokens.size() && tokens.get(pos).value.equals("(")) {
                    pos++; List<Expr> args = new ArrayList<>();
                    if (!tokens.get(pos).value.equals(")")) {
                        args.add(parseExpr());
                        while (tokens.get(pos).value.equals(",")) { pos++; args.add(parseExpr()); }
                    }
                    pos++; return new CallExpr(new Identifier(name), args);
                }
                if (pos < tokens.size() && tokens.get(pos).value.equals("[")) {
                    pos++; Expr index = parseExpr(); pos++; // ]
                    return new IndexExpr(new Identifier(name), index);
                }
                return new Identifier(name);
            }
            if (t.value.equals("(")) {
                pos++; Expr e = parseExpr(); pos++; // )
                return e;
            }
            if (t.value.equals("[")) {
                pos++; List<Expr> elements = new ArrayList<>();
                if (!tokens.get(pos).value.equals("]")) {
                    elements.add(parseExpr());
                    while (tokens.get(pos).value.equals(",")) { pos++; elements.add(parseExpr()); }
                }
                pos++; return new ListLit(elements);
            }
            return null;
        }
    }

    static abstract class Expr {}
    static class LetStmt extends Statement { String name; Expr value; LetStmt(String n, Expr v) { name = n; value = v; } }
    static class FnStmt extends Statement { String name; List<String> params; Block body; FnStmt(String n, List<String> p, Block b) { name = n; params = p; body = b; } }
    static class IfStmt extends Statement { Expr condition; Block thenBlock; Block elseBlock; IfStmt(Expr c, Block t, Block e) { condition = c; thenBlock = t; elseBlock = e; } }
    static class WhileStmt extends Statement { Expr condition; Block body; WhileStmt(Expr c, Block b) { condition = c; body = b; } }
    static class ForStmt extends Statement { String varName; Expr iterable; Block body; ForStmt(String v, Expr i, Block b) { varName = v; iterable = i; body = b; } }
    static class ReturnStmt extends Statement { Expr value; ReturnStmt(Expr v) { value = v; } }
    static class BreakStmt extends Statement {}
