def get_lines(content_bytes):
    """Splits content into lines at \n, preserving the \n if it exists."""
    lines = []
    start = 0
    while True:
        pos = content_bytes.find(b'\n', start)
        if pos == -1:
            if start < len(content_bytes):
                lines.append(content_bytes[start:])
            break
        lines.append(content_bytes[start:pos+1])
        start = pos + 1
    return lines

def parse_range(s):
    """Parses a git range like '-2,2' or '+2' into (start, count)."""
    s = s.decode()
    if s.startswith('-'):
        s = s[1:]
    if ',' in s:
        a, b = map(int, s.split(','))
    else:
        a = int(s)
        b = 1
    return a, b

