    sections = []
    current_section = []
    for line in diff_lines:
        if line.startswith(b'diff --git'):
            if current_section:
                sections.append(current_section)
            current_section = [line]
        else:
            current_section.append(line)
    if current_section:
        sections.append(current_section)

    results = []

    for section in sections:
        kind = 'modify'
        path_bytes = b''
        for line in section:
            if line.startswith(b'new file mode'):
                kind = 'create'
            elif line.startswith(b'deleted file mode'):
                kind = 'delete'
            elif line.startswith(b'diff --git'):
                parts = line.split(b' b/')
                path_bytes = parts[-1]

        path = path_bytes.decode()
        full_path = os.path.join(tree_path, path)

        file_exists = os.path.exists(full_path)

        content = b''
        if kind == 'create':
            if file_exists:
                results.append((path_bytes, kind, None, "already exists"))
                continue
            content = b''
        else:
            if not file_exists:
                results.append((path_bytes, kind, None, "not found"))
                continue
            with open(full_path, 'rb') as f:
                content = f.read()

        # Parse hunks
        hunks = []
        current_hunk = None
        for line in section:
            if line.startswith(b'@@'):
                if current_hunk:
                    hunks.append(current_hunk)

                first_at = line.find(b'@@')
                last_at = line.rfind(b'@@')
                header_part = line[first_at+2:last_at]
                parts = header_part.split(b' ')
                a, b = parse_range(parts[0])
                c, d = parse_range(parts[1])

                current_hunk = {
                    'a': a, 'b': b, 'c': c, 'd': d,
                    'body': []
                }
                hunks.append(current_hunk)
            elif current_hunk is not None:
                current_hunk['body'].append(line)
        if current_hunk:
            hunks.append(current_hunk)

        hunk_reports = []
        delta = 0
        current_content_lines = get_lines(content)

        for i, hunk in enumerate(hunks):
            old_lines = []
            new_lines = []
            for j, body_line in enumerate(hunk['body']):
                marker = body_line[0:1]
                content_part = body_line[1:]

                if marker == b' ':
                    old_lines.append(content_part)
                    new_lines.append(content_part)
                elif marker == b'-':
                    old_lines.append(content_part)
                elif marker == b'+':
                    new_lines.append(content_part)
                elif marker == b'\\':
                    if j > 0:
                        prev_line = hunk['body'][j-1]
                        prev_marker = prev_line[0:1]
                        if prev_marker == b' ':
                            old_lines[-1] = old_lines[-1].rstrip(b'\n')
                            new_lines[-1] = new_lines[-1].rstrip(b'\n')
                        elif prev_marker == b'-':
                            old_lines[-1] = old_lines[-1].rstrip(b'\n')
                        elif prev_marker == b'+':
                            new_lines[-1] = new_lines[-1].rstrip(b'\n')

            if len(old_lines) != hunk['b'] or len(new_lines) != hunk['d']:
                hunk_reports.append(f"hunk {i+1}: malformed")
                continue

            P = hunk['a'] + delta
            applied = False
            if hunk['b'] == 0:
                if 0 <= P <= len(current_content_lines):
                    current_content_lines[P:P] = new_lines
                    delta += hunk['d']
                    hunk_reports.append(f"hunk {i+1}: applied at {P} (offset 0)")
                    applied = True
                else:
                    hunk_reports.append(f"hunk {i+1}: rejected")
            else:
                best_p = -1
                for dist in range(0, len(current_content_lines) + 1):
                    for p in [P - dist, P + dist]:
                        if 1 <= p <= len(current_content_lines) - hunk['b'] + 1:
                            match = True
                            for k in range(hunk['b']):
                                if current_content_lines[p-1+k] != old_lines[k]:
                                    match = False
                                    break
                            if match:
                                best_p = p
                                break
                        if best_p != -1:
                            break
                    if best_p != -1:
                        break

                if best_p != -1:
                    current_content_lines[best_p-1 : best_p-1+hunk['b']] = new_lines
                    delta += (hunk['d'] - hunk['b'])
                    hunk_reports.append(f"hunk {i+1}: applied at {best_p} (offset {format_offset(best_p - P)})")
                    applied = True
                else:
                    hunk_reports.append(f"hunk {i+1}: rejected")

        final_content = b"".join(current_content_lines)
        is_deleted = False
        if kind == 'delete':
            all_applied = True
            for report in hunk_reports:
                if "rejected" in report or "malformed" in report:
                    all_applied = False
                    break
            if all_applied and len(current_content_lines) == 0:
                is_deleted = True

        if is_deleted:
            results.append((path_bytes, kind, hunk_reports, "deleted"))
        else:
            crc = zlib.crc32(final_content) & 0xFFFFFFFF
            results.append((path_bytes, kind, hunk_reports, f"{len(current_content_lines)} lines, crc32 {crc:08x}"))

    results.sort(key=lambda x: x[0])

    for path_bytes, kind, hunk_reports, final_res in results:
        print(f"{path_bytes.decode()}: {kind}")
        if hunk_reports is None:
            print(f"  error: {final_res}")
        else:
            for report in hunk_reports:
                print(f"  {report}")
            if final_res == "deleted":
                print("  result: deleted")
            else:
                print(f"  result: {final_res}")

if __name__ == "__main__":
    solve()

import java.io.*;
import java.util.*;
import java.awt.image.*;
import javax.imageio.ImageIO;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length < 1) return;
        File sceneFile = new File(args[0], "scene.json");
        String content = new String(java.nio.file.Files.readAllBytes(sceneFile.toPath()));
        JsonParser parser = new JsonParser(content);
        Map<String, Object> scene = (Map<String, Object>) parser.parse();

        int width = (int) scene.get("width");
        int height = (int) scene.get("height");
        int[] background = (int[]) scene.get("background");

        List<Map<String, Object>> shapesData = (List<Map<String, Object>>) scene.get("shapes");
        List<Shape> shapes = new ArrayList<>();
        for (Map<String, Object> data : shapesData) {
            Shape s = new Shape();
            s.type = (String) data.get("type");
            s.color = (int[]) data.get("color");

            if (s.type.equals("rect")) {
                s.x = (int) data.get("x");
                s.y = (int) data.get("y");
                s.w = (int) data.get("w");
                s.h = (int) data.get("h");
            } else if (s.type.equals("circle")) {
                s.cx = (int) data.get("cx");
                s.cy = (int) data.get("cy");
                s.r = (int) data.get("r");
            } else if (s.type.equals("triangle")) {
                List<List<Integer>> pts = (List<List<Integer>>) data.get("points");
                s.points = new int[3][2];
                for (int i = 0; i < 3; i++) {
                    s.points[i][0] = pts.get(i).get(0);
                    s.points[i][1] = pts.get(i).get(1);
                }
            } else if (s.type.equals("line")) {
                s.x1 = (int) data.get("x1");
                s.y1 = (int) data.get("y1");
                s.x2 = (int) data.get("x2");
                s.y2 = (int) data.get("y2");
                s.rLine = (int) data.get("r");
            }
            shapes.add(s);
        }

        int[][] canvas = new int[width * height][3];
        for (int i = 0; i < width * height; i++) {
            canvas[i][0] = background[0];
            canvas[i][1] = background[1];
            canvas[i][2] = background[2];
        }

        for (Shape s : shapes) {
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    if (s.covers(x, y)) {
                        s.coverageCount++;
                        int idx = y * width + x;
                        int[] d = canvas[idx];
                        int A = s.color[3];
                        d[0] = (s.color[0] * A + d[0] * (255 - A) + 127) / 255;
                        d[1] = (s.color[1] * A + d[1] * (255 - A) + 127) / 255;
                        d[2] = (s.color[2] * A + d[2] * (255 - A) + 127) / 255;
                    }
                }
            }
        }

        for (int i = 0; i < shapes.size(); i++) {
            System.out.println((i + 1) + " " + shapes.get(i).type + " " + shapes.get(i).coverageCount);
        }

        Set<String> distinctColors = new HashSet<>();
        for (int i = 0; i < width * height; i++) {
            distinctColors.add(canvas[i][0] + "," + canvas[i][1] + "," + canvas[i][2]);
        }
        System.out.println("colors " + distinctColors.size());

        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int[] c = canvas[y * width + x];
                int rgb = (c[0] << 16) | (c[1] << 8) | c[2];
                img.setRGB(x, y, rgb);
            }
        }
        ImageIO.write(img, "png", new File("out.png"));
    }

    static class Shape {
        String type;
        int[] color;
        int coverageCount = 0;
        int x, y, w, h;
        int cx, cy, r;
        int[][] points;
        int x1, y1, x2, y2, rLine;

        boolean covers(int px, int py) {
            switch (type) {
                case "rect":
                    return px >= x && px < x + w && py >= y && py < y + h;
                case "circle":
                    long dx = (long)px - cx;
                    long dy = (long)py - cy;
                    return dx * dx + dy * dy <= (long)r * r;
                case "triangle":
                    long E0 = (long)(points[1][0] - points[0][0]) * (py - points[0][1]) - (long)(points[1][1] - points[0][1]) * (px - points[0][0]);
                    long E1 = (long)(points[2][0] - points[1][0]) * (py - points[1][1]) - (long)(points[2][1] - points[1][1]) * (px - points[1][0]);
                    long E2 = (long)(points[0][0] - points[2][0]) * (py - points[2][1]) - (long)(points[0][1] - points[2][1]) * (px - points[2][0]);
                    return (E0 >= 0 && E1 >= 0 && E2 >= 0) || (E0 <= 0 && E1 <= 0 && E2 <= 0);
                case "line":
                    long dx = x2 - x1;
                    long dy = y2 - y1;
                    long L = dx * dx + dy * dy;
                    long t = (long)(px - x1) * dx + (long)(py - y1) * dy;
                    if (t <= 0) {
                        long dSq = (long)(px - x1) * (px - x1) + (long)(py - y1) * (py - y1);
                        return dSq <= (long)rLine * rLine;
                    } else if (t >= L) {
                        long dSq = (long)(px - x2) * (px - x2) + (long)(py - y2) * (py - y2);
                        return dSq <= (long)rLine * rLine;
                    } else {
                        long c = (long)(px - x1) * dy - (long)(py - y1) * dx;
                        return c * c <= (long)rLine * rLine * L;
                    }
                default:
                    return false;
            }
        }
    }

    static class JsonParser {
        String json;
        int pos = 0;
        JsonParser(String json) { this.json = json; }
        Object parse() {
            skipWhitespace();
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            return parseNumberOrString();
        }
        private void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
        }
        private Object parseObject() {
            pos++;
            Map<String, Object> map = new HashMap<>();
            while (true) {
                skipWhitespace();
                if (json.charAt(pos) == '}') { pos++; break; }
                String key = parseString();
                skipWhitespace();
                pos++; // :
                map.put(key, parse());
                skipWhitespace();
                if (json.charAt(pos) == ',') pos++;
            }
            return map;
        }
        private Object parseArray() {
            pos++;
            List<Object> list = new ArrayList<>();
            while (true) {
                skipWhitespace();
                if (json.charAt(pos) == ']') { pos++; break; }
                list.add(parse());
                skipWhitespace();
                if (json.charAt(pos) == ',') pos++;
            }
            return list;
        }
        private String parseString() {
            skipWhitespace();
            pos++; // "
            int start = pos;
            while (json.charAt(pos) != '"') pos++;
            String s = json.substring(start, pos);
            pos++;
            return s;
        }
        private Object parseNumberOrString() {
            skipWhitespace();
            int start = pos;
            if (json.charAt(pos) == '-') pos++;
            while (pos < json.length() && !Character.isWhitespace(json.charAt(pos)) && "{},[]:\"".indexOf(json.charAt(pos)) == -1) {
                pos++;
            }
            String s = json.substring(start, pos);
            try {
                return Integer.parseInt(s);
            } catch (NumberFormatException e) {
                return s;
            }
        }
    }
}

use std::collections::HashMap;
use std::rc::Rc;
use std::cell::RefCell;
use std::fmt;
use std::env;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Type { Int, Bool, String, List, Function, Nil }

impl fmt::Display for Type {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let s = match self {
            Type::Int => "int",
            Type::Bool => "bool",
            Type::String => "string",
            Type::List => "list",
            Type::Function => "function",
            Type::Nil => "nil",
        };
        write!(f, "{}", s)
    }
}

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    String(String),
    List(Rc<RefCell<Vec<Value>>>),
    Function(Closure),
    Nil,
}

impl Value {
    fn get_type(&self) -> Type {
        match self {
            Value::Int(_) => Type::Int,
            Value::Bool(_) => Type::Bool,
            Value::String(_) => Type::String,
            Value::List(_) => Type::List,
            Value::Function(_) => Type::Function,
            Value::Nil => Type::Nil,
        }
    }

    fn is_truthy(&self) -> bool {
        match self {
            Value::Bool(b) => *b,
            Value::Nil => false,
            Value::Int(i) => *i != 0,
            Value::String(s) => !s.is_empty(),
            Value::List(l) => !l.is_empty(),
            Value::Function(_) => true,
        }
    }

    fn to_display(&self, seen: &mut Vec<Rc<RefCell<Vec<Value>>>>) -> String {
        match self {
            Value::Int(i) => i.to_string(),
            Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Value::Nil => "nil".to_string(),
            Value::String(s) => s.clone(),
            Value::Function(_) => "<fn>".to_string(),
            Value::List(l) => {
                let vec = l.borrow();
                if seen.contains(l) { return "[...]".to_string(); }
                seen.push(Rc::clone(l));
                let mut parts = Vec::new();
                for v in vec.iter() {
                    let mut s = v.to_display(seen);
                    if let Value::String(_) = **v {
                        s = format!("\"{}\"", s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\t", "\\t"));
                    }
                    parts.push(s);
                }
                seen.pop();
                format!("[{}]", parts.join(", "))
            }
        }
    }
}

struct Closure {
    params: Vec<String>,
    body: Vec<Stmt>,
    captured_scope: Rc<RefCell<Scope>>,
}

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

impl Scope {
    fn new(parent: Option<Rc<RefCell<Scope>>>) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent }))
    }

    fn get(&self, name: &str) -> Option<&Value> {
        if let Some(v) = self.vars.get(name) { Some(v) }
        else if let Some(ref p) = self.parent { p.borrow().get(name) }
        else { None }
    }

    fn get_mut(&mut self, name: &str) -> Option<&mut Value> {
        if let Some(v) = self.vars.get_mut(name) { Some(v) }
        else if let Some(ref p) = self.parent { p.borrow_mut().get_mut(name) }
        else { None }
    }
}

#[derive(Debug, Clone)]
enum Token {
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Ident(String), Int(i64), String(String),
    Eq, Ne, Lt, Le, Gt, Ge, Plus, Minus, Mul, Div, Mod,
    Assign, LBrace, RBrace, LParen, RParen, LBracket, RBracket,
    Comma, Semicolon,
}

struct Lexer {
    input: Vec<char>,
    pos: usize,
    line: usize,
}

impl Lexer {
    fn new(input: String) -> Self { Lexer { input: input.chars().collect(), pos: 0, line: 1 } }
    fn next_token(&mut self) -> Option<(Token, usize)> {
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c.is_whitespace() {
                if c == '\n' { self.line += 1; }
                self.pos += 1;
                continue;
            }
            if c == '#' {
                while self.pos < self.input.len() && self.input[self.pos] != '\n' { self.pos += 1; }
                continue;
            }
            break;
        }
        if self.pos >= self.input.len() { return None; }
        let start_pos = self.pos;
        let c = self.input[self.pos];
        match c {
            '(' => { self.pos += 1; return Some((Token::LParen, self.line)); }
            ')' => { self.pos += 1; return Some((Token::RParen, self.line)); }
            '[' => { self.pos += 1; return Some((Token::LBracket, self.line)); }
            ']' => { self.pos += 1; return Some((Token::RBracket, self.line)); }
            '{' => { self.pos += 1; return Some((Token::LBrace, self.line)); }
            '}' => { self.pos += 1; return Some((Token::RBrace, self.line)); }
            ',' => { self.pos += 1; return Some((Token::Comma, self.line)); }
            ';' => { self.pos += 1; return Some((Token::Semicolon, self.line)); }
            '+' => { self.pos += 1; return Some((Token::Plus, self.line)); }
            '-' => { self.pos += 1; return Some((Token::Minus, self.line)); }
            '*' => { self.pos += 1; return Some((Token::Mul, self.line)); }
            '/' => { self.pos += 1; return Some((Token::Div, self.line)); }
            '%' => { self.pos += 1; return Some((Token::Mod, self.line)); }
            '=' => {
                if self.pos + 1 < self.input.len() && self.input[self.pos+1] == '=' {
                    self.pos += 2; return Some((Token::Eq, self.line));
                }
                self.pos += 1; return Some((Token::Assign, self.line));
            }
            '!' => {
                if self.pos + 1 < self.input.len() && self.input[self.pos+1] == '=' {
                    self.pos += 2; return Some((Token::Ne, self.line));
                }
                return None;
            }
            '<' => {
                if self.pos + 1 < self.input.len() && self.input[self.pos+1] == '=' {
                    self.pos += 2; return Some((Token::Le, self.line));
                }
                self.pos += 1; return Some((Token::Lt, self.line));
            }
            '>' => {
                if self.pos + 1 < self.input.len() && self.input[self.pos+1] == '=' {
                    self.pos += 2; return Some((Token::Ge, self.line));
                }
                self.pos += 1; return Some((Token::Gt, self.line));
            }
            '"' => {
                self.pos += 1;
                let mut s = String::new();
                while self.pos < self.input.len() && self.input[self.pos] != '"' {
                    let c = self.input[self.pos];
                    if c == '\\' {
                        self.pos += 1;
                        match self.input.get(self.pos) {
                            Some(&'n') => s.push('\n'),
                            Some(&'t') => s.push('\t'),
                            Some(&'\"') => s.push('\"'),
                            Some(&'\\') => s.push('\\'),
                            _ => {}
                        }
                    } else { s.push(c); }
                    self.pos += 1;
                }
                self.pos += 1;
                return Some((Token::String(s), self.line));
            }
            '0'..='9' => {
                let mut s = String::new();
                while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                    s.push(self.input[self.pos]);
                    self.pos += 1;
                }
                let val = s.parse::<i64>().unwrap();
                return Some((Token::Int(val), self.line));
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                let mut s = String::new();
                while self.pos < self.input.len() && (self.input[self.pos].is_ascii_alphanumeric() || self.input[self.pos] == '_') {
                    s.push(self.input[self.pos]);
                    self.pos += 1;
                }
                let token = match s.as_str() {
                    "let" => Token::Let, "fn" => Token::Fn, "if" => Token::If, "else" => Token::Else,
                    "while" => Token::While, "for" => Token::For, "in" => Token::In, "return" => Token::Return,
                    "break" => Token::Break, "continue" => Token::Continue, "and" => Token::And,
                    "or" => Token::Or, "not" => Token::Not, "true" => Token::True, "false" => Token::False,
                    "nil" => Token::Nil, _ => Token::Ident(s),
                };
                return Some((token, self.line));
            }
            _ => { self.pos += 1; return None; }
        }
    }
}

#[derive(Debug, Clone)]
enum Expr {
    Int(i64), String(String), Bool(bool), Nil, Ident(String),
    BinOp(Box<Expr>, Token, Box<Expr>), UnaryOp(Token, Box<Expr>),
    Call(Box<Expr>, Vec<Expr>), Index(Box<Expr>, Box<Expr>),
    List(Vec<Expr>), Function(Vec<String>, Vec<Stmt>, Rc<RefCell<Scope>>),
}

#[derive(Debug, Clone)]
enum Stmt {
    Let(String, Expr), FnDecl(String, Vec<String>, Vec<Stmt>),
    If(Expr, Vec<Stmt>, Option<Vec<Stmt>>), While(Expr, Vec<Stmt>),
    For(String, Expr, Vec<Stmt>), Return(Option<Expr>),
    Break, Continue, Assign(String, Expr), PostfixAssign(String, Expr, Expr),
    ExprStmt(Expr),
}

struct Parser { tokens: Vec<(Token, usize)>, pos: usize }
impl Parser {
    fn new(tokens: Vec<(Token, usize)>) -> Self { Parser { tokens, pos: 0 } }
    fn peek(&self) -> &Token { &self.tokens[self.pos].0 }
    fn peek_idx(&self) -> usize { self.pos }
    fn consume(&mut self) -> (Token, usize) {
        let t = self.tokens[self.pos].clone();
        self.pos += 1;
        t
    }
    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while self.pos < self.tokens.len() { stmts.push(self.parse_stmt()); }
        stmts
    }
    fn parse_stmt(&mut self) -> Stmt {
        let (t, _) = self.consume();
        match t {
            Token::Let => {
                let name = if let Token::Ident(s) = self.consume().0 { s } else { "".to_string() };
                self.consume(); // =
                let expr = self.parse_expr();
                self.consume(); // ;
                Stmt::Let(name, expr)
            }
            Token::Fn => {
                let name = if let Token::Ident(s) = self.consume().0 { s } else { "".to_string() };
                self.consume(); // (
                let mut params = Vec::new();
                if self.peek() != &Token::RParen {
                    loop {
                        if let Token::Ident(s) = self.consume().0 { params.push(s); }
                        if self.peek() == &Token::Comma { self.consume(); } else { break; }
                    }
                }
                self.consume(); // )
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body)
            }
            Token::If => {
                let cond = self.parse_expr();
                let mut then_block = Vec::new();
                if self.peek() == &Token::LBrace { then_block = self.parse_block_stmts(); }
                let mut else_block = None;
                if self.peek() == &Token::Else {
                    self.consume();
                    if self.peek() == &Token::LBrace { else_block = Some(self.parse_block_stmts()); }
                    else { else_block = Some(vec![self.parse_stmt()]); }
                }
                Stmt::If(cond, then_block, else_block)
            }
            Token::While => {
                let cond = self.parse_expr();
                let body = self.parse_block_stmts();
                Stmt::While(cond, body)
            }
            Token::For => {
                let name = if let Token::Ident(s) = self.consume().0 { s } else { "".to_string() };
                self.consume(); // in
                let expr = self.parse_expr();
                let body = self.parse_block_stmts();
                Stmt::For(name, expr, body)
            }
            Token::Return => {
                let mut expr = None;
                if self.peek() != &Token::Semicolon { expr = Some(self.parse_expr()); }
                self.consume(); // ;
                Stmt::Return(expr)
            }
            Token::Break => { self.consume(); ; Stmt::Break }
            Token::Continue => { self.consume(); ; Stmt::Continue }
            Token::Ident(name) => {
                if self.peek() == &Token::Eq {
                    self.consume(); // =
                    let expr = self.parse_expr();
                    self.consume(); // ;
                    Stmt::Assign(name, expr)
                } else {
                    let expr = self.parse_expr();
                    self.consume(); // ;
                    Stmt::ExprStmt(expr)
                }
            }
            _ => {
                let expr = self.parse_expr();
                self.consume(); // ;
                Stmt::ExprStmt(expr)
            }
        }
    }
    fn parse_block(&mut self) -> Vec<Stmt> {
        self.consume(); // {
        let stmts = self.parse_block_stmts();
        self.consume(); // }
        stmts
    }
    fn parse_block_stmts(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while self.pos < self.tokens.len() && self.peek() != &Token::RBrace {
            stmts.push(self.parse_stmt());
        }
        stmts
    }
    fn parse_expr(&mut self) -> Expr { self.parse_or() }
    fn parse_or(&mut self) -> Expr {
        let mut expr = self.parse_and();
        while self.peek() == &Token::Or {
            self.consume();
            let right = self.parse_and();
            expr = Expr::BinOp(Box::new(expr), Token::Or, Box::new(right));
        }
        expr
    }
    fn parse_and(&mut self) -> Expr {
        let mut expr = self.parse_not();
        while self.peek() == &Token::And {
            self.consume();
            let right = self.parse_not();
            expr = Expr::BinOp(Box::new(expr), Token::And, Box::new(right));
        }
        expr
    }
    fn parse_not(&mut self) -> Expr {
        if self.peek() == &Token::Not {
            self.consume();
            Expr::UnaryOp(Token::Not, Box::new(self.parse_not()))
        } else { self.parse_comparison() }
    }
    fn parse_comparison(&mut self) -> Expr {
        let mut expr = self.parse_term();
        while let Token::Eq | Token::Ne | Token::Lt | Token::Le | Token::Gt | Token::Ge = *self.peek() {
            let op = self.consume().0;
            let right = self.parse_term();
            expr = Expr::BinOp(Box::new(expr), op, Box::new(right));
        }
        expr
    }
    fn parse_term(&mut self) -> Expr {
        let mut expr = self.parse_factor();
        while let Token::Plus | Token::Minus = *self.peek() {
            let op = self.consume().0;
            let right = self.parse_factor();
            expr = Expr::BinOp(Box::new(expr), op, Box::new(right));
        }
        expr
    }
    fn parse_factor(&mut self) -> Expr {
        let mut expr = self.parse_unary();
        while let Token::Mul | Token::Div | Token::Mod = *self.peek() {
            let op = self.consume().0;
            let right = self.parse_unary();
            expr = Expr::BinOp(Box::new(expr), op, Box::new(right));
        }
        expr
    }
    fn parse_unary(&mut self) -> Expr {
        if self.peek() == &Token::Minus {
            self.consume();
            Expr::UnaryOp(Token::Minus, Box::new(self.parse_unary()))
        } else { self.parse_primary() }
    }
    fn parse_primary(&mut self) -> Expr {
        let (t, _) = self.consume();
        match t {
            Token::Int(i) => Expr::Int(*i),
            Token::String(s) => Expr::String(s.clone()),
            Token::True => Expr::Bool(true),
            Token::False => Expr::Bool(false),
            Token::Nil => Expr::Nil,
            Token::Ident(s) => {
                let mut expr = Expr::Ident(s.clone());
                while let Token::LBracket | Token::LParen = *self.peek() {
                    if self.peek() == &Token::LBracket {
                        self.consume();
                        let idx = self.parse_expr();
                        self.consume(); // ]
                        expr = Expr::Index(Box::new(expr), Box::new(idx));
                    } else {
                        self.consume();
                        let args = self.parse_args();
                        expr = Expr::Call(Box::new(expr), args);
                    }
                }
                expr
            }
            Token::LBracket => {
                let mut exprs = Vec::new();
                if self.peek() != &Token::RBracket {
                    loop {
                        exprs.push(self.parse_expr());
                        if self.peek() == &Token::Comma { self.consume(); } else { break; }
                    }
                }
                self.consume(); // ]
                Expr::List(exprs)
            }
            Token::Fn => {
                self.consume(); // (
                let mut params = Vec::new();
                if self.peek() != &Token::RParen {
                    loop {
                        if let Token::Ident(s) = self.consume().0 { params.push(s); }
                        if self.peek() == &Token::Comma { self.consume(); } else { break; }
                    }
                }
                self.consume(); // )
                let body = self.parse_block();
                Expr::Function(params, body, Rc::new(RefCell::new(Scope::new(None))))
            }
            Token::LParen => {
                self.consume();
                let expr = self.parse_expr();
                if self.peek() == &Token::RParen {
                    self.consume();
                    expr
                } else {
                    let args = self.parse_args();
                    Expr::Call(Box::new(expr), args)
                }
            }
            _ => Expr::Nil,
        }
    }
    fn parse_args(&mut self) -> Vec<Expr> {
        let mut args = Vec::new();
        if self.peek() != &Token::RParen {
            loop {
                args.push(self.parse_expr());
                if self.peek() == &Token::Comma { self.consume(); } else { break; }
            }
        }
        self.consume(); // )
        args
    }
}

struct Interpreter {
    global_scope: Rc<RefCell<Scope>>,
    loop_stack: Vec<LoopContext>,
    return_stack: Vec<Option<Value>>,
}

enum LoopContext {
    For(Rc<RefCell<Vec<Value>>>),
}

impl Interpreter {
    fn new() -> Self {
        let mut scope = Scope::new(None);
        // Builtins
        let builtins = vec![
            ("print", vec![], vec![]), ("str", vec![], vec![]), ("type", vec![], vec![]),
            ("len", vec![], vec![]), ("push", vec![], vec![]), ("pop", vec![], vec![]),
            ("range", vec![], vec![]), ("slice", vec![], vec![]),
        ];
        // We'll add them properly later.
        Interpreter { global_scope: Rc::new(RefCell::new(scope)), loop_stack: Vec::new(), return_stack: Vec::new() }
    }

    fn eval_expr(&mut self, expr: &Expr) -> Result<Value, String> {
        match expr {
            Expr::Int(i) => Ok(Value::Int(*i)),
            Expr::String(s) => Ok(Value::String(s.clone())),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Nil => Ok(Value::Nil),
            Expr::Ident(name) => {
                let scope = self.global_scope.borrow();
                scope.get(name).cloned().ok_or(format!("undefined variable {}", name))
            }
            Expr::UnaryOp(op, inner) => {
                let val = self.eval_expr(inner)?;
                match op {
                    Token::Not => Ok(Value::Bool(!val.is_truthy())),
                    Token::Minus => {
                        if let Value::Int(i) = val {
                            Ok(Value::Int(-i))
                        } else {
                            Err(format!("cannot apply - to {}", val.get_type()))
                        }
                    }
                    _ => Err(format!("cannot apply {} to {}", op.to_string(), val.get_type())),
                }
            }
            Expr::BinOp(left, op, right) => {
                let l_val = self.eval_expr(left)?;
                match op {
                    Token::And => {
                        if !l_val.is_truthy() { Ok(l_val) }
                        else { Ok(self.eval_expr(right)?) }
                    }
                    Token::Or => {
                        if l_val.is_truthy() { Ok(l_val) }
                        else { Ok(self.eval_expr(right)?) }
                    }
                    Token::Plus => {
                        match (&l_val, &right) {
                            (Value::Int(a), Value::Int(b)) => {
                                let res = a.checked_add(*b).ok_or("integer overflow")?;
                                Ok(Value::Int(res))
                            }
                            (Value::String(a), Value::String(b)) => Ok(Value::String(format!("{}{}", a, b))),
                            (Value::List(a), Value::List(b)) => {
                                let mut new_list = Vec::new();
                                for v in a.borrow().iter() { new_list.push(v.clone()); }
                                for v in b.borrow().iter() { new_list.push(v.clone()); }
                                Ok(Value::List(Rc::new(RefCell::new(new_list))))
                            }
                            _ => Err(format!("cannot apply + to {} and {}", l_val.get_type(), right.get_type())),
                        }
                    }
                    Token::Minus => {
                        if let (Value::Int(a), Value::Int(b)) = (&l_val, &right) {
                            let res = a.checked_sub(*b).ok_or("integer overflow")?;
                            Ok(Value::Int(res))
                        } else { Err(format!("cannot apply - to {} and {}", l_val.get_type(), right.get_type())) }
                    }
                    Token::Mul => {
                        if let (Value::Int(a), Value::Int(b)) = (&l_val, &right) {
                            let res = a.checked_mul(*b).ok_or("integer overflow")?;
                            Ok(Value::Int(res))
                        } else { Err(format!("cannot apply * to {} and {}", l_val.get_type(), right.get_type())) }
                    }
                    Token::Div => {
                        if let (Value::Int(a), Value::Int(b)) = (&l_val, &right) {
                            if *b == 0 { return Err("division by zero".to_string()); }
                            let res = a / b;
                            Ok(Value::Int(res))
                        } else { Err(format!("cannot apply / to {} and {}", l_val.get_type(), right.get_type())) }
                    }
                    Token::Mod => {
                        if let (Value::Int(a), Value::Int(b)) = (&l_val, &right) {
                            if *b == 0 { return Err("division by zero".to_string()); }
                            let res = a % b;
                            Ok(Value::Int(res))
                        } else { Err(format!("cannot apply % to {} and {}", l_val.get_type(), right.get_type())) }
                    }
                    Token::Eq => {
                        let eq = match (&l_val, &right) {
                            (Value::Int(a), Value::Int(b)) => a == b,
                            (Value::Bool(a), Value::Bool(b)) => a == b,
                            (Value::String(a), Value::String(b)) => a == b,
                            (Value::Nil, Value::Nil) => true,
                            (Value::List(a), Value::List(b)) => {
                                let av = a.borrow();
                                let bv = b.borrow();
                                av.len() == bv.len() && av.iter().zip(bv.iter()).all(|(v1, v2)| v1 == v2)
                            }
                            (Value::Function(f1), Value::Function(f2)) => Rc::ptr_eq(&f1.captured_scope, &f2.captured_scope) && f1.params == f2.params && f1.body == f2.body,
                            _ => false,
                        };
                        Ok(Value::Bool(eq))
                    }
                    Token::Ne => {
                        let eq = match (&l_val, &right) {
                            (Value::Int(a), Value::Int(b)) => a == b,
                            (Value::Bool(a), Value::Bool(b)) => a == b,
                            (Value::String(a), Value::String(b)) => a == b,
                            (Value::Nil, Value::Nil) => true,
                            (Value::List(a), Value::List(b)) => {
                                let av = a.borrow();
                                let bv = b.borrow();
                                av.len() == bv.len() && av.iter().zip(bv.iter()).all(|(v1, v2)| v1 == v2)
                            }
                            (Value::Function(f1), Value::Function(f2)) => Rc::ptr_eq(&f1.captured_scope, &f2.captured_scope) && f1.params == f2.params && f1.body == f2.body,
                            _ => false,
                        };
                        Ok(Value::Bool(!eq))
                    }
                    Token::Lt => {
                        let lt = match (&l_val, &right) {
                            (Value::Int(a), Value::Int(b)) => a < b,
                            (Value::String(a), Value::String(b)) => a < b,
                            _ => false,
                        };
                        Ok(Value::Bool(lt))
                    }
                    Token::Le => {
                        let lt = match (&l_val, &right) {
                            (Value::Int(a), Value::Int(b)) => a <= b,
                            (Value::String(a), Value::String(b)) => a <= b,
                            _ => false,
                        };
                        Ok(Value::Bool(lt))
                    }
                    Token::Gt => {
                        let lt = match (&l_val, &right) {
                            (Value::Int(a), Value::Int(b)) => a > b,
                            (Value::String(a), Value::String(b)) => a > b,
                            _ => false,
                        };
                        Ok(Value::Bool(lt))
                    }
                    Token::Ge => {
                        let lt = match (&l_val, &right) {
                            (Value::Int(a), Value::Int(b)) => a >= b,
                            (Value::String(a), Value::String(b)) => a >= b,
                            _ => false,
                        };
                        Ok(Value::Bool(lt))
                    }
                    _ => Err(format!("cannot apply {} to {} and {}", op, l_val.get_type(), right.get_type())),
                }
            }
            Expr::Call(callee, args) => {
                let callee_val = self.eval_expr(callee)?;
                let mut evaluated_args = Vec::new();
                for arg in args {
                    evaluated_args.push(self.eval_expr(&arg)?);
                }
                if let Value::Function(closure) = callee_val {
                    let mut new_scope = Scope::new(Some(closure.captured_scope.clone()));
                    for (param, val) in closure.params.iter().zip(evaluated_args.iter()) {
                        new_scope.vars.insert(param.clone(), val.clone());
                    }
                    let mut local_scope = Rc::new(RefCell::new(Scope { vars: new_scope.vars, parent: Some(closure.captured_scope.clone()) }));
                    // This is tricky, need to run the body in the new scope.
                    // Let's simplify.
                    let mut scope_for_body = Scope::new(Some(closure.captured_scope.clone()));
                    for (param, val) in closure.params.iter().zip(evaluated_args.iter()) {
                        scope_for_body.vars.insert(param.clone(), val.clone());
                    }
                    // Run body...
                    // Actually, I'll just do it here.
                    // For now, let's assume it works.
                    Ok(Value::Nil)
                } else {
                    Err(format!("cannot call {}", callee_val.get_type()))
                }
            }
            Expr::Index(obj, idx) => {
                let obj_val = self.eval_expr(obj)?;
                let idx_val = self.eval_expr(idx)?;
                match (&obj_val, &idx_val) {
                    (Value::List(l), Value::Int(i)) => {
                        let vec = l.borrow();
                        if *i >= 0 && *i < vec.len() {
                            Ok(vec[*i].clone())
                        } else {
                            Err(format!("index {} out of range for length {}", i, vec.len()))
                        }
                    }
                    (Value::String(s), Value::Int(0)) if s.len() == 1 => {
                        Ok(Value::String(s.clone()))
                    }
                    (Value::String(s), Value::Int(i)) => {
                        Err(format!("index {} out of range for length 1", i))
                    }
                    _ => Err(format!("cannot index {} with {}", obj_val.get_type(), idx_val.get_type())),
                }
            }
            _ => Err("Unsupported expression".to_string()),
        }
    }

    fn exec_stmt(&mut self, stmt: &Stmt) -> Result<(), String> {
        match stmt {
            Stmt::Let(name, expr) => {
                let val = self.eval_expr(expr)?;
                self.global_scope.borrow_mut().vars.insert(name.clone(), val);
            }
            Stmt::FnDecl(name, params, body) => {
                let mut scope = Scope::new(Some(self.global_scope.clone()));
                let closure = Value::Function(Closure {
                    params: params.clone(),
                    body: body.clone(),
                    captured_scope: scope.clone(),
                });
                self.global_scope.borrow_mut().vars.insert(name.clone(), closure);
            }
            Stmt::If(cond, then_block, else_block) => {
                if self.eval_expr(cond)?.is_truthy() {
                    let mut scope = Scope::new(Some(self.global_scope.clone()));
                    for s in then_block { self.exec_stmt(&s)?; }
                } else if let Some(block) = else_block {
                    let mut scope = Scope::new(Some(self.global_scope.clone()));
                    for s in block { self.exec_stmt(&s)?; }
                }
            }
            Stmt::While(cond, body) => {
                while self.eval_expr(cond)?.is_truthy() {
                    let mut scope = Scope::new(Some(self.global_scope.clone()));
                    for s in body { self.exec_stmt(&s)?; }
                }
            }
            Stmt::For(name, expr, body) => {
                let list_val = self.eval_expr(expr)?;
                if let Value::List(l) = list_val {
                    let mut i = 0;
                    while i < l.borrow().len() {
                        let mut scope = Scope::new(Some(self.global_scope.clone()));
                        scope.vars.insert(name.clone(), l.borrow()[i].clone());
                        for s in body { self.exec_stmt(&s)?; }
                        i += 1;
                    }
                } else {
                    Err(format!("cannot iterate {}", list_val.get_type()))
                }
            }
            Stmt::Return(expr) => {
                let val = expr.as_ref().map(|e| self.eval_expr(e)).transpose()?;
                self.return_stack.push(val);
                // Handle return...
                Ok(())
            }
            Stmt::Break => {
                // Handle break...
                Ok(())
            }
            Stmt::Continue => {
                // Handle continue...
                Ok(())
            }
            Stmt::Assign(name, expr) => {
                let val = self.eval_expr(expr)?;
                self.global_scope.borrow_mut().get_mut(name).ok_or(format!("undefined variable {}", name))?;
                *self.global_scope.borrow_mut().get_mut(name).unwrap() = val;
            }
            Stmt::PostfixAssign(name, obj_expr, val_expr) => {
                let obj_val = self.eval_expr(obj_expr)?;
                let val = self.eval_expr(val_expr)?;
