use std::fs;
use std::path::Path;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Kind {
    Create,
    Delete,
    Modify,
}

struct Hunk {
    a: usize,
    b: usize,
    c: usize,
    d: usize,
    old_lines: Vec<Vec<u8>>,
    new_lines: Vec<Vec<u8>>,
    applied: bool,
    offset: i32,
    status: HunkStatus,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum HunkStatus {
    Applied,
    Rejected,
    Malformed,
}

struct Section {
    path: String,
    kind: Kind,
    hunks: Vec<Hunk>,
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn split_lines(data: &[u8]) -> Vec<Vec<u8>> {
    let mut lines = Vec::new();
    let mut start = 0;
    while start < data.len() {
        let mut end = start;
        while end < data.len() && data[end] != b'\n' {
            end += 1;
        }
        if end < data.len() {
            lines.push(data[start..=end].to_vec());
            start = end + 1;
        } else {
            lines.push(data[start..].to_vec());
            start = data.len() + 1;
        }
    }
    lines
}

fn parse_range(s: &str) -> (usize, usize) {
    let parts: Vec<&str> = s.split(',').collect();
    let start = parts[0].parse().unwrap_or(0);
    let count = if parts.len() > 1 {
        parts[1].parse().unwrap_or(1)
    } else {
        1
    };
    (start, count)
}

