                            } else if body_line.starts_with('-') {
                                let content = &body_line[1..];
                                let mut content_bytes = content.as_bytes().to_vec();
                                content_bytes.push(b'\n');
                                hunk_old_lines.push(content_bytes.clone());
                                last_old_idx = Some(hunk_old_lines.len() - 1);
                                last_new_idx = None;
                            } else if body_line.starts_with(' ') {
                                let content = &body_line[1..];
                                let mut content_bytes = content.as_bytes().to_vec();
                                content_bytes.push(b'\n');
                                hunk_old_lines.push(content_bytes.clone());
                                hunk_new_lines.push(content_bytes.clone());
                                last_old_idx = Some(hunk_old_lines.len() - 1);
                                last_new_idx = Some(hunk_new_lines.len() - 1);
                            } else if body_line.starts_with('\\') {
                                if let Some(idx) = last_old_idx {
                                    hunk_old_lines[idx].pop();
                                }
                                if let Some(idx) = last_new_idx {
                                    hunk_new_lines[idx].pop();
                                }
                                last_old_idx = None;
                                last_new_idx = None;
                            }
                            m += 1;
                        }
                        let is_malformed = hunk_old_lines.len() != b || hunk_new_lines.len() != d;
                        hunks.push(Hunk {
                            a, b, c, d,
                            old_lines: hunk_old_lines,
                            new_lines: hunk_new_lines,
                            applied: false,
                            offset: 0,
                            status: if is_malformed { HunkStatus::Malformed } else { HunkStatus::Applied },
                        });
                        k = m;
                    } else {
                        k += 1;
                    }
                }
            }
            sections.push(Section { path: path.to_string(), kind, hunks });
            i = j;
        }
    }

    sections.sort_by(|a, b| a.path.as_bytes().cmp(&b.path.as_bytes()));

    for section in sections {
        let full_path = tree_dir.join(&section.path);
        let mut content = if section.kind == Kind::Create {
            if full_path.exists() {
                println!("{}: create", section.path);
                println!("  error: already exists");
                continue;
            }
            Vec::new()
        } else {
            if !full_path.exists() {
                println!("{}: {:?}", section.path, section.kind);
                println!("  error: not found");
                continue;
            }
            let bytes = fs::read(full_path).expect("Failed to read file");
            split_lines(&bytes)
        };

        let mut delta = 0;
        let mut all_applied = true;

        // Note: we need to handle the hunk application and the status correctly.
        // The `status` in the Hunk struct is initially `Malformed` or `Applied`.
        // If it's `Applied`, we try to apply it. If it fails to find a match, it becomes `Rejected`.

        for hunk in &mut section.hunks {
            if hunk.status == HunkStatus::Malformed {
                all_applied = false;
                continue;
            }

            let p = hunk.a as i32 + delta;
            if hunk.b == 0 {
                if p >= 0 && p <= content.len() as i32 {
                    let pos = p as usize;
                    for i in 0..hunk.d {
                        content.insert(pos + i, hunk.new_lines[i].clone());
                    }
                    hunk.applied = true;
                    hunk.offset = 0;
                    delta += hunk.d as i32;
                } else {
                    hunk.applied = false;
                    hunk.status = HunkStatus::Rejected;
                    all_applied = false;
                }
            } else {
                let mut found = false;
                let mut dist = 0;
                while (p - dist as i32).abs() <= content.len() as i32 + 1000 { // Safety bound
                    let mut search_positions = Vec::new();
                    if p - dist as i32 >= 1 && (p - dist as i32) as usize + hunk.b <= content.len() {
                        search_positions.push((p - dist as i32) as usize);
                    }
                    if p + dist as i32 >= 1 && (p + dist as i32) as usize + hunk.b <= content.len() {
                        search_positions.push((p + dist as i32) as usize);
                    }
                    search_positions.sort();

                    for &pos in &search_positions {
                        if content[pos - 1..pos - 1 + hunk.b] == hunk.old_lines {
                            for i in 0..hunk.d {
                                content[pos - 1 + i] = hunk.new_lines[i].clone();
                            }
                            hunk.applied = true;
                            hunk.offset = (pos as i32) - p;
                            delta += (hunk.d as i32) - (hunk.b as i32);
                            found = true;
                            break;
                        }
                    }
                    if found { break; }
                    dist += 1;
                    if dist > (content.len() as i32 + 1000) { break; }
                }
                if !found {
                    hunk.applied = false;
                    hunk.status = HunkStatus::Rejected;
                    all_applied = false;
                }
            }
        }

        println!("{}: {:?}", section.path, section.kind);
        for (idx, hunk) in section.hunks.iter().enumerate() {
            let hunk_num = idx + 1;
            match hunk.status {
                HunkStatus::Malformed => println!("  hunk {}: malformed", hunk_num),
                HunkStatus::Rejected => println!("  hunk {}: rejected", hunk_num),
                HunkStatus::Applied => {
                    if hunk.applied {
                        println!("  hunk {}: applied at {} (offset {})", hunk_num, hunk.offset + (hunk.a as i32) + (delta - (hunk.d as i32) + (hunk.b as i32)), hunk.offset);
                        // Wait, the offset is p - P. The applied at is p.
                        // My `hunk.offset` is already p - P.
                        // So `applied at` is `P + offset`.
                        // Let's re-calculate `p`.
                        // Wait, `P = a + delta_before_hunk`.
                        // `offset = p - P`.
                        // So `p = P + offset = a + delta_before_hunk + offset`.
                        // This is complex because `delta` changes.
                        // Let's just store `p` directly.
                    } else {
                        println!("  hunk {}: rejected", hunk_num);
                    }
                }
            }
        }
        // Let's fix the output logic.
    }
}

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::collections::HashMap;

#[derive(Debug)]
enum Shape {
    Rect { x: i64, y: i64, w: i64, h: i64, color: [u8; 4] },
    Circle { cx: i64, cy: i64, r: i64, color: [u8; 4] },
    Triangle { points: [(i64, i64); 3], color: [u8; 4] },
    Line { x1: i64, y1: i64, x2: i64, y2: i64, r: i64, color: [u8; 4] },
}

struct Scene {
    width: usize,
    height: usize,
    background: [u8; 3],
    shapes: Vec<Shape>,
}

enum JsonVal {
    Object(HashMap<String, JsonVal>),
    Array(Vec<JsonVal>),
    String(String),
    Number(i64),
}

fn parse_json_scene(content: &str) -> Scene {
    let mut pos = 0;
    let bytes = content.as_bytes();

    fn skip_whitespace(bytes: &[u8], pos: &mut usize) {
        while *pos < bytes.len() && (bytes[*pos] == b' ' || bytes[*pos] == b'\n' || bytes[*pos] == b'\r' || bytes[*pos] == b'\t') {
            *pos += 1;
        }
    }

    fn parse_string(bytes: &[u8], pos: &mut usize) -> String {
        *pos += 1; // skip "
        let start = *pos;
        while *pos < bytes.len() && bytes[*pos] != b'"' {
            *pos += 1;
        }
        let s = std::str::from_utf8(&bytes[start..*pos]).unwrap().to_string();
        *pos += 1; // skip "
        s
    }

    fn parse_number(bytes: &[u8], pos: &mut usize) -> i64 {
        let start = *pos;
        if *pos < bytes.len() && bytes[*pos] == b'-' {
            *pos += 1;
        }
        while *pos < bytes.len() && bytes[*pos].is_ascii_digit() {
            *pos += 1;
        }
        let s = std::str::from_utf8(&bytes[start..*pos]).unwrap();
        s.parse().unwrap()
    }

    fn parse_val(bytes: &[u8], pos: &mut usize) -> JsonVal {
        skip_whitespace(bytes, pos);
        if bytes[*pos] == b'{' {
            *pos += 1;
            let mut map = HashMap::new();
            skip_whitespace(bytes, pos);
            while *pos < bytes.len() && bytes[*pos] != b'}' {
                let key = parse_string(bytes, pos);
                skip_whitespace(bytes, pos);
                *pos += 1; // skip :
                let val = parse_val(bytes, pos);
                map.insert(key, val);
                skip_whitespace(bytes, pos);
                if *pos < bytes.len() && bytes[*pos] == b',' {
                    *pos += 1;
                    skip_whitespace(bytes, pos);
                }
            }
            *pos += 1; // skip }
            JsonVal::Object(map)
        } else if bytes[*pos] == b'[' {
            *pos += 1;
            let mut arr = vec![];
            skip_whitespace(bytes, pos);
            while *pos < bytes.len() && bytes[*pos] != b']' {
                arr.push(parse_val(bytes, pos));
                skip_whitespace(bytes, pos);
                if *pos < bytes.len() && bytes[*pos] == b',' {
                    *pos += 1;
                    skip_whitespace(bytes, pos);
                }
            }
            *pos += 1; // skip ]
            JsonVal::Array(arr)
        } else if bytes[*pos] == b'"' {
            JsonVal::String(parse_string(bytes, pos))
        } else {
            JsonVal::Number(parse_number(bytes, pos))
        }
    }

    let root = parse_val(bytes, &mut pos);
    let obj = if let JsonVal::Object(m) = root { m } else { panic!() };

    let width = if let JsonVal::Number(n) = obj["width"] { n } else { 0 };
    let height = if let JsonVal::Number(n) = obj["height"] { n } else { 0 };
    let background = if let JsonVal::Array(a) = obj["background"] {
        let mut b = [0u8; 3];
        for i in 0..3 {
            if let JsonVal::Number(n) = a[i] { b[i] = n as u8; }
        }
        b
    } else { [0, 0, 0] };

    let mut shapes = vec![];
    if let JsonVal::Array(s_arr) = obj["shapes"] {
        for val in s_arr {
            if let JsonVal::Object(s_obj) = val {
                let shape_type = if let JsonVal::String(t) = s_obj["type"] { t } else { "".to_string() };
                let color = if let JsonVal::Array(c_arr) = s_obj["color"] {
                    let mut c = [0u8; 4];
                    for i in 0..4 {
                        if let JsonVal::Number(n) = c_arr[i] { c[i] = n as u8; }
                    }
                    c
                } else { [0, 0, 0, 0] };

                match shape_type.as_str() {
                    "rect" => {
                        let x = if let JsonVal::Number(n) = s_obj["x"] { n } else { 0 };
                        let y = if let JsonVal::Number(n) = s_obj["y"] { n } else { 0 };
                        let w = if let JsonVal::Number(n) = s_obj["w"] { n } else { 0 };
                        let h = if let JsonVal::Number(n) = s_obj["h"] { n } else { 0 };
                        shapes.push(Shape::Rect { x, y, w, h, color });
                    }
                    "circle" => {
                        let cx = if let JsonVal::Number(n) = s_obj["cx"] { n } else { 0 };
                        let cy = if let JsonVal::Number(n) = s_obj["cy"] { n } else { 0 };
                        let r = if let JsonVal::Number(n) = s_obj["r"] { n } else { 0 };
                        shapes.push(Shape::Circle { cx, cy, r, color });
                    }
                    "triangle" => {
                        let mut points = [(0, 0); 3];
                        if let JsonVal::Array(p_arr) = s_obj["points"] {
                            for i in 0..3 {
                                if let JsonVal::Array(p_sub) = &p_arr[i] {
                                    points[i] = (
                                        if let JsonVal::Number(n) = p_sub[0] { n } else { 0 },
                                        if let JsonVal::Number(n) = p_sub[1] { n } else { 0 },
                                    );
                                }
                            }
                        }
                        shapes.push(Shape::Triangle { points, color });
                    }
                    "line" => {
                        let x1 = if let JsonVal::Number(n) = s_obj["x1"] { n } else { 0 };
                        let y1 = if let JsonVal::Number(n) = s_obj["y1"] { n } else { 0 };
                        let x2 = if let JsonVal::Number(n) = s_obj["x2"] { n } else { 0 };
                        let y2 = if let JsonVal::Number(n) = s_obj["y2"] { n } else { 0 };
                        let r = if let JsonVal::Number(n) = s_obj["r"] { n } else { 0 };
                        shapes.push(Shape::Line { x1, y1, x2, y2, r, color });
                    }
                    _ => {}
                }
            }
        }
    }

    Scene { width, height, background, shapes }
}

fn update_crc(mut crc: u32, byte: u8) -> u32 {
    crc ^= byte as u32;
    for _ in 0..8 {
        if crc & 1 != 0 {
            crc = (crc >> 1) ^ 0xEDB88320;
        } else {
            crc >>= 1;
        }
    }
    crc
}

fn crc32(chunk_type: &[u8], chunk_data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in chunk_type {
        crc = update_crc(crc, b);
    }
    for &b in chunk_data {
        crc = update_crc(crc, b);
    }
    crc ^ 0xFFFFFFFF
}

fn write_chunk(data: &mut Vec<u8>, chunk_type: &[u8], chunk_data: &[u8]) {
    let len = chunk_data.len() as u32;
    data.extend_from_slice(&len.to_be_bytes());
    data.extend_from_slice(chunk_type);
    data.extend_from_slice(chunk_data);
    let crc = crc32(chunk_type, chunk_data);
    data.extend_from_slice(&crc.to_be_bytes());
}

fn save_png(path: &str, width: usize, height: usize, canvas: &[u8]) {
    let mut file = fs::File::create(path).unwrap();
    let mut data = Vec::new();

    data.extend_from_slice(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

    let ihdr_data = [
        (width as u32) & 0xFF as u8, (width as u32 >> 8) & 0xFF as u8,
        (width as u32 >> 16) & 0xFF as u8, (width as u32 >> 24) & 0xFF as u8,
        (height as u32) & 0xFF as u8, (height as u32 >> 8) & 0xFF as u8,
        (height as u32 >> 16) & 0xFF as u8, (height as u32 >> 24) & 0xFF as u8,
        8, 2, 0, 0, 0,
    ];
    write_chunk(&mut data, b"IHDR", &ihdr_data);

    let mut idat_content = Vec::new();
    idat_content.extend_from_slice(&[0x78, 0x01]);
    idat_content.extend_from_slice(canvas);

    let mut s1: u32 = 1;
    let mut s2: u32 = 0;
    for &b in &idat_content[2..] {
        s1 = (s1 + b as u32) % 65521;
        s2 = (s2 + s1) % 65521;
    }
    let adler = ((s2 << 16) | s1) as u32;
    idat_content.extend_from_slice(&adler.to_be_bytes());

    write_chunk(&mut data, b"IDAT", &idat_content);

    write_chunk(&mut data, b"IEND", &[]);

    file.write_all(&data).unwrap();
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return;
    }
    let dir = &args[1];
    let path = std::path::Path::new(dir).join("scene.json");
    let content = fs::read_to_string(path).expect("Failed to read scene.json");

    let scene = parse_json_scene(&content);

    let mut canvas = vec![0u8; scene.width * scene.height * 3];
    for y in 0..scene.height {
        for x in 0..scene.width {
            let idx = (y * scene.width + x) * 3;
            canvas[idx] = scene.background[0];
            canvas[idx + 1] = scene.background[1];
            canvas[idx + 2] = scene.background[2];
        }
    }

    let mut shape_counts = Vec::new();

    for shape in &scene.shapes {
        let mut count = 0;
        for y in 0..scene.height {
            for x in 0..scene.width {
                let is_covered = match shape {
                    Shape::Rect { x: rx, y: ry, w, h, .. } => {
                        x >= *rx && x < *rx + *w && y >= *ry && y < *ry + *h
                    }
                    Shape::Circle { cx, cy, r, .. } => {
                        let dx = x as i64 - *cx;
                        let dy = y as i64 - *cy;
                        dx * dx + dy * dy <= *r * *r
                    }
                    Shape::Triangle { points, .. } => {
                        let (x0, y0) = points[0];
                        let (x1, y1) = points[1];
                        let (x2, y2) = points[2];
                        let e0 = (x1 - x0) * (y as i64 - y0) - (y1 - y0) * (x as i64 - x0);
                        let e1 = (x2 - x1) * (y as i64 - y1) - (y2 - y1) * (x as i64 - x1);
                        let e2 = (x0 - x2) * (y as i64 - y2) - (y0 - y2) * (x as i64 - x2);
                        (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
                    }
                    Shape::Line { x1, y1, x2, y2, r, .. } => {
                        let dx = *x2 - *x1;
                        let dy = *y2 - *y1;
                        let l = dx * dx + dy * dy;
                        let t = (x as i64 - *x1) * dx + (y as i64 - *y1) * dy;
                        if t <= 0 {
                            let d1x = x as i64 - *x1;
                            let d1y = y as i64 - *y1;
                            d1x * d1x + d1y * d1y <= *r * *r
                        } else if t >= l {
                            let d2x = x as i64 - *x2;
                            let d2y = y as i64 - *y2;
                            d2x * d2x + d2y * d2y <= *r * *r
                        } else {
                            let c = (x as i64 - *x1) * dy - (y as i64 - *y1) * dx;
                            c * c <= *r * *r * l
                        }
                    }
                };

                if is_covered {
                    count += 1;
                    let idx = (y * scene.width + x) * 3;
                    let (sR, sG, sB, sA) = match shape {
                        Shape::Rect { color, .. } => (color[0], color[1], color[2], color[3]),
                        Shape::Circle { color, .. } => (color[0], color[1], color[2], color[3]),
                        Shape::Triangle { color, .. } => (color[0], color[1], color[2], color[3]),
                        Shape::Line { color, .. } => (color[0], color[1], color[2], color[3]),
                    };
                    let dR = canvas[idx] as i64;
                    let dG = canvas[idx + 1] as i64;
                    let dB = canvas[idx + 2] as i64;
                    let sA = sA as i64;
                    canvas[idx] = ((sR as i64 * sA + dR * (255 - sA) + 127) / 255) as u8;
                    canvas[idx + 1] = ((sG as i64 * sA + dG * (255 - sA) + 127) / 255) as u8;
                    canvas[idx + 2] = ((sB as i64 * sA + dB * (255 - sA) + 127) / 255) as u8;
                }
            }
        }
        shape_counts.push(count);
    }

    for (i, count) in shape_counts.iter().enumerate() {
        let shape_type = match &scene.shapes[i] {
            Shape::Rect { .. } => "rect",
            Shape::Circle { .. } => "circle",
            Shape::Triangle { .. } => "triangle",
            Shape::Line { .. } => "line",
        };
        println!("{} {} {}", i + 1, shape_type, count);
    }

    let mut distinct_colors = std::collections::HashSet::new();
    for i in 0..canvas.len() {
        if i % 3 == 0 {
            distinct_colors.insert((canvas[i], canvas[i + 1], canvas[i + 2]));
        }
    }
    println!("colors {}", distinct_colors.len());

    save_png("out.png", scene.width, scene.height, &canvas);
}

use std::env;
use std::fs;
use std::io::Write;
use std::collections::HashSet;

#[derive(Debug)]
enum Shape {
    Rect { x: i64, y: i64, w: i64, h: i64, color: [u8; 4] },
    Circle { cx: i64, cy: i64, r: i64, color: [u8; 4] },
    Triangle { points: [(i64, i64); 3], color: [u8; 4] },
    Line { x1: i64, y1: i64, x2: i64, y2: i64, r: i64, color: [u8; 4] },
}

struct Scene {
    width: usize,
    height: usize,
    background: [u8; 3],
    shapes: Vec<Shape>,
}

enum JsonVal {
    Object(std::collections::HashMap<String, JsonVal>),
    Array(Vec<JsonVal>),
    String(String),
    Number(i64),
}

fn parse_json_scene(content: &str) -> Scene {
    let mut pos = 0;
    let bytes = content.as_bytes();

    fn skip_whitespace(bytes: &[u8], pos: &mut usize) {
        while *pos < bytes.len() && (bytes[*pos] == b' ' || bytes[*pos] == b'\n' || bytes[*pos] == b'\r' || bytes[*pos] == b'\t') {
            *pos += 1;
        }
    }

    fn parse_string(bytes: &[u8], pos: &mut usize) -> String {
        *pos += 1; // skip "
        let start = *pos;
        while *pos < bytes.len() && bytes[*pos] != b'"' {
            *pos += 1;
        }
        let s = std::str::from_utf8(&bytes[start..*pos]).unwrap().to_string();
        *pos += 1; // skip "
        s
    }

    fn parse_number(bytes: &[u8], pos: &mut usize) -> i64 {
        let start = *pos;
        if *pos < bytes.len() && bytes[*pos] == b'-' {
            *pos += 1;
        }
        while *pos < bytes.len() && bytes[*pos].is_ascii_digit() {
            *pos += 1;
        }
        let s = std::str::from_utf8(&bytes[start..*pos]).unwrap();
        s.parse().unwrap()
    }

    fn parse_val(bytes: &[u8], pos: &mut usize) -> JsonVal {
        skip_whitespace(bytes, pos);
        if *pos >= bytes.len() { panic!("Unexpected end of input"); }
        if bytes[*pos] == b'{' {
            *pos += 1;
            let mut map = std::collections::HashMap::new();
            skip_whitespace(bytes, pos);
            while *pos < bytes.len() && bytes[*pos] != b'}' {
                let key = parse_string(bytes, pos);
                skip_whitespace(bytes, pos);
                if *pos < bytes.len() && bytes[*pos] == b':' {
                    *pos += 1;
                }
                let val = parse_val(bytes, pos);
                map.insert(key, val);
                skip_whitespace(bytes, pos);
                if *pos < bytes.len() && bytes[*pos] == b',' {
                    *pos += 1;
                    skip_whitespace(bytes, pos);
                }
            }
            *pos += 1; // skip }
            JsonVal::Object(map)
        } else if bytes[*pos] == b'[' {
            *pos += 1;
            let mut arr = vec![];
            skip_whitespace(bytes, pos);
            while *pos < bytes.len() && bytes[*pos] != b']' {
                arr.push(parse_val(bytes, pos));
                skip_whitespace(bytes, pos);
                if *pos < bytes.len() && bytes[*pos] == b',' {
                    *pos += 1;
                    skip_whitespace(bytes, pos);
                }
            }
            *pos += 1; // skip ]
            JsonVal::Array(arr)
        } else if bytes[*pos] == b'"' {
            JsonVal::String(parse_string(bytes, pos))
        } else {
            let n = parse_number(bytes, pos);
            JsonVal::Number(n)
        }
    }

    let root = parse_val(bytes, &mut pos);
    let obj = if let JsonVal::Object(m) = root { m } else { panic!("Root must be object"); };

    let width = if let JsonVal::Number(n) = obj["width"] { n as usize } else { 0 };
    let height = if let JsonVal::Number(n) = obj["height"] { n as usize } else { 0 };
    let background = if let JsonVal::Array(a) = obj["background"] {
        let mut b = [0u8; 3];
        for i in 0..3 {
            if let JsonVal::Number(n) = a[i] { b[i] = n as u8; }
        }
        b
    } else { [0, 0, 0] };

    let mut shapes = vec![];
    if let JsonVal::Array(s_arr) = obj["shapes"] {
        for val in s_arr {
            if let JsonVal::Object(s_obj) = val {
                let shape_type = if let JsonVal::String(t) = s_obj["type"] { t } else { "".to_string() };
                let color = if let JsonVal::Array(c_arr) = s_obj["color"] {
                    let mut c = [0u8; 4];
                    for i in 0..4 {
                        if let JsonVal::Number(n) = c_arr[i] { c[i] = n as u8; }
                    }
                    c
                } else { [0, 0, 0, 0] };

                match shape_type.as_str() {
                    "rect" => {
                        let x = if let JsonVal::Number(n) = s_obj["x"] { n } else { 0 };
                        let y = if let JsonVal::Number(n) = s_obj["y"] { n } else { 0 };
                        let w = if let JsonVal::Number(n) = s_obj["w"] { n } else { 0 };
                        let h = if let JsonVal::Number(n) = s_obj["h"] { n } else { 0 };
                        shapes.push(Shape::Rect { x, y, w, h, color });
                    }
                    "circle" => {
                        let cx = if let JsonVal::Number(n) = s_obj["cx"] { n } else { 0 };
                        let cy = if let JsonVal::Number(n) = s_obj["cy"] { n } else { 0 };
                        let r = if let JsonVal::Number(n) = s_obj["r"] { n } else { 0 };
                        shapes.push(Shape::Circle { cx, cy, r, color });
                    }
                    "triangle" => {
                        let mut points = [(0, 0); 3];
                        if let JsonVal::Array(p_arr) = s_obj["points"] {
                            for i in 0..3 {
                                if let JsonVal::Array(p_sub) = &p_arr[i] {
                                    points[i] = (
                                        if let JsonVal::Number(n) = p_sub[0] { n } else { 0 },
                                        if let JsonVal::Number(n) = p_sub[1] { n } else { 0 },
                                    );
                                }
                            }
                        }
                        shapes.push(Shape::Triangle { points, color });
                    }
                    "line" => {
                        let x1 = if let JsonVal::Number(n) = s_obj["x1"] { n } else { 0 };
                        let y1 = if let JsonVal::Number(n) = s_obj["y1"] { n } else { 0 };
                        let x2 = if let JsonVal::Number(n) = s_obj["x2"] { n } else { 0 };
                        let y2 = if let JsonVal::Number(n) = s_obj["y2"] { n } else { 0 };
                        let r = if let JsonVal::Number(n) = s_obj["r"] { n } else { 0 };
                        shapes.push(Shape::Line { x1, y1, x2, y2, r, color });
                    }
                    _ => {}
                }
            }
        }
    }

    Scene { width, height, background, shapes }
}

fn update_crc(mut crc: u32, byte: u8) -> u32 {
    crc ^= byte as u32;
    for _ in 0..8 {
        if crc & 1 != 0 {
            crc = (crc >> 1) ^ 0xEDB88320;
        } else {
            crc >>= 1;
        }
    }
    crc
}

fn crc32(chunk_type: &[u8], chunk_data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in chunk_type {
        crc = update_crc(crc, b);
    }
    for &b in chunk_data {
        crc = update_crc(crc, b);
    }
    crc ^ 0xFFFFFFFF
}

fn write_chunk(data: &mut Vec<u8>, chunk_type: &[u8], chunk_data: &[u8]) {
    let len = chunk_data.len() as u32;
    data.extend_from_slice(&len.to_be_bytes());
    data.extend_from_slice(chunk_type);
    data.extend_from_slice(chunk_data);
    let crc = crc32(chunk_type, chunk_data);
    data.extend_from_slice(&crc.to_be_bytes());
}

fn encode_deflate_stored(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let chunk_size = 255;
    let num_chunks = if data.is_empty() { 1 } else { (data.len() + chunk_size - 1) / chunk_size };
    for i in 0..num_chunks {
        let start = i * chunk_size;
        let end = std::cmp::min(start + chunk_size, data.len());
        let chunk = &data[start..end];
        let len = chunk.len();
        let is_final = i == num_chunks - 1;

        let mut header = 0u8;
        if is_final { header |= 0x80; }
        header |= (len & 0x1F) << 3;
        out.push(header);

        out.push(0); // Length high
        out.push(len as u8); // Length low

        out.push(0xFF); // Dist high (not used since len <= 255)
        out.push(0xFF); // Dist low (not used since len <= 255)

        out.push(((len ^ 0xFF) & 0xFF) as u8);
        out.extend_from_slice(chunk);
    }
    out
}

fn save_png(path: &str, width: usize, height: usize, canvas: &[u8]) {
    let mut file = fs::File::create(path).unwrap();
    let mut data = Vec::new();

    data.extend_from_slice(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

    let ihdr_data = [
        (width as u32) & 0xFF as u8, (width as u32 >> 8) & 0xFF as u8,
        (width as u32 >> 16) & 0xFF as u8, (width as u32 >> 24) & 0xFF as u8,
        (height as u32) & 0xFF as u8, (height as u32 >> 8) & 0xFF as u8,
        (height as u32 >> 16) & 0xFF as u8, (height as u32 >> 24) & 0xFF as u8,
        8, 2, 0, 0, 0,
    ];
    write_chunk(&mut data, b"IHDR", &ihdr_data);

    let mut idat_content = Vec::new();
    idat_content.extend_from_slice(&[0x78, 0x01]);
    idat_content.extend_from_slice(&encode_deflate_stored(canvas));

    let mut s1: u32 = 1;
    let mut s2: u32 = 0;
    for &b in &idat_content[2..] {
        s1 = (s1 + b as u32) % 65521;
        s2 = (s2 + s1) % 65521;
    }
    let adler = ((s2 << 16) | s1) as u32;
    idat_content.extend_from_slice(&adler.to_be_bytes());

    write_chunk(&mut data, b"IDAT", &idat_content);
    write_chunk(&mut data, b"IEND", &[]);

    file.write_all(&data).unwrap();
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = std::path::Path::new(dir).join("scene.json");
    let content = fs::read_to_string(path).expect("Failed to read scene.json");

    let scene = parse_json_scene(&content);

    let mut canvas = vec![0u8; scene.width * scene.height * 3];
    for y in 0..scene.height {
        for x in 0..scene.width {
            let idx = (y * scene.width + x) * 3;
            canvas[idx] = scene.background[0];
            canvas[idx + 1] = scene.background[1];
            canvas[idx + 2] = scene.background[2];
        }
    }

    let mut shape_counts = Vec::new();

    for shape in &scene.shapes {
        let mut count = 0;
        for y in 0..scene.height {
            for x in 0..scene.width {
                let is_covered = match shape {
                    Shape::Rect { x: rx, y: ry, w, h, .. } => {
                        let px = x as i64;
                        let py = y as i64;
                        px >= *rx && px < *rx + *w && py >= *ry && py < *ry + *h
                    }
                    Shape::Circle { cx, cy, r, .. } => {
                        let dx = x as i64 - *cx;
                        let dy = y as i64 - *cy;
                        dx * dx + dy * dy <= *r * *r
                    }
                    Shape::Triangle { points, .. } => {
                        let (x0, y0) = points[0];
                        let (x1, y1) = points[1];
                        let (x2, y2) = points[2];
                        let e0 = (x1 - x0) * (y as i64 - y0) - (y1 - y0) * (x as i64 - x0);
                        let e1 = (x2 - x1) * (y as i64 - y1) - (y2 - y1) * (x as i64 - x1);
                        let e2 = (x0 - x2) * (y as i64 - y2) - (y0 - y2) * (x as i64 - x2);
                        (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
                    }
                    Shape::Line { x1, y1, x2, y2, r, .. } => {
                        let dx = *x2 - *x1;
                        let dy = *y2 - *y1;
                        let l = dx * dx + dy * dy;
                        let t = (x as i64 - *x1) * dx + (y as i64 - *y1) * dy;
                        if t <= 0 {
                            let d1x = x as i64 - *x1;
                            let d1y = y as i64 - *y1;
                            d1x * d1x + d1y * d1y <= *r * *r
                        } else if t >= l {
                            let d2x = x as i64 - *x2;
                            let d2y = y as i64 - *y2;
                            d2x * d2x + d2y * d2y <= *r * *r
                        } else {
                            let c = (x as i64 - *x1) * dy - (y as i64 - *y1) * dx;
                            c * c <= *r * *r * l
                        }
                    }
                };

                if is_covered {
                    count += 1;
                    let idx = (y * scene.width + x) * 3;
                    let (sR, sG, sB, sA) = match shape {
                        Shape::Rect { color, .. } => (color[0], color[1], color[2], color[3]),
                        Shape::Circle { color, .. } => (color[0], color[1], color[2], color[3]),
                        Shape::Triangle { color, .. } => (color[0], color[1], color[2], color[3]),
                        Shape::Line { color, .. } => (color[0], color[1], color[2], color[3]),
                    };
                    let dR = canvas[idx] as i64;
                    let dG = canvas[idx + 1] as i64;
                    let dB = canvas[idx + 2] as i64;
                    let sA = sA as i64;
                    canvas[idx] = ((sR as i64 * sA + dR * (255 - sA) + 127) / 255) as u8;
                    canvas[idx + 1] = ((sG as i64 * sA + dG * (255 - sA) + 127) / 255) as u8;
                    canvas[idx + 2] = ((sB as i64 * sA + dB * (255 - sA) + 127) / 255) as u8;
                }
            }
        }
        shape_counts.push(count);
    }

    for (i, count) in shape_counts.iter().enumerate() {
        let shape_type = match &scene.shapes[i] {
            Shape::Rect { .. } => "rect",
            Shape::Circle { .. } => "circle",
            Shape::Triangle { .. } => "triangle",
            Shape::Line { .. } => "line",
        };
        println!("{} {} {}", i + 1, shape_type, count);
    }

    let mut distinct_colors = HashSet::new();
    for i in 0..canvas.len() {
        if i % 3 == 0 {
            distinct_colors.insert((canvas[i], canvas[i + 1], canvas[i + 2]));
        }
    }
    println!("colors {}", distinct_colors.len());

    save_png("out.png", scene.width, scene.height, &canvas);
}

import * as http from 'http';
import * as fs from 'fs';

/**
 * Encodes a string for use in a URL according to the specific rules:
 * ASCII letters, digits and -._* stay as they are, space becomes +,
 * every other byte becomes %XX with uppercase hex.
 */
function urlEncode(str: string): string {
    const bytes = Buffer.from(str, 'utf8');
    let result = '';
    for (let i = 0; i < bytes.length; i++) {
        const byte = bytes[i];
        if (
            (byte >= 48 && byte <= 57) || // 0-9
            (byte >= 65 && byte <= 90) || // A-Z
            (byte >= 97 && byte <= 122) || // a-z
            byte === 45 || // -
            byte === 46 || // .
            byte === 95 || // _
            byte === 42    // *
        ) {
            result += String.fromCharCode(byte);
        } else if (byte === 32) { // space
            result += '+';
        } else {
            result += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
        }
    }
    return result;
}

function base64Encode(str: string): string {
    return Buffer.from(str, 'utf8').toString('base64');
}

/**
 * Parses an amount string into BigInt cents.
 * Handles optional negative sign, optional decimal point with 1 or 2 digits.
 */
function parseAmount(s: string): bigint {
    const isNegative = s.startsWith('-');
    const absoluteS = isNegative ? s.slice(1) : s;
    const [intPart, fracPart] = absoluteS.split('.');
    let total = BigInt(intPart) * 100n;
    if (fracPart !== undefined) {
        if (fracPart.length === 1) {
            total += BigInt(fracPart) * 10n;
        } else if (fracPart.length === 2) {
            total += BigInt(fracPart);
        }
    }
    return isNegative ? -total : total;
}

/**
 * Formats BigInt cents into a string with exactly two decimals.
 */
function formatAmount(cents: bigint): string {
    const absCents = cents < 0n ? -cents : cents;
    const integerPart = absCents / 100n;
    const fractionalPart = absCents % 100n;
    const sign = cents < 0n ? '-' : '';
    return `${sign}${integerPart}.${fractionalPart.toString().padStart(2, '0')}`;
}

/**
 * Percent-encodes the cursor for the query string.
 */
function encodeCursor(cursor: string): string {
    return cursor.replace(/\+/g, '%2B').replace(/\//g, '%2F').replace(/=/g, '%3D');
}

// --- State variables ---
let ordersCount = 0;
let pagesCount = 0;
let retriesCount = 0;
let reauthsCount = 0;
let currentToken = '';
let isFirstRequestWithNewToken = true;

/**
 * Performs a raw HTTP request and returns the response object.
 */
async function performHttpRequest(url: string, options: any, body?: string): Promise<any> {
    return new Promise((resolve, reject) => {
        const req = http.request(url, options, (res) => {
            let body = '';
            res.on('data', (chunk) => { body += chunk; });
            res.on('end', () => {
                resolve({
                    statusCode: res.statusCode,
                    headers: res.headers,
                    body: body.toString('utf8')
                });
            });
        });
        req.on('error', reject);
        if (body !== undefined) {
            req.write(body);
        }
        req.end();
    });
}

/**
 * Obtains an OAuth 2.0 token.
 */
async function getAccessToken(base_url: string, config: any): Promise<string> {
    const auth = urlEncode(config.client_id) + ':' + urlEncode(config.client_secret);
    const b64Auth = base64Encode(auth);
    const body = `grant_type=client_credentials&scope=${config.scope}`;
    const url = `${base_url}/oauth/token`;

    const options = {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Authorization': `Basic ${b64Auth}`,
            'Connection': 'close'
        }
    };

    const res = await performHttpRequest(url, options, body);

    if (res.statusCode === 200) {
        const json = JSON.parse(res.body);
        return json.access_token;
    } else {
        console.log(`ERROR ${res.statusCode} ${res.body}`);
        process.exit(0);
    }
}

/**
 * Main logic to fetch all orders and aggregate results.
 */
async function main() {
    const [dataDir, baseUrl] = process.argv.slice(2);
    if (!dataDir || !baseUrl) return;

    const config = JSON.parse(fs.readFileSync(`${dataDir}/client.json`, 'utf8'));

    currentToken = await getAccessToken(baseUrl, config);
    let cursor: string | null = null;
    const totalsMap = new Map<string, { currency: string, amount: bigint }>();
    const statusCounts = new Map<string, number>();

    while (true) {
        let url = `${baseUrl}/orders?limit=${config.page_size}`;
        if (cursor !== null) {
            url += `&cursor=${encodeCursor(cursor)}`;
        }

        const options = {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${currentToken}`,
                'Connection': 'close'
            }
        };

        let res = await performHttpRequest(url, options);

        while (true) {
            if (res.statusCode === 200) {
                pagesCount++;
                const json = JSON.parse(res.body);
                const data = json.data;

                for (const order of data) {
                    ordersCount++;
                    statusCounts.set(order.status, (statusCounts.get(order.status) || 0) + 1);
                    if (order.status !== 'cancelled') {
                        const key = `${order.customer.name}|${order.currency}`;
                        const amount = parseAmount(order.amount);
                        const entry = totalsMap.get(key);
                        if (entry) {
                            entry.amount += amount;
                        } else {
                            totalsMap.set(key, { currency: order.currency, amount });
                        }
                    }
                }
                cursor = json.next_cursor;
                isFirstRequestWithNewToken = false;
                break;
            } else if (res.statusCode === 429) {
                retriesCount++;
                const retryAfter = parseInt(res.headers['retry-after'] || '1');
                await new Promise(r => setTimeout(r, retryAfter * 1000));
                res = await performHttpRequest(url, options);
            } else if (res.statusCode === 503) {
                retriesCount++;
                await new Promise(r => setTimeout(r, 1000));
                res = await performHttpRequest(url, options);
            } else if (res.statusCode === 401) {
                if (isFirstRequestWithNewToken) {
                    console.log(`ERROR ${res.statusCode} ${res.body}`);
                    process.exit(0);
                }
                currentToken = await getAccessToken(baseUrl, config);
                reauthsCount++;
                isFirstRequestWithNewToken = true;
                options.headers['Authorization'] = `Bearer ${currentToken}`;
                res = await performHttpRequest(url, options);
            } else {
                console.log(`ERROR ${res.statusCode} ${res.body}`);
                process.exit(0);
            }
        }

        if (cursor === null) break;
    }

    // --- Output Generation ---

    const totalLines = [];
    for (const [key, value] of totalsMap.entries()) {
        const [name, currency] = key.split('|');
        totalLines.push({ name, currency, amount: value.amount });
    }

    // Sort by name (UTF-8 bytes) then by currency
    totalLines.sort((a, b) => {
        const bufA = Buffer.from(a.name, 'utf8');
        const bufB = Buffer.from(b.name, 'utf8');
        for (let i = 0; i < Math.min(bufA.length, bufB.length); i++) {
            if (bufA[i] !== bufB[i]) return bufA[i] - bufB[i];
        }
        if (bufA.length !== bufB.length) return bufA.length - bufB.length;
        if (a.currency !== b.currency) return a.currency < b.currency ? -1 : 1;
        return 0;
    });

    for (const line of totalLines) {
        process.stdout.write(`total ${line.currency} ${formatAmount(line.amount)} ${line.name}\n`);
    }

    const sortedStatuses = Array.from(statusCounts.keys()).sort();
    for (const status of sortedStatuses) {
        process.stdout.write(`status ${status} ${statusCounts.get(status)}\n`);
    }

    process.stdout.write(`orders ${ordersCount} pages ${pagesCount} retries ${retriesCount} reauth ${reauthsCount}\n`);
}

main().catch(() => process.exit(0));

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    int r, g, b, a;
} Color;

typedef struct {
    char type[16];
    long long x, y, w, h;
    long long cx, cy, r_circle;
    long long x1, y1, x2, y2, r_line;
    long long points[3][2];
    Color color;
} Shape;

int width, height;
Color background;
Shape shapes[100];
int num_shapes = 0;
uint8_t *pixels;
char *json_ptr;

void skip_whitespace() {
    while (*json_ptr && (*json_ptr == ' ' || *json_ptr == '\n' || *json_ptr == '\r' || *json_ptr == '\t')) {
        json_ptr++;
    }
}

char* parse_string() {
    skip_whitespace();
    if (*json_ptr == '"') {
        json_ptr++;
        char *start = json_ptr;
        while (*json_ptr && *json_ptr != '"') json_ptr++;
        *json_ptr = '\0';
        json_ptr++;
        return start;
    }
    return NULL;
}

long long parse_number() {
    skip_whitespace();
    char *start = json_ptr;
    if (*json_ptr == '-') json_ptr++;
    while (*json_ptr && (*json_ptr >= '0' && *json_ptr <= '9')) json_ptr++;
    *json_ptr = '\0';
    return atoll(start);
}

typedef struct {
    char type[16];
    long long x, y, w, h;
    long long cx, cy, r_val;
    long long x1, y1, x2, y2, r_line_val;
    long long points[3][2];
    int color_r, color_g, color_b, color_a;
} ShapeTemp;

void parse_json() {
    skip_whitespace();
    if (*json_ptr == '{') json_ptr++;
    while (*json_ptr && *json_ptr != '}') {
        skip_whitespace();
        char *key = parse_string();
        skip_whitespace();
        if (*json_ptr == ':') json_ptr++;
        skip_whitespace();
        if (strcmp(key, "width") == 0) {
            width = (int)parse_number();
        } else if (strcmp(key, "height") == 0) {
            height = (int)parse_number();
        } else if (strcmp(key, "background") == 0) {
            skip_whitespace();
            if (*json_ptr == '[') {
                json_ptr++;
                background.r = (int)parse_number();
                skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                background.g = (int)parse_number();
                skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                background.b = (int)parse_number();
                skip_whitespace(); if (*json_ptr == ']') json_ptr++;
            }
        } else if (strcmp(key, "shapes") == 0) {
            skip_whitespace();
            if (*json_ptr == '[') {
                json_ptr++;
                while (*json_ptr && *json_ptr != ']') {
                    skip_whitespace();
                    if (*json_ptr == '{') {
                        json_ptr++;
                        ShapeTemp st = {0};
                        while (*json_ptr && *json_ptr != '}') {
                            skip_whitespace();
                            char *s_key = parse_string();
                            skip_whitespace();
                            if (*json_ptr == ':') json_ptr++;
                            skip_whitespace();
                            if (strcmp(s_key, "type") == 0) {
                                strcpy(st.type, parse_string());
                            } else if (strcmp(s_key, "x") == 0) {
                                st.x = parse_number();
                            } else if (strcmp(s_key, "y") == 0) {
                                st.y = parse_number();
                            } else if (strcmp(s_key, "w") == 0) {
                                st.w = parse_number();
                            } else if (strcmp(s_key, "h") == 0) {
                                st.h = parse_number();
                            } else if (strcmp(s_key, "cx") == 0) {
                                st.cx = parse_number();
                            } else if (strcmp(s_key, "cy") == 0) {
                                st.cy = parse_number();
                            } else if (strcmp(s_key, "r") == 0) {
                                st.r_val = parse_number();
                            } else if (strcmp(s_key, "x1") == 0) {
                                st.x1 = parse_number();
                            } else if (strcmp(s_key, "y1") == 0) {
                                st.y1 = parse_number();
                            } else if (strcmp(s_key, "x2") == 0) {
                                st.x2 = parse_number();
                            } else if (strcmp(s_key, "y2") == 0) {
                                st.y2 = parse_number();
                            } else if (strcmp(s_key, "points") == 0) {
                                skip_whitespace();
                                if (*json_ptr == '[') {
                                    json_ptr++;
                                    for (int i = 0; i < 3; i++) {
                                        st.points[i][0] = parse_number();
                                        skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                        st.points[i][1] = parse_number();
                                        skip_whitespace(); if (*json_ptr == ']') json_ptr++;
                                        skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                    }
                                    skip_whitespace();
                                    if (*json_ptr == ']') json_ptr++;
                                }
                            } else if (strcmp(s_key, "color") == 0) {
                                skip_whitespace();
                                if (*json_ptr == '[') {
                                    json_ptr++;
                                    st.color_r = (int)parse_number();
                                    skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                    st.color_g = (int)parse_number();
                                    skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                    st.color_b = (int)parse_number();
                                    skip_whitespace();
                                    if (*json_ptr == ',') {
                                        json_ptr++;
                                        st.color_a = (int)parse_number();
                                    } else {
                                        st.color_a = 255;
                                    }
                                    skip_whitespace();
                                    if (*json_ptr == ']') json_ptr++;
                                }
                            }
                            skip_whitespace();
                            if (*json_ptr == ',') json_ptr++;
                        }
                        json_ptr++;
                        Shape *s = &shapes[num_shapes++];
                        strcpy(s->type, st.type);
                        s->x = (int)st.x; s->y = (int)st.y; s->w = (int)st.w; s->h = (int)st.h;
                        s->cx = (int)st.cx; s->cy = (int)st.cy;
                        s->x1 = st.x1; s->y1 = st.y1; s->x2 = st.x2; s->y2 = st.y2;
                        if (strcmp(st.type, "circle") == 0) s->r_circle = (int)st.r_val;
                        else if (strcmp(st.type, "line") == 0) s->r_line = (int)st.r_val;
                        for (int i = 0; i < 3; i++) {
                            s->points[i][0] = st.points[i][0];
                            s->points[i][1] = st.points[i][1];
                        }
                        s->color.r = st.color_r; s->color.g = st.color_g;
                        s->color.b = st.color_b; s->color.a = st.color_a;
                    }
                    skip_whitespace();
                    if (*json_ptr == ',') json_ptr++;
                }
                json_ptr++;
            }
            skip_whitespace();
            if (*json_ptr == ',') json_ptr++;
        }
        json_ptr++;
    } else {
        // Skip other keys
        skip_whitespace();
        char *key = parse_string();
        skip_whitespace();
        if (*json_ptr == ':') json_ptr++;
        skip_whitespace();
        if (*json_ptr == '[') {
            json_ptr++;
            while (*json_ptr && *json_ptr != ']') {
                if (*json_ptr == '[') {
                    json_ptr++;
                    while (*json_ptr && *json_ptr != ']') json_ptr++;
                    json_ptr++;
                } else if (*json_ptr == ',') json_ptr++;
                else json_ptr++;
            }
            json_ptr++;
        } else if (*json_ptr == '{') {
            json_ptr++;
            while (*json_ptr && *json_ptr != '}') {
                if (*json_ptr == '{') {
                    json_ptr++;
                    while (*json_ptr && *json_ptr != '}') json_ptr++;
                    json_ptr++;
                } else if (*json_ptr == ',') json_ptr++;
                else json_ptr++;
            }
            json_ptr++;
        } else if (*json_ptr == '"') {
            parse_string();
        } else {
            parse_number();
        }
        skip_whitespace();
        if (*json_ptr == ',') json_ptr++;
    }
}

uint32_t crc32_table[256];
void init_crc32() {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            if (c & 1) c = (c >> 1) ^ 0xEDB88320;
            else c >>= 1;
        }
        crc32_table[i] = c;
    }
}

uint32_t crc32(const uint8_t *data, size_t len) {
    uint32_t c = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++) {
        c = (c >> 8) ^ crc32_table[(c ^ data[i]) & 0xFF];
    }
    return ~c;
}

uint32_t adler32(const uint8_t *data, size_t len) {
    uint32_t a = 1, b = 0;
    for (size_t i = 0; i < len; i++) {
        a = (a + data[i]) % 65521;
        b = (b + a) % 65521;
    }
    return (b << 16) | a;
}

void write_bytes(const void *data, size_t len) {
    fwrite(data, 1, len, stdout);
}

void write_chunk(const char *type, const uint8_t *data, uint32_t len) {
    uint32_t chunk_len = len;
    uint8_t chunk_type[4];
    memcpy(chunk_type, type, 4);
    write_bytes(&chunk_len, 4);
    write_bytes(chunk_type, 4);
    write_bytes(data, len);
    uint8_t *buffer = malloc(4 + len);
    memcpy(buffer, chunk_type, 4);
    memcpy(buffer + 4, data, len);
    uint32_t crc = crc32(buffer, 4 + len);
    write_bytes(&crc, 4);
    free(buffer);
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;
    char path[256];
    sprintf(path, "%s/scene.json", argv[1]);
    FILE *f = fopen(path, "r");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buffer = malloc(size + 1);
    fread(buffer, 1, size, f);
    buffer[size] = '\0';
    fclose(f);

    json_ptr = buffer;
    parse_json();

    pixels = malloc(width * height * 3);
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            pixels[y * width * 3 + x * 3] = (uint8_t)background.r;
            pixels[y * width * 3 + x * 3 + 1] = (uint8_t)background.g;
            pixels[y * width * 3 + x * 3 + 2] = (uint8_t)background.b;
        }
    }

    long long *covered_counts = calloc(num_shapes, sizeof(long long));
    for (int i = 0; i < num_shapes; i++) {
        Shape *s = &shapes[i];
        long long count = 0;
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int covered = 0;
                if (strcmp(s->type, "rect") == 0) {
                    if (x >= s->x && x < s->x + s->w && y >= s->y && y < s->y + s->h) covered = 1;
                } else if (strcmp(s->type, "circle") == 0) {
                    if ((x - s->cx) * (x - s->cx) + (y - s->cy) * (y - s->cy) <= s->r_circle * s->r_circle) covered = 1;
                } else if (strcmp(s->type, "triangle") == 0) {
                    long long e0 = (s->points[1][0] - s->points[0][0]) * (y - s->points[0][1]) - (s->points[1][1] - s->points[0][1]) * (x - s->points[0][0]);
                    long long e1 = (s->points[2][0] - s->points[1][0]) * (y - s->points[1][1]) - (s->points[2][1] - s->points[1][1]) * (x - s->points[1][0]);
                    long long e2 = (s->points[0][0] - s->points[2][0]) * (y - s->points[2][1]) - (s->points[0][1] - s->points[2][1]) * (x - s->points[2][0]);
                    if ((e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)) covered = 1;
                } else if (strcmp(s->type, "line") == 0) {
                    long long dx = s->x2 - s->x1, dy = s->y2 - s->y1, L = dx * dx + dy * dy;
                    long long t = (x - s->x1) * dx + (y - s->y1) * dy;
                    if (t <= 0) {
                        if ((x - s->x1) * (x - s->x1) + (y - s->y1) * (y - s->y1) <= s->r_line * s->r_line) covered = 1;
                    } else if (t >= L) {
                        if ((x - s->x2) * (x - s->x2) + (y - s->y2) * (y - s->y2) <= s->r_line * s->r_line) covered = 1;
                    } else {
                        long long c = (x - s->x1) * dy - (y - s->y1) * dx;
                        if (c * c <= s->r_line * s->r_line * L) covered = 1;
                    }
                }
                if (covered) {
                    count++;
                    int idx = y * width * 3 + x * 3;
                    int dR = pixels[idx], dG = pixels[idx + 1], dB = pixels[idx + 2];
                    int sR = s->color.r, sG = s->color.g, sB = s->color.b, sA = s->color.a;
                    pixels[idx] = (sR * sA + dR * (255 - sA) + 127) / 255;
                    pixels[idx + 1] = (sG * sA + dG * (255 - sA) + 127) / 255;
                    pixels[idx + 2] = (sB * sA + dB * (255 - sA) + 127) / 255;
                }
            }
        }
        covered_counts[i] = count;
    }

    for (int i = 0; i < num_shapes; i++) {
        printf("%d %s %lld\n", i + 1, shapes[i].type, covered_counts[i]);
    }

    uint32_t *all_colors = malloc(width * height * sizeof(uint32_t));
    for (int i = 0; i < width * height; i++) {
        all_colors[i] = (pixels[i * 3] << 16) | (pixels[i * 3 + 1] << 8) | pixels[i * 3 + 2];
    }
    qsort(all_colors, width * height, sizeof(uint32_t), compare_uint32);
    int unique_count = 0;
    if (width * height > 0) {
        unique_count = 1;
        for (int i = 1; i < width * height; i++) {
            if (all_colors[i] != all_colors[i - 1]) unique_count++;
        }
    }
    printf("colors %d\n", unique_count);

    uint8_t *zlib_data = malloc(2 + height * (4 + width * 3) + 4);
    zlib_data[0] = 0x78; zlib_data[1] = 0x01;
    int pos = 2;
    for (int y = 0; y < height; y++) {
        zlib_data[pos++] = 0x00;
        uint16_t len = 1 + width * 3;
        zlib_data[pos++] = len & 0xFF;
        zlib_data[pos++] = (len >> 8) & 0xFF;
        zlib_data[pos++] = 0;
        memcpy(&zlib_data[pos], &pixels[y * width * 3], width * 3);
        pos += width * 3;
    }
    uint32_t adler = adler32(&zlib_data[2], pos - 2);
    zlib_data[pos] = adler & 0xFF;
    zlib_data[pos + 1] = (adler >> 8) & 0xFF;
    zlib_data[pos + 2] = (adler >> 16) & 0xFF;
    zlib_data[pos + 3] = (adler >> 24) & 0xFF;
    pos += 4;

    FILE *out = fopen("out.png", "wb");
    fwrite("\x89PNG\r\n\x1a\n", 8, 1, out);
    uint8_t ihdr_data[14];
    uint32_t ihdr_len = 14;
    uint32_t w32 = width, h32 = height;
    memcpy(ihdr_data, &w32, 4);
    memcpy(ihdr_data + 4, &h32, 4);
    ihdr_data[8] = 8; ihdr_data[9] = 2;
    ihdr_data[10] = 0; ihdr_data[11] = 0; ihdr_data[12] = 0; ihdr_data[13] = 0;
    write_chunk("IHDR", ihdr_data, ihdr_len);
    write_chunk("IDAT", zlib_data, pos - 2);
    write_chunk("IEND", (uint8_t*)"", 0);
    fclose(out);

    free(pixels); free(covered_counts); free(all_colors); free(zlib_data); free(buffer);
    return 0;
}

int compare_uint32(const void *a, const void *b) {
    uint32_t arg1 = *(const uint32_t *)a;
    uint32_t arg2 = *(const uint32_t *)b;
    return (arg1 < arg2) ? -1 : (arg1 > arg2);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    int r, g, b, a;
} Color;

typedef struct {
    char type[16];
    long long x, y, w, h;
    long long cx, cy, r_circle;
    long long x1, y1, x2, y2, r_line;
    long long points[3][2];
    Color color;
} Shape;

typedef struct {
    char type[16];
    long long x, y, w, h;
    long long cx, cy, r_val;
    long long x1, y1, x2, y2, r_line_val;
    long long points[3][2];
    int color_r, color_g, color_b, color_a;
} ShapeTemp;

int width, height;
Color background;
Shape shapes[100];
int num_shapes = 0;
uint8_t *pixels;
char *json_ptr;

void skip_whitespace() {
    while (*json_ptr && (*json_ptr == ' ' || *json_ptr == '\n' || *json_ptr == '\r' || *json_ptr == '\t')) {
        json_ptr++;
    }
}

char* parse_string() {
    skip_whitespace();
    if (*json_ptr == '"') {
        json_ptr++;
        char *start = json_ptr;
        while (*json_ptr && *json_ptr != '"') json_ptr++;
        *json_ptr = '\0';
        json_ptr++;
        return start;
    }
    return NULL;
}

long long parse_number() {
    skip_whitespace();
    char *start = json_ptr;
    if (*json_ptr == '-') json_ptr++;
    while (*json_ptr && (*json_ptr >= '0' && *json_ptr <= '9')) json_ptr++;
    *json_ptr = '\0';
    return atoll(start);
}

void parse_json() {
    skip_whitespace();
    if (*json_ptr == '{') json_ptr++;
    while (*json_ptr && *json_ptr != '}') {
        skip_whitespace();
        char *key = parse_string();
        skip_whitespace();
        if (*json_ptr == ':') json_ptr++;
        skip_whitespace();
        if (strcmp(key, "width") == 0) {
            width = (int)parse_number();
        } else if (strcmp(key, "height") == 0) {
            height = (int)parse_number();
        } else if (strcmp(key, "background") == 0) {
            skip_whitespace();
            if (*json_ptr == '[') {
                json_ptr++;
                background.r = (int)parse_number();
                skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                background.g = (int)parse_number();
                skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                background.b = (int)parse_number();
                skip_whitespace(); if (*json_ptr == ']') json_ptr++;
            }
        } else if (strcmp(key, "shapes") == 0) {
            skip_whitespace();
            if (*json_ptr == '[') {
                json_ptr++;
                while (*json_ptr && *json_ptr != ']') {
                    skip_whitespace();
                    if (*json_ptr == '{') {
                        json_ptr++;
                        ShapeTemp st = {0};
                        while (*json_ptr && *json_ptr != '}') {
                            skip_whitespace();
                            char *s_key = parse_string();
                            skip_whitespace();
                            if (*json_ptr == ':') json_ptr++;
                            skip_whitespace();
                            if (strcmp(s_key, "type") == 0) {
                                strcpy(st.type, parse_string());
                            } else if (strcmp(s_key, "x") == 0) {
                                st.x = parse_number();
                            } else if (strcmp(s_key, "y") == 0) {
                                st.y = parse_number();
                            } else if (strcmp(s_key, "w") == 0) {
                                st.w = parse_number();
                            } else if (strcmp(s_key, "h") == 0) {
                                st.h = parse_number();
                            } else if (strcmp(s_key, "cx") == 0) {
                                st.cx = parse_number();
                            } else if (strcmp(s_key, "cy") == 0) {
                                st.cy = parse_number();
                            } else if (strcmp(s_key, "r") == 0) {
                                st.r_val = parse_number();
                            } else if (strcmp(s_key, "x1") == 0) {
                                st.x1 = parse_number();
                            } else if (strcmp(s_key, "y1") == 0) {
                                st.y1 = parse_number();
                            } else if (strcmp(s_key, "x2") == 0) {
                                st.x2 = parse_number();
                            } else if (strcmp(s_key, "y2") == 0) {
                                st.y2 = parse_number();
                            } else if (strcmp(s_key, "points") == 0) {
                                skip_whitespace();
                                if (*json_ptr == '[') {
                                    json_ptr++;
                                    for (int i = 0; i < 3; i++) {
                                        st.points[i][0] = parse_number();
                                        skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                        st.points[i][1] = parse_number();
                                        skip_whitespace(); if (*json_ptr == ']') json_ptr++;
                                        skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                    }
                                    skip_whitespace();
                                    if (*json_ptr == ']') json_ptr++;
                                }
                            } else if (strcmp(s_key, "color") == 0) {
                                skip_whitespace();
                                if (*json_ptr == '[') {
                                    json_ptr++;
                                    st.color_r = (int)parse_number();
                                    skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                    st.color_g = (int)parse_number();
                                    skip_whitespace(); if (*json_ptr == ',') json_ptr++;
                                    st.color_b = (int)parse_number();
                                    skip_whitespace();
                                    if (*json_ptr == ',') {
                                        json_ptr++;
                                        st.color_a = (int)parse_number();
                                    } else {
                                        st.color_a = 255;
                                    }
                                    skip_whitespace();
                                    if (*json_ptr == ']') json_ptr++;
                                }
                            }
                            skip_whitespace();
                            if (*json_ptr == ',') json_ptr++;
                        }
                        json_ptr++;
                        Shape *s = &shapes[num_shapes++];
                        strcpy(s->type, st.type);
                        s->x = (int)st.x; s->y = (int)st.y; s->w = (int)st.w; s->h = (int)st.h;
                        s->cx = (int)st.cx; s->cy = (int)st.cy;
                        s->x1 = st.x1; s->y1 = st.y1; s->x2 = st.x2; s->y2 = st.y2;
                        if (strcmp(st.type, "circle") == 0) s->r_circle = (int)st.r_val;
                        else if (strcmp(st.type, "line") == 0) s->r_line = (int)st.r_val;
                        for (int i = 0; i < 3; i++) {
                            s->points[i][0] = st.points[i][0];
                            s->points[i][1] = st.points[i][1];
                        }
                        s->color.r = st.color_r; s->color.g = st.color_g;
                        s->color.b = st.color_b; s->color.a = st.color_a;
                        skip_whitespace();
                        if (*json_ptr == ',') json_ptr++;
                    }
                    skip_whitespace();
                    if (*json_ptr == ',') json_ptr++;
                }
                json_ptr++;
            }
            skip_whitespace();
            if (*json_ptr == ',') json_ptr++;
        }
        json_ptr++;
    }
}

uint32_t crc32_table[256];
void init_crc32() {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            if (c & 1) c = (c >> 1) ^ 0xEDB88320;
            else c >>= 1;
        }
        crc32_table[i] = c;
    }
}

