}

uint32_t adler32(const uint8_t *data, size_t len) {
    uint32_t a = 1, b = 0;
    for (size_t i = 0; i < len; i++) {
        a = (a + data[i]) % 65521;
        b = (b + a) % 65521;
    }
    return (b << 16) | a;
}

void write_chunk(FILE *f, const char *type, const uint8_t *data, uint32_t len) {
    uint32_t chunk_len = len;
    uint8_t chunk_type[4];
    memcpy(chunk_type, type, 4);
    fwrite(&chunk_len, 4, 1, f);
    fwrite(chunk_type, 4, 1, f);
    fwrite(data, 1, len, f);
    uint8_t *buffer = malloc(4 + len);
    memcpy(buffer, chunk_type, 4);
    memcpy(buffer + 4, data, len);
    uint32_t crc = crc32(buffer, 4 + len);
    fwrite(&crc, 4, 1, f);
    free(buffer);
}

