        printf("%d %s %lld\n", i + 1, shapes[i].type, covered_counts[i]);
    }

    uint32_t *all_colors = malloc(width * height * sizeof(uint32_t));
    for (int i = 0; i < width * height; i++) {
        all_colors[i] = (pixels[i * 3] << 16) | (pixels[i * 3 + 1] << 8) | pixels[i * 3 + 2];
    }
    qsort(all_colors, width * height, sizeof(uint32_t), compare_uint32);
    int unique_count = 0;
    if (width * height > 0) {
        unique_count = 1;
        for (int i = 1; i < width * height; i++) {
            if (all_colors[i] != all_colors[i - 1]) unique_count++;
        }
    }
    printf("colors %d\n", unique_count);

    uint8_t *zlib_data = malloc(height * (5 + 3 * width));
    int pos = 0;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            uint8_t *p = &pixels[y * width * 3 + x * 3];
            zlib_data[pos++] = 0x81;
            zlib_data[pos++] = 0x08;
            zlib_data[pos++] = 0x00;
            zlib_data[pos++] = 0x00;
            zlib_data[pos++] = 0x01;
            zlib_data[pos++] = p[0];
            zlib_data[pos++] = p[1];
            zlib_data[pos++] = p[2];
        }
    }
    uint32_t adler = adler32(&zlib_data[0], pos);

    FILE *out = fopen("out.png", "wb");
    fwrite("\x89PNG\r\n\x1a\n", 8, 1, out);
    uint32_t w32 = width, h32 = height;
    uint8_t ihdr_data[14];
    memcpy(ihdr_data, &w32, 4);
    memcpy(ihdr_data + 4, &h32, 4);
    ihdr_data[8] = 8; ihdr_data[9] = 2;
    ihdr_data[10] = 0; ihdr_data[11] = 0; ihdr_data[12] = 0; ihdr_data[13] = 0;
    write_chunk(out, "IHDR", ihdr_data, 14);

    uint8_t *idat_full = malloc(2 + pos + 4);
    idat_full[0] = 0x78; idat_full[1] = 0x01;
    memcpy(idat_full + 2, zlib_data, pos);
    idat_full[2 + pos] = adler & 0xFF;
    idat_full[3 + pos] = (adler >> 8) & 0xFF;
    idat_full[4 + pos] = (adler >> 16) & 0xFF;
    idat_full[5 + pos] = (adler >> 24) & 0xFF;
    write_chunk(out, "IDAT", idat_full, pos + 4);
    free(idat_full);

    write_chunk(out, "IEND", (uint8_t*)"", 0);
    fclose(out);

    free(pixels); free(covered_counts); free(all_colors); free(zlib_data); free(buffer);
    return 0;
}

import java.io.*;
import java.net.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.math.*;

public class Main {
    static int orderCount = 0;
    static int pageCount = 0;
    static int retryCount = 0;
    static int reauthCount = 0;

    public static void main(String[] args) throws Exception {
        if (args.length < 2) return;
        String dataDir = args[0];
        String baseUrl = args[1];

        File configFile = new File(dataDir, "client.json");
        String configJson = Files.readString(configFile.toPath());
        JsonParser parser = new JsonParser(configJson);
        Map<String, Object> config = (Map<String, Object>) parser.parse();

        String clientId = (String) config.get("client_id");
        String clientSecret = (String) config.get("client_secret");
        String scope = (String) config.get("scope");
        int pageSize = (int) ((Number) config.get("page_size")).intValue();

        String token = getToken(baseUrl, clientId, clientSecret, scope);
        if (token == null) return;

        Map<String, BigDecimal> totals = new HashMap<>();
        Map<String, Integer> statusCounts = new HashMap<>();
        String nextCursor = null;
        boolean firstRequestWithCurrentToken = true;

        while (true) {
            String urlStr = baseUrl + "/orders?limit=" + pageSize;
            if (nextCursor != null) {
                String encodedCursor = nextCursor.replace("+", "%2B").replace("/", "%2F").replace("=", "%3D");
                urlStr += "&cursor=" + encodedCursor;
            }

            HttpURLConnection conn = (HttpURLConnection) new URL(urlStr).openConnection();
            conn.setRequestMethod("GET");
            conn.setRequestProperty("Host", new URL(urlStr).getHost());
            conn.setRequestProperty("Connection", "close");
            conn.setRequestProperty("Authorization", "Bearer " + token);

            int responseCode = conn.getResponseCode();
            if (responseCode == 200) {
                pageCount++;
                byte[] bodyBytes = conn.getInputStream().readAllBytes();
                Map<String, Object> resp = (Map<String, Object>) new JsonParser(new String(bodyBytes, StandardCharsets.UTF_8)).parse();
                List<Map<String, Object>> data = (List<Map<String, Object>>) resp.get("data");
                if (data != null) {
                    for (Map<String, Object> order : data) {
                        orderCount++;
                        String status = (String) order.get("status");
                        statusCounts.put(status, statusCounts.getOrDefault(status, 0) + 1);

                        if (!"cancelled".equals(status)) {
                            Map<String, Object> customer = (Map<String, Object>) order.get("customer");
                            String name = (String) customer.get("name");
                            String currency = (String) order.get("currency");
                            String amountStr = (String) order.get("amount");
                            long cents = parseAmount(amountStr);

                            String key = name + "\u0000" + currency;
                            totals.put(key, totals.getOrDefault(key, BigDecimal.ZERO).add(BigDecimal.valueOf(cents)));
                        }
                    }
                }
                nextCursor = (String) resp.get("next_cursor");
                firstRequestWithCurrentToken = false;
                if (nextCursor == null) break;
            } else if (responseCode == 429) {
                retryCount++;
                int retryAfter = Integer.parseInt(conn.getHeaderField("Retry-After"));
                Thread.sleep(retryAfter * 1000L);
                continue;
            } else if (responseCode == 503) {
                retryCount++;
                Thread.sleep(1000);
                continue;
            } else if (responseCode == 401) {
                if (conn.getHeaderField("WWW-Authenticate").contains("invalid_token")) {
                    if (firstRequestWithCurrentToken) {
                        printError(responseCode, new String(conn.getErrorStream().readAllBytes(), StandardCharsets.UTF_8));
                        return;
                    } else {
                        token = getToken(baseUrl, clientId, clientSecret, scope);
                        if (token == null) return;
                        reauthCount++;
                        firstRequestWithCurrentToken = true;
                        continue;
                    }
                }
            }

            if (responseCode != 200) {
                printError(responseCode, new String(conn.getErrorStream().readAllBytes(), StandardCharsets.UTF_8));
                return;
            }
            if (nextCursor == null) break;
        }

        List<TotalRecord> totalList = new ArrayList<>();
        for (Map.Entry<String, BigDecimal> entry : totals.entrySet()) {
            String[] parts = entry.getKey().split("\u0000");
            totalList.add(new TotalRecord(parts[0], parts[1], entry.getValue()));
        }
        Collections.sort(totalList, (a, b) -> {
            int cmp = a.name.compareTo(b.name);
            return (cmp != 0) ? cmp : a.currency.compareTo(b.currency);
        });

        for (TotalRecord tr : totalList) {
            System.out.println("total " + tr.currency + " " + tr.amount.divide(new BigDecimal("100")).setScale(2, RoundingMode.HALF_UP).toPlainString() + " " + tr.name);
        }

        List<StatusRecord> statusList = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : statusCounts.entrySet()) {
            statusList.add(new StatusRecord(entry.getKey(), entry.getValue()));
        }
        Collections.sort(statusList, (a, b) -> a.status.compareTo(b.status));
        for (StatusRecord sr : statusList) {
            System.out.println("status " + sr.status + " " + sr.count);
        }

        System.out.println("orders " + orderCount + " pages " + pageCount + " retries " + retryCount + " reauth " + reauthCount);
    }

    private static String getToken(String baseUrl, String clientId, String clientSecret, String scope) throws Exception {
        String urlStr = baseUrl + "/oauth/token";
        String auth = URLEncoder.encode(clientId, "UTF-8") + ":" + URLEncoder.encode(clientSecret, "UTF-8");
        String b64 = Base64.getEncoder().encodeToString(auth.getBytes(StandardCharsets.UTF_8));

        HttpURLConnection conn = (HttpURLConnection) new URL(urlStr).openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Host", new URL(urlStr).getHost());
        conn.setRequestProperty("Connection", "close");
        conn.setRequestProperty("Authorization", "Basic " + b64);
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");

        String body = "grant_type=client_credentials&scope=" + scope;
        conn.setDoOutput(true);
        try (OutputStream os = conn.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }

        int code = conn.getResponseCode();
        if (code == 200) {
            Map<String, Object> resp = (Map<String, Object>) new JsonParser(new String(conn.getInputStream().readAllBytes(), StandardCharsets.UTF_8)).parse();
            return (String) resp.get("access_token");
        } else {
            printError(code, new String(conn.getErrorStream().readAllBytes(), StandardCharsets.UTF_8));
            return null;
        }
    }

    private static long parseAmount(String s) {
        boolean isNegative = s.startsWith("-");
        String absS = isNegative ? s.substring(1) : s;
        long cents;
        int dotIndex = absS.indexOf('.');
        if (dotIndex == -1) {
            cents = Long.parseLong(absS) * 100;
        } else {
            String before = absS.substring(0, dotIndex);
            String after = absS.substring(dotIndex + 1);
            long beforeCents = Long.parseLong(before) * 100;
            long afterCents = (after.length() == 1) ? Long.parseLong(after) * 10 : Long.parseLong(after);
            cents = beforeCents + afterCents;
        }
        return isNegative ? -cents : cents;
    }

    private static void printError(int status, String body) {
        System.out.println("ERROR " + status + " " + body);
        System.exit(0);
    }

    static class TotalRecord {
        String name, currency;
        BigDecimal amount;
        TotalRecord(String n, String c, BigDecimal a) { name = n; currency = c; amount = a; }
    }

    static class StatusRecord {
        String status;
        int count;
        StatusRecord(String s, int c) { status = s; count = c; }
    }

    static class JsonParser {
        String json;
        int pos = 0;
        JsonParser(String json) { this.json = json; }

        Object parse() {
            skip();
            if (pos >= json.length()) return null;
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (json.startsWith("true", pos)) { pos += 4; return true; }
            if (json.startsWith("false", pos)) { pos += 5; return false; }
            if (json.startsWith("null", pos)) { pos += 4; return null; }
            return parseNumber();
        }

        void skip() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
        }

        private Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // {
            skip();
            while (pos < json.length() && json.charAt(pos) != '}') {
                String key = parseString().toString();
                skip();
                pos++; // :
                skip();
                map.put(key, parse());
                skip();
                if (pos < json.length() && json.charAt(pos) == ',') {
                    pos++;
                    skip();
                }
            }
            pos++; // }
            return map;
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // [
            skip();
            while (pos < json.length() && json.charAt(pos) != ']') {
                list.add(parse());
                skip();
                if (pos < json.length() && json.charAt(pos) == ',') {
                    pos++;
                    skip();
                }
            }
            pos++; // ]
            return list;
        }

        private String parseString() {
            pos++; // "
            StringBuilder sb = new StringBuilder();
            while (pos < json.length()) {
                char c = json.charAt(pos);
                if (c == '"') {
                    pos++;
                    break;
                }
                if (c == '\\') {
                    pos++;
                    char esc = json.charAt(pos);
                    if (esc == 'u') {
                        int code = Integer.parseInt(json.substring(pos + 1, pos + 5), 16);
                        pos += 5;
                        if (code >= 0xD800 && code <= 0xDBFF) {
                            int nextCode = Integer.parseInt(json.substring(pos + 1, pos + 5), 16);
                            pos += 5;
                            sb.append((char) code);
                            sb.append((char) nextCode);
                        } else {
                            sb.append((char) code);
                        }
                    } else if (esc == 'n') { sb.append('\n'); pos++; }
                    else if (esc == 'r') { sb.append('\r'); pos++; }
                    else if (esc == 't') { sb.append('\t'); pos++; }
                    else if (esc == '\\') { sb.append('\\'); pos++; }
                    else if (esc == '"') { sb.append('"'); pos++; }
                    else if (esc == '/') { sb.append('/'); pos++; }
                    else { sb.append(esc); pos++; }
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            return sb.toString();
        }

        private Number parseNumber() {
            int start = pos;
            while (pos < json.length() && "0123456789+-.eE".indexOf(json.charAt(pos)) != -1) pos++;
            String s = json.substring(start, pos);
            if (s.contains(".") || s.toLowerCase().contains("e")) return Double.parseDouble(s);
            return Long.parseLong(s);
        }
    }
}

