    private static int compareUtf8(String s1, String s2) {
        byte[] b1 = s1.getBytes(StandardCharsets.UTF_8);
        byte[] b2 = s2.getBytes(StandardCharsets.UTF_8);
        int len = Math.min(b1.length, b2.length);
        for (int i = 0; i < len; i++) {
            int c1 = b1[i] & 0xFF;
            int c2 = b2[i] & 0xFF;
            if (c1 != c2) return c1 - c2;
        }
        return b1.length - b2.length;
    }

    private static String getToken(String baseUrl, String clientId, String clientSecret, String scope) throws Exception {
        String urlStr = baseUrl + "/oauth/token";
        String auth = formUrlencode(clientId) + ":" + formUrlencode(clientSecret);
        String b64 = Base64.getEncoder().encodeToString(auth.getBytes(StandardCharsets.UTF_8));

        HttpURLConnection conn = (HttpURLConnection) new URL(urlStr).openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Host", new URL(urlStr).getHost());
        conn.setRequestProperty("Connection", "close");
        conn.setRequestProperty("Authorization", "Basic " + b64);
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");

        String body = "grant_type=client_credentials&scope=" + scope;
        conn.setDoOutput(true);
        try (OutputStream os = conn.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }

        int code = conn.getResponseCode();
        if (code == 200) {
            Map<String, Object> resp = (Map<String, Object>) new JsonParser(new String(conn.getInputStream().readAllBytes(), StandardCharsets.UTF_8)).parse();
            return (String) resp.get("access_token");
        } else {
            printError(code, new String(conn.getErrorStream().readAllBytes(), StandardCharsets.UTF_8));
            return null;
        }
    }

    private static String formUrlencode(String s) {
        StringBuilder sb = new StringBuilder();
        for (byte b : s.getBytes(StandardCharsets.UTF_8)) {
            char c = (char) b;
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
                c == '-' || c == '.' || c == '_' || c == '*') {
                sb.append(c);
            } else if (c == ' ') {
                sb.append('+');
            } else {
                sb.append(String.format("%%%02X", b & 0xFF));
            }
        }
        return sb.toString();
    }

    private static long parseAmount(String s) {
        boolean isNegative = s.startsWith("-");
        String absS = isNegative ? s.substring(1) : s;
        int dotIndex = absS.indexOf('.');
