            long beforeCents = Long.parseLong(before) * 100;
            long afterCents = (after.length() == 1) ? Long.parseLong(after) * 10 : Long.parseLong(after.substring(0, Math.min(after.length(), 2)));
            cents = beforeCents + afterCents;
