            pos++; // {
            skip();
            while (pos < json.length()) {
                skip();
                if (pos >= json.length() || json.charAt(pos) == '}') break;
                String key = parseString();
                skip();
                pos++; // :
                skip();
                map.put(key, parse());
                skip();
                if (pos < json.length() && json.charAt(pos) == ',') {
