                        } else {
                            sb.append((char) code);
                        }
                    } else if (esc == 'n') { sb.append('\n'); pos++; }
                    else if (esc == 'r') { sb.append('\r'); pos++; }
                    else if (esc == 't') { sb.append('\t'); pos++; }
                    else if (esc == '\\') { sb.append('\\'); pos++; }
                    else if (esc == '"') { sb.append('"'); pos++; }
                    else if (esc == '/') { sb.append('/'); pos++; }
                    else { sb.append(esc); pos++; }
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            return sb.toString();
        }

        private Number parseNumber() {
            int start = pos;
            while (pos < json.length() && "0123456789+-.eE".indexOf(json.charAt(pos)) != -1) pos++;
            String s = json.substring(start, pos);
            if (s.contains(".") || s.toLowerCase().contains("e")) return Double.parseDouble(s);
            return Long.parseLong(s);
        }
    }
}

