// --- Data Structures ---

typedef enum {
    TYPE_INT32, TYPE_INT64, TYPE_UINT32, TYPE_UINT64,
    TYPE_SINT32, TYPE_SINT64, TYPE_BOOL, TYPE_STRING,
    TYPE_BYTES, TYPE_FIXED32, TYPE_FIXED64, TYPE_SFIXED32,
    TYPE_SFIXED64, TYPE_MESSAGE, TYPE_ENUM, TYPE_MAP
} FieldType;

typedef struct Field {
    char *name;
    FieldType type;
    int number;
    bool is_repeated;
    bool is_optional;
    char *oneof_name;
    struct Field *next;
} Field;

typedef struct EnumValue {
    int64_t number;
    char *name;
} EnumValue;

typedef struct Enum {
    char *name;
    EnumValue *values;
    int values_count;
} Enum;

typedef struct Oneof {
    char *name;
    Field *fields; // fields belonging to this oneof
} Oneof;

typedef struct Message {
    char *name;
    Field *fields; // sorted by number
    Enum *enums;
    Oneof *oneofs;
    int oneofs_count;
} Message;

typedef struct Type {
    FieldType type;
    union {
        Message *msg;
        Enum *enm;
    } data;
    char *name;
} Type;

Type *types[1024];
int types_count = 0;

Type* find_type(const char *name) {
    for (int i = 0; i < types_count; i++) {
        if (strcmp(types[i]->name, name) == 0) return types[i];
    }
    return NULL;
}

// --- Parsing ---

typedef struct {
    char *source;
    int pos;
} Parser;

void skip_whitespace(Parser *p) {
    while (p->source[p->pos] && (isspace(p->source[p->pos]) || p->source[p->pos] == '/' || p->source[p->pos] == '*')) {
        if (p->source[p->pos] == '/' && p->source[p->pos + 1] == '/') {
            while (p->source[p->pos] && p->source[p->pos] != '\n') p->pos++;
        } else if (p->source[p->pos] == '*' && p->source[p->pos + 1] == '/') {
            p->pos += 2;
            while (p->source[p->pos] && !(p->source[p->pos] == '*' && p->source[p->pos + 1] == '/')) p->pos++;
            if (p->source[p->pos]) p->pos += 2;
        } else if (isspace(p->source[p->pos])) {
            p->pos++;
        } else {
            break;
        }
    }
}

char* parse_identifier(Parser *p) {
    skip_whitespace(p);
    int start = p->pos;
    while (p->source[p->pos] && (isalnum(p->source[p->pos]) || p->source[p->pos] == '_')) p->pos++;
    int len = p->pos - start;
    char *res = malloc(len + 1);
    strncpy(res, p->source + start, len);
    res[len] = '\0';
    return res;
}

char* parse_string(Parser *p) {
    skip_whitespace(p);
    if (p->source[p->pos] != '"') return NULL;
    p->pos++;
    int start = p->pos;
    while (p->source[p->pos] && p->source[p->pos] != '"') p->pos++;
    int len = p->pos - start;
    char *res = malloc(len + 1);
    strncpy(res, p->source + start, len);
    res[len] = '\0';
    p->pos++;
    return res;
}

// --- Decoding ---

typedef struct Value {
    FieldType type;
    union {
        int64_t i64;
        uint64_t u64;
        bool b;
        char *s;
        unsigned char *bytes;
        size_t bytes_len;
        struct Value *msg;
        struct Value **list;
        size_t list_count;
        struct MapEntry *map;
        size_t map_count;
    } data;
    bool occurred;
} Value;

typedef struct MapEntry {
    char *key_str;
    int64_t key_i64;
    Value *value;
} MapEntry;

uint64_t decode_varint(const uint8_t **ptr) {
    uint64_t result = 0;
    int shift = 0;
    while (1) {
        uint8_t byte = **ptr;
        (*ptr)++;
        result |= (uint64_t)(byte & 0x7F) << shift;
        if (!(byte & 0x80)) break;
        shift += 7;
    }
    return result;
}

int64_t decode_zigzag(uint64_t n) {
    return (n >> 1) ^ (-(n & 1));
}

Value* create_value(FieldType type) {
    Value *v = calloc(1, sizeof(Value));
    v->type = type;
    return v;
}

void free_value(Value *v) {
    if (!v) return;
    if (v->type == TYPE_STRING) free(v->data.s);
    else if (v->type == TYPE_BYTES) free(v->data.bytes);
    else if (v->type == TYPE_MESSAGE) {
        // Handled in message decoding
    } else if (v->type == TYPE_MAP) {
        for (size_t i = 0; i < v->data.map_count; i++) {
            free(v->data.map[i].key_str);
            free_value(v->data.map[i].value);
        }
        free(v->data.map);
    } else if (v->type == TYPE_LIST) { // list_count > 0
        for (size_t i = 0; i < v->data.list_count; i++) free_value(v->data.list[i]);
        free(v->data.list);
    }
    free(v);
}

// --- Parsing Schema (simplified) ---

Message* parse_message(Parser *p) {
    skip_whitespace(p);
    if (strcmp(p->source + p->pos, "message") != 0) return NULL;
    p->pos += 8;
    skip_whitespace(p);
    char *name = parse_identifier(p);
    skip_whitespace(p);
    if (p->source[p->pos] != '{') return NULL;
    p->pos++;
    Message *m = calloc(1, sizeof(Message));
    m->name = name;
    while (1) {
        skip_whitespace(p);
        if (p->source[p->pos] == '}') { p->pos++; break; }
        if (strncmp(p->source + p->pos, "message", 7) == 0) {
            // Nested message - but for simplicity, we'll just parse fields.
            // The rules say every message/enum name is unique.
            p->pos += 7;
            parse_message(p);
        } else if (strncmp(p->source + p->pos, "enum", 4) == 0) {
            p->pos += 4;
            // Parse enum
            parse_identifier(p);
            p->pos++; // {
            while (p->source[p->pos] != '}') {
                parse_identifier(p);
                p->pos++; // =
                p->pos++; // number
                p->pos++; // ;
                skip_whitespace(p);
            }
            p->pos++;
        } else if (strncmp(p->source + p->pos, "oneof", 5) == 0) {
            p->pos += 5;
            skip_whitespace(p);
            char *oneof_name = parse_identifier(p);
            skip_whitespace(p);
            p->pos++; // {
            // ... parse oneof fields ...
            p->pos++; // }
        } else {
            // Field
            char *label = NULL;
            if (strncmp(p->source + p->pos, "repeated", 8) == 0) {
                p->pos += 8;
                label = "repeated";
            } else if (strncmp(p->source + p->pos, "optional", 8) == 0) {
                p->pos += 8;
                label = "optional";
            }
            skip_whitespace(p);
            char *type_name = parse_identifier(p);
            skip_whitespace(p);
            char *field_name = parse_identifier(p);
            skip_whitespace(p);
            p->pos++; // =
            skip_whitespace(p);
            int field_num = atoi(p->source + p->pos);
            while (isdigit(p->source[p->pos])) p->pos++;
            skip_whitespace(p);
            if (p->source[p->pos] == ';') p->pos++;

            Field *f = calloc(1, sizeof(Field));
            f->name = field_name;
            f->number = field_num;
            f->is_repeated = (label && strcmp(label, "repeated") == 0);
            f->is_optional = (label && strcmp(label, "optional") == 0);
            // Determine type
            Type *t = find_type(type_name);
            if (t) f->type = t->type;
            else {
                // scalar types
                if (strcmp(type_name, "int32") == 0) f->type = TYPE_INT32;
                else if (strcmp(type_name, "int64") == 0) f->type = TYPE_INT64;
                else if (strcmp(type_name, "uint32") == 0) f->type = TYPE_UINT32;
                else if (strcmp(type_name, "uint64") == 0) f->type = TYPE_UINT64;
                else if (strcmp(type_name, "sint32") == 0) f->type = TYPE_SINT32;
                else if (strcmp(type_name, "sint64") == 0) f->type = TYPE_SINT64;
                else if (strcmp(type_name, "bool") == 0) f->type = TYPE_BOOL;
                else if (strcmp(type_name, "string") == 0) f->type = TYPE_STRING;
                else if (strcmp(type_name, "bytes") == 0) f->type = TYPE_BYTES;
                else if (strcmp(type_name, "fixed32") == 0) f->type = TYPE_FIXED32;
                else if (strcmp(type_name, "fixed64") == 0) f->type = TYPE_FIXED64;
                else if (strcmp(type_name, "sfixed32") == 0) f->type = TYPE_SFIXED32;
                else if (strcmp(type_name, "sfixed64") == 0) f->type = TYPE_SFIXED64;
                else f->type = TYPE_MESSAGE; // default
            }
            f->next = m->fields;
            m->fields = f;
            free(label);
            free(type_name);
        }
    }
    return m;
}

