    static class RegexEngine {
        List<List<Piece>> branches = new ArrayList<>();
        int groupCount = 0;

        RegexEngine(String pattern) {
            parse(pattern);
        }

        private void parse(String pattern) {
            int i = 0;
            while (i < pattern.length()) {
                List<Piece> branch = new ArrayList<>();
                while (i < pattern.length() && pattern.charAt(i) != '|' && pattern.charAt(i) != ')') {
                    branch.add(parsePiece(pattern, i));
                }
                branches.add(branch);
                if (i < pattern.length() && pattern.charAt(i) == '|') {
                    i++;
                } else {
                    break;
                }
            }
        }

        private Piece parsePiece(String pattern, int i) {
            Atom atom = parseAtom(pattern, i);
            int nextI = atom.lastIdx;
            if (nextI < pattern.length() && (pattern.charAt(nextI) == '*' || pattern.charAt(nextI) == '+' || pattern.charAt(nextI) == '?')) {
                char q = pattern.charAt(nextI);
                nextI++;
                int min = 0, max = 100;
                if (q == '*') { min = 0; max = 100; }
                else if (q == '+') { min = 1; max = 100; }
                else if (q == '?') { min = 0; max = 1; }

                if (nextI < pattern.length() && pattern.charAt(nextI) == '{') {
                    nextI++;
                    int start = 0;
                    while (pattern.charAt(nextI) != '}') {
                        if (Character.isDigit(pattern.charAt(nextI))) start = start * 10 + (pattern.charAt(nextI) - '0');
                        nextI++;
                    }
                    if (nextI < pattern.length() && pattern.charAt(nextI) == ',') {
                        nextI++;
                        int end = 0;
                        while (pattern.charAt(nextI) != '}') {
                            if (Character.isDigit(pattern.charAt(nextI))) end = end * 10 + (pattern.charAt(nextI) - '0');
                            nextI++;
                        }
                        max = end;
                    } else {
                        max = start;
                    }
                    nextI++;
                }
                boolean lazy = false;
                if (nextI < pattern.length() && pattern.charAt(nextI) == '?') {
                    lazy = true;
                    nextI++;
                }
                atom.lastIdx = nextI;
                return new Piece(atom, min, max, lazy);
            }
            atom.lastIdx = nextI;
            return new Piece(atom, 1, 1, false);
        }

        private Atom parseAtom(String pattern, int i) {
            char c = pattern.charAt(i);
            if (c == '(') {
                i++;
                boolean nonCapturing = false;
                if (i < pattern.length() && pattern.charAt(i) == ':') {
                    nonCapturing = true;
                    i++;
                }
                int groupIdx = ++groupCount;
                int start = i;
                int depth = 1;
                while (depth > 0) {
                    if (pattern.charAt(i) == '(') depth++;
                    else if (pattern.charAt(i) == ')') depth--;
                    i++;
                }
                String sub = pattern.substring(start, i - 1);
                RegexEngine subEngine = new RegexEngine(sub);
                Atom atom = new Atom(0);
                atom.subPieces = subEngine.branches;
                atom.nonCapturing = nonCapturing;
                atom.groupIdx = groupIdx;
                atom.lastIdx = i;
                return atom;
            } else if (c == '[') {
                i++;
                boolean negate = false;
                if (i < pattern.length() && pattern.charAt(i) == '^') {
                    negate = true;
                    i++;
                }
                List<String> items = new ArrayList<>();
                while (i < pattern.length() && pattern.charAt(i) != ']') {
                    if (pattern.charAt(i) == '\\') {
                        i++;
                        items.add(String.valueOf(pattern.charAt(i)));
                    } else {
