                i++;
                Atom atom = new Atom(4);
                atom.classItems = items;
                atom.classNegate = negate;
                atom.lastIdx = i;
                return atom;
            } else if (c == '.') {
                i++;
                Atom atom = new Atom(1);
                atom.lastIdx = i;
                return atom;
            } else if (c == '^') {
                i++;
                Atom atom = new Atom(2);
                atom.lastIdx = i;
                return atom;
            } else if (c == '$') {
                i++;
                Atom atom = new Atom(3);
                atom.lastIdx = i;
                return atom;
            } else if (c == '\\') {
                i++;
                char esc = pattern.charAt(i);
                i++;
                Atom atom = new Atom(5);
                atom.escapeChar = esc;
                atom.lastIdx = i;
                return atom;
            } else {
                i++;
                Atom atom = new Atom(6);
                atom.literal = c;
                atom.lastIdx = i;
                return atom;
            }
        }
