    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        File dir = new File(args[0]);
        File casesFile = new File(dir, "cases.txt");
        if (!casesFile.exists()) return;

        BufferedReader reader = new BufferedReader(new FileReader(casesFile));
        String line;
        int lineNum = 1;
        while ((line = reader.readLine()) != null) {
            int tab = line.indexOf('\t');
            if (tab == -1) {
                System.out.println(lineNum + ": no match");
            } else {
                String pattern = line.substring(0, tab);
                String subject = line.substring(tab + 1);
                RegexEngine engine = new RegexEngine(pattern);
                MatchResult result = findFirstMatch(engine, subject);
                if (result == null) {
                    System.out.println(lineNum + ": no match");
                } else {
                    StringBuilder sb = new StringBuilder();
                    sb.append(lineNum).append(": ").append(result.captures[0][0]).append("-").append(result.captures[0][1]);
                    for (int i = 1; i < result.captures.length; i++) {
                        if (result.captures[i][0] == -1) {
                            sb.append(" -");
                        } else {
                            sb.append(" ").append(result.captures[i][0]).append("-").append(result.captures[i][1]);
                        }
                    }
                    System.out.println(sb.toString());
                }
            }
            lineNum++;
        }
        reader.close();
    }

    private static MatchResult findFirstMatch(RegexEngine engine, String subject) {
        for (int i = 0; i <= subject.length(); i++) {
            MatchResult res = matchRegex(engine.branches, 0, subject, i, new int[engine.groupCount + 1][2]);
            if (res != null) {
                res.captures[0] = new int[]{i, res.end};
                return res;
            }
        }
        return null;
    }

    private static MatchResult matchRegex(List<List<Piece>> branches, int branchIdx, String subject, int pos, int[][] captures) {
        if (branchIdx >= branches.size()) return null;
        MatchResult res = matchBranch(branches.get(branchIdx), 0, subject, pos, captures);
        if (res != null) return res;
        return matchRegex(branches, branchIdx + 1, subject, pos, captures);
    }

    private static MatchResult matchBranch(List<Piece> branch, int pieceIdx, String subject, int pos, int[][] captures) {
        if (pieceIdx == branch.size()) {
            return new MatchResult(pos, captures, false);
        }

        Piece p = branch.get(pieceIdx);
        if (p.lazy) {
            for (int k = p.min; k <= p.max; k++) {
                MatchResult res = matchKTimes(p.atom, subject, pos, captures, k, p.min);
                if (res != null) {
                    if (k == p.min || (k > p.min && res.lastIterationWasOptionalEmpty)) {
                        MatchResult finalRes = matchBranch(branch, pieceIdx + 1, subject, res.end, res.captures);
                        if (finalRes != null) {
                            finalRes.captures[0] = new int[]{pos, finalRes.end};
                            return finalRes;
                        }
                    }
                }
            }
        } else {
            for (int k = p.max; k >= p.min; k--) {
                MatchResult res = matchKTimes(p.atom, subject, pos, captures, k, p.min);
                if (res != null) {
                    if (k == p.min || (k > p.min && res.lastIterationWasOptionalEmpty)) {
                        MatchResult finalRes = matchBranch(branch, pieceIdx + 1, subject, res.end, res.captures);
                        if (finalRes != null) {
                            finalRes.captures[0] = new int[]{pos, finalRes.end};
                            return finalRes;
                        }
                    } else {
                        continue;
                    }
                }
            }
        }
        return null;
    }

    private static MatchResult matchKTimes(Atom atom, String subject, int pos, int[][] captures, int k, int min) {
        int currentPos = pos;
        int[][] currentCaptures = captures.clone();
        boolean lastWasOptionalEmpty = false;

        for (int i = 1; i <= k; i++) {
            List<MatchResult> matches = atomMatch(atom, subject, currentPos, currentCaptures);
            if (matches.isEmpty()) return null;
            MatchResult m = matches.get(0);
            currentPos = m.end;
            currentCaptures = m.captures;
            lastWasOptionalEmpty = (m.end == currentPos && i > min);
        }
        return new MatchResult(currentPos, currentCaptures, lastWasOptionalEmpty);
    }

    private static List<MatchResult> atomMatch(Atom atom, String subject, int pos, int[][] currentCaptures) {
        List<MatchResult> results = new ArrayList<>();
        switch (atom.type) {
            case 1: // Dot
                if (pos < subject.length()) {
                    int[][] caps = currentCaptures.clone();
                    results.add(new MatchResult(pos + 1, caps, false));
                }
                break;
            case 2: // AnchorStart
                if (pos == 0) {
                    int[][] caps = currentCaptures.clone();
                    results.add(new MatchResult(pos, caps, false));
                }
                break;
            case 3: // AnchorEnd
                if (pos == subject.length()) {
                    int[][] caps = currentCaptures.clone();
                    results.add(new MatchResult(pos, caps, false));
                }
                break;
            case 4: // Class
                if (pos < subject.length()) {
                    char c = subject.charAt(pos);
                    boolean matches = false;
                    if (atom.classNegate) {
                        matches = true;
                        for (String item : atom.classItems) {
                            if (item.length() == 1 && item.charAt(0) == c) { matches = false; break; }
                            if (item.contains("-") && c >= item.charAt(0) && c <= item.charAt(2)) { matches = false; break; }
                        }
                    } else {
                        matches = false;
                        for (String item : atom.classItems) {
                            if (item.length() == 1 && item.charAt(0) == c) { matches = true; break; }
                            if (item.contains("-") && c >= item.charAt(0) && c <= item.charAt(2)) { matches = true; break; }
                        }
                    }
                    if (matches) {
                        int[][] caps = currentCaptures.clone();
                        results.add(new MatchResult(pos + 1, caps, false));
                    }
                }
                break;
            case 5: // Escape
                if (pos < subject.length()) {
                    char c = subject.charAt(pos);
                    boolean matches = false;
                    if (atom.escapeChar == 'd') matches = c >= '0' && c <= '9';
                    else if (atom.escapeChar == 'w') matches = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_';
                    else if (atom.escapeChar == 's') matches = c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
                    else if (atom.escapeChar == 'D') matches = !(c >= '0' && c <= '9');
                    else if (atom.escapeChar == 'W') matches = !((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_');
                    else if (atom.escapeChar == 'S') matches = !(c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v');
                    else matches = true;
                    if (matches) {
                        int[][] caps = currentCaptures.clone();
                        results.add(new MatchResult(pos + 1, caps, false));
                    }
                }
                break;
            case 6: // Literal
                if (pos < subject.length() && subject.charAt(pos) == atom.literal) {
                    int[][] caps = currentCaptures.clone();
                    results.add(new MatchResult(pos + 1, caps, false));
                }
                break;
            case 0: // Group
                for (List<Piece> branch : atom.subPieces) {
                    MatchResult res = matchBranch(branch, 0, subject, pos, currentCaptures);
                    if (res != null) {
                        int[][] newCaps = res.captures.clone();
                        for (int i = 1; i < newCaps.length; i++) {
                            if (newCaps[i][0] != -1) {
                                newCaps[i][0] += pos;
                                newCaps[i][1] += pos;
                            }
                        }
                        newCaps[atom.groupIdx] = new int[]{res.captures[0][0] + pos, res.captures[0][1] + pos};
                        results.add(new MatchResult(res.end, newCaps, false));
                    }
                }
                break;
        }
        return results;
    }
