    private func matchRegex(_ regex: Regex, pos: Int) -> (Int, Captures)? {
        for branch in regex.branches {
            if let result = matchBranch(branch, pos: pos) {
                return result
            }
        }
        return nil
    }

    private func matchBranch(_ branch: Branch, pos: Int) -> (Int, Captures)? {
        if branch.pieces.isEmpty {
            return (pos, currentCaptures)
        }

        let piece = branch.pieces[0]
        let rest = Array(branch.pieces.dropFirst())

        let options = piece.getOptions(pos)
        for (endPos, captures) in options {
            let oldCaptures = currentCaptures
            currentCaptures.update(with: captures, offset: 0)

            if let result = matchBranch(Branch(pieces: rest), pos: endPos) {
                return result
            }
            currentCaptures = oldCaptures
        }

        return nil
    }

    private func matchAtom(_ atom: Atom, pos: Int) -> [(Int, Captures)] {
        switch atom {
        case .dot:
            if pos < subject.count { return [(pos + 1, Captures(count: 100))] }
            return []
        case .anchorStart:
            return pos == 0 ? [(pos, Captures(count: 100))] : []
        case .anchorEnd:
            return pos == subject.count ? [(pos, Captures(count: 100))] : []
        case .literal(let char):
            if pos < subject.count && subject[pos] == char {
                return [(pos + 1, Captures(count: 100))]
            }
            return []
        case .escape(let set):
            if pos < subject.count && set.contains(subject[pos]) {
                return [(pos + 1, Captures(count: 100))]
            }
            return []
        case .class(let set, let isNegated):
            if pos < subject.count {
                let char = subject[pos]
                let matches = isNegated ? !set.contains(char) : set.contains(char)
                if matches { return [(pos + 1, Captures(count: 100))] }
            }
            return []
        case .group(let node, let isCapturing, let gIndex):
            var results = [(Int, Captures)]()
            if let regex = node as? Regex {
                for branch in regex.branches {
                    if let res = matchBranch(branch, pos: pos) {
                        var newCaps = res.1.copy()
                        if let idx = gIndex {
                            newCaps.spans[idx] = (pos, res.0)
                        }
                        results.append((res.0, newCaps))
                    }
                }
            } else if let branch = node as? Branch {
                if let res = matchBranch(branch, pos: pos) {
                    var newCaps = res.1.copy()
                    if let idx = gIndex {
                        newCaps.spans[idx] = (pos, res.0)
                    }
                    results.append((res.0, newCaps))
                }
            }
            return results
        }
    }

    private func matchAtomKTimes(_ atom: Atom, pos: Int, k: Int, min: Int) -> [(Int, Captures)] {
        if k == 0 { return [(pos, Captures(count: 100))] }
        var results = [(Int, Captures)]()
        let matches = matchAtom(atom, pos: pos)
        for (endPos, captures) in matches {
            if endPos == pos && k > 1 && 1 > min { continue }
            let subResults = matchAtomKTimes(atom, pos: endPos, k: k - 1, min: min)
            for sub in subResults {
                var combined = captures.copy()
                combined.update(with: sub.1, offset: 0)
                results.append((sub.0, combined))
            }
        }
        return results
    }

    private func getOptions(_ piece: Piece, pos: Int) -> [(Int, Captures)] {
        let atom = piece.atom
        if let q = piece.quantifier {
            var results = [(Int, Captures)]()
            let maxK = min(q.max, subject.count)
            if q.lazy {
                for k in q.min...maxK {
                    results.append(contentsOf: matchAtomKTimes(atom, pos: pos, k: k, min: q.min))
                }
            } else {
                for k in stride(from: maxK, through: q.min, by: -1) {
                    results.append(contentsOf: matchAtomKTimes(atom, pos: pos, k: k, min: q.min))
                }
            }
            return results
        } else {
            return matchAtom(atom, pos: pos)
        }
    }

    // The Piece.getOptions needs to be accessible.
    // Let's put it in the Piece struct or a helper.
}

// Extension to Piece to include getOptions
extension Piece {
    func getOptions(_ pos: Int, matcher: Matcher) -> [(Int, Captures)] {
        let atom = self.atom
        if let q = self.quantifier {
            var results = [(Int, Captures)]()
            let maxK = min(q.max, matcher.subject.count)
            if q.lazy {
                for k in q.min...maxK {
                    results.append(contentsOf: matcher.matchAtomKTimes(atom, pos: pos, k: k, min: q.min))
                }
            } else {
                for k in stride(from: maxK, through: q.min, by: -1) {
                    results.append(contentsOf: matcher.matchAtomKTimes(atom, pos: pos, k: k, min: q.min))
                }
            }
            return results
        } else {
            return matcher.matchAtom(atom, pos: pos)
        }
    }
}

// Redefining Matcher to include Piece.getOptions properly
class MatcherV2 {
    let subject: [Character]
    var currentCaptures = Captures(count: 0)
    var memo = [String: Bool]()

    init(subject: String) {
        self.subject = Array(subject)
    }

    func findFirstMatch(regex: Regex) -> (start: Int, end: Int, captures: Captures)? {
        for pos in 0...subject.count {
            currentCaptures = Captures(count: 100)
            memo.removeAll()
            if let result = matchRegex(regex, pos: pos) {
                return (pos, result.0, result.1)
            }
        }
        return nil
    }

    private func matchRegex(_ regex: Regex, pos: Int) -> (Int, Captures)? {
        for branch in regex.branches {
            if let result = matchBranch(branch, pos: pos) {
                return result
            }
        }
        return nil
    }

    private func matchBranch(_ branch: Branch, pos: Int) -> (Int, Captures)? {
        if branch.pieces.isEmpty {
            return (pos, currentCaptures)
        }

        let piece = branch.pieces[0]
        let rest = Array(branch.pieces.dropFirst())

        let options = piece.getOptions(pos, matcher: self)
        for (endPos, captures) in options {
            let oldCaptures = currentCaptures
            currentCaptures.update(with: captures, offset: 0)

            if let result = matchBranch(Branch(pieces: rest), pos: endPos) {
                return result
            }
            currentCaptures = oldCaptures
        }

        return nil
    }

    func matchAtom(_ atom: Atom, pos: Int) -> [(Int, Captures)] {
        switch atom {
        case .dot:
            if pos < subject.count { return [(pos + 1, Captures(count: 100))] }
            return []
        case .anchorStart:
            return pos == 0 ? [(pos, Captures(count: 100))] : []
        case .anchorEnd:
            return pos == subject.count ? [(pos, Captures(count: 100))] : []
        case .literal(let char):
            if pos < subject.count && subject[pos] == char {
                return [(pos + 1, Captures(count: 100))]
            }
            return []
        case .escape(let set):
            if pos < subject.count && set.contains(subject[pos]) {
                return [(pos + 1, Captures(count: 100))]
            }
            return []
        case .class(let set, let isNegated):
            if pos < subject.count {
                let char = subject[pos]
                let matches = isNegated ? !set.contains(char) : set.contains(char)
                if matches { return [(pos + 1, Captures(count: 100))] }
            }
            return []
        case .group(let node, let isCapturing, let gIndex):
            var results = [(Int, Captures)]()
            if let regex = node as? Regex {
                for branch in regex.branches {
                    if let res = matchBranch(branch, pos: pos) {
                        var newCaps = res.1.copy()
                        if let idx = gIndex {
                            newCaps.spans[idx] = (pos, res.0)
                        }
                        results.append((res.0, newCaps))
                    }
                }
            } else if let branch = node as? Branch {
                if let res = matchBranch(branch, pos: pos) {
                    var newCaps = res.1.copy()
                    if let idx = gIndex {
                        newCaps.spans[idx] = (pos, res.0)
                    }
                    results.append((res.0, newCaps))
                }
            }
            return results
        }
    }

    func matchAtomKTimes(_ atom: Atom, pos: Int, k: Int, min: Int) -> [(Int, Captures)] {
        if k == 0 { return [(pos, Captures(count: 100))] }
        var results = [(Int, Captures)]()
        let matches = matchAtom(atom, pos: pos)
        for (endPos, captures) in matches {
            if endPos == pos && k > 1 && 1 > min { continue }
            let subResults = matchAtomKTimes(atom, pos: endPos, k: k - 1, min: min)
            for sub in subResults {
                var combined = captures.copy()
                combined.update(with: sub.1, offset: 0)
                results.append((sub.0, combined))
            }
        }
        return results
    }
}

// MARK: - Main

func main() {
    let args = CommandLine.arguments
    guard args.count > 1 else { return }
    let dir = args[1]
    let filePath = "\(dir)/cases.txt"

    guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else { return }
    let lines = content.components(separatedBy: .newlines)

    for (index, line) in lines.enumerated() {
        if line.isEmpty { continue }
        let parts = line.components(separatedBy: "\t")
        if parts.count < 2 { continue }

        let pattern = parts[0]
        let subject = parts[1]

        let parser = RegexParser(pattern)
        let regex = parser.parse()

        let matcher = MatcherV2(subject: subject)
        if let result = matcher.findFirstMatch(regex: regex) {
            var output = "\(index + 1): \(result.start)-\(result.end)"
            for i in 1...99 {
                if let span = result.captures.spans[i] {
                    output += " \(span.start)-\(span.end)"
                } else {
                    output += " -"
                }
            }
            print(output)
        } else {
            print("\(index + 1): no match")
        }
    }
}

main()

use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

#[derive(Clone, Debug)]
enum Atom {
    Group(usize, Regex),
    NonCapturingGroup(Regex),
    Dot,
    AnchorStart,
    AnchorEnd,
    Class(Vec<char>),
    Escape(Vec<char>),
    Literal(char),
}

#[derive(Clone, Debug)]
struct Quantifier {
    min: usize,
    max: usize,
    lazy: bool,
}

#[derive(Clone, Debug)]
struct Piece {
    atom: Atom,
    quantifier: Option<Quantifier>,
}

#[derive(Clone, Debug)]
struct Branch {
    pieces: Vec<Piece>,
}

#[derive(Clone, Debug)]
struct Regex {
    branches: Vec<Branch>,
    group_mapping: Vec<usize>,
}

struct Match {
    start: usize,
    end: usize,
    captures: Vec<Option<(usize, usize)>>,
}

static mut GROUP_COUNTER: usize = 0;

impl Regex {
    fn new() -> Self {
        Regex {
            branches: Vec::new(),
            group_mapping: Vec::new(),
        }
    }
}

fn parse_regex(chars: &mut std::iter::Peekable<std::str::Chars>) -> Regex {
    let mut regex = Regex::new();
    while let Some(&c) = chars.peek() {
        if c == ')' {
            chars.next();
            break;
        }
        if c == '|' {
            chars.next();
            break;
        }

        let mut branch = Branch { pieces: Vec::new() };
        while let Some(&c) = chars.peek() {
            if c == '|' || c == ')' {
                break;
            }
            branch.pieces.push(parse_piece(chars));
        }
        regex.branches.push(branch);

        if chars.peek() == Some(&'|') {
            chars.next();
            let mut next_branch = Branch { pieces: Vec::new() };
            while let Some(&c) = chars.peek() {
                if c == '|' || c == ')' {
                    break;
                }
                next_branch.pieces.push(parse_piece(chars));
            }
            regex.branches.push(next_branch);
            chars.next();
        }
    }
    regex
}

fn parse_piece(chars: &mut std::iter::Peekable<std::str::Chars>) -> Piece {
    let atom = parse_atom(chars);
    let mut quantifier = None;

    if let Some(&c) = chars.peek() {
        if c == '*' || c == '+' || c == '?' || c == '{' {
            let mut q_str = String::new();
            if *c == '*' || *c == '+' || *c == '?' {
                q_str.push(chars.next().unwrap());
            } else {
                q_str.push(chars.next().unwrap());
                while let Some(&c) = chars.peek() {
                    if c == '}' {
                        chars.next();
                        break;
                    }
                    q_str.push(chars.next().unwrap());
                }
            }

            let (min, max, lazy) = if q_str == "*" {
                (0, 100, false)
            } else if q_str == "+" {
                (1, 100, false)
            } else if q_str == "?" {
                (0, 1, false)
            } else if q_str.starts_with('{') && q_str.ends_with('}') {
                let parts: Vec<&str> = q_str[1..q_str.len()-1].split(',').collect();
                let min = parts[0].trim().parse().unwrap_or(0);
                let max = if parts.len() == 1 { 100 } else { parts[1].trim().parse().unwrap_or(100) };
                (min, max, false)
            } else {
                (0, 0, false)
            };

            let mut lazy = false;
            if chars.peek() == Some(&'?') {
                lazy = true;
                chars.next();
            }

            quantifier = Some(Quantifier { min, max, lazy });
        }
    }

    Piece { atom, quantifier }
}

fn parse_atom(chars: &mut std::iter::Peekable<std::str::Chars>) -> Atom {
    match chars.next() {
        Some('(') => {
            if chars.peek() == Some(&'?') && chars.next() == Some(&':') {
                Atom::NonCapturingGroup(parse_regex(chars))
            } else {
                let mut regex = parse_regex(chars);
                let id = unsafe { GROUP_COUNTER };
                unsafe { GROUP_COUNTER += 1; }

                let mut mapping = vec![0; regex.group_mapping.len() + 1];
                for (i, &m) in regex.group_mapping.iter().enumerate() {
                    mapping[i + 1] = m + id;
                }
                regex.group_mapping = mapping;
                Atom::Group(id, regex)
            }
        }
        Some('.') => Atom::Dot,
        Some('^') => Atom::AnchorStart,
        Some('$') => Atom::AnchorEnd,
        Some('[') => {
            let mut items = Vec::new();
            let mut negated = false;
            if chars.peek() == Some(&'^') {
                negated = true;
                chars.next();
            }
            while let Some(&c) = chars.peek() {
                if c == ']' {
                    chars.next();
                    break;
                }
                let mut item = String::new();
                if chars.peek() == Some(&'\\') {
                    chars.next();
                    item.push(chars.next().unwrap());
                } else {
                    item.push(chars.next().unwrap());
                }

                if item.len() == 1 {
                    items.push(item.chars().next().unwrap());
                } else if item.contains('-') {
                    let parts: Vec<&str> = item.split('-').collect();
                    let start = parts[0].chars().next().unwrap();
                    let end = parts[1].chars().next().unwrap();
                    for c in start..=end {
                        items.push(c);
                    }
                } else if item == "d" || item == "D" || item == "w" || item == "W" || item == "s" || item == "S" {
                    let set = match item {
                        "d" => "0123456789",
                        "w" => "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_",
                        "s" => " \t\n\r\f\v",
                        _ => "",
                    };
                    if item.starts_with('D') || item.starts_with('W') || item.starts_with('S') {
                        for c in 0..128 {
                            if !set.contains(c as u8 as char) {
                                items.push(c as char);
                            }
                        }
                    } else {
                        for c in set.chars() {
                            items.push(c);
                        }
                    }
                }

                if chars.peek() == Some(&'-') && chars.peek_next() != Some(&']') {
                    chars.next();
                    // already handled range
                }
            }
            Atom::Class(items)
        }
        Some('\\') => {
            let escaped = chars.next().unwrap();
            let mut set = Vec::new();
            match escaped {
                'd' => set = "0123456789".chars().collect(),
                'w' => set = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_".chars().collect(),
                's' => set = " \t\n\r\f\v".chars().collect(),
                'D' => {
                    for c in 0..128 {
                        if !("0123456789".contains(c as u8 as char)) { set.push(c as char); }
                    }
                }
                'W' => {
                    for c in 0..128 {
                        if !("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_".contains(c as u8 as char)) { set.push(c as char); }
                    }
                }
                'S' => {
                    for c in 0..128 {
                        if !(" \t\n\r\f\v".contains(c as u8 as char)) { set.push(c as char); }
                    }
                }
                _ => set = vec![escaped],
            }
            Atom::Escape(set)
        }
        Some(c) => Atom::Literal(c),
        None => Atom::Literal(' '),
    }
}

fn match_atom(atom: &Atom, pos: usize, subject: &str, current_captures: &mut Vec<Option<(usize, usize)>>) -> Vec<(usize, Vec<Option<(usize, usize)>>)> {
    let mut results = Vec::new();
    match atom {
        Atom::Literal(c) => {
            if pos < subject.len() && subject.as_bytes()[pos] as char == *c {
                results.push((pos + 1, current_captures.clone()));
            }
        }
        Atom::Dot => {
            if pos < subject.len() {
                results.push((pos + 1, current_captures.clone()));
            }
        }
        Atom::AnchorStart => {
            if pos == 0 {
                results.push((pos, current_captures.clone()));
            }
        }
        Atom::AnchorEnd => {
            if pos == subject.len() {
                results.push((pos, current_captures.clone()));
            }
        }
        Atom::Class(items) => {
            if pos < subject.len() {
                let c = subject.as_bytes()[pos] as char;
                if items.contains(&c) {
                    results.push((pos + 1, current_captures.clone()));
                }
            }
        }
        Atom::Escape(items) => {
            if pos < subject.len() {
                let c = subject.as_bytes()[pos] as char;
                if items.contains(&c) {
                    results.push((pos + 1, current_captures.clone()));
                }
            }
        }
        Atom::Group(id, regex) => {
            if let Some(m) = match_regex(regex, pos, subject) {
                let mut next_captures = current_captures.clone();
                next_captures[id] = Some((m.start, m.end));
                for (i, &global_id) in regex.group_mapping.iter().enumerate() {
                    if global_id != 0 {
                        next_captures[global_id] = m.captures[i];
                    }
                }
                results.push((m.end, next_captures));
            }
        }
        Atom::NonCapturingGroup(regex) => {
            if let Some(m) = match_regex(regex, pos, subject) {
                results.push((m.end, current_captures.clone()));
            }
        }
    }
    results
}

fn match_regex(regex: &Regex, pos: usize, subject: &str) -> Option<Match> {
    for i in 0..=subject.len() {
        for branch in &regex.branches {
            if let Some(m) = match_branch(branch, i, 0, &mut vec![None; 100], subject) {
                return Some(Match {
                    start: i,
                    end: m.end,
                    captures: m.captures,
                });
            }
        }
    }
    None
}

fn match_branch(branch: &Branch, pos: usize, piece_idx: usize, captures: &mut Vec<Option<(usize, usize)>>, subject: &str) -> Option<Match> {
    if piece_idx == branch.pieces.len() {
        return Some(Match {
            start: pos,
            end: pos,
            captures: captures.clone(),
        });
    }

    let piece = &branch.pieces[piece_idx];
    if let Some(q) = &piece.quantifier {
        let mut ways = Vec::new();
        // ways(k, pos)
        let mut ways_k = vec![Vec::new(); q.max + 1];
        ways_k[0].push((pos, captures.clone(), false));

        for k in 1..=q.max {
            for (p1, c1, e1) in &ways_k[k - 1] {
                if k - 1 > q.min && *e1 { continue; }
                let mut atom_results = match_atom(&piece.atom, *p1, subject, &mut Vec::new());
                for (p2, c2) in atom_results {
                    ways_k[k].push((p2, c2, p2 == *p1));
                }
            }
        }

        let mut order: Vec<usize> = (q.min..=q.max).collect();
        if !q.lazy {
            order.reverse();
        }

        for &k in &order {
            for (new_pos, new_captures, _) in &ways_k[k] {
                if let Some(m) = match_branch(branch, *new_pos, piece_idx + 1, &mut new_captures.clone(), subject) {
                    return Some(Match {
                        start: pos,
                        end: m.end,
                        captures: m.captures,
                    });
                }
            }
        }
    } else {
        let mut atom_results = match_atom(&piece.atom, pos, subject, &mut Vec::new());
        for (new_pos, new_captures) in atom_results {
            if let Some(m) = match_branch(branch, new_pos, piece_idx + 1, &mut new_captures.clone(), subject) {
                return Some(Match {
                    start: pos,
                    end: m.end,
                    captures: m.captures,
                });
            }
        }
    }
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = Path::new(dir).join("cases.txt");
    let file = File::open(path).expect("Could not open cases.txt");
    let reader = BufReader::new(file);

    for (i, line) in reader.lines().enumerate() {
        let line = line.unwrap();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() < 2 { continue; }
        let pattern_str = parts[0];
        let subject = parts[1];

        let mut chars = pattern_str.chars().peekable();
        let regex = parse_regex(&mut chars);

        match match_regex(&regex, 0, subject) {
            Some(m) => {
                let mut out = format!("{}: {}-{}", i + 1, m.start, m.end);
                for cap in m.captures {
                    match cap {
                        Some((s, e)) => out.push_str(&format!(" {}-{}", s, e)),
                        None => out.push_str(" -"),
                    }
                }
                println!("{}", out);
            }
            None => println!("{}: no match", i + 1),
        }
    }
}

import sys
import os

# Set recursion limit for deep regex trees
sys.setrecursionlimit(5000)

class Atom:
    pass

class GroupNode(Atom):
    def __init__(self, regex, group_num):
        self.regex = regex
        self.group_num = group_num

class NonCapturingGroupNode(Atom):
    def __init__(self, regex):
        self.regex = regex

class DotNode(Atom):
    pass

class AnchorStartNode(Atom):
    pass

class AnchorEndNode(Atom):
    pass

class ClassNode(Atom):
    def __init__(self, negated, chars):
        self.negated = negated
        self.chars = chars

class EscapeNode(Atom):
    def __init__(self, chars):
        self.chars = chars

class LiteralNode(Atom):
    def __init__(self, char):
        self.char = char

class PieceNode:
    def __init__(self, atom, quantifier=None):
        self.atom = atom
        self.quantifier = quantifier

class BranchNode:
    def __init__(self, branches):
        self.branches = branches

class RegexNode:
    def __init__(self, node):
        self.node = node

class Quantifier:
    def __init__(self, min_val, max_val, lazy=False):
        self.min_val = min_val
        self.max_val = max_val
        self.lazy = lazy

def parse_regex(pattern):
    pos = 0
    group_count = 0

    def parse_regex_recursive():
        nonlocal pos, group_count
        branches = []
        while pos < len(pattern) and pattern[pos] != ')':
            branches.append(parse_branch())
            if pos < len(pattern) and pattern[pos] == '|':
                pos += 1
