#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

#define MAX_SUBJECT_LEN 81
#define MAX_NODES 3000
#define MAX_GROUPS 60

typedef struct {
    int start;
    int end;
} Span;

typedef struct {
    bool success;
    int new_pos;
    Span* captures;
} MatchResult;

typedef enum {
    NODE_BRANCH,
    NODE_SEQUENCE,
    NODE_ATOM_LITERAL,
    NODE_ATOM_DOT,
    NODE_ATOM_ANCHOR,
    NODE_ATOM_CLASS,
    NODE_QUANTIFIER,
    NODE_GROUP_CAPTURING,
    NODE_GROUP_NON_CAPTURING
} NodeType;

typedef struct Node {
    NodeType type;
    int id;
    union {
        struct { struct Node **branches; int count; } branch;
        struct { struct Node **pieces; int count; } sequence;
        struct { unsigned char c; } literal;
        struct { int anchor_type; } anchor; 
        struct { bool *allowed; } class;
        struct { struct Node *atom; int min, max; bool greedy; } quantifier;
        struct { struct Node *sub_regex; int group_id; } group;
    } data;
} Node;

Node nodes[MAX_NODES];
int node_count = 0;
bool memo[MAX_NODES][MAX_SUBJECT_LEN];

Node* create_node(NodeType type) {
    nodes[node_count].type = type;
    nodes[node_count].id = node_count;
    memset(&nodes[node_count], 0, sizeof(Node));
    return &nodes[node_count++];
}

const char* current_regex;
int regex_ptr = 0;
int group_counter = 0;

Node* parse_regex();
Node* parse_branch();

Node* parse_atom() {
    if (regex_ptr >= (int)strlen(current_regex)) return NULL;
    char c = current_regex[regex_ptr];
    if (c == '(') {
        regex_ptr++;
        Node* n;
        if (regex_ptr < (int)strlen(current_regex) && current_regex[regex_ptr] == ':') {
            regex_ptr++;
            Node* sub = parse_regex();
            regex_ptr++; 
            n = create_node(NODE_GROUP_NON_CAPTURING);
            n->data.group.sub_regex = sub;
        } else {
            Node* sub = parse_regex();
            regex_ptr++;
            n = create_node(NODE_GROUP_CAPTURING);
            n->data.group.sub_regex = sub;
            n->data.group.group_id = ++group_counter;
        }
        return n;
    } else if (c == '.') {
        regex_ptr++;
        Node* n = create_node(NODE_ATOM_DOT);
        return n;
    } else if (c == '^') {
        regex_ptr++;
        Node* n = create_node(NODE_ATOM_ANCHOR);
        n->data.anchor.anchor_type = 0;
        return n;
    } else if (c == '$') {
        regex_ptr++;
        Node* n = create_node(NODE_ATOM_ANCHOR);
        n->data.anchor.anchor_type = 1;
        return n;
    } else if (c == '[') {
        regex_ptr++;
        Node* n = create_node(NODE_ATOM_CLASS);
        bool negate = false;
        if (current_regex[regex_ptr] == '^') {
            negate = true;
            regex_ptr++;
        }
        n->data.class.allowed = calloc(256, sizeof(bool));
        for (int i = 0; i < 256; i++) n->data.class.allowed[i] = true;
        if (negate) {
            for (int i = 0; i < 256; i++) n->data.class.allowed[i] = false;
        }
        while (current_regex[regex_ptr] != ']' && current_regex[regex_ptr] != '\0') {
            char sc = current_regex[regex_ptr];
            if (sc == '\\') {
                regex_ptr++;
                char esc = current_regex[regex_ptr];
                regex_ptr++;
                if (esc == 'd') {
                    for (int i = 0; i < 10; i++) n->data.class.allowed[i] = !negate;
                } else if (esc == 'w') {
                    for (int i = 0; i < 256; i++) {
                        if ((i >= 'A' && i <= 'Z') || (i >= 'a' && i <= 'z') || (i >= '0' && i <= '9') || i == '_')
                            n->data.class.allowed[i] = !negate;
                    }
                } else if (esc == 's') {
                    int s_chars[] = {0x20, 0x09, 0x0A, 0x0D, 0x0C, 0x0B};
                    for (int i = 0; i < 6; i++) n->data.class.allowed[s_chars[i]] = !negate;
                } else if (esc == 'D') {
                    for (int i = 0; i < 10; i++) n->data.class.allowed[i] = negate;
                } else if (esc == 'W') {
                    for (int i = 0; i < 256; i++) {
                        if ((i >= 'A' && i <= 'Z') || (i >= 'a' && i <= 'z') || (i >= '0' && i <= '9') || i == '_')
                            n->data.class.allowed[i] = negate;
                    }
                } else if (esc == 'S') {
                    int s_chars[] = {0x20, 0x09, 0x0A, 0x0D, 0x0C, 0x0B};
                    for (int i = 0; i < 6; i++) n->data.class.allowed[s_chars[i]] = negate;
                } else {
                    n->data.class.allowed[(unsigned char)esc] = !negate;
                }
            } else if (sc == '-') {
                if (current_regex[regex_ptr + 1] != ']') {
                    regex_ptr++;
                    char start = current_regex[regex_ptr];
                    regex_ptr++;
                    char end = current_regex[regex_ptr];
                    regex_ptr++;
                    for (int i = (unsigned char)start; i <= (unsigned char)end; i++)
                        n->data.class.allowed[i] = !negate;
                } else {
                    n->data.class.allowed[(unsigned char)sc] = !negate;
                }
            } else {
                n->data.class.allowed[(unsigned char)sc] = !negate;
            }
            regex_ptr++;
        }
        regex_ptr++;
        return n;
    } else if (c == '\\') {
        regex_ptr++;
        char esc = current_regex[regex_ptr];
        regex_ptr++;
        Node* n = create_node(NODE_ATOM_LITERAL);
        if (esc == 'd') n->data.literal.c = 0xFF;
        else if (esc == 'w') n->data.literal.c = 0xFE;
        else if (esc == 's') n->data.literal.c = 0xFD;
        else if (esc == 'D') n->data.literal.c = 0xFC;
        else if (esc == 'W') n->data.literal.c = 0xFB;
        else if (esc == 'S') n->data.literal.c = 0xFA;
        else n->data.literal.c = (unsigned char)esc;
        return n;
    } else {
        Node* n = create_node(NODE_ATOM_LITERAL);
        n->data.literal.c = (unsigned char)c;
        regex_ptr++;
        return n;
    }
}

Node* parse_piece() {
    Node* atom = parse_atom();
    if (regex_ptr < (int)strlen(current_regex)) {
        char c = current_regex[regex_ptr];
        if (c == '*' || c == '+' || c == '?' || c == '{') {
            Node* quant = create_node(NODE_QUANTIFIER);
            quant->data.quantifier.atom = atom;
            if (c == '*') {
                quant->data.quantifier.min = 0;
                quant->data.quantifier.max = 81;
                quant->data.quantifier.greedy = true;
            } else if (c == '+') {
                quant->data.quantifier.min = 1;
                quant->data.quantifier.max = 81;
                quant->data.quantifier.greedy = true;
            } else if (c == '?') {
                quant->data.quantifier.min = 0;
                quant->data.quantifier.max = 1;
                quant->data.quantifier.greedy = true;
            } else if (c == '{') {
                regex_ptr++;
                int m = 0, n_val = 0;
                while (isdigit(current_regex[regex_ptr])) {
                    m = m * 10 + (current_regex[regex_ptr] - '0');
                    regex_ptr++;
                }
                if (current_regex[regex_ptr] == ',') {
                    regex_ptr++;
                    while (isdigit(current_regex[regex_ptr])) {
                        n_val = n_val * 10 + (current_regex[regex_ptr] - '0');
                        regex_ptr++;
                    }
                    quant->data.quantifier.min = m;
                    quant->data.quantifier.max = n_val;
                } else {
                    quant->data.quantifier.min = m;
                    quant->data.quantifier.max = m;
                }
                regex_ptr++;
                if (current_regex[regex_ptr] == '?') {
                    quant->data.quantifier.greedy = false;
                    regex_ptr++;
                }
                regex_ptr++;
            }
            regex_ptr++;
            Node* seq = create_node(NODE_SEQUENCE);
            seq->data.sequence.pieces = malloc(sizeof(Node*));
            seq->data.sequence.pieces[0] = quant;
            seq->data.sequence.count = 1;
            return seq;
        }
    }
    return atom;
}

Node* parse_branch() {
    Node* n = create_node(NODE_BRANCH);
    n->data.branch.branches = malloc(sizeof(Node*));
    n->data.branch.count = 0;
    n->data.branch.branches[n->data.branch.count++] = parse_piece();
    while (regex_ptr < (int)strlen(current_regex) && current_regex[regex_ptr] == '|') {
        regex_ptr++;
        n->data.branch.branches = realloc(n->data.branch.branches, sizeof(Node*) * (n->data.branch.count + 1));
        n->data.branch.branches[n->data.branch.count++] = parse_branch();
    }
    return n;
}

Node* parse_regex() {
    Node* n = parse_branch();
    while (regex_ptr < (int)strlen(current_regex) && current_regex[regex_ptr] == '|') {
        regex_ptr++;
        Node* next = parse_branch();
        Node* seq = create_node(NODE_SEQUENCE);
        seq->data.sequence.pieces = malloc(sizeof(Node*) * 2);
        seq->data.sequence.pieces[0] = n;
        seq->data.sequence.pieces[1] = next;
        seq->data.sequence.count = 2;
        n = seq;
    }
    return n;
}

MatchResult match_atom(Node* node, int pos, Span* captures, const char* subject, int sub_len);
MatchResult match_recursive(Node* node, int pos, Span* captures, const char* subject, int sub_len);

MatchResult match_atom(Node* node, int pos, Span* captures, const char* subject, int sub_len) {
    MatchResult res = {false, pos, NULL};
    if (node->type == NODE_ATOM_LITERAL) {
        unsigned char c = (unsigned char)node->data.literal.c;
        if (c == 0xFF) {
            if (pos < sub_len && subject[pos] >= '0' && subject[pos] <= '9') {
                res.success = true; res.new_pos = pos + 1;
            }
        } else if (c == 0xFE) {
            if (pos < sub_len && ((subject[pos] >= 'A' && subject[pos] <= 'Z') || (subject[pos] >= 'a' && subject[pos] <= 'z') || (subject[pos] >= '0' && subject[pos] <= '9') || subject[pos] == '_')) {
                res.success = true; res.new_pos = pos + 1;
            }
        } else if (c == 0xFD) {
            int s_chars[] = {0x20, 0x09, 0x0A, 0x0D, 0x0C, 0x0B};
            for (int i = 0; i < 6; i++) if (subject[pos] == (char)s_chars[i]) { res.success = true; res.new_pos = pos + 1; break; }
        } else if (c == 0xFC) {
            if (pos < sub_len && !((subject[pos] >= '0' && subject[pos] <= '9'))) {
                res.success = true; res.new_pos = pos + 1;
            }
        } else if (c == 0xFB) {
            if (pos < sub_len && !((subject[pos] >= 'A' && subject[pos] <= 'Z') || (subject[pos] >= 'a' && subject[pos] <= 'z') || (subject[pos] >= '0' && subject[pos] <= '9') || subject[pos] == '_')) {
                res.success = true; res.new_pos = pos + 1;
            }
        } else if (c == 0xFA) {
            int s_chars[] = {0x20, 0x09, 0x0A, 0x0D, 0x0C, 0x0B};
            bool is_s = false;
            for (int i = 0; i < 6; i++) if (subject[pos] == (char)s_chars[i]) { is_s = true; break; }
            if (pos < sub_len && !is_s) { res.success = true; res.new_pos = pos + 1; }
        } else {
            if (pos < sub_len && subject[pos] == (char)c) {
                res.success = true; res.new_pos = pos + 1;
            }
        }
    } else if (node->type == NODE_ATOM_DOT) {
        if (pos < sub_len) { res.success = true; res.new_pos = pos + 1; }
    } else if (node->type == NODE_ATOM_ANCHOR) {
        if (node->data.anchor.anchor_type == 0) {
            if (pos == 0) { res.success = true; res.new_pos = pos; }
        } else {
            if (pos == sub_len) { res.success = true; res.new_pos = pos; }
        }
    } else if (node->type == NODE_ATOM_CLASS) {
        if (pos < sub_len && node->data.class.allowed[(unsigned char)subject[pos]]) {
            res.success = true; res.new_pos = pos + 1;
        }
    } else if (node->type == NODE_GROUP_CAPTURING) {
        MatchResult sub_res = match_recursive(node->data.group.sub_regex, pos, captures, subject, sub_len);
        if (sub_res.success) {
            res = sub_res;
            captures[node->data.group.group_id] = (Span){pos, sub_res.new_pos};
        }
    } else if (node->type == NODE_GROUP_NON_CAPTURING) {
        res = match_recursive(node->data.group.sub_regex, pos, captures, subject, sub_len);
    }
    return res;
}

MatchResult match_k_iterations(Node* atom, int pos, int k, int m, Span* captures, const char* subject, int sub_len) {
    if (k == 0) return (MatchResult){true, pos, captures};
    MatchResult res = match_atom(atom, pos, captures, subject, sub_len);
    if (res.success) {
        bool is_optional_empty = (res.new_pos == pos && k > m);
        if (is_optional_empty) {
            if (k == 1) return res;
            else return (MatchResult){false, pos, NULL};
        }
        MatchResult next = match_k_iterations(atom, res.new_pos, k - 1, m, captures, subject, sub_len);
        if (next.success) return next;
    }
    return (MatchResult){false, pos, NULL};
}

MatchResult match_recursive(Node* node, int pos, Span* captures, const char* subject, int sub_len) {
    if (memo[node->id][pos]) return (MatchResult){false, pos, NULL};

    Span current_captures[MAX_GROUPS];
    memcpy(current_captures, captures, sizeof(Span) * MAX_GROUPS);

    MatchResult res = {false, pos, NULL};
    if (node->type == NODE_BRANCH) {
        for (int i = 0; i < node->data.branch.count; i++) {
            res = match_recursive(node->data.branch.branches[i], pos, current_captures, subject, sub_len);
            if (res.success) break;
        }
    } else if (node->type == NODE_SEQUENCE) {
        int curr_pos = pos;
        bool failed = false;
        for (int i = 0; i < node->data.sequence.count; i++) {
            res = match_recursive(node->data.sequence.pieces[i], curr_pos, current_captures, subject, sub_len);
            if (res.success) {
                curr_pos = res.new_pos;
                if (res.captures) {
                    memcpy(current_captures, res.captures, sizeof(Span) * MAX_GROUPS);
                }
            } else {
                failed = true;
                break;
            }
        }
        if (!failed) {
            res.success = true;
            res.new_pos = curr_pos;
            res.captures = malloc(sizeof(Span) * MAX_GROUPS);
            memcpy(res.captures, current_captures, sizeof(Span) * MAX_GROUPS);
