async function main() {
    const [dataDir, baseUrl] = process.argv.slice(2);
    if (!dataDir || !baseUrl) return;

    const taskPath = path.join(dataDir, 'task.json');
    const inventoryPath = path.join(dataDir, 'inventory.csv');
    const ratesPath = path.join(dataDir, 'rates.json');

    const task = JSON.parse(fs.readFileSync(taskPath, 'utf8'));
    const inventoryData = fs.readFileSync(inventoryPath, 'utf8');
    const inventoryContent = inventoryData.startsWith('\uFEFF') ? inventoryData.slice(1) : inventoryData;
    const inventoryRows = parseCSV(inventoryContent);
    const inventory = new Map<string, any>();
    for (let i = 1; i < inventoryRows.length; i++) {
        const [sku, name, price_cents, currency, stock] = inventoryRows[i];
        inventory.set(sku, {
            sku,
            name,
            price_cents: parseInt(price_cents, 10),
            currency,
            stock: parseInt(stock, 10)
        });
    }

    const ratesData = JSON.parse(fs.readFileSync(ratesPath, 'utf8'));
    const rates = ratesData.rates;

    let conversation: any[] = [
        { role: "system", content: task.system },
        { role: "user", content: task.user }
    ];

    let totalPrompt = 0;
    let totalCompletion = 0;
    let totalUsage = 0;
    let requestCount = 0;
    let outputLines: string[] = [];

    const printLine = (line: string) => {
        outputLines.push(line);
        process.stdout.write(line + '\n');
    };

    const handle_error = (status: number, message: string) => {
        for (const line of outputLines) {
            process.stdout.write(line + '\n');
        }
        process.stdout.write(`ERROR ${status} ${message}\n`);
        process.exit(0);
    };

    while (true) {
        requestCount++;
        const body = JSON.stringify({
            model: task.model,
            messages: conversation,
            tools: task.tools,
            tool_choice: "auto"
        });

        const url = new URL(baseUrl + '/chat/completions');

        const request = http.request({
            hostname: url.hostname,
            port: url.port,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${task.api_key}`,
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(body),
                'Host': url.hostname,
            },
        }, (res) => {
            let responseBody = "";
            res.on('data', (chunk) => { responseBody += chunk; });
            res.on('end', () => {
                if (res.statusCode !== 200) {
                    try {
                        const err = JSON.parse(responseBody);
                        handle_error(res.statusCode, err.error?.message || "Unknown error");
                    } catch (e) {
                        handle_error(res.statusCode, "Unknown error");
                    }
                }

                const data = JSON.parse(responseBody);
                const choice = data.choices[0];
                const message = choice.message;
                const finishReason = choice.finish_reason;

                totalPrompt += data.usage.prompt_tokens;
                totalCompletion += data.usage.completion_tokens;
                totalUsage += data.usage.total_tokens;

                if (finishReason === "tool_calls") {
                    if (typeof message.content === "string") {
                        printLine(`SAY ${message.content}`);
                    }

                    conversation.push(message);

                    for (const toolCall of message.tool_calls) {
                        printLine(`CALL ${toolCall.id} ${toolCall.function.name}`);

                        let result: any;
                        const args = JSON.parse(toolCall.function.arguments);
                        const name = toolCall.function.name;

                        if (name === "inventory_lookup") {
                            const item = inventory.get(args.sku);
                            result = item ? {
                                sku: item.sku,
                                name: item.name,
                                price_cents: item.price_cents,
                                currency: item.currency,
                                stock: item.stock
                            } : { error: `unknown sku: ${args.sku}` };
                        } else if (name === "convert_currency") {
                            const { amount_cents, from, to } = args;
                            const rateFrom = rates[from];
                            const rateTo = rates[to];
                            const converted = Math.floor((2 * amount_cents * rateTo + rateFrom) / (2 * rateFrom));
                            result = {
                                amount_cents: converted,
                                currency: to
                            };
                        } else {
                            result = { error: `unknown tool: ${name}` };
                        }

                        const resultStr = serializeToolResult(result);
                        printLine(`RESULT ${toolCall.id} ${resultStr}`);
                        conversation.push({
                            role: "tool",
                            tool_call_id: toolCall.id,
                            content: resultStr
                        });
                    }
                } else if (finishReason === "stop") {
                    printLine(`FINAL ${message.content}`);
                    process.stdout.write(`USAGE prompt=${totalPrompt} completion=${totalCompletion} total=${totalUsage} requests=${requestCount}\n`);
                    process.exit(0);
                }
            });
        });

        request.on('error', (e) => {
            handle_error(500, e.message);
        });

        request.write(body);
        request.end();
    }
}

