func makeInventoryResult(sku: String, name: String, priceCents: Int, currency: String, stock: Int) -> String {
    return "{\"sku\":\"\(escapeJSONString(sku))\",\"name\":\"\(escapeJSONString(name))\",\"price_cents\":\(priceCents),\"currency\":\"\(escapeJSONString(currency))\",\"stock\":\(stock)}"
}

func makeConvertResult(amountCents: Int, currency: String) -> String {
    return "{\"amount_cents\":\(amountCents),\"currency\":\"\(escapeJSONString(currency))\"}"
}

func makeErrorResult(message: String) -> String {
    return "{\"error\":\"\(escapeJSONString(message))\"}"
}

// MARK: - HTTP Client
func sendRequest(url: URL, headers: [String: String], body: Data?) -> (Data, Int)? {
    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    for (key, value) in headers {
        request.setValue(value, forHTTPHeaderField: key)
    }
    if let body = body {
        request.httpBody = body
        request.setValue("\(body.count)", forHTTPHeaderField: "Content-Length")
    }

    let semaphore = DispatchSemaphore(value: 0)
    var responseData: Data?
    var responseCode: Int = 0

    let task = URLSession.shared.dataTask(with: request) { data, response, _ in
        if let httpResponse = response as? HTTPURLResponse {
            responseCode = httpResponse.statusCode
        }
        responseData = data
        semaphore.signal()
    }
    task.resume()
    semaphore.wait()

    return (responseData ?? Data(), responseCode)
}

// MARK: - Main Logic
let args = CommandLine.arguments
guard args.count == 3 else { exit(0) }
let dataDir = args[1]
let baseUrlStr = args[2]

let taskPath = "\(dataDir)/task.json"
let inventoryPath = "\(dataDir)/inventory.csv"
let ratesPath = "\(dataDir)/rates.json"

let taskData = try Data(contentsOf: URL(fileURLWithPath: taskPath))
let taskJson = try JSONSerialization.jsonObject(with: taskData) as? [String: Any]
let apiKey = taskJson?["api_key"] as? String ?? ""
let model = taskJson?["model"] as? String ?? ""
let system = taskJson?["system"] as? String ?? ""
let user = taskJson?["user"] as? String ?? ""
let tools = taskJson?["tools"] as? [[String: Any]] ?? []

let inventoryData = try Data(contentsOf: URL(fileURLWithPath: inventoryPath))
let csvRecords = parseCSV(data: inventoryData)
var inventory = [[String: Any]]()
if !csvRecords.isEmpty {
    let header = csvRecords[0]
    for i in 1..<csvRecords.count {
        let row = csvRecords[i]
        var dict = [String: Any]()
        for (j, key) in header.enumerated() {
            let value = row[j]
            if key == "price_cents" || key == "stock" {
                dict[key] = Int(value) ?? 0
            } else {
                dict[key] = value
            }
        }
        inventory.append(dict)
    }
}

let ratesData = try Data(contentsOf: URL(fileURLWithPath: ratesPath))
let ratesJson = try JSONSerialization.jsonObject(with: ratesData) as? [String: Any]
let rates = ratesJson?["rates"] as? [String: Int] ?? [:]

var conversation: [[String: Any]] = [
    ["role": "system", "content": system],
    ["role": "user", "content": user]
]

var totalPrompt = 0
var totalCompletion = 0
var totalTokens = 0
var requestCount = 0

let endpointUrl = URL(string: "\(baseUrlStr)/chat/completions")!

while true {
    requestCount += 1
    let requestBody: [String: Any] = [
        "model": model,
        "messages": conversation,
        "tools": tools,
        "tool_choice": "auto"
    ]

    let bodyData = try JSONSerialization.data(withJSONObject: requestBody, options: [])
    let headers = ["Authorization": "Bearer \(apiKey)", "Content-Type": "application/json"]

    guard let (responseData, responseCode) = sendRequest(url: endpointUrl, headers: headers, body: bodyData) else {
        exit(0)
    }

    guard responseCode == 200 else {
        if let json = try? JSONSerialization.jsonObject(with: responseData) as? [String: Any],
           let error = json["error"] as? [String: Any],
           let message = error["message"] as? String {
            print("ERROR \(responseCode) \(message)")
        } else {
            print("ERROR \(responseCode) Unknown error")
        }
        exit(0)
    }

    guard let json = try? JSONSerialization.jsonObject(with: responseData) as? [String: Any],
          let choices = json["choices"] as? [[String: Any]],
          let firstChoice = choices.first,
          let message = firstChoice["message"] as? [String: Any],
          let finishReason = firstChoice["finish_reason"] as? String else {
        exit(0)
    }

    if let usage = json["usage"] as? [String: Any] {
        totalPrompt += usage["prompt_tokens"] as? Int ?? 0
        totalCompletion += usage["completion_tokens"] as? Int ?? 0
        totalTokens += usage["total_tokens"] as? Int ?? 0
    }

    if finishReason == "tool_calls" {
        if let content = message["content"] as? String {
            print("SAY \(content)")
        }

        let toolCalls = message["tool_calls"] as? [[String: Any]] ?? []
        var results = [[String: Any]]()

        for tc in toolCalls {
            let callId = tc["id"] as? String ?? ""
            let function = tc["function"] as? [String: Any] ?? [:]
            let name = function["name"] as? String ?? ""
            let arguments = function["arguments"] as? String ?? ""

            print("CALL \(callId) \(name)")

            var resultStr = ""
            if name == "inventory_lookup" {
                if let args = try? JSONSerialization.jsonObject(with: arguments.data(using: .utf8)!) as? [String: Any],
                   let sku = args["sku"] as? String {
                    var found = false
                    for row in inventory {
                        if let rowSku = row["sku"] as? String, rowSku == sku {
                            resultStr = makeInventoryResult(
                                sku: rowSku,
                                name: row["name"] as? String ?? "",
                                priceCents: row["price_cents"] as? Int ?? 0,
                                currency: row["currency"] as? String ?? "",
                                stock: row["stock"] as? Int ?? 0
                            )
                            found = true
                            break
                        }
                    }
                    if !found {
                        resultStr = makeErrorResult(message: "unknown sku: \(sku)")
                    }
                }
            } else if name == "convert_currency" {
                if let args = try? JSONSerialization.jsonObject(with: arguments.data(using: .utf8)!) as? [String: Any],
                   let amountCents = args["amount_cents"] as? Int,
                   let from = args["from"] as? String,
                   let to = args["to"] as? String {
                    if let rateFrom = rates[from], let rateTo = rates[to] {
                        let numerator = amountCents * rateTo
                        let denominator = rateFrom
                        let converted = (2 * numerator + denominator) / (2 * denominator)
                        resultStr = makeConvertResult(amountCents: converted, currency: to)
                    }
                }
            } else {
                resultStr = makeErrorResult(message: "unknown tool: \(name)")
            }

            print("RESULT \(callId) \(resultStr)")
            results.append(["role": "tool", "tool_call_id": callId, "content": resultStr])
        }

        let assistantMsg: [String: Any] = [
            "role": "assistant",
            "content": message["content"] ?? NSNull(),
            "tool_calls": toolCalls.map { tc -> [String: Any] in
                let function = tc["function"] as? [String: Any] ?? [:]
                return [
                    "id": tc["id"] ?? "",
                    "type": tc["type"] ?? "",
                    "function": [
                        "name": function["name"] ?? "",
                        "arguments": function["arguments"] ?? ""
                    ]
                ]
            }
        ]

        conversation.append(assistantMsg)
        conversation.append(contentsOf: results)

    } else if finishReason == "stop" {
        if let content = message["content"] as? String {
            print("FINAL \(content)")
        } else if let content = message["content"] as? NSNull {
            print("FINAL ")
        }
        print("USAGE prompt=\(totalPrompt) completion=\(totalCompletion) total=\(totalTokens) requests=\(requestCount)")
        break
    } else {
        break
    }
}

exit(0)

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".wav"));
        if (files == null) return;
        Arrays.sort(files, Comparator.comparing(File::getName));

        for (int i = 0; i < files.length; i++) {
            processFile(files[i]);
            if (i < files.length - 1) {
                System.out.println();
            }
        }
    }

    private static void processFile(File file) {
        try {
            byte[] allBytes = Files.readAllBytes(file.toPath());
            ByteBuffer buffer = ByteBuffer.wrap(allBytes).order(ByteOrder.LITTLE_ENDIAN);

            if (buffer.getInt() != 0x46464952) { // RIFF
                System.out.println(file.getName() + ": unsupported");
                return;
            }
            buffer.getInt(); // size
            if (buffer.getInt() != 0x45564157) { // WAVE
                System.out.println(file.getName() + ": unsupported");
                return;
            }

            int fmtBodyStart = -1;
            int fmtSize = -1;
            int dataBodyStart = -1;
            int dataSize = -1;

            while (buffer.hasRemaining()) {
                byte[] idBytes = new byte[4];
                buffer.get(idBytes);
                String id = new String(idBytes);
                int size = buffer.getInt();
                if (id.equals("fmt ")) {
                    fmtBodyStart = buffer.position();
                    fmtSize = size;
                } else if (id.equals("data")) {
                    dataBodyStart = buffer.position();
                    dataSize = size;
                }
                int currentPos = buffer.position();
                buffer.position(currentPos + size);
                if (size % 2 != 0) buffer.get();
            }

            if (fmtBodyStart == -1 || dataBodyStart == -1) {
                System.out.println(file.getName() + ": unsupported");
                return;
            }

            buffer.position(fmtBodyStart);
            short tag = buffer.getShort();
            short channels = buffer.getShort();
            int sampleRate = buffer.getInt();
            int byteRate = buffer.getInt();
            short blockAlign = buffer.getShort();
            short bitsPerSample = buffer.getShort();

            short effectiveFormat;
            if (tag == (short) 0xFFFE) {
                buffer.position(fmtBodyStart + 24);
                effectiveFormat = buffer.getShort();
            } else {
                effectiveFormat = tag;
            }

            if (effectiveFormat != 1 || bitsPerSample != 16 || (channels < 1 || channels > 2) || (sampleRate != 8000 && sampleRate != 16000)) {
                System.out.println(file.getName() + ": unsupported");
                return;
            }

            buffer.position(dataBodyStart);
            int numFrames = dataSize / (2 * channels);
            int[] leftSamples = new int[numFrames];
            for (int i = 0; i < numFrames; i++) {
                leftSamples[i] = buffer.getShort();
                if (channels == 2) buffer.getShort();
            }

            int N = sampleRate / 50;
            int numBlocks = numFrames / N;
            char[] labels = new char[numBlocks];
            int[] lowFreqs = {697, 770, 852, 941};
            int[] highFreqs = {1209, 1336, 1477, 1633};
            char[][] keypad = {
                {'1', '2', '3', 'A'},
                {'4', '5', '6', 'B'},
                {'7', '8', '9', 'C'},
                {'*', '0', '#', 'D'}
            };

            for (int b = 0; b < numBlocks; b++) {
                long E = 0;
                for (int n = 0; n < N; n++) {
                    E += (long) leftSamples[b * N + n] * leftSamples[b * N + n];
                }

                if (E < 1000000L * N) {
                    labels[b] = '\0';
                } else {
                    double maxRl = -1, maxRh = -1;
                    int lIdx = -1, hIdx = -1;

                    for (int i = 0; i < 4; i++) {
                        double cL = 2.0 * Math.cos(2.0 * Math.PI * lowFreqs[i] / sampleRate);
                        double s1 = 0, s2 = 0;
                        for (int n = 0; n < N; n++) {
                            double s = leftSamples[b * N + n] + cL * s1 - s2;
                            s2 = s1; s1 = s;
                        }
                        double P = s1 * s1 + s2 * s2 - cL * s1 * s2;
                        double r = 2.0 * P / (N * E);
                        if (r > maxRl) { maxRl = r; lIdx = i; }
                    }
                    for (int i = 0; i < 4; i++) {
                        double cH = 2.0 * Math.cos(2.0 * Math.PI * highFreqs[i] / sampleRate);
                        double s1 = 0, s2 = 0;
                        for (int n = 0; n < N; n++) {
                            double s = leftSamples[b * N + n] + cH * s1 - s2;
                            s2 = s1; s1 = s;
                        }
                        double P = s1 * s1 + s2 * s2 - cH * s1 * s2;
                        double r = 2.0 * P / (N * E);
                        if (r > maxRh) { maxRh = r; hIdx = i; }
                    }

                    if (maxRl >= 0.1 && maxRh >= 0.1 && (maxRl + maxRh) >= 0.6) {
                        labels[b] = keypad[lIdx][hIdx];
                    } else {
                        labels[b] = '\0';
                    }
                }
            }

            char[] bridged = new char[numBlocks];
            System.arraycopy(labels, 0, bridged, 0, numBlocks);
            for (int i = 1; i < numBlocks - 1; i++) {
                if (labels[i] == '\0' && labels[i - 1] != '\0' && labels[i - 1] == labels[i + 1]) {
                    bridged[i] = labels[i - 1];
                }
            }

            System.out.println(file.getName() + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
            StringBuilder digits = new StringBuilder();
            int i = 0;
            while (i < numBlocks) {
                if (bridged[i] != '\0') {
                    int start = i;
                    while (i < numBlocks && bridged[i] == bridged[start]) {
                        i++;
                    }
                    int len = i - start;
                    if (len >= 2) {
                        System.out.println(bridged[start] + " " + (start * 20) + " " + (i * 20));
                        for (int k = 0; k < len; k++) digits.append(bridged[start]);
                    }
                } else {
                    i++;
                }
            }
            System.out.println("digits: " + digits.toString());

        } catch (Exception e) {
            System.out.println(file.getName() + ": unsupported");
        }
    }
}

