import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Inventory {
        String sku;
        String name;
        long priceCents;
        String currency;
        long stock;
    }

    static Map<String, Inventory> inventory = new HashMap<>();
    static long scale;
    static Map<String, Long> rates = new HashMap<>();

    static long totalPromptTokens = 0;
    static long totalCompletionTokens = 0;
    static long totalTotalTokens = 0;
    static int totalRequests = 0;

    public static void main(String[] args) throws Exception {
        if (args.length < 2) return;
        String dataDir = args[0];
        String baseUrl = args[1];

        loadInventory(Paths.get(dataDir, "inventory.csv"));
        loadRates(Paths.get(dataDir, "rates.json"));

        String taskJson = Files.readString(Paths.get(dataDir, "task.json"));
        JsonParser parser = new JsonParser(taskJson);
        JsonObject task = parser.parseObject();
        String apiKey = task.getString("api_key");
        String model = task.getString("model");
        String system = task.getString("system");
        String user = task.getString("user");
        JsonElement tools = task.get("tools");

        List<JsonElement> messages = new ArrayList<>();
        messages.add(new JsonObject().put("role", "system").put("content", system));
        messages.add(new JsonObject().put("role", "user").put("content", user));

        HttpClient client = HttpClient.newHttpClient();
        String endpoint = baseUrl + "/chat/completions";

        while (true) {
            totalRequests++;
            JsonObject requestBody = new JsonObject();
            requestBody.put("model", model);
            requestBody.put("messages", new JsonArray(messages));
            requestBody.put("tools", tools);
            requestBody.put("tool_choice", "auto");

            String bodyStr = requestBody.toString();
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(endpoint))
                    .header("Authorization", "Bearer " + apiKey)
                    .header("Content-Type", "application/json")
                    .header("Host", getHost(baseUrl))
                    .POST(HttpRequest.BodyPublishers.ofString(bodyStr))
                    .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

            if (response.statusCode() != 200) {
                JsonParser errorParser = new JsonParser(response.body());
                JsonObject errorObj = errorParser.parseObject();
                JsonObject error = (JsonObject) errorObj.get("error");
                System.out.println("ERROR " + response.statusCode() + " " + error.getString("message"));
                System.exit(0);
            }

            JsonParser respParser = new JsonParser(response.body());
            JsonObject respJson = respParser.parseObject();
            JsonArray choices = (JsonArray) respJson.get("choices");
            JsonObject choice = (JsonObject) choices.get(0);
            JsonObject message = (JsonObject) choice.get("message");
            String finishReason = choice.getString("finish_reason");

            if (finishReason.equals("tool_calls")) {
                String content = message.getString("content");
                if (content != null) {
                    System.out.println("SAY " + content);
                }

                JsonArray toolCalls = (JsonArray) message.get("tool_calls");
                List<String> results = new ArrayList<>();
                List<String> callIds = new ArrayList<>();
                List<String> callNames = new ArrayList<>();

                for (int i = 0; i < toolCalls.size(); i++) {
                    JsonObject tc = (JsonObject) toolCalls.get(i);
                    String id = tc.getString("id");
                    JsonObject func = (JsonObject) tc.get("function");
                    String name = func.getString("name");
                    String argsStr = func.getString("arguments");

                    callIds.add(id);
                    callNames.add(name);
                    System.out.println("CALL " + id + " " + name);

                    JsonObject args = new JsonParser(argsStr).parseObject();
                    String resultStr;
