    private static List<String[]> parseCSVCorrect(Path path) throws IOException {
        byte[] bytes = Files.readAllBytes(path);
        int start = 0;
        if (bytes.length >= 3 && bytes[0] == (byte)0xEF && bytes[1] == (byte)0xBB && bytes[2] == (byte)0xBF) {
            start = 3;
        }
        String content = new String(bytes, start, bytes.length - start, StandardCharsets.UTF_8);
        List<String[]> records = new ArrayList<>();
        int i = 0;
        while (i < content.length()) {
            List<String> fields = new ArrayList<>();
            while (i < content.length()) {
                StringBuilder sb = new StringBuilder();
                if (content.charAt(i) == '"') {
                    i++;
                    while (i < content.length()) {
                        if (content.charAt(i) == '"') {
                            if (i + 1 < content.length() && content.charAt(i + 1) == '"') {
                                sb.append('"');
                                i += 2;
                            } else {
                                i++;
                                break;
                            }
                        } else {
                            sb.append(content.charAt(i));
                            i++;
                        }
                    }
                } else {
                    while (i < content.length() && content.charAt(i) != ',' && content.charAt(i) != '\r' && content.charAt(i) != '\n') {
                        sb.append(content.charAt(i));
                        i++;
                    }
                }
                fields.add(sb.toString());
                if (i < content.length() && content.charAt(i) == ',') {
                    i++;
                } else {
                    break;
                }
            }
            records.add(fields.toArray(new String[0]));
            if (i < content.length() && content.charAt(i) == '\r') {
                i++;
                if (i < content.length() && content.charAt(i) == '\n') i++;
            } else if (i < content.length() && content.charAt(i) == '\n') {
                i++;
            }
        }
        return records;
    }

