    static class JsonParser {
        private final String json;
        private int pos = 0;
        public JsonParser(String json) { this.json = json; }
        public JsonElement parse() {
            skipWhitespace();
            JsonElement element = parseValue();
            skipWhitespace();
            return element;
        }
        public JsonObject parseObject() {
            skipWhitespace();
            if (json.charAt(pos) != '{') throw new RuntimeException("Expected {");
            pos++;
            JsonObject obj = new JsonObject();
            while (true) {
                skipWhitespace();
                if (json.charAt(pos) == '}') {
                    pos++;
                    break;
                }
                String key = parseString();
                skipWhitespace();
                if (json.charAt(pos) != ':') throw new RuntimeException("Expected :");
                pos++;
                obj.put(key, parseValue());
                skipWhitespace();
                if (json.charAt(pos) == ',') pos++;
            }
            return obj;
        }
        private JsonElement parseValue() {
            skipWhitespace();
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBoolean();
            if (c == 'n') return parseNull();
            return parseNumber();
        }
        private JsonArray parseArray() {
            skipWhitespace();
            pos++;
            JsonArray arr = new JsonArray();
            while (true) {
                skipWhitespace();
                if (json.charAt(pos) == ']') {
                    pos++;
                    break;
                }
                arr.add(parseValue());
                skipWhitespace();
                if (json.charAt(pos) == ',') pos++;
            }
            return arr;
        }
        private JsonString parseString() {
            skipWhitespace();
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < json.length()) {
                char c = json.charAt(pos);
                if (c == '"') {
                    pos++;
                    break;
                } else if (c == '\\') {
                    pos++;
                    char escaped = json.charAt(pos);
                    if (escaped == '"') sb.append('"');
                    else if (escaped == '\\') sb.append('\\');
                    else if (escaped == 'b') sb.append('\b');
                    else if (escaped == 'f') sb.append('\f');
                    else if (escaped == 'n') sb.append('\n');
                    else if (escaped == 'r') sb.append('\r');
                    else if (escaped == 't') sb.append('\t');
                    else if (escaped == 'u') {
                        pos += 4;
                        String hex = json.substring(pos - 4, pos);
                        int code = Integer.parseInt(hex, 16);
                        if (code >= 0xD800 && code <= 0xDBFF) {
                            pos += 4;
                            String hex2 = json.substring(pos - 4, pos);
                            int code2 = Integer.parseInt(hex2, 16);
                            code = 0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00);
                        }
                        sb.append((char) code);
                    }
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            return new JsonString(sb.toString());
        }
        private JsonNumber parseNumber() {
            int start = pos;
            while (pos < json.length() && "0123456789.-eE".indexOf(json.charAt(pos)) != -1) pos++;
            String numStr = json.substring(start, pos);
            if (numStr.contains(".") || numStr.contains("e") || numStr.contains("E")) return new JsonNumber(Double.parseDouble(numStr));
            return new JsonNumber(Long.parseLong(numStr));
        }
        private JsonBoolean parseBoolean() {
            if (json.startsWith("true", pos)) { pos += 4; return new JsonBoolean(true); }
            else { pos += 5; return new JsonBoolean(false); }
        }
        private JsonNull parseNull() { pos += 4; return new JsonNull(); }
        private void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
        }
    }

    interface JsonElement {
        String asString();
        long asLong();
        double asDouble();
        JsonObject asJsonObject();
        JsonArray asJsonArray();
    }

    static class JsonObject implements JsonElement {
        private final Map<String, JsonElement> map = new LinkedHashMap<>();
        public JsonObject put(String key, JsonElement value) { map.put(key, value); return this; }
        public JsonElement get(String key) { return map.get(key); }
        public String getString(String key) { return asString(); }
        public long getLong(String key) { return asLong(); }
        public JsonObject asJsonObject() { return this; }
        public JsonArray asJsonArray() { throw new RuntimeException("Not an array"); }
        public String asString() { return null; }
        public long asLong() { return 0; }
        public double asDouble() { return 0; }
        public String toString() {
            StringBuilder sb = new StringBuilder("{");
            Iterator<Map.Entry<String, JsonElement>> it = map.entrySet().iterator();
            while (it.hasNext()) {
                Map.Entry<String, JsonElement> entry = it.next();
                sb.append("\"").append(entry.getKey()).append("\":").append(entry.getValue().toString());
                if (it.hasNext()) sb.append(",");
                sb.append(" ");
            }
            sb.append("}");
            return sb.toString().trim();
        }
    }

    static class JsonArray implements JsonElement {
        private final List<JsonElement> list = new ArrayList<>();
        public JsonArray(List<JsonElement> list) { this.list = list; }
        public void add(JsonElement element) { list.add(element); }
        public JsonObject asJsonObject() { throw new RuntimeException("Not an object"); }
        public JsonArray asJsonArray() { return this; }
        public String asString() { return null; }
        public long asLong() { return 0; }
        public double asDouble() { return 0; }
        public String toString() {
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                sb.append(list.get(i).toString());
                if (i < list.size() - 1) sb.append(", ");
            }
            sb.append("]");
            return sb.toString();
        }
    }

    static class JsonString implements JsonElement {
        private final String val;
        public JsonString(String val) { this.val = val; }
        public String asString() { return val; }
        public long asLong() { return Long.parseLong(val); }
        public double asDouble() { return Double.parseDouble(val); }
        public JsonObject asJsonObject() { throw new RuntimeException("Not an object"); }
        public JsonArray asJsonArray() { throw new RuntimeException("Not an array"); }
        public String toString() {
            StringBuilder sb = new StringBuilder("\"");
            for (int i = 0; i < val.length(); i++) {
                char c = val.charAt(i);
                if (c == '"') sb.append("\\\"");
                else if (c == '\\') sb.append("\\\\");
                else if (c == '\b') sb.append("\\b");
                else if (c == '\f') sb.append("\\f");
                else if (c == '\n') sb.append("\\n");
                else if (c == '\r') sb.append("\\r");
                else if (c == '\t') sb.append("\\t");
                else if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                else sb.append(c);
            }
            sb.append("\"");
            return sb.toString();
        }
    }

    static class JsonNumber implements JsonElement {
        private final double val;
        public JsonNumber(double val) { this.val = val; }
        public String asString() { return String.valueOf(val); }
        public long asLong() { return (long) val; }
        public double asDouble() { return val; }
        public JsonObject asJsonObject() { throw new RuntimeException("Not an object"); }
        public JsonArray asJsonArray() { throw new RuntimeException("Not an array"); }
        public String toString() {
            return (val == (long) val) ? String.valueOf((long) val) : String.valueOf(val);
        }
    }

    static class JsonBoolean implements JsonElement {
        private final boolean val;
        public JsonBoolean(boolean val) { this.val = val; }
        public String asString() { return String.valueOf(val); }
        public long asLong() { return val ? 1 : 0; }
        public double asDouble() { return val ? 1.0 : 0.0; }
        public JsonObject asJsonObject() { throw new RuntimeException("Not an object"); }
        public JsonArray asJsonArray() { throw new RuntimeException("Not an array"); }
        public String toString() { return String.valueOf(val); }
    }

    static class JsonNull implements JsonElement {
        public String asString() { return null; }
        public long asLong() { return 0; }
        public double asDouble() { return 0; }
        public JsonObject asJsonObject() { throw new RuntimeException("Not an object"); }
        public JsonArray asJsonArray() { throw new RuntimeException("Not an array"); }
        public String toString() { return "null"; }
    }
