                rValues[j] = 2.0 * p / (Double(N) * E)
            }

            var maxRLow = -1.0
            var flIdx = -1
            for j in 0..<4 {
                if rValues[j] > maxRLow {
                    maxRLow = rValues[j]
                    flIdx = j
                }
            }

            var maxRHigh = -1.0
            var fhIdx = -1
            for j in 4..<8 {
                if rValues[j] > maxRHigh {
                    maxRHigh = rValues[j]
                    fhIdx = j - 4
                }
            }

            if maxRLow >= 0.1 && maxRHigh >= 0.1 && (maxRLow + maxRHigh) >= 0.6 {
                labels[b] = keypad[flIdx][fhIdx]
            }
        }

        // Bridging logic
        var bridgedLabels = labels
        for b in 1..<(numBlocks - 1) {
            if labels[b] == nil {
                if let prev = labels[b-1], let next = labels[b+1], prev == next {
                    bridgedLabels[b] = prev
                }
            }
        }

        // Identify key presses
        var keyPresses = [(String, Int, Int)]()
        var i = 0
        while i < numBlocks {
            if let digit = bridgedLabels[i] {
                var j = i
                while j < numBlocks && bridgedLabels[j] == digit {
