                    };
                    labels[b] = keypad[`${fl}-${fh}`];
                }
            }
        }

        const bridgedLabels = [...labels];
        for (let b = 1; b < numBlocks - 1; b++) {
            if (bridgedLabels[b] === null && labels[b - 1] !== null && labels[b - 1] === labels[b + 1]) {
                bridgedLabels[b] = labels[b - 1];
            }
        }

        const keyPresses: { digit: string, start: number, end: number }[] = [];
        let i = 0;
        while (i < numBlocks) {
            if (bridgedLabels[i] !== null) {
                const digit = bridgedLabels[i];
                let j = i;
                while (j < numBlocks && bridgedLabels[j] === digit) {
                    j++;
                }
                if (j - i >= 2) {
                    keyPresses.push({
                        digit,
                        start: 20 * i,
                        end: 20 * j
                    });
                }
                i = j;
            } else {
                i++;
            }
        }

        console.log(`${fileName}: ${rate} Hz, ${channels} ch, ${numBlocks} blocks`);
        for (const kp of keyPresses) {
            console.log(`${kp.digit} ${kp.start} ${kp.end}`);
        }
        let digits = "";
        for (const kp of keyPresses) {
            digits += kp.digit;
        }
        console.log(`digits: ${digits}`);
    }
