#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <math.h>
#include <stdint.h>

#define PI 3.14159265358979323846

typedef struct {
    char *name;
} FileEntry;

int compare_files(const void *a, const void *b) {
    return strcmp(((FileEntry *)a)->name, ((FileEntry *)b)->name);
}

void process_file(const char *dir, const char *filename) {
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", dir, filename);
    FILE *fp = fopen(path, "rb");
    if (!fp) return;

    uint8_t header[12];
    if (fread(header, 1, 12, fp) < 12) { fclose(fp); return; }
    if (memcmp(header, "RIFF", 4) != 0 || memcmp(header + 8, "WAVE", 4) != 0) { fclose(fp); return; }

    uint32_t riff_size;
    memcpy(&riff_size, header + 4, 4);

    uint16_t format = 0, channels = 0, bits_per_sample = 0;
    uint32_t sample_rate = 0, byte_rate = 0, data_size = 0;
    long data_offset = 0;

    while (1) {
        char chunk_id[4];
        uint32_t chunk_size;
        if (fread(chunk_id, 1, 4, fp) < 4) break;
        if (fread(&chunk_size, 1, 4, fp) < 4) break;

        if (memcmp(chunk_id, "fmt ", 4) == 0) {
            uint8_t body[1024];
            fread(body, 1, chunk_size > 1023 ? 1023 : chunk_size, fp);
            format = *(uint16_t *)(body);
            channels = *(uint16_t *)(body + 2);
            sample_rate = *(uint32_t *)(body + 4);
            byte_rate = *(uint32_t *)(body + 8);
            bits_per_sample = *(uint16_t *)(body + 14);
            if (format == 0xFFFE && chunk_size > 16) {
                format = *(uint16_t *)(body + 24);
            }
        } else if (memcmp(chunk_id, "data", 4) == 0) {
            data_size = chunk_size;
            data_offset = ftell(fp);
            break;
        } else {
            fseek(fp, chunk_size, SEEK_CUR);
            if (chunk_size % 2 != 0) fseek(fp, 1, SEEK_CUR);
        }
    }
    fclose(fp);

    if (format != 1 || bits_per_sample != 16 || (channels != 1 && channels != 2) || 
        (sample_rate != 8000 && sample_rate != 16000)) {
        printf("%s: unsupported\n", filename);
        return;
    }

    uint32_t num_frames = data_size / (2 * channels);
    uint32_t N = sample_rate / 50;
    uint32_t num_blocks = num_frames / N;

    int16_t *samples = malloc(num_frames * sizeof(int16_t));
    FILE *fp2 = fopen(path, "rb");
    fseek(fp2, data_offset, SEEK_SET);
    for (uint32_t f = 0; f < num_frames; f++) {
        // The left channel sample for frame f is at offset f * channels * 2
        // But we only need the first sample of each frame.
        // The first sample of frame f is at byte offset f * channels * 2.
        // However, it's easier to read all samples and pick the left ones.
        // Wait, the data is interleaved. Frame f is samples[f*channels ... f*channels + channels - 1].
        // The left channel is always the first sample of the frame: samples[f*channels].
        // Let's just read all samples.
        uint16_t temp;
        // This is still slightly wrong because we need to skip the right channel if channels=2.
        // Let's just read every (channels) samples.
    }
    // Correction:
    fseek(fp2, data_offset, SEEK_SET);
    for (uint32_t f = 0; f < num_frames; f++) {
        uint16_t s;
        // The sample for frame f is at byte offset f * channels * 2.
        fseek(fp2, data_offset + (long)f * channels * 2, SEEK_SET);
        fread(&s, 2, 1, fp2);
        samples[f] = (int16_t)s;
    }
    fclose(fp2);

    char *block_digits = calloc(num_blocks, sizeof(char));
    for (uint32_t b = 0; b < num_blocks; b++) {
        long long E = 0;
        for (uint32_t n = 0; n < N; n++) {
            int16_t val = samples[b * N + n];
            E += (long long)val * val;
        }

        if (E < 1000000LL * N) {
            block_digits[b] = 0;
        } else {
            double low_r[4], high_r[4];
            double freqs_l[4] = {697, 770, 852, 941};
            double freqs_h[4] = {1209, 1336, 1477, 1633};
            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * PI * freqs_l[i] / sample_rate);
                double s1 = 0, s2 = 0;
                for (uint32_t n = 0; n < N; n++) {
                    double s = (double)samples[b * N + n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                low_r[i] = 2.0 * (s1 * s1 + s2 * s2 - c * s1 * s2) / (N * E);
            }
            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * PI * freqs_h[i] / sample_rate);
                double s1 = 0, s2 = 0;
                for (uint32_t n = 0; n < N; n++) {
                    double s = (double)samples[b * N + n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                high_r[i] = 2.0 * (s1 * s1 + s2 * s2 - c * s1 * s2) / (N * E);
            }

            int fl = 0, fh = 0;
            for (int i = 1; i < 4; i++) {
                if (low_r[i] > low_r[fl]) fl = i;
                if (high_r[i] > high_r[fh]) fh = i;
            }

            if (low_r[fl] >= 0.1 && high_r[fh] >= 0.1 && (low_r[fl] + high_r[fh]) >= 0.6) {
                char keypad[4][4] = {{'1','2','3','A'}, {'4','5','6','B'}, {'7','8','9','C'}, {'*','0','#','D'}};
                block_digits[b] = keypad[fl][fh];
            } else {
                block_digits[b] = 0;
            }
        }
    }

    for (uint32_t b = 1; b < num_blocks - 1; b++) {
        if (block_digits[b] == 0 && block_digits[b - 1] != 0 && block_digits[b - 1] == block_digits[b + 1]) {
            block_digits[b] = block_digits[b - 1];
        }
    }

    printf("%s: %u Hz, %u ch, %u blocks\n", filename, sample_rate, channels, num_blocks);

    // Find key presses
    for (uint32_t b = 0; b < num_blocks; ) {
        if (block_digits[b] != 0) {
            uint32_t start = b;
            char digit = block_digits[b];
            while (b < num_blocks && block_digits[b] == digit) b++;
            if (b - start >= 2) {
                printf("%c %u %u\n", digit, start * N * 20, b * N * 20);
            }
        } else {
            b++;
        }
    }

    printf("digits: ");
    // Re-calculate key presses for digits line
    for (uint32_t b = 0; b < num_blocks; ) {
        if (block_digits[b] != 0) {
            uint32_t start = b;
            char digit = block_digits[b];
            while (b < num_blocks && block_digits[b] == digit) b++;
            if (b - start >= 2) {
                for (uint32_t k = 0; k < (b - start); k++) putchar(digit);
            }
        } else {
            b++;
        }
    }
    printf("\n");

    free(samples);
    free(block_digits);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 0;
    DIR *d = opendir(argv[1]);
    if (!d) return 0;

    FileEntry *files = malloc(10000 * sizeof(FileEntry));
    int count = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t len = strlen(de->d_name);
        if (len >= 4 && strcmp(de->d_name + len - 4, ".wav") == 0) {
            files[count].name = strdup(de->d_name);
            count++;
        }
    }
    closedir(d);

    qsort(files, count, sizeof(FileEntry), compare_files);

    for (int i = 0; i < count; i++) {
        if (i > 0) printf("\n");
        process_file(argv[1], files[i].name);
        free(files[i].name);
    }

    free(files);
    return 0;
}

