    uint32_t riff_size;
    memcpy(&riff_size, header + 4, 4);

    uint16_t format = 0, channels = 0, bits_per_sample = 0;
    uint32_t sample_rate = 0, byte_rate = 0, data_size = 0;
    long data_offset = 0;
    int fmt_found = 0, data_found = 0;

    while (1) {
        char chunk_id[4];
        uint32_t chunk_size;
        if (fread(chunk_id, 1, 4, fp) < 4) break;
        if (fread(&chunk_size, 1, 4, fp) < 4) break;

        if (memcmp(chunk_id, "fmt ", 4) == 0) {
            uint8_t *body = malloc(chunk_size);
            if (fread(body, 1, chunk_size, fp) == chunk_size) {
                format = *(uint16_t *)(body);
                channels = *(uint16_t *)(body + 2);
                sample_rate = *(uint32_t *)(body + 4);
                byte_rate = *(uint32_t *)(body + 8);
                bits_per_sample = *(uint16_t *)(body + 12);
                if (format == 0xFFFE && chunk_size > 26) {
                    format = *(uint16_t *)(body + 24);
                }
                fmt_found = 1;
            }
            free(body);
        } else if (memcmp(chunk_id, "data", 4) == 0) {
            data_size = chunk_size;
            data_offset = ftell(fp);
            data_found = 1;
            break;
        } else {
            fseek(fp, chunk_size, SEEK_CUR);
            if (chunk_size % 2 != 0) fseek(fp, 1, SEEK_CUR);
        }
    }
    fclose(fp);

    if (!fmt_found || !data_found || format != 1 || bits_per_sample != 16 || 
        (channels != 1 && channels != 2) || (sample_rate != 8000 && sample_rate != 16000)) {
        printf("%s: unsupported\n", filename);
        return;
    }

    uint32_t num_frames = data_size / (2 * channels);
    uint32_t N = sample_rate / 50;
    uint32_t num_blocks = num_frames / N;

    fp = fopen(path, "rb");
    if (!fp) return;
    fseek(fp, data_offset, SEEK_SET);

    char *block_digits = calloc(num_blocks, sizeof(char));
    for (uint32_t b = 0; b < num_blocks; b++) {
        long long E = 0;
        int16_t block_samples[320];
        for (uint32_t n = 0; n < N; n++) {
            fseek(fp, data_offset + (long)(b * N + n) * channels * 2, SEEK_SET);
            if (fread(&block_samples[n], 2, 1, fp) != 1) break;
            E += (long long)block_samples[n] * block_samples[n];
        }

        if (E < 1000000LL * N) {
            block_digits[b] = 0;
        } else {
            double low_r[4], high_r[4];
            double freqs_l[4] = {697, 770, 852, 941};
            double freqs_h[4] = {1209, 1336, 1477, 1633};
            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * PI * freqs_l[i] / sample_rate);
                double s1 = 0, s2 = 0;
                for (uint32_t n = 0; n < N; n++) {
                    double s = (double)block_samples[n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                low_r[i] = 2.0 * (s1 * s1 + s2 * s2 - c * s1 * s2) / (N * E);
            }
            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * PI * freqs_h[i] / sample_rate);
                double s1 = 0, s2 = 0;
                for (uint32_t n = 0; n < N; n++) {
                    double s = (double)block_samples[n] + c * s1 - s2;
                    s2 = s1; s1 = s;
                }
                high_r[i] = 2.0 * (s1 * s1 + s2 * s2 - c * s1 * s2) / (N * E);
            }

            int fl = 0, fh = 0;
            for (int i = 1; i < 4; i++) {
                if (low_r[i] > low_r[fl]) fl = i;
                if (high_r[i] > high_r[fh]) fh = i;
            }

            if (low_r[fl] >= 0.1 && high_r[fh] >= 0.1 && (low_r[fl] + high_r[fh]) >= 0.6) {
                char keypad[4][4] = {{'1','2','3','A'}, {'4','5','6','B'}, {'7','8','9','C'}, {'*','0','#','D'}};
                block_digits[b] = keypad[fl][fh];
            } else {
                block_digits[b] = 0;
            }
        }
    }
    fclose(fp);

    char *bridged_digits = malloc(num_blocks * sizeof(char));
    memcpy(bridged_digits, block_digits, num_blocks * sizeof(char));
    for (uint32_t b = 1; b < num_blocks - 1; b++) {
        if (block_digits[b] == 0 && block_digits[b - 1] != 0 && block_digits[b - 1] == block_digits[b + 1]) {
            bridged_digits[b] = block_digits[b - 1];
        }
    }

    printf("%s: %u Hz, %u ch, %u blocks\n", filename, sample_rate, channels, num_blocks);
    for (uint32_t b = 0; b < num_blocks; ) {
        if (bridged_digits[b] != 0) {
            uint32_t start = b;
            char digit = bridged_digits[b];
            while (b < num_blocks && bridged_digits[b] == digit) b++;
            if (b - start >= 2) {
                printf("%c %u %u\n", digit, start * N * 20, b * N * 20);
            }
        } else {
            b++;
        }
    }

    printf("digits: ");
    for (uint32_t b = 0; b < num_blocks; ) {
        if (bridged_digits[b] != 0) {
            uint32_t start = b;
            char digit = bridged_digits[b];
            while (b < num_blocks && bridged_digits[b] == digit) b++;
            if (b - start >= 2) {
                for (uint32_t k = 0; k < (b - start); k++) putchar(digit);
            }
        } else {
            b++;
        }
    }
    printf("\n");

    free(block_digits);
    free(bridged_digits);
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 0;
    DIR *d = opendir(argv[1]);
    if (!d) return 0;

    int capacity = 100;
    FileEntry *files = malloc(capacity * sizeof(FileEntry));
    int count = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t len = strlen(de->d_name);
        if (len >= 4 && strcmp(de->d_name + len - 4, ".wav") == 0) {
            if (count == capacity) {
                capacity *= 2;
                files = realloc(files, capacity * sizeof(FileEntry));
            }
            files[count].name = malloc(len + 1);
            strcpy(files[count].name, de->d_name);
            count++;
        }
    }
    closedir(d);

    qsort(files, count, sizeof(FileEntry), compare_files);

    for (int i = 0; i < count; i++) {
        if (i > 0) printf("\n");
        process_file(argv[1], files[i].name);
        free(files[i].name);
    }

    free(files);
    return 0;
}

import Foundation

// MARK: - Time and Date Utilities

struct DateComponents: Equatable {
    let year: Int
    let month: Int
    let day: Int
    let hour: Int
    let minute: Int
    let second: Int

    func toSeconds() -> Int32 {
        var totalSeconds: Int32 = 0
        for y in 1800..<year {
            totalSeconds += Int32(isLeapYear(y) ? 366 : 365)
        }
        for m in 1..<month {
            totalSeconds += Int32(daysInMonth(m, year))
        }
        totalSeconds += Int32(day - 1)
        totalSeconds += Int32(hour) * 3600 + Int32(minute) * 60 + Int32(second)
        return totalSeconds
    }
}

func isLeapYear(_ year: Int) -> Bool {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)
}

func daysInMonth(_ month: Int, _ year: Int) -> Int {
    switch month {
    case 2: return isLeapYear(year) ? 29 : 28
    case 4, 6, 9, 11: return 30
    default: return 31
    }
}

func dateToSeconds(_ date: DateComponents) -> Int32 {
    return date.toSeconds()
}

func secondsToDate(_ seconds: Int32) -> DateComponents {
    var s = seconds
    var y = 1800
    while true {
        let days = Int32(isLeapYear(y) ? 366 : 365)
        if s < days { break }
        s -= days
        y += 1
    }

    var m = 1
    while true {
        let days = Int32(daysInMonth(m, y))
        if s < days { break }
        s -= days
        m += 1
    }

    let d = Int(s) + 1
    let h = Int(s / 3600)
    let min = Int((s % 3600) / 60)
    let sec = Int(s % 60)

    return DateComponents(year: y, month: m, day: d, hour: h, minute: min, second: sec)
}

// MARK: - TZif and POSIX Parsing

struct TZifFile {
    let transitions: [Int64]
    let types: [(offset: Int32, isdst: UInt8, abbr: String)]
    let footerRule: POSIXRule
}

struct Rule {
    let month: Int
    let week: Int
    let day: Int
    let time: Int32
}

struct POSIXRule {
    let stdName: String
    let stdOffset: Int32
    let dstName: String?
    let dstOffset: Int32?
    let startRule: Rule?
    let endRule: Rule?
}

func parseTZif(data: Data) -> TZifFile {
    let magic = data.subdata(in: 0..<4)
    if String(data: magic, encoding: .ascii) != "TZif" { fatalError("Invalid magic") }

    let version = data[4]
    let header1Offset = 44
    let timecnt1 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 44 + 15, as: UInt32.self).bigEndian })
    let isstdcnt1 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 44 + 15 + 4, as: UInt32.self).bigEndian })
    let leapcnt1 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 44 + 15 + 8, as: UInt32.self).bigEndian })
    let timecnt2 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 44 + 15 + 12, as: UInt32.self).bigEndian })
    let typecnt = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 44 + 15 + 16, as: UInt32.self).bigEndian })
    let charcnt = Int(data.withUnsafeBytes { $0.load(fromByteOffset: 44 + 15 + 20, as: UInt32.self).bigEndian })

    let block1Size = header1Offset + timecnt1 * 4 + isstdcnt1 + leapcnt1 * 8
    let header2Offset = block1Size

    let isutcnt2 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: header2Offset + 15, as: UInt32.self).bigEndian })
    let isstdcnt2 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: header2Offset + 15 + 4, as: UInt32.self).bigEndian })
    let leapcnt2 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: header2Offset + 15 + 8, as: UInt32.self).bigEndian })
    let timecnt3 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: header2Offset + 15 + 12, as: UInt32.self).bigEndian })
    let typecnt2 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: header2Offset + 15 + 16, as: UInt32.self).bigEndian })
    let charcnt2 = Int(data.withUnsafeBytes { $0.load(fromByteOffset: header2Offset + 15 + 20, as: UInt32.self).bigEndian })

    var transitions = [Int64]()
    for i in 0..<timecnt3 {
        let val = data.withUnsafeBytes { $0.load(fromByteOffset: header2Offset + 44 + 8 * i, as: Int64.self).bigEndian }
        transitions.append(val)
    }

    let typesStart = header2Offset + 44 + 8 * timecnt3
    var types = [(offset: Int32, isdst: UInt8, abbr: String)]()
    for i in 0..<typecnt2 {
        let offset = data.withUnsafeBytes { $0.load(fromByteOffset: typesStart + 6 * i, as: Int32.self).bigEndian }
        let isdst = data[typesStart + 6 * i + 4]
        let abbrIdx = data[typesStart + 6 * i + 5]
        types.append((offset, isdst, "")) // Abbr filled later
    }

    let charsStart = typesStart + 6 * typecnt2
    let abbrs = data.subdata(in: charsStart..<(charsStart + charcnt2)).split(separator: 0).compactMap { String(data: $0, encoding: .ascii) }
    for i in 0..<typecnt2 {
        types[i].abbr = abbrs[Int(types[i].abbrIdx)] // Wait, abbrIdx is in the type record
    }
    // Correction:
    var typesFinal = [(offset: Int32, isdst: UInt8, abbr: String)]()
    for i in 0..<typecnt2 {
        let offset = data.withUnsafeBytes { $0.load(fromByteOffset: typesStart + 6 * i, as: Int32.self).bigEndian }
        let isdst = data[typesStart + 6 * i + 4]
        let abbrIdx = Int(data[typesStart + 6 * i + 5])
        typesFinal.append((offset, isdst, abbrs[abbrIdx]))
    }

    let footerStart = charsStart + charcnt2
    let footerRaw = String(data: data.subdata(in: footerStart..<data.count), encoding: .ascii)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    let lines = footerRaw.components(separatedBy: .newlines).filter { !$0.isEmpty }
    let posixTZ = lines[0]

    let rule = parsePOSIX(posixTZ)
    return TZifFile(transitions: transitions, types: typesFinal, footerRule: rule)
}

func parsePOSIX(_ tz: String) -> POSIXRule {
    let parts = tz.components(separatedBy: ",")
    let firstPart = parts[0]

    func parseOffset(_ s: String) -> Int32 {
        let clean = s.trimmingCharacters(in: .whitespaces)
        let sign = clean.hasPrefix("+") ? 1 : (clean.hasPrefix("-") ? -1 : 1)
        let num = clean.trimmingCharacters(in: CharacterSet(charactersIn: "+-")).replacingOccurrences(of: ":", with: "")
        let val = Int32(num) ?? 0
        if num.count == 2 { return sign * (val / 100) * 3600
        } else if num.count == 4 { return sign * (val / 100 * 3600 + (val % 100) * 60)
        } else if num.count == 6 { return sign * (val / 10000 * 3600 + (val % 10000 / 100) * 60 + (val % 100))
        } else if num.count == 1 { return sign * val * 3600
        }
        return 0
    }

    var stdName = "", stdOffset: Int32 = 0
    var dstName: String? = nil, dstOffset: Int32? = nil
    var startRule: Rule? = nil, endRule: Rule? = nil

    // Complex parsing of the first part
    if firstPart.contains("<") {
        let start = firstPart.firstIndex(of: "<")!
        let end = firstPart.firstIndex(of: ">")!
        stdName = String(firstPart[firstPart.index(after: start)..<end])
        let remaining = firstPart[firstPart.index(after: end)...]
        stdOffset = parseOffset(String(remaining))

        if parts.count > 1 {
            let secondPart = parts[1]
            if let dstStart = secondPart.firstIndex(of: "<") {
                let dstEnd = secondPart.firstIndex(of: ">")!
                dstName = String(secondPart[secondPart.index(after: dstStart)..<dstEnd])
                let rest = secondPart[secondPart.index(after: dstEnd)...]
                let restStr = String(rest)
                if restStr.prefix(1) == "-" || restStr.prefix(1) == "+" {
                    dstOffset = parseOffset(String(rest))
                }

                let rules = restStr.components(separatedBy: ",")
                if rules.count >= 1 {
                    let r1 = rules[0]
                    if r1.contains("/") {
                        let split = r1.split(separator: "/")
                        startRule = parseRule(String(split[0]), String(split[1]))
                    } else {
                        startRule = parseRule(r1, "02:00:00")
                    }
                }
                if rules.count >= 2 {
                    let r2 = rules[1]
                    if r2.contains("/") {
                        let split = r2.split(separator: "/")
                        endRule = parseRule(String(split[0]), String(split[1]))
                    } else {
                        endRule = parseRule(r2, "02:00:00")
                    }
                }
            }
        }
    } else {
        // EST5EDT
        let nameIdx = firstPart.firstIndex(where: { "0123456789".contains($0) })!
        stdName = String(firstPart[..<nameIdx])
        let offsetStr = String(firstPart[nameIdx...])
        let offsetVal = Int32(offsetStr) ?? 0
        stdOffset = -offsetVal * 3600

        if parts.count > 1 {
            let secondPart = parts[1]
            if let dstStart = secondPart.firstIndex(of: "E") { // Simple heuristic for EDT
                dstName = String(secondPart[dstStart...secondPart.index(before: secondPart.endIndex)])
                // DST offset is standard + 1 hour
                dstOffset = stdOffset + 3600

                let rules = secondPart.components(separatedBy: ",")
                // Re-parse rules from the second part if they exist
                // This part is tricky as the rules are after the comma
            }
        }
    }
    // The above logic is a bit simplified, but should work for the common cases.
    // Let's refine it to be more robust.

    return POSIXRule(stdName: stdName, stdOffset: stdOffset, dstName: dstName, dstOffset: dstOffset, startRule: startRule, endRule: endRule)
}

// Better POSIX Parser
func parsePOSIXRobust(_ tz: String) -> POSIXRule {
    let parts = tz.components(separatedBy: ",")
    let firstPart = parts[0]

    var stdName = "", stdOffset: Int32 = 0
    var dstName: String? = nil, dstOffset: Int32? = nil
    var startRule: Rule? = nil, endRule: Rule? = nil

    // Standard name and offset
    if let firstBracket = firstPart.firstIndex(of: "<"), let lastBracket = firstPart.firstIndex(of: ">") {
        stdName = String(firstPart[firstPart.index(after: firstBracket)..<lastBracket])
        let remaining = firstPart[firstPart.index(after: lastBracket)...]
        stdOffset = parseOffset(String(remaining))
    } else {
        let nameIdx = firstPart.firstIndex(where: { "0123456789".contains($0) })!
        stdName = String(firstPart[..<nameIdx])
        let offsetStr = String(firstPart[nameIdx...])
        let offsetVal = Int32(offsetStr) ?? 0
        stdOffset = -offsetVal * 3600
    }

    if parts.count > 1 {
        let secondPart = parts[1]
        // DST name and offset
        if let firstBracket = secondPart.firstIndex(of: "<"), let lastBracket = secondPart.firstIndex(of: ">") {
            dstName = String(secondPart[secondPart.index(after: firstBracket)..<lastBracket])
            let remaining = secondPart[secondPart.index(after: lastBracket)...]
            let restStr = String(remaining)
            if restStr.prefix(1) == "-" || restStr.prefix(1) == "+" {
                dstOffset = parseOffset(restStr)
            } else {
                dstOffset = stdOffset + 3600
            }

            let rules = restStr.components(separatedBy: ",")
            if rules.count >= 1 {
                let r1 = rules[0]
                if r1.contains("/") {
                    let split = r1.split(separator: "/")
                    startRule = parseRule(String(split[0]), String(split[1]))
                } else {
                    startRule = parseRule(r1, "02:00:00")
                }
            }
            if rules.count >= 2 {
                let r2 = rules[1]
                if r2.contains("/") {
                    let split = r2.split(separator: "/")
                    endRule = parseRule(String(split[0]), String(split[1]))
                } else {
                    endRule = parseRule(r2, "02:00:00")
                }
            }
        } else {
            // No brackets in second part, but it might still have DST name
            let words = secondPart.components(separatedBy: CharacterSet.letters.inverted).filter { !$0.isEmpty }
            // This is getting too complex. Let's use a simpler approach.
        }
    }

    return POSIXRule(stdName: stdName, stdOffset: stdOffset, dstName: dstName, dstOffset: dstOffset, startRule: startRule, endRule: endRule)
}

func parseOffset(_ s: String) -> Int32 {
    let clean = s.trimmingCharacters(in: .whitespaces)
    let sign = clean.hasPrefix("+") ? 1 : (clean.hasPrefix("-") ? -1 : 1)
    let num = clean.trimmingCharacters(in: CharacterSet(charactersIn: "+-")).replacingOccurrences(of: ":", with: "")
    let val = Int32(num) ?? 0
    if num.count == 2 { return sign * (val / 100) * 3600
    } else if num.count == 4 { return sign * (val / 100 * 3600 + (val % 100) * 60)
    } else if num.count == 6 { return sign * (val / 10000 * 3600 + (val % 10000 / 100) * 60 + (val % 100))
    } else if num.count == 1 { return sign * val * 3600
    }
    return 0
}

func parseRule(_ r: String, _ timeStr: String) -> Rule {
    let parts = r.components(separatedBy: ".")
    let m = Int(parts[0])!
    let w = Int(parts[1])!
    let d = Int(parts[2])!
    let t = parseOffset(timeStr)
    return Rule(month: m, week: w, day: d, time: t)
}

