// Real conversion logic
func getLocalTime(utc: Int64, tz: TZifFile) -> (DateComponents, Int32, String) {
    var offset: Int32 = 0
    var abbr = ""

    if !tz.transitions.isEmpty && utc >= tz.transitions[0] && utc <= tz.transitions.last! {
        var idx = 0
        for i in 0..<tz.transitions.count {
            if utc >= tz.transitions[i] {
                idx = i
            }
        }
        let type = tz.types[idx]
        offset = type.offset
        abbr = type.abbr
    } else if !tz.transitions.isEmpty && utc < tz.transitions[0] {
        offset = tz.types[0].offset
        abbr = tz.types[0].abbr
    } else {
        // Footer rule
        // Find year
        var y = 1800
        var currentUTC = utc
        while true {
            let d = Int32(isLeapYear(y) ? 366 : 365)
            if currentUTC < Int64(d) { break }
            currentUTC -= Int64(d)
            y += 1
        }

        let rule = tz.footerRule
        let stdOff = rule.stdOffset
        let dstOff = rule.dstOffset ?? stdOff + 3600

        var startUTC: Int64 = 0
        var endUTC: Int64 = 0

        if let start = rule.startRule, let end = rule.endRule {
            let sDate = DateComponents(year: y, month: start.month, day: start.day, hour: Int(start.time / 3600), minute: Int((start.time % 3600) / 60), second: Int(start.time % 60))
            let eDate = DateComponents(year: y, month: end.month, day: end.day, hour: Int(end.time / 3600), minute: Int((end.time % 3600) / 60), second: Int(end.time % 60))

            startUTC = Int64(dateToSeconds(sDate)) + Int64(stdOff)
            endUTC = Int64(dateToSeconds(eDate)) + Int64(dstOff)

            if startUTC < endUTC {
                if utc >= startUTC && utc < endUTC {
                    offset = dstOff
                    abbr = rule.dstName ?? ""
                } else {
                    offset = stdOff
                    abbr = rule.stdName
                }
            } else {
                if utc >= endUTC && utc < startUTC {
                    offset = dstOff
                    abbr = rule.dstName ?? ""
                } else {
                    offset = stdOff
                    abbr = rule.stdName
                }
            }
        } else {
            offset = stdOff
            abbr = rule.stdName
        }
    }

    let localSecs = Int32(utc) - offset
    let localComp = secondsToDate(localSecs)
    return (localComp, offset, abbr)
}

