import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;

public class Main {
    private static boolean closeSent = false;

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            try {
                handleSession(args[i]);
            } catch (Exception e) {
                // Session ended or failed
            }
            closeSent = false;
        }
    }

    private static void handleSession(String url) throws Exception {
        int schemeEnd = url.indexOf("://");
        int pathStart = url.indexOf("/", schemeEnd + 3);
        if (pathStart == -1) pathStart = url.length();
        String hostPort = url.substring(schemeEnd + 3, pathStart);
        String path = url.substring(pathStart);

        String[] hostParts = hostPort.split(":");
        String host = hostParts[0];
        int port = Integer.parseInt(hostParts[1]);

        Socket socket = new Socket(host, port);
        InputStream in = socket.getInputStream();
        OutputStream out = socket.getOutputStream();

        // Handshake
        byte[] keyBytes = new byte[16];
        new SecureRandom().nextBytes(keyBytes);
        String key = Base64.getEncoder().encodeToString(keyBytes);

        PrintWriter writer = new PrintWriter(new OutputStreamWriter(out, StandardCharsets.UTF_8));
        writer.print("GET " + path + " HTTP/1.1\r\n");
        writer.print("Host: " + hostPort + "\r\n");
        writer.print("Upgrade: websocket\r\n");
        writer.print("Connection: Upgrade\r\n");
        writer.print("Sec-WebSocket-Version: 13\r\n");
        writer.print("Sec-WebSocket-Key: " + key + "\r\n");
        writer.print("\r\n");
        writer.flush();

        ByteArrayOutputStream response = new ByteArrayOutputStream();
        byte[] buf = new byte[1024];
        int bytesRead;
        byte[] remainingBytes = null;
        while ((bytesRead = in.read(buf)) != -1) {
            response.write(buf, 0, bytesRead);
            byte[] current = response.toByteArray();
            int pos = -1;
            for (int i = 0; i < current.length - 3; i++) {
                if (current[i] == '\r' && current[i+1] == '\n' && current[i+2] == '\r' && current[i+3] == '\n') {
                    pos = i;
                    break;
                }
            }
            if (pos != -1) {
                remainingBytes = new byte[current.length - (pos + 4)];
                System.arraycopy(current, pos + 4, remainingBytes, 0, remainingBytes.length);
                break;
            }
        }

        String fullResponse = response.toString(StandardCharsets.UTF_8);
        String[] lines = fullResponse.split("\r\n");
        String statusLine = lines[0];
        int firstSpace = statusLine.indexOf(' ');
        int secondSpace = statusLine.indexOf(' ', firstSpace + 1);
        String statusInfo = statusLine.substring(firstSpace + 1);

        if (!statusInfo.startsWith("101")) {
            System.out.println("handshake failed: " + statusInfo);
            socket.close();
            return;
        }

        String accept = "";
        for (int i = 1; i < lines.length; i++) {
            if (lines[i].toLowerCase().startsWith("sec-websocket-accept:")) {
                accept = lines[i].substring(lines[i].indexOf(":") + 1).trim();
                break;
            }
        }

        MessageDigest md = MessageDigest.getInstance("SHA-1");
        md.update(keyBytes);
        md.update("258EAFA5-E914-47DA-95CA-C5AB0DC85B11".getBytes(StandardCharsets.UTF_8));
        String expectedAccept = Base64.getEncoder().encodeToString(md.digest());

        if (!expectedAccept.equals(accept)) {
            System.out.println("handshake failed: bad Sec-WebSocket-Accept");
            socket.close();
            return;
        }

        InputStream frameIn = new MultiInputStream(new ByteArrayInputStream(remainingBytes), in);

        ByteArrayOutputStream messageBuffer = new ByteArrayOutputStream();
        int currentOpcode = -1;

        while (true) {
            Frame frame = readFrame(frameIn);
            if (frame == null) break;

            if (frame.opcode == 9) {
                sendFrame(out, 10, frame.payload);
            } else if (frame.opcode == 10) {
                // Pong
            } else if (frame.opcode == 8) {
                handleClose(frame, out);
                break;
            } else {
                if (currentOpcode == -1) currentOpcode = frame.opcode;
                messageBuffer.write(frame.payload);
                if (frame.fin) {
                    if (currentOpcode == 1) {
                        String text = new String(messageBuffer.toByteArray(), StandardCharsets.UTF_8);
                        handleCommand(text, out, frameIn);
                    } else if (currentOpcode == 2) {
                        // Binary message - only happens after SHA1
                    }
                    messageBuffer.reset();
                    currentOpcode = -1;
                }
            }
        }
        socket.close();
    }

    private static void handleCommand(String text, OutputStream out, InputStream in) throws Exception {
        if (text.startsWith("ADD ")) {
            String[] parts = text.split(" ");
            long a = Long.parseLong(parts[1]);
            long b = Long.parseLong(parts[2]);
            long sum = a + b;
            sendFrame(out, 1, String.valueOf(sum).getBytes(StandardCharsets.UTF_8));
            System.out.println("ADD " + parts[1] + " " + parts[2] + " -> " + sum);
        } else if (text.startsWith("REV ")) {
            String content = text.substring(4);
            String reversed = reverseCodePoints(content);
            sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8));
            System.out.println("REV " + content + " -> " + reversed);
        } else if (text.equals("SHA1")) {
            ByteArrayOutputStream binBuffer = new ByteArrayOutputStream();
            int binOpcode = -1;
            while (true) {
                Frame f = readFrame(in);
                if (f == null) break;
                if (f.opcode == 9) {
                    sendFrame(out, 10, f.payload);
                } else if (f.opcode == 10) {
                    // ignore
                } else if (f.opcode == 8) {
                    handleClose(f, out);
                    throw new RuntimeException("Session closed");
                } else {
                    if (binOpcode == -1) binOpcode = f.opcode;
                    binBuffer.write(f.payload);
                    if (f.fin) {
                        byte[] data = binBuffer.toByteArray();
                        String hex = calculateSHA1(data);
                        sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8));
                        System.out.println("SHA1 " + data.length + " -> " + hex);
                        break;
                    }
                }
            }
        } else if (text.equals("BYE")) {
            sendFrame(out, 8, new byte[]{0x03, (byte) 0xE8});
            closeSent = true;
            while (true) {
                Frame f = readFrame(in);
                if (f == null) break;
                if (f.opcode == 9) {
                    sendFrame(out, 10, f.payload);
                } else if (f.opcode == 10) {
                    // ignore
                } else if (f.opcode == 8) {
                    handleClose(f, out);
                    break;
                }
            }
            throw new RuntimeException("Session closed");
        }
    }

    private static void handleClose(Frame f, OutputStream out) throws IOException {
        int code = ((f.payload[0] & 0xFF) << 8) | (f.payload[1] & 0xFF);
        String reason = "";
        if (f.payload.length > 2) {
            reason = new String(f.payload, 2, f.payload.length - 2, StandardCharsets.UTF_8);
        }
        System.out.println("closed " + code + (reason.isEmpty() ? "" : " " + reason));
        if (!closeSent) {
            sendFrame(out, 8, new byte[]{ (byte) (code >> 8), (byte) (code & 0xFF) });
            closeSent = true;
        }
        throw new RuntimeException("Session closed");
    }

    private static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        out.write(0x80 | (opcode & 0x0F));
        if (payload.length <= 125) {
            out.write(payload.length);
        } else if (payload.length <= 65535) {
            out.write(126);
            out.write((payload.length >> 8) & 0xFF);
            out.write(payload.length & 0xFF);
        } else {
            out.write(127);
            byte[] b = new byte[8];
            for (int i = 7; i >= 0; i--) {
                b[i] = (byte) (payload.length >> (8 * (7 - i)));
            }
            out.write(b);
        }
        byte[] mask = new byte[4];
        new SecureRandom().nextBytes(mask);
        out.write(mask);
        byte[] masked = new byte[payload.length];
        for (int i = 0; i < payload.length; i++) {
            masked[i] = (byte) (payload[i] ^ mask[i % 4]);
        }
        out.write(masked);
        out.flush();
    }

    private static Frame readFrame(InputStream in) throws IOException {
        int b1 = in.read();
        int b2 = in.read();
        if (b1 == -1 || b2 == -1) return null;
        Frame f = new Frame();
        f.fin = (b1 & 0x80) != 0;
        f.opcode = b1 & 0x0F;
        int len = b2 & 0x7F;
        if (len == 126) {
            f.payloadLength = (in.read() << 8) | in.read();
        } else if (len == 127) {
            f.payloadLength = 0;
            for (int i = 0; i < 8; i++) {
                f.payloadLength = (f.payloadLength << 8) | (in.read() & 0xFF);
            }
        } else {
            f.payloadLength = len;
        }
        byte[] skip = new byte[4];
        readFully(in, skip);
        f.payload = new byte[(int) f.payloadLength];
        readFully(in, f.payload);
        return f;
    }

    private static void readFully(InputStream in, byte[] b) throws IOException {
        int totalRead = 0;
        while (totalRead < b.length) {
            int read = in.read(b, totalRead, b.length - totalRead);
            if (read == -1) throw new IOException("Stream closed");
            totalRead += read;
        }
    }

    private static String calculateSHA1(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] digest = md.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static String reverseCodePoints(String text) {
        int[] codePoints = text.codePoints().toArray();
        for (int i = 0; i < codePoints.length / 2; i++) {
            int temp = codePoints[i];
            codePoints[i] = codePoints[codePoints.length - 1 - i];
            codePoints[codePoints.length - 1 - i] = temp;
        }
        return new String(codePoints, 0, codePoints.length);
    }

    static class Frame {
        boolean fin;
        int opcode;
        long payloadLength;
        byte[] payload;
    }

    static class MultiInputStream extends InputStream {
        private final InputStream first;
        private final InputStream second;
        private final byte[] firstBuffer;
        private int firstBufferPtr = 0;

        public MultiInputStream(InputStream first, InputStream second, byte[] firstBuffer) {
            this.first = first;
            this.second = second;
            this.firstBuffer = firstBuffer;
        }

        @Override
        public int read() throws IOException {
            if (firstBufferPtr < firstBuffer.length) {
                return firstBuffer[firstBufferPtr++] & 0xFF;
            } else {
                return first.read();
            }
        }

        @Override
        public int read(byte[] b, int off, int len) throws IOException {
            if (firstBufferPtr < firstBuffer.length) {
                int available = firstBuffer.length - firstBufferPtr;
                int toRead = Math.min(available, len);
                System.arraycopy(firstBuffer, firstBufferPtr, b, off, toRead);
                firstBufferPtr += toRead;
                return toRead;
            } else {
                return second.read(b, off, len);
            }
        }
    }
}

