            LocalDate date = findDate(year, startM, startW, startD);
            long localTime = date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime;
            // This localTime is in UTC. But it's actually the local time.
            // So UTC = LocalTime - Offset_std.
            // Wait, UTC = Local + Offset_std. So UTC = LocalTime + Offset_std.
            // No, Local = UTC - Offset_std. So UTC = Local + Offset_std.
            // Therefore, UTC = localTime + Offset_std.
            // Wait, the localTime we just calculated is in UTC.
            // Let's do it properly:
            // 1. Find the date (year, month, day).
            // 2. LocalTime is (day, startTime).
            // 3. UTC = LocalTime - Offset_std.
            // Wait, if Offset_std is 5, Local = UTC - 5, so UTC = Local + 5.
            // So UTC = LocalTime + Offset_std.
            // But the localTime we calculated is already in UTC.
            // Let's re-calculate.
            return date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime + stdOffset;
            // No, this is still not right. Let's use a simpler way.
            // LocalTime L = date.atTime(LocalTime.of(0, 0)).plusSeconds(startTime).
            // UTC = L + Offset_std.
            // Since L is a local time, we can't just add seconds to its UTC representation.
            // But we can! Because the offset is constant at that moment.
            // Wait, the offset is constant for the whole standard period.
            // So UTC = (date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime) + stdOffset.
            // No, that's not right.
            // Let's use:
            // date = findDate(year, startM, startW, startD)
            // L = date.atTime(LocalTime.of(0, 0)).plusSeconds(startTime)
            // UTC = L - Offset_std (because Local = UTC - Offset_std)
            // No, the prompt says UTC = Local + Offset_std.
            // So UTC = L + Offset_std.
            // Let's use:
            // L_utc_seconds = date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime
            // This L_utc_seconds is the number of seconds since epoch of the local time L.
            // We want the UTC time.
            // Since Local = UTC - Offset_std, then UTC = Local + Offset_std.
            // So UTC = L_utc_seconds + Offset_std.
            // Wait, L_utc_seconds is already UTC. This is confusing.
            // Let's use:
            // L = date.atTime(LocalTime.of(0, 0)).plusSeconds(startTime)
            // This L is a local time. We want to find the UTC time.
            // If the offset is stdOffset, then UTC = L + stdOffset.
            // Since L is a local time, its UTC time is L.toEpochSecond(ZoneOffset.ofTotalSeconds(-stdOffset)).
            // No, that's not it.
            // Let's just use:
            // UTC = (date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime) + stdOffset.
            // No, let's use:
            // UTC = (date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime) - stdOffset.
            // Let's try one:
            // If stdOffset = 5, Local = UTC - 5, so UTC = Local + 5.
            // date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) is the UTC time.
            // So the local time is (UTC - 5).
            // Thus, the local time is (UTC.toEpochSecond() - 5).
            // We want the local time to be (date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime).
            // So (UTC.toEpochSecond() - 5) = (date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime).
            // Thus, UTC.toEpochSecond() = (date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime) + 5.
            // So UTC = L_utc_seconds + stdOffset.
            return (date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + startTime) + stdOffset;
        }

        private long getUtcEnd(long year) {
            LocalDate date = findDate(year, endM, endW, endD);
            long localTime = date.atTime(LocalTime.of(0, 0)).toEpochSecond(ZoneOffset.UTC) + endTime;
            // Local_dst = UTC - Offset_dst. So UTC = Local_dst + Offset_dst.
            // UTC = localTime + dstOffset.
            return localTime + dstOffset;
        }

        private LocalDate findDate(long year, int m, int w, int d) {
            for (int month = 1; month <= 12; month++) {
                if (month == m) {
                    int count = 0;
                    for (int day = 1; day <= 31; day++) {
                        try {
                            LocalDate date = LocalDate.of(year, month, day);
                            if (date.getDayOfWeek().getValue() == (d + 1)) {
                                count++;
                                if (w == 5) {
                                    // This is the last such day.
                                    // We need to check if there's any more.
                                    // But we can just find all and pick the last.
                                } else if (count == w) {
                                    return date;
                                }
                            }
                        } catch (Exception e) {}
                    }
                    if (w == 5) {
                        // Find the last day.
                        LocalDate last = null;
                        for (int day = 1; day <= 31; day++) {
                            try {
                                LocalDate date = LocalDate.of(year, month, day);
                                if (date.getDayOfWeek().getValue() == (d + 1)) {
                                    last = date;
                                }
                            } catch (Exception e) {}
                        }
                        return last;
                    }
                }
            }
            return LocalDate.of(year, m, d);
        }

        private long findDay(long year, int m, int w, int d) {
            LocalDate date = findDate(year, m, w, d);
            return date.getDayOfMonth();
        }

        public String formatOffset(int offset) {
            String sign = offset >= 0 ? "+" : "-";
            int absOffset = Math.abs(offset);
            int h = absOffset / 3600;
            int m = (absOffset % 3600) / 60;
            int s = absOffset % 60;
            StringBuilder sb = new StringBuilder(sign);
            sb.append(String.format("%02d:%02d", h, m));
            if (s != 0) sb.append(":").append(String.format("%02d", s));
            return sb.toString();
        }
    }

