                    long t_std = ldt.toEpochSecond(ZoneOffset.UTC) + tz.stdOffset;
                    long t_dst = ldt.toEpochSecond(ZoneOffset.UTC) + tz.dstOffset;

                    if (t_std < us || t_std >= ue) {
                        solutions.add(t_std);
                    }
                    if (t_dst >= us && t_dst < ue) {
                        solutions.add(t_dst);
                    }
                }
                Collections.sort(solutions);
                List<Long> uniqueSolutions = new ArrayList<>();
                if (!solutions.isEmpty()) {
                    uniqueSolutions.add(solutions.get(0));
                    for (int i = 1; i < solutions.size(); i++) {
                        if (!solutions.get(i).equals(solutions.get(i - 1))) {
                            uniqueSolutions.add(solutions.get(i));
