                    long t2 = uniqueSolutions.get(1);
                    String res1 = tz.convertUtc(t1);
                    String res2 = tz.convertUtc(t2);
                    String[] parts1 = res1.split(" ");
                    String[] parts2 = res2.split(" ");
                    int split1 = parts1[1].lastIndexOf('+');
                    int split1m = parts1[1].lastIndexOf('-');
                    int split1_idx = Math.max(split1, split1m);
                    String offset1 = parts1[1].substring(0, split1_idx);
                    String abbr1 = parts1[1].substring(split1_idx);
                    int split2 = parts2[1].lastIndexOf('+');
                    int split2m = parts2[1].lastIndexOf('-');
                    int split2_idx = Math.max(split2, split2m);
                    String offset2 = parts2[1].substring(0, split2_idx);
                    String abbr2 = parts2[1].substring(split2_idx);
                    System.out.println(line + " -> " + t1 + " " + offset1 + " " + abbr1 + " | " + t2 + " " + offset2 + " " + abbr2);
                } else {
                    long t = ldt.toEpochSecond(ZoneOffset.UTC) + tz.stdOffset;
                    // Wait, the gap t is L - Offset_std.
                    // But I need to find the correct Offset_std.
