                    long gapT = ldt.toEpochSecond(ZoneOffset.UTC) - tz.stdOffset;
                    // Wait, let's try both.
                    long t_gap1 = ldt.toEpochSecond(ZoneOffset.UTC) + tz.stdOffset;
                    long t_gap2 = ldt.toEpochSecond(ZoneOffset.UTC) - tz.stdOffset;
                    // Actually, let's just use the one that's not a solution.
