                    long finalT = t_gap1;
                    // Check if t_gap1 is a solution.
                    boolean isSol1 = false;
                    for (long sol : uniqueSolutions) if (sol == t_gap1) isSol1 = true;
                    if (isSol1) finalT = t_gap2;

                    String result = tz.convertUtc(finalT);
