use std::collections::HashMap;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

#[derive(Debug, Clone)]
struct TypeRecord {
    offset: i32,
    isdst: u8,
    abbr_idx: u8,
}

struct TZif {
    transitions: Vec<i64>,
    types: Vec<TypeRecord>,
    abbreviations: Vec<String>,
    std_offset: i32,
    dst_offset: Option<i32>,
    start_rule: Option<Rule>,
    end_rule: Option<Rule>,
    last_transition: i64,
}

#[derive(Clone, Copy)]
struct Rule {
    month: u32,
    week: u32,
    day: u32,
    time_offset: i32,
}

fn is_leap(y: i32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

fn days_in_month(m: u32, y: i32) -> u32 {
    match m {
        2 => if is_leap(y) { 29 } else { 28 },
        4 | 6 | 9 | 11 => 30,
        _ => 31,
    }
}

fn date_to_seconds(y: i32, m: u32, d: u32) -> i64 {
    let mut seconds = 0i64;
    for year in 1800..y {
        seconds += if is_leap(year) { 366 } else { 365 };
    }
    for month in 1..m {
        seconds += days_in_month(month as u32, y) as i64;
    }
    seconds += d as i64;
    seconds * 86400
}

fn get_date_from_rule(rule: &Rule, y: i32) -> (u32, u32, u32) {
    let m = rule.month;
    let d_base = rule.day;
    let w = rule.week;
    let mut day;
    if w < 5 {
        let first_day_of_month = 1;
        let first_d_day = if (first_day_of_month + d_base - 1) % 7 == 0 {
            first_day_of_month
        } else {
            first_day_of_month + (7 - (first_day_of_month + d_base - 1) % 7) % 7
        };
        day = first_d_day + (w - 1) * 7;
    } else {
        let last_day = days_in_month(m, y);
        day = if (last_day + d_base - 1) % 7 == 0 {
            last_day
        } else {
            last_day - (last_day + d_base - 1) % 7
        };
    }
    (m, day, day)
}

fn parse_offset(s: &str) -> i32 {
    let s = s.trim_matches(|c| c == '<' || c == '>');
    let mut sign = 1;
    let mut s = s.to_string();
    if s.starts_with('+') {
        s.remove(0);
    } else if s.starts_with('-') {
        sign = -1;
        s.remove(0);
    }
    let parts: Vec<&str> = s.split(':').collect();
    let mut total = 0;
    if !parts.is_empty() {
        total += parts[0].parse::<i32>().unwrap_or(0) * 3600;
    }
    if parts.len() > 1 {
        total += parts[1].parse::<i32>().unwrap_or(0) * 60;
    }
    if parts.len() > 2 {
        total += parts[2].parse::<i32>().unwrap_or(0);
    }
    total * sign
}

fn parse_rule(s: &str) -> Option<Rule> {
    if s.is_empty() { return None; }
    let parts: Vec<&str> = s.split(|c| c == '.' || c == '/').collect();
    let m = parts[0].parse::<u32>().ok()?;
    let w = parts[1].parse::<u32>().ok()?;
    let d = parts[2].parse::<u32>().ok()?;
    let mut time_offset = 0;
    if parts.len() > 3 {
        let t_str = parts[3];
        let mut sign = 1;
        let mut t_str = t_str.to_string();
        if t_str.starts_with('+') {
            t_str.remove(0);
        } else if t_str.starts_with('-') {
            sign = -1;
            t_str.remove(0);
        }
        let t_parts: Vec<&str> = t_str.split(':').collect();
        let mut total = 0;
        if !t_parts.is_empty() {
            total += t_parts[0].parse::<i32>().unwrap_or(0) * 3600;
        }
        if t_parts.len() > 1 {
            total += t_parts[1].parse::<i32>().unwrap_or(0) * 60;
        }
        if t_parts.len() > 2 {
            total += t_parts[2].parse::<i32>().unwrap_or(0);
        }
        time_offset = total * sign;
    }
    Some(Rule { month: m, week: w, day: d, time_offset })
}

fn load_tzif(path: &Path) -> TZif {
    let mut file = File::open(path).unwrap();
    let mut buf = Vec::new();
    std::io::Read::read_to_end(&mut file, &mut buf).unwrap();

    let mut cursor = 0;
    let mut header = &buf[cursor..cursor+44];
    cursor += 44;
    let timecnt = i32::from_be_bytes(header[32..36].try_into().unwrap()) as usize;
    let typecnt = i32::from_be_bytes(header[36..40].try_into().unwrap()) as usize;
    let charcnt = i32::from_be_bytes(header[40..44].try_into().unwrap()) as usize;

    let _block1_start = cursor;
    cursor += timecnt * 4;
    let block2_start = cursor;
    cursor += timecnt * 8;
    let types_start = cursor;
    cursor += timecnt;
    let type_records_start = cursor;
    cursor += typecnt * 6;
    let chars_start = cursor;
    cursor += charcnt;
    let leap_start = cursor;
    let leapcnt = i32::from_be_bytes(header[16..20].try_into().unwrap()) as usize;
    cursor += leapcnt * 12;
    let footer_start = cursor;

    let mut transitions = Vec::new();
    for i in 0..timecnt {
        transitions.push(i64::from_be_bytes(buf[block2_start + i*8 .. block2_start + i*8 + 8].try_into().unwrap()));
    }

    let mut types = Vec::new();
    for i in 0..typecnt {
        let offset = i32::from_be_bytes(buf[type_records_start + i*6 .. type_records_start + i*6 + 4].try_into().unwrap());
        let isdst = buf[type_records_start + i*6 + 4];
        let abbr_idx = buf[type_records_start + i*6 + 5];
        types.push(TypeRecord { offset, isdst, abbr_idx });
    }

    let mut abbreviations = Vec::new();
    for i in 0..charcnt {
        let mut s = String::new();
        let mut j = chars_start + i;
        while j < buf.len() && buf[j] != 0 {
            s.push(buf[j] as char);
            j += 1;
        }
        abbreviations.push(s);
    }

    let footer_str = String::from_utf8_lossy(&buf[footer_start..]).trim().split('\n').nth(1).unwrap().to_string();
    let parts: Vec<&str> = footer_str.split(',').collect();
    let std_part = parts[0];
    let std_offset = parse_offset(std_part);
    let mut dst_offset = None;
    if parts.len() > 1 {
        let dst_part = parts[1];
        if dst_part.contains('<') || dst_part.len() >= 3 {
            let mut s = dst_part.to_string();
            if s.starts_with('<') { s.remove(0); s.pop(); }
            if s.contains(':') || s.contains('+') || s.contains('-') {
                dst_offset = Some(parse_offset(dst_part));
            } else {
                dst_offset = Some(std_offset + 3600);
            }
        }
    }
    let start_rule = parts.get(2).and_then(|s| parse_rule(s));
    let end_rule = parts.get(3).and_then(|s| parse_rule(s));

    TZif {
        transitions,
        types,
        abbreviations,
        std_offset,
        dst_offset,
        start_rule,
        end_rule,
        last_transition: if transitions.is_empty() { i64::MIN } else { *transitions.last().unwrap() },
    }
}

