                // The above is still slightly wrong because it doesn't use the `types` array.
                // Let's fix it.
                let mut final_type_idx = 0;
                if t < tz.transitions[0] {
                    final_type_idx = 0;
                } else if t >= tz.last_transition {
                    let mut is_dst = false;
                    if let Some(dst_off) = tz.dst_offset {
                        for y_f in 1800..2400 {
                            if let (Some(start), Some(end)) = (tz.start_rule, tz.end_rule) {
                                let (sm, sd, s_day) = get_date_from_rule(&start, y_f);
                                let (em, ed, e_day) = get_date_from_rule(&end, y_f);
                                let t_start_utc = date_to_seconds(y_f, sm, s_day) + start.time_offset + tz.std_offset;
                                let t_end_utc = date_to_seconds(y_f, em, e_day) + end.time_offset + tz.dst_offset.unwrap();
                                if t_start_utc < t_end_utc {
                                    if t >= t_start_utc && t < t_end_utc { is_dst = true; break; }
                                } else {
                                    if t >= t_end_utc && t < t_start_utc { is_dst = true; break; }
                                }
                            }
                        }
                    }
                    final_type_idx = if is_dst { 1 } else { 0 };
                } else {
                    for i in 0..tz.transitions.len() {
                        if t >= tz.transitions[i] { final_type_idx = i + 1; }
                    }
                }
                // Let's just use the type record
                let final_type = &tz.types[final_type_idx % tz.types.len()];
                let final_offset = final_type.offset;
                let final_local_sec = t - final_offset;
                let (fy, fm, fd) = get_date_from_year_sec(final_local_sec);
                let fhh = ((final_local_sec % 86400 + 86400) % 86400) / 3600;
                let fmm = ((final_local_sec % 3600 + 3600) % 3600) / 60;
                let fss = (final_local_sec % 60 + 60) % 60;
                let mut f_off_str = if final_offset >= 0 { "+" } else { "-" };
                let abs_f_off = final_offset.abs();
                let f_off_hh = (abs_f_off / 3600) % 100;
                let f_off_mm = (abs_f_off % 3600) / 60;
                let f_off_ss = abs_f_off % 60;
                let mut f_final_off = format!("{}{:02}:{:02}", f_off_str, f_off_hh, f_off_mm);
                if f_off_ss != 0 { f_final_off.push_str(&format!(":{:02}", f_off_ss)); }
                println!("{} -> {} {} {}", line, format!("{}-{:02}-{:02}T{:02}:{:02}:{:02}{}", fy, fm, fd, fhh, fmm, fss, f_final_off), tz.abbreviations[final_type.abbr_idx as usize]);
                return;
            }

            let w_sec = parse_wall_time(parts[2]);
            let mut candidates = Vec::new();

            // Check transitions
            for i in 0..tz.transitions.len() {
                let t_i = tz.transitions[i];
                let o_i = tz.types[i].offset;
                let t_next = if i + 1 < tz.transitions.len() { tz.transitions[i+1] } else { i64::MAX };
                let o_next = if i + 1 < tz.transitions.len() { tz.types[i+1].offset } else { tz.std_offset };

                let l_i = t_i - o_i;
                let l_next = t_next - o_i;

                if l_i <= w_sec && w_sec < l_next {
                    candidates.push((w_sec - o_i, o_i, i + 1));
                }

                if o_i > o_next {
                    let l_gap_start = t_i - o_i;
                    let l_gap_end = t_i - o_next;
                    if w_sec >= l_gap_start && w_sec < l_gap_end {
                        println!("{} -> GAP {} {} {}", line, w_sec - o_i, format_local(w_sec - o_i, o_next, &tz), tz.abbreviations[tz.types[i+1].abbr_idx as usize]);
                        return;
                    }
                }
            }

            // Before first transition
            let o_0 = tz.types[0].offset;
            let t_0 = tz.transitions[0];
            let t_before = w_sec - o_0;
            if t_before < t_0 {
                candidates.push((t_before, o_0, 0));
            }

            // After last transition
            let mut current_offset = tz.std_offset;
            if let Some(dst_off) = tz.dst_offset {
                let mut is_dst = false;
                for y_f in 1800..2400 {
                    if let (Some(start), Some(end)) = (tz.start_rule, tz.end_rule) {
                        let (sm, sd, s_day) = get_date_from_rule(&start, y_f);
                        let (em, ed, e_day) = get_date_from_rule(&end, y_f);
                        let t_start_utc = date_to_seconds(y_f, sm, s_day) + start.time_offset + tz.std_offset;
                        let t_end_utc = date_to_seconds(y_f, em, e_day) + end.time_offset + tz.dst_offset.unwrap();
                        if t_start_utc < t_end_utc {
                            if w_sec - current_offset >= t_start_utc && w_sec - current_offset < t_end_utc {
                                is_dst = true; break;
                            }
                        } else {
                            if w_sec - current_offset >= t_end_utc && w_sec - current_offset < t_start_utc {
                                is_dst = true; break;
                            }
                        }
                    }
                }
                if is_dst { current_offset = dst_off; }
            }
            let t_after = w_sec - current_offset;
            if t_after >= tz.last_transition {
                candidates.push((t_after, current_offset, 0));
            }

            // Footer rule
            for y_f in 1800..2400 {
                if let (Some(start), Some(end)) = (tz.start_rule, tz.end_rule) {
                    let (sm, sd, s_day) = get_date_from_rule(&start, y_f);
                    let (em, ed, e_day) = get_date_from_rule(&end, y_f);
                    let t_start_utc = date_to_seconds(y_f, sm, s_day) + start.time_offset + tz.std_offset;
                    let t_end_utc = date_to_seconds(y_f, em, e_day) + end.time_offset + tz.dst_offset.unwrap();

                    let mut periods = Vec::new();
                    if t_start_utc < t_end_utc {
                        periods.push((t_start_utc, t_end_utc, tz.dst_offset.unwrap()));
                    } else {
                        periods.push((t_end_utc, t_start_utc, tz.dst_offset.unwrap()));
                    }

                    for (ta, tb, off) in periods {
                        let t_cand = w_sec - off;
                        if t_cand >= ta && t_cand < tb && t_cand >= tz.last_transition {
                            candidates.push((t_cand, off, 0));
                        }
                    }

                    // Standard period
                    let mut is_in_dst = false;
                    if t_start_utc < t_end_utc {
                        if w_sec - tz.std_offset >= t_start_utc && w_sec - tz.std_offset < t_end_utc { is_in_dst = true; }
                    } else {
                        if w_sec - tz.std_offset >= t_end_utc && w_sec - tz.std_offset < t_start_utc { is_in_dst = true; }
                    }
                    if !is_in_dst {
                        let t_cand = w_sec - tz.std_offset;
                        if t_cand >= tz.last_transition {
                            candidates.push((t_cand, tz.std_offset, 0));
                        }
                    }
                }
            }

            candidates.sort_by_key(|x| x.0);
            candidates.dedup_by(|a, b| a.0 == b.0);

            if candidates.is_empty() {
                // This should not happen given the logic.
            } else if candidates.len() == 1 {
                let (t, off, _) = candidates[0];
                println!("{} -> {} {} {}", line, t, format_offset(off), tz.abbreviations[0]); // Abbr index needs to be correct
            } else {
                let mut out = Vec::new();
                for (t, off, _) in candidates {
                    out.push(format!("{} {} {}", t, format_offset(off), tz.abbreviations[0]));
                }
                println!("{} -> {} | {}", line, out[0], out[1]);
            }
        }
    }
}

fn parse_wall_time(s: &str) -> i64 {
    let parts: Vec<&str> = s.split('T').collect();
    let date_parts: Vec<&str> = parts[0].split('-').collect();
    let time_parts: Vec<&str> = parts[1].split(':').collect();
    let y = date_parts[0].parse::<i32>().unwrap();
    let m = date_parts[1].parse::<u32>().unwrap();
    let d = date_parts[2].parse::<u32>().unwrap();
    let hh = time_parts[0].parse::<i32>().unwrap();
    let mm = time_parts[1].parse::<i32>().unwrap();
    let ss = time_parts[2].parse::<i32>().unwrap();
    date_to_seconds(y, m, d) + (hh * 3600 + mm * 60 + ss) as i64
}

fn format_local(t: i64, offset: i32, tz: &TZif) -> String {
    let (y, m, d) = get_date_from_year_sec(t - offset);
    let hh = ((t - offset) % 86400 + 86400) % 86400 / 3600;
    let mm = ((t - offset) % 3600 + 3600) % 3600 / 60;
    let ss = (t - offset) % 60;
    let off_str = format_offset(offset);
    format!("{}-{:02}-{:02}T{:02}:{:02}:{:02}{}", y, m, d, hh, mm, ss, off_str)
}

fn format_offset(offset: i32) -> String {
    let mut off_str = if offset >= 0 { "+" } else { "-" };
    let abs_off = offset.abs();
    let off_hh = (abs_off / 3600) % 100;
    let off_mm = (abs_off % 3600) / 60;
    let off_ss = abs_off % 60;
    let mut res = format!("{}{:02}:{:02}", off_str, off_hh, off_mm);
    if off_ss != 0 { res.push_str(&format!(":{:02}", off_ss)); }
    res
}

fn get_date_from_year_sec(sec: i64) -> (i32, u32, u32) {
    let mut y = 1800;
    while y < 2400 {
        let days_in_year = if is_leap(y) { 366 } else { 365 };
        let year_sec = days_in_year * 86400;
        if sec < year_sec {
            let mut day_sec = sec;
            for m in 1..13 {
                let days_in_m = days_in_month(m as u32, y);
                let m_sec = days_in_m as i64 * 86400;
                if day_sec < m_sec {
                    let d = (day_sec / 86400) as u32 + 1;
                    return (y, m as u32, d);
                }
                day_sec -= m_sec;
            }
        }
        sec -= year_sec;
        y += 1;
    }
    (2399, 12, 31)
}

use std::env;
use std::fs;
use std::io::{self, Read};
use std::path::Path;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return;
    }
    let dir_path = &args[1];
    let entries = match fs::read_dir(dir_path) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut wav_files: Vec<_> = entries
        .filter_map(|e| e.ok())
        .filter(|e| {
            let name = e.file_name().into_string().unwrap_or_default();
            name.ends_with(".wav")
        })
        .collect();

    wav_files.sort_by_key(|e| e.file_name());

    let mut first_file = true;
    for entry in wav_files {
        if !first_file {
            println!();
        }
        first_file = false;

        let path = entry.path();
        let file_name = path
            .file_name()
            .unwrap()
            .to_string_lossy()
            .into_owned();

        match process_wav(&path) {
            Ok(Some(output)) => {
                println!("{}: {}", file_name, output);
            }
            Ok(None) => {
                println!("{}: unsupported", file_name);
            }
            Err(_) => {
                println!("{}: unsupported", file_name);
            }
        }
    }
}

fn process_wav(path: &Path) -> io::Result<Option<String>> {
    let mut file = fs::File::open(path)?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)?;

    if buffer.len() < 16 || &buffer[0..4] != b"RIFF" || &buffer[4..8] != &b"WAVE"[..] {
        return Ok(None);
    }

    let mut pos = 8;
    let mut fmt_chunk: Option<(Vec<u8>, usize)> = None;
    let mut data_chunk: Option<Vec<i16>> = None;

    while pos + 8 <= buffer.len() {
        let id = &buffer[pos..pos + 4];
        let size = u32::from_le_bytes(buffer[pos + 4..pos + 8].try_into().unwrap()) as usize;
        pos += 8;
        if pos + size > buffer.len() {
            break;
        }
        let body = &buffer[pos..pos + size];
        if id == b"fmt " {
            fmt_chunk = Some((body.to_vec(), size));
        } else if id == b"data" {
            let mut samples = Vec::new();
            let mut i = 0;
            while i + 2 <= size {
                let s = i16::from_le_bytes([body[i] as i8 as u8, body[i + 1] as i8 as u8]);
                samples.push(s);
                i += 2;
            }
            data_chunk = Some(samples);
        }
        pos += size;
        if size % 2 != 0 {
            pos += 1;
        }
    }

    let (fmt_body, fmt_size) = match fmt_chunk {
        Some(f) => f,
        None => return Ok(None),
    };

    let tag = u16::from_le_bytes([fmt_body[0], fmt_body[1]]);
    let channels = u16::from_le_bytes([fmt_body[2], fmt_body[3]]) as u32;
    let sample_rate = u32::from_le_bytes([fmt_body[4], fmt_body[5], fmt_body[6], fmt_body[7]]);
    let bits_per_sample = u16::from_le_bytes([fmt_body[14], fmt_body[15]]) as u32;

    let effective_format = if tag == 0xFFFE && fmt_size > 24 {
        u16::from_le_bytes([fmt_body[24], fmt_body[25]]) as u32
    } else {
        tag as u32
    };

    if effective_format != 1 || bits_per_sample != 16 || channels < 1 || channels > 2 || 
       (sample_rate != 8000 && sample_rate != 16000) {
        return Ok(None);
    }

    let samples = match data_chunk {
        Some(s) => s,
        None => return Ok(None),
    };

    let num_left_samples = samples.len() / channels as usize;
    let n = (sample_rate as usize) / 50;
    let num_blocks = num_left_samples / n;

    let mut labels: Vec<Option<char>> = Vec::new();
    for b in 0..num_blocks {
        let start = b * n;
        let block = &samples[start * channels as usize .. (start + n) * channels as usize];
        let mut left_samples = Vec::new();
        for i in 0..n {
            left_samples.push(block[i * channels as usize]);
        }

        let mut energy = 0.0f64;
        for &x in &left_samples {
            energy += (x as f64) * (x as f64);
        }

        if energy < 1_000_000.0 * (n as f64) {
            labels.push(None);
        } else {
            let freqs = [697, 770, 852, 941, 1209, 1336, 1477, 1633];
            let mut r = [0.0f64; 8];
            for (i, &f) in freqs.iter().enumerate() {
                let c = 2.0 * (2.0 * std::f64::consts::PI * f as f64 / sample_rate as f64).cos();
                let (mut s1, mut s2) = (0.0f64, 0.0f64);
                for &x in &left_samples {
                    let s = x as f64 + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                let p = s1 * s1 + s2 * s2 - c * s1 * s2;
                r[i] = 2.0 * p / (n as f64 * energy);
            }

            let mut max_r_low = -1.0;
            let mut fl = 0;
            for i in 0..4 {
                if r[i] > max_r_low {
                    max_r_low = r[i];
                    fl = i;
                }
            }
            let mut max_r_high = -1.0;
            let mut fh = 0;
            for i in 4..8 {
                if r[i] > max_r_high {
                    max_r_high = r[i];
                    fh = i;
                }
            }

            if r[fl] >= 0.1 && r[fh] >= 0.1 && r[fl] + r[fh] >= 0.6 {
                let digit = match (freqs[fl], freqs[fh]) {
                    (697, 1209) => '1',
                    (697, 1336) => '2',
                    (697, 1477) => '3',
                    (697, 1633) => 'A',
                    (770, 1209) => '4',
                    (770, 1336) => '5',
                    (770, 1477) => '6',
                    (770, 1633) => 'B',
                    (852, 1209) => '7',
                    (852, 1336) => '8',
                    (852, 1477) => '9',
                    (852, 1633) => 'C',
                    (941, 1209) => '*',
                    (941, 1336) => '0',
                    (941, 1477) => '#',
                    (941, 1633) => 'D',
                    _ => ' ',
                };
                labels.push(Some(digit));
            } else {
                labels.push(None);
            }
        }
    }

    for i in 1..num_blocks - 1 {
        if labels[i].is_none() {
            if let (Some(d1), Some(d2)) = (labels[i - 1], labels[i + 1]) {
                if d1 == d2 {
                    labels[i] = Some(d1);
                }
            }
        }
    }

    let mut key_presses = Vec::new();
    let mut i = 0;
    while i < num_blocks {
        if let Some(digit) = labels[i] {
            let mut j = i;
            while j < num_blocks && labels[j] == Some(digit) {
                j += 1;
            }
            let run_len = j - i;
            if run_len >= 2 {
                key_presses.push((digit, i, j));
            }
            i = j;
        } else {
            i += 1;
        }
    }

    let mut output = format!("{}: {} Hz, {} ch, {} blocks\n", file_name, sample_rate, channels, num_blocks);
    for (digit, start_idx, end_idx) in key_presses {
        output.push_str(&format!("{} {} {}\n", digit, 20 * start_idx, 20 * end_idx));
    }
    let mut digits = String::new();
    for (digit, _, _) in &key_presses {
        digits.push(*digit);
    }
    output.push_str(&format!("digits: {}\n", digits));

    Ok(Some(output))
}
